INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37928, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存続", "is_correct": true, "explanation": "「映画館は存続できなくなった」で、閉館せずに続けられなくなるという意味になる。"}, {"text": "出勤", "is_correct": false, "explanation": "出勤は人が仕事に行くことで、映画館を主語にしては使えない。"}, {"text": "通院", "is_correct": false, "explanation": "通院は病院に通うことで、映画館には当てはまらない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は人が歩くことで、映画館ができる動作ではない。"}], "explanations": {"存続": "「映画館は存続できなくなった」で、閉館せずに続けられなくなるという意味になる。", "出勤": "出勤は人が仕事に行くことで、映画館を主語にしては使えない。", "通院": "通院は病院に通うことで、映画館には当てはまらない。", "散歩": "散歩は人が歩くことで、映画館ができる動作ではない。"}, "sentence_index": 6, "correct_answer": "存続"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で中断した試合を存続するかどうか、審判が決めた。", "explanation": "ここは〈続行〉の意味。進行中の試合などを続けることは続行を使い、存続は組織や制度に使うので合わない。"}, {"text": "彼は時計の針を三日間存続させた。", "explanation": "ここは〈保持〉の意味。物の位置を保つ場合は保持を使い、存続は合わない。"}, {"text": "彼は学年一位の成績を存続している。", "explanation": "ここは〈保持〉の意味。成績や地位を保つ場合は保持を使い、存続は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37928, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は子どもたちの応援で存続を決まった。", "corrected_sentence": "この店は子どもたちの応援で存続が決まった。", "error_description": "「決まる」は主語に「が」を取る。存続が主語になるので「を」ではなく「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37928, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は常連客のおかげで存続できる続けている。", "corrected_sentence": "この店は常連客のおかげで存続し続けている。", "error_description": "「存続」に続く動詞は「し続ける」の形になる。「できる続けている」は文法的に成り立たず、「存続し続けている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37929, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "存続の対義語。組織や制度をやめて終わらせることを指す。"}, {"text": "発展", "is_correct": false, "explanation": "物事が伸びて広がることで、続くことを止める意味にはならない。"}, {"text": "誕生", "is_correct": false, "explanation": "新しく生まれることで、存続の対義語とは辞書でも結ばれない。"}, {"text": "増加", "is_correct": false, "explanation": "数や量が増えることで、続いていく状態との対義関係はない。"}], "correct_answer": "廃止", "explanations": {"廃止": "存続の対義語。組織や制度をやめて終わらせることを指す。", "発展": "物事が伸びて広がることで、続くことを止める意味にはならない。", "誕生": "新しく生まれることで、存続の対義語とは辞書でも結ばれない。", "増加": "数や量が増えることで、続いていく状態との対義関係はない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37929, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「存続には～が欠かせない」の形で、必要とされる対象を示す「に」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「存続を」は目的語として文を組み立てるが、この文では「欠かせない」の条件を示す位置なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「存続がは」は主格の「が」と「は」が重なり、名詞が続かないので成り立たない。"}, {"text": "も", "is_correct": false, "explanation": "「存続もは」は「も」と「は」が重なり、文の形が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「存続には～が欠かせない」の形で、必要とされる対象を示す「に」が付く。", "を": "「存続を」は目的語として文を組み立てるが、この文では「欠かせない」の条件を示す位置なので合わない。", "が": "「存続がは」は主格の「が」と「は」が重なり、名詞が続かないので成り立たない。", "も": "「存続もは」は「も」と「は」が重なり、文の形が成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "も": "additive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "存続の対義語。制度を取りやめて終わらせることを指し、文中の「廃止を求める声」とも対応する。"}, {"text": "導入", "is_correct": false, "explanation": "新しく取り入れることで、続けるか止めるかの対義にはならない。"}, {"text": "改善", "is_correct": false, "explanation": "よりよくすることで、存続とは対義関係にない。"}, {"text": "拡大", "is_correct": false, "explanation": "規模を広げることで、続いていく状態との対義関係はない。"}], "correct_answer": "廃止", "explanations": {"廃止": "存続の対義語。制度を取りやめて終わらせることを指し、文中の「廃止を求める声」とも対応する。", "導入": "新しく取り入れることで、続けるか止めるかの対義にはならない。", "改善": "よりよくすることで、存続とは対義関係にない。", "拡大": "規模を広げることで、続いていく状態との対義関係はない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37929, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がなくならずに、同じ状態のままで続くこと。", "primary_collocate": null, "pronunciation": "そんぞく", "ipa": "soɴzokɯ", "syllable_count": 4, "sentences": [{"text": "我々は、この不可逆的な変化の連鎖をどう受け止めるべきか、文明の存続をかけて抜本的な転換を迫られているのである。", "target_word": "存続", "complexity_tier": "T5", "furigana": "我々[われわれ]は、この不可逆的[ふかぎゃくてき]な変化[へんか]の連鎖[れんさ]をどう受[う]け止[と]めるべきか、文明[ぶんめい]の存続[そんぞく]をかけて抜本的[ばっぽんてき]な転換[てんかん]を迫[せま]られているのである。", "sentence_source": "mined"}, {"text": "売り上げが急に落ち込み、会社の存続が危ぶまれている。", "target_word": "存続", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが急[きゅう]に落[お]ち込[こ]み、会社[かいしゃ]の存続[そんぞく]が危[あや]ぶまれている。", "sentence_source": "generated"}, {"text": "少子化が進み、この小さな村の存続は難しくなってきた。", "target_word": "存続", "complexity_tier": "T3", "furigana": "少子化[しょうしか]が進[すす]み、この小[ちい]さな村[むら]の存続[そんぞく]は難[むずか]しくなってきた。", "sentence_source": "generated"}, {"text": "資金が足りないため、劇団は存続するために寄付を集めることにした。", "target_word": "存続", "complexity_tier": "T3", "furigana": "資金[しきん]が足[た]りないため、劇団[げきだん]は存続[そんぞく]するために寄付[きふ]を集[あつ]めることにした。", "sentence_source": "generated"}, {"text": "市民の反対運動によって、古い図書館の存続が決まった。", "target_word": "存続", "complexity_tier": "T3", "furigana": "市民[しみん]の反対[はんたい]運動[うんどう]によって、古[ふる]い図書館[としょかん]の存続[そんぞく]が決[き]まった。", "sentence_source": "generated"}, {"text": "経営陣は工場の存続よりも、従業員の雇用を守ることを優先した。", "target_word": "存続", "complexity_tier": "T4", "furigana": "経営陣[けいえいじん]は工場[こうじょう]の存続[そんぞく]よりも、従業員[じゅうぎょういん]の雇用[こよう]を守[まも]ることを優先[ゆうせん]した。", "sentence_source": "generated"}, {"text": "条約の存続を望む声と、廃止を求める声が議会で対立している。", "target_word": "存続", "complexity_tier": "T4", "furigana": "条約[じょうやく]の存続[そんぞく]を望[のぞ]む声[こえ]と、廃止[はいし]を求[もと]める声[こえ]が議会[ぎかい]で対立[たいりつ]している。", "sentence_source": "generated"}, {"text": "伝統行事の存続には、若い世代の協力が欠かせない。", "target_word": "存続", "complexity_tier": "T3", "furigana": "伝統[でんとう]行事[ぎょうじ]の存続[そんぞく]には、若[わか]い世代[せだい]の協力[きょうりょく]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "赤字が続いたので、店の存続をめぐって家族で何度も話し合った。", "target_word": "存続", "complexity_tier": "T3", "furigana": "赤字[あかじ]が続[つづ]いたので、店[みせ]の存続[そんぞく]をめぐって家族[かぞく]で何度[なんど]も話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "国の存続を左右する重大な決定なので、議会は慎重に議論した。", "target_word": "存続", "complexity_tier": "T4", "furigana": "国[くに]の存続[そんぞく]を左右[さゆう]する重大[じゅうだい]な決定[けってい]なので、議会[ぎかい]は慎重[しんちょう]に議論[ぎろん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "存続", "label": "基本形(名詞)"}, {"form": "存続する", "label": "辞書形"}, {"form": "存続した", "label": "過去形"}, {"form": "存続しない", "label": "否定形"}, {"form": "存続させる", "label": "使役形"}], "register": "formal", "sense_fingerprint": "組織・制度・国などが消えずに続いていくこと(書き言葉的)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37929, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存続", "is_correct": true, "explanation": "「文明の存続をかける」は、文明が残るかどうかを賭けるという意味で文脈に合う。"}, {"text": "発注", "is_correct": false, "explanation": "「文明の発注」は成り立たず、「をかける」ともつながらない。"}, {"text": "記念", "is_correct": false, "explanation": "「文明の記念をかける」は不自然で、抜本的な転換の文脈に合わない。"}, {"text": "授賞", "is_correct": false, "explanation": "「授賞をかける」は賞に関する文脈でしか使えず、文明とは結びつかない。"}], "explanations": {"存続": "「文明の存続をかける」は、文明が残るかどうかを賭けるという意味で文脈に合う。", "発注": "「文明の発注」は成り立たず、「をかける」ともつながらない。", "記念": "「文明の記念をかける」は不自然で、抜本的な転換の文脈に合わない。", "授賞": "「授賞をかける」は賞に関する文脈でしか使えず、文明とは結びつかない。"}, "sentence_index": 0, "correct_answer": "存続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日の練習を存続している。", "explanation": "ここは〈継続〉の意味。存続は組織や制度などが消えずに続くことを指すので、個人の練習には使わない。"}, {"text": "彼は体重を存続するために毎日走っている。", "explanation": "ここは〈維持〉の意味。体重のような数値の状態を保つ場合は維持を使い、存続は合わない。"}, {"text": "古い建物の存続部分を調べた。", "explanation": "ここは〈残存〉の意味。壊れずに残っている部分を指すので、続いていくことを表す存続は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37929, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存続", "is_correct": true, "explanation": "「条約の存続を望む声」と「廃止を求める声」が対になり、文脈に合う。"}, {"text": "出費", "is_correct": false, "explanation": "「条約の出費を望む」は意味が通らない。"}, {"text": "消灯", "is_correct": false, "explanation": "「条約の消灯」は成り立たず、望む対象にならない。"}, {"text": "味見", "is_correct": false, "explanation": "「条約の味見」は文脈に合わず、議会の対立とも関係しない。"}], "explanations": {"存続": "「条約の存続を望む声」と「廃止を求める声」が対になり、文脈に合う。", "出費": "「条約の出費を望む」は意味が通らない。", "消灯": "「条約の消灯」は成り立たず、望む対象にならない。", "味見": "「条約の味見」は文脈に合わず、議会の対立とも関係しない。"}, "sentence_index": 6, "correct_answer": "存続"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で中断した試合を存続するかどうか、審判が決めた。", "explanation": "ここは〈続行〉の意味。試合のように進行中の出来事を続けることは続行を使い、存続は組織や制度に使うので合わない。"}, {"text": "その木の高さを五年間存続した。", "explanation": "ここは〈維持〉の意味。高さのような数値を保つ場合は維持を使い、存続は合わない。"}, {"text": "彼は長年の記録を存続している。", "explanation": "ここは〈保持〉の意味。記録や成績を持ち続ける場合は保持を使い、存続は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37929, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "経営の立て直しがなければ、会社の存続を危ぶまれる。", "corrected_sentence": "経営の立て直しがなければ、会社の存続が危ぶまれる。", "error_description": "「危ぶまれる」は受け身で、主語に「が」を取る。存続が主語になるので「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37929, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この決定は国の存続を左右な重大な問題だ。", "corrected_sentence": "この決定は国の存続を左右する重大な問題だ。", "error_description": "「左右する」は動詞なので「～する」の形が必要。「左右な」は活用が誤りで、目的語の「存続を」を取る動詞として「左右する」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37930, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37930, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「メディアの取材」と名詞を結ぶ連体の「の」で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「メディアが取材を受けて」は主語になり、社長の取材の対象として不自然。"}, {"text": "を", "is_correct": false, "explanation": "「メディアを取材を受けて」は目的語が二つになり、文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「メディアと取材を受けて」は相手を示すが、取材の相手として不自然。"}], "correct_answer": "の", "explanations": {"の": "「メディアの取材」と名詞を結ぶ連体の「の」で、ここに入る。", "が": "「メディアが取材を受けて」は主語になり、社長の取材の対象として不自然。", "を": "「メディアを取材を受けて」は目的語が二つになり、文が崩れる。", "と": "「メディアと取材を受けて」は相手を示すが、取材の相手として不自然。"}, "error_tags": {"が": "主語を示す助詞", "を": "目的語を示す助詞", "と": "並列・相手を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37930, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の間で情報や思いをつたえるもの。", "primary_collocate": null, "pronunciation": "めでぃあ", "ipa": "me̞dʲia", "syllable_count": 3, "sentences": [{"text": "テレビや新聞などのメディアは、毎日ニュースを伝えています。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "テレビや新聞(しんぶん)などのメディアは、毎日(まいにち)ニュースを伝(つた)えています。", "sentence_source": "generated"}, {"text": "昔は手紙が、遠くの人に思いを伝えるメディアでした。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "昔(むかし)は手紙(てがみ)が、遠(とお)くの人(ひと)に思(おも)いを伝(つた)えるメディアでした。", "sentence_source": "generated"}, {"text": "メディアによって、同じ事件でも伝え方がちがいます。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "メディアによって、同(おな)じ事件(じけん)でも伝(つた)え方(かた)がちがいます。", "sentence_source": "generated"}, {"text": "祖父はラジオというメディアが好きで、朝から聞いています。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "祖父(そふ)はラジオというメディアが好(す)きで、朝(あさ)から聞(き)いています。", "sentence_source": "generated"}, {"text": "町の祭りがメディアに取り上げられて、観光客が増えました。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "町(まち)の祭(まつ)りがメディアに取(と)り上(あ)げられて、観光客(かんこうきゃく)が増(ふ)えました。", "sentence_source": "generated"}, {"text": "新しいメディアが生まれるたびに、人々の暮らしは変わってきました。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "新(あたら)しいメディアが生(う)まれるたびに、人々(ひとびと)の暮(く)らしは変(か)わってきました。", "sentence_source": "generated"}, {"text": "先生は「メディアの情報をそのまま信じてはいけません」と言いました。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "先生(せんせい)は「メディアの情報(じょうほう)をそのまま信(しん)じてはいけません」と言(い)いました。", "sentence_source": "generated"}, {"text": "社長はメディアの取材を受けて、新商品について話しました。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "社長(しゃちょう)はメディアの取材(しゅざい)を受(う)けて、新商品(しんしょうひん)について話(はな)しました。", "sentence_source": "generated"}, {"text": "私たちは、メディアを通じて世界のできごとを知ります。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "私(わたし)たちは、メディアを通(つう)じて世界(せかい)のできごとを知(し)ります。", "sentence_source": "generated"}, {"text": "音楽も絵も、人の気持ちを伝えるメディアになります。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "音楽(おんがく)も絵(え)も、人(ひと)の気持(きも)ちを伝(つた)えるメディアになります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メディア", "label": "基本形"}], "register": "中立", "sense_fingerprint": "テレビ・新聞・手紙など、人と人の間で情報や気持ちを伝えるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37930, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メディア", "is_correct": true, "explanation": "テレビや新聞と並べて、情報を伝える媒体の総称として入る。"}, {"text": "ドラマ", "is_correct": false, "explanation": "番組の一種で、毎日ニュースを伝える役割はないので合わない。"}, {"text": "小説", "is_correct": false, "explanation": "文字で書かれた作品で、毎日ニュースを伝えるものではないので合わない。"}, {"text": "俳優", "is_correct": false, "explanation": "人を指す語で、毎日ニュースを伝える主語としては合わない。"}], "explanations": {"メディア": "テレビや新聞と並べて、情報を伝える媒体の総称として入る。", "ドラマ": "番組の一種で、毎日ニュースを伝える役割はないので合わない。", "小説": "文字で書かれた作品で、毎日ニュースを伝えるものではないので合わない。", "俳優": "人を指す語で、毎日ニュースを伝える主語としては合わない。"}, "sentence_index": 0, "correct_answer": "メディア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出張のメディアは、会社が払ってくれます。", "explanation": "ここは〈交通費〉の意味。乗り物の代金を指すので、人に情報や思いを伝えるという定義には合わない。"}, {"text": "ハサミは、紙を切るためのメディアです。", "explanation": "ここは〈道具〉の意味。ハサミのような物を指す語をメディアに替えても不自然で、情報や思いを伝えるという定義とは合わない。"}, {"text": "バスは、駅まで行くためのメディアとして便利です。", "explanation": "ここは〈手段〉の意味。移動の手段はメディアとは呼ばないので、情報や思いを伝えるという定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37930, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メディア", "is_correct": true, "explanation": "「〜の情報」として、情報を伝える媒体を指すので入る。"}, {"text": "習慣", "is_correct": false, "explanation": "行動の繰り返しを指す語で、信じてはいけない情報の対象にはならない。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを指す語で、そのまま信じる情報の対象としては合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の景色を指す語で、情報という語と結びつかない。"}], "explanations": {"メディア": "「〜の情報」として、情報を伝える媒体を指すので入る。", "習慣": "行動の繰り返しを指す語で、信じてはいけない情報の対象にはならない。", "感情": "心の動きを指す語で、そのまま信じる情報の対象としては合わない。", "夕焼け": "空の景色を指す語で、情報という語と結びつかない。"}, "sentence_index": 6, "correct_answer": "メディア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は、しょうゆというメディアで味を整えています。", "explanation": "ここは〈調味料〉の意味。味つけに使うものを指すので、人に情報や思いを伝えるという定義には合わない。"}, {"text": "ドライバーは、ネジをしめるためのメディアです。", "explanation": "ここは〈工具〉の意味。ネジを締める道具を指す語で、メディアは情報や思いを伝えるものなので合わない。"}, {"text": "このストーブは、灯油というメディアで部屋をあたためます。", "explanation": "ここは〈燃料〉の意味。部屋をあたためるエネルギー源を指すので、情報や思いを伝えるという定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37930, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族は毎朝、テレビというメディアに天気を確かめます。", "corrected_sentence": "家族は毎朝、テレビというメディアで天気を確かめます。", "error_description": "「メディア」の後の助詞が誤り。手段を表す「で」が正しく、「に」では「確かめる」と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37930, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "絵本は、子どもが言葉を覚えるための大切なメディアだです。", "corrected_sentence": "絵本は、子どもが言葉を覚えるための大切なメディアです。", "error_description": "名詞「メディア」に「です」を続けるときは、間に「だ」を挟まない。「だです」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
