INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37931, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "情報や芸術作品などを、大勢の人に伝えるための方法や手段。", "primary_collocate": null, "pronunciation": "めでぃあ", "ipa": "me̞dʲia", "syllable_count": 3, "sentences": [{"text": "この雑誌は、新しい映画を多くの人に知らせるメディアとして使われています。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "この雑誌(ざっし)は、新(あたら)しい映画(えいが)を多(おお)くの人(ひと)に知(し)らせるメディアとして使(つか)われています。", "sentence_source": "generated"}, {"text": "会社は広告を出すメディアを、テレビからインターネットに変えました。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は広告(こうこく)を出(だ)すメディアを、テレビからインターネットに変(か)えました。", "sentence_source": "generated"}, {"text": "美術館は、動画というメディアを使って作品を紹介しています。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "美術館(びじゅつかん)は、動画(どうが)というメディアを使(つか)って作品(さくひん)を紹介(しょうかい)しています。", "sentence_source": "generated"}, {"text": "新商品を広めるために、どのメディアがいちばん効果的かを考えました。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "新商品(しんしょうひん)を広(ひろ)めるために、どのメディアがいちばん効果的(こうかてき)かを考(かんが)えました。", "sentence_source": "generated"}, {"text": "紙のメディアは減っていますが、本が好きな人はまだたくさんいます。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "紙(かみ)のメディアは減(へ)っていますが、本(ほん)が好(す)きな人(ひと)はまだたくさんいます。", "sentence_source": "generated"}, {"text": "作家は、自分の詩を小さなメディアで発表しました。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "作家(さっか)は、自分(じぶん)の詩(し)を小(ちい)さなメディアで発表(はっぴょう)しました。", "sentence_source": "generated"}, {"text": "選挙の前には、さまざまなメディアが候補者の考えを伝えます。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "選挙(せんきょ)の前(まえ)には、さまざまなメディアが候補者(こうほしゃ)の考(かんが)えを伝(つた)えます。", "sentence_source": "generated"}, {"text": "地震のとき、ラジオは多くの人に避難の情報を届ける大切なメディアになります。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "地震(じしん)のとき、ラジオは多(おお)くの人(ひと)に避難(ひなん)の情報(じょうほう)を届(とど)ける大切(たいせつ)なメディアになります。", "sentence_source": "generated"}, {"text": "新しい商品を売るには、客に合ったメディアを選ぶことが大事です。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "新(あたら)しい商品(しょうひん)を売(う)るには、客(きゃく)に合(あ)ったメディアを選(えら)ぶことが大事(だいじ)です。", "sentence_source": "generated"}, {"text": "彼女は漫画というメディアで、戦争の悲しさを伝えています。", "target_word": "メディア", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は漫画(まんが)というメディアで、戦争(せんそう)の悲(かな)しさを伝(つた)えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メディア", "label": "基本形"}], "register": "中立", "sense_fingerprint": "広告・報道・作品発表など、大勢に伝えるための方法・手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37931, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メディア", "is_correct": true, "explanation": "情報や作品を大勢に伝える方法・手段の意味で、「〜として使われる」に入る。"}, {"text": "試験", "is_correct": false, "explanation": "能力を調べるものであり、映画を知らせる手段としては使わない。"}, {"text": "調味料", "is_correct": false, "explanation": "料理に使うもので、映画を知らせる手段にはならない。"}, {"text": "薬品", "is_correct": false, "explanation": "治療や化学に使う物質で、映画を大勢に知らせる手段としては合わない。"}], "explanations": {"メディア": "情報や作品を大勢に伝える方法・手段の意味で、「〜として使われる」に入る。", "試験": "能力を調べるものであり、映画を知らせる手段としては使わない。", "調味料": "料理に使うもので、映画を知らせる手段にはならない。", "薬品": "治療や化学に使う物質で、映画を大勢に知らせる手段としては合わない。"}, "sentence_index": 0, "correct_answer": "メディア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい店を開くためのメディアを集めています。", "explanation": "ここは〈資金〉の意味。店を開くお金を指すので、大勢に情報や芸術作品を伝える方法や手段という定義には合わない。"}, {"text": "洗濯機は、衣類を洗うためのメディアです。", "explanation": "ここは〈機械〉の意味。衣類を洗う機械は、情報を大勢に伝える手段ではないので定義に合わない。"}, {"text": "このフライパンは、肉を焼くためのメディアです。", "explanation": "ここは〈調理器具〉の意味。肉を焼く道具は、大勢に情報や作品を伝える手段ではないので定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37931, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メディア", "is_correct": true, "explanation": "選挙の際に候補者の考えを大勢に伝える媒体として入る。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指す語で、候補者の考えを伝える主語にはならない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を指す語で、候補者の考えを伝える主語としては合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを指す語で、候補者の考えを伝える主語としては合わない。"}], "explanations": {"メディア": "選挙の際に候補者の考えを大勢に伝える媒体として入る。", "天気": "空模様を指す語で、候補者の考えを伝える主語にはならない。", "体温": "体の温度を指す語で、候補者の考えを伝える主語としては合わない。", "体重": "体の重さを指す語で、候補者の考えを伝える主語としては合わない。"}, "sentence_index": 6, "correct_answer": "メディア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は、ガソリンというメディアで走ります。", "explanation": "ここは〈燃料〉の意味。車を動かすエネルギーを指すので、大勢に情報を伝える方法や手段という定義には合わない。"}, {"text": "カレーは、新鮮なメディアで作ると、おいしくなる。", "explanation": "ここは〈材料〉の意味。料理の材料を指す語で、大勢に伝える方法・手段の定義とは合わない。"}, {"text": "ペンチは、針金を切るためのメディアです。", "explanation": "ここは〈工具〉の意味。針金を切る道具は、大勢に伝える方法とは関係ないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37931, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、防災の情報を伝えるメディアとしで、アプリを作った。", "corrected_sentence": "市は、防災の情報を伝えるメディアとして、アプリを作った。", "error_description": "資格・役割を表す「として」の後に「で」は続かない。「としで」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37931, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スマホは、災害時に大切なメディアなります。", "corrected_sentence": "スマホは、災害時に大切なメディアになります。", "error_description": "「〜になる」の「に」が抜けている。「メディアなります」は誤りで、「メディアになります」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37932, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の目的語を示す"}, {"text": "に", "is_correct": false, "explanation": "「見る」の対象を示す形にならず、ここでは不自然"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ「の」で、「見る」の目的語にならない"}, {"text": "が", "is_correct": false, "explanation": "「ドラマが見る」となり、見る人が主語にならない"}], "correct_answer": "を", "explanations": {"を": "「見る」の目的語を示す", "に": "「見る」の対象を示す形にならず、ここでは不自然", "の": "名詞をつなぐ「の」で、「見る」の目的語にならない", "が": "「ドラマが見る」となり、見る人が主語にならない"}, "error_tags": {"に": "相手", "の": "所属", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37932, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ドラマの話」と名詞をつなぎ、話の所属を示す"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「ドラマへの話」は話題の関係にならない"}, {"text": "と", "is_correct": false, "explanation": "「ドラマと話を」は並列になり、ここでは話の所属にならない"}, {"text": "を", "is_correct": false, "explanation": "「ドラマを話を」と目的語が二つ重なり不自然"}], "correct_answer": "の", "explanations": {"の": "「ドラマの話」と名詞をつなぎ、話の所属を示す", "へ": "方向を表し、「ドラマへの話」は話題の関係にならない", "と": "「ドラマと話を」は並列になり、ここでは話の所属にならない", "を": "「ドラマを話を」と目的語が二つ重なり不自然"}, "error_tags": {"へ": "方向", "と": "並列", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37932, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人やできごとをえがいた、テレビやえいがのはなし。", "primary_collocate": null, "pronunciation": "どらま", "ipa": "dorama", "syllable_count": 3, "sentences": [{"text": "このドラマは、家族のきずなをえがいた話だ。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "このドラマは、家族[かぞく]のきずなをえがいた話[はなし]だ。", "sentence_source": "generated"}, {"text": "毎週木曜日の夜に、ドラマを見るのが楽しみだ。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]木曜日[もくようび]の夜[よる]に、ドラマを見[み]るのが楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "昨日のドラマで、主人公が泣くところがよかった。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "昨日[きのう]のドラマで、主人公[しゅじんこう]が泣[な]くところがよかった。", "sentence_source": "generated"}, {"text": "姉はドラマを見て、いつも泣いている。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "姉[あね]はドラマを見[み]て、いつも泣[な]いている。", "sentence_source": "generated"}, {"text": "学校を舞台にしたドラマが、人気になっている。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "学校[がっこう]を舞台[ぶたい]にしたドラマが、人気[にんき]になっている。", "sentence_source": "generated"}, {"text": "母はドラマの続きが気になって、早く帰ってきた。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "母[はは]はドラマの続[つづ]きが気[き]になって、早[はや]く帰[かえ]ってきた。", "sentence_source": "generated"}, {"text": "このドラマには、友達とけんかをした人の気持ちがよく出ている。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "このドラマには、友達[ともだち]とけんかをした人[ひと]の気持[きも]ちがよく出[で]ている。", "sentence_source": "generated"}, {"text": "先週見たドラマの話を、友達としている。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "先週[せんしゅう]見[み]たドラマの話[はなし]を、友達[ともだち]としている。", "sentence_source": "generated"}, {"text": "昔の町の暮らしをえがいたドラマを、祖父と一緒に見た。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "昔[むかし]の町[まち]の暮[く]らしをえがいたドラマを、祖父[そふ]と一緒[いっしょ]に見[み]た。", "sentence_source": "generated"}, {"text": "ドラマが終わると、みんなでその話をした。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "ドラマが終[お]わると、みんなでその話[はなし]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドラマ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人やできごとを描いたテレビや映画の話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: えがい (Zipf 1.72)','sentence 8 above tier T2: contains vocabulary far above tier T2: えがい (Zipf 1.72)']::text[], '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37932, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドラマ", "is_correct": true, "explanation": "文の主語で、家族のきずなを描いた作品を指す"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は話を描く作品ではないので、この文に合わない"}, {"text": "窓", "is_correct": false, "explanation": "窓は家族のきずなを描かないので合わない"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は話をえがく作品ではないので不自然"}], "explanations": {"ドラマ": "文の主語で、家族のきずなを描いた作品を指す", "鉛筆": "鉛筆は話を描く作品ではないので、この文に合わない", "窓": "窓は家族のきずなを描かないので合わない", "椅子": "椅子は話をえがく作品ではないので不自然"}, "sentence_index": 0, "correct_answer": "ドラマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドラマは、布を縫い合わせて服を仕立てる道具だ。", "explanation": "〈ミシン〉の説明。ドラマは俳優が演じる映像作品で、布を縫う道具ではないので合わない"}, {"text": "ドラマは、人やできごとを文章でえがいた話だ。", "explanation": "〈小説〉の説明。ドラマは映像で見せる作品で、文章でえがくものではない"}, {"text": "ドラマは、一枚の絵で人の気持ちをえがいている。", "explanation": "〈絵画〉の説明。ドラマは動く映像の作品で、一枚の絵にはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37932, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドラマ", "is_correct": true, "explanation": "文の主語で、人の気持ちがよく出ている作品を指す"}, {"text": "皿", "is_correct": false, "explanation": "皿は気持ちを表す作品ではないので、この文に合わない"}, {"text": "靴", "is_correct": false, "explanation": "靴は人の気持ちを描かないので合わない"}, {"text": "机", "is_correct": false, "explanation": "机は作品にならないので、この文に合わない"}], "explanations": {"ドラマ": "文の主語で、人の気持ちがよく出ている作品を指す", "皿": "皿は気持ちを表す作品ではないので、この文に合わない", "靴": "靴は人の気持ちを描かないので合わない", "机": "机は作品にならないので、この文に合わない"}, "sentence_index": 6, "correct_answer": "ドラマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドラマは、言葉の意味を一つずつ説明している。", "explanation": "〈辞書〉の説明。ドラマは物語を見せる作品で、言葉の意味を説明するものではない"}, {"text": "ドラマは、町の道や建物の位置を示している。", "explanation": "〈地図〉の説明。ドラマは場所を示すための図ではない"}, {"text": "ドラマは、その日の出来事を記事にして伝えている。", "explanation": "〈新聞〉の説明。ドラマは出来事を記事で報じるものではなく、物語として描くもの"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37932, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、ドラマを感動して、とても泣いた。", "corrected_sentence": "昨日、ドラマに感動して、とても泣いた。", "error_description": "『感動する』は『に』と組むので『を』は誤り。正しくは『ドラマに感動して』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
