INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37933, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「あのドラマ」を話題として提示する"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、話題の提示にならない"}, {"text": "に", "is_correct": false, "explanation": "「ドラマに見る」の形にならず、文の骨組みに合わない"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、話題の提示にならない"}], "correct_answer": "は", "explanations": {"は": "「あのドラマ」を話題として提示する", "へ": "方向を表し、話題の提示にならない", "に": "「ドラマに見る」の形にならず、文の骨組みに合わない", "から": "起点を表し、話題の提示にならない"}, "error_tags": {"へ": "方向", "に": "着点", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
