INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37933, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "俳優が演じる、物語形式のテレビ番組や映画。", "primary_collocate": null, "pronunciation": "どらま", "ipa": "dorama", "syllable_count": 3, "sentences": [{"text": "有名な俳優が出ているドラマを、毎週録画している。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な俳優[はいゆう]が出[で]ているドラマを、毎週[まいしゅう]録画[ろくが]している。", "sentence_source": "generated"}, {"text": "あのドラマは、原作の小説を読んでから見るとおもしろい。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "あのドラマは、原作[げんさく]の小説[しょうせつ]を読[よ]んでから見[み]るとおもしろい。", "sentence_source": "generated"}, {"text": "新しいドラマの主役に、人気の女優が選ばれた。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "新[あたら]しいドラマの主役[しゅやく]に、人気[にんき]の女優[じょゆう]が選[えら]ばれた。", "sentence_source": "generated"}, {"text": "このドラマは全十話で、来週が最終回だ。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "このドラマは全十話[ぜんじゅうわ]で、来週[らいしゅう]が最終回[さいしゅうかい]だ。", "sentence_source": "generated"}, {"text": "刑事が事件を解決するドラマが好きで、よく見ている。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "刑事[けいじ]が事件[じけん]を解決[かいけつ]するドラマが好[す]きで、よく見[み]ている。", "sentence_source": "generated"}, {"text": "彼女はドラマで医者の役を演じて、有名になった。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はドラマで医者[いしゃ]の役[やく]を演[えん]じて、有名[ゆうめい]になった。", "sentence_source": "generated"}, {"text": "そのドラマは映画化されて、劇場で公開された。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "そのドラマは映画化[えいがか]されて、劇場[げきじょう]で公開[こうかい]された。", "sentence_source": "generated"}, {"text": "脚本家が書いたドラマの台本を、俳優たちが読んでいる。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "脚本家[きゃくほんか]が書[か]いたドラマの台本[だいほん]を、俳優[はいゆう]たちが読[よ]んでいる。", "sentence_source": "generated"}, {"text": "ドラマの撮影現場は、朝早くから忙しそうだった。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "ドラマの撮影現場[さつえいげんば]は、朝早[あさはや]くから忙[いそが]しそうだった。", "sentence_source": "generated"}, {"text": "昨夜のドラマは視聴率が高く、話題になった。", "target_word": "ドラマ", "complexity_tier": "T3", "furigana": "昨夜[さくや]のドラマは視聴率[しちょうりつ]が高[たか]く、話題[わだい]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドラマ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "俳優が演じる物語形式のテレビ番組や映画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37933, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドラマ", "is_correct": true, "explanation": "文の主語で、有名な俳優が出る番組を指す"}, {"text": "皿", "is_correct": false, "explanation": "皿は番組ではないので、録画の対象にならない"}, {"text": "靴", "is_correct": false, "explanation": "靴は録画の対象にならない"}, {"text": "机", "is_correct": false, "explanation": "机は録画の対象にならない"}], "explanations": {"ドラマ": "文の主語で、有名な俳優が出る番組を指す", "皿": "皿は番組ではないので、録画の対象にならない", "靴": "靴は録画の対象にならない", "机": "机は録画の対象にならない"}, "sentence_index": 0, "correct_answer": "ドラマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドラマは、食材を細かく刻む台所の道具だ。", "explanation": "〈包丁〉の説明。ドラマは俳優が演じて映す作品で、食材を刻む道具ではないので合わない"}, {"text": "ドラマは、絵と文章で物語を伝える本だ。", "explanation": "〈絵本〉の説明。ドラマは本ではなく、俳優が演じて映す映像作品"}, {"text": "ドラマは、コマごとに絵を並べて物語を描く。", "explanation": "〈漫画〉の説明。ドラマは絵を並べて描く作品ではなく、俳優が演じて映す作品"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37933, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドラマ", "is_correct": true, "explanation": "文の主語で、映画化されて公開された作品を指す"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は映画化されないので、この文に合わない"}, {"text": "窓", "is_correct": false, "explanation": "窓は映画化されないので、この文に合わない"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は映画化されないので、この文に合わない"}], "explanations": {"ドラマ": "文の主語で、映画化されて公開された作品を指す", "鉛筆": "鉛筆は映画化されないので、この文に合わない", "窓": "窓は映画化されないので、この文に合わない", "椅子": "椅子は映画化されないので、この文に合わない"}, "sentence_index": 6, "correct_answer": "ドラマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドラマは、音の高さと長さを書き表した譜面だ。", "explanation": "〈楽譜〉の説明。ドラマは音符で書かれたものではなく、映像で見せる作品"}, {"text": "ドラマは、建物の形や大きさを正確に示した図面だ。", "explanation": "〈設計図〉の説明。ドラマは建物を示す図面ではない"}, {"text": "ドラマは、材料と手順を順番に書いたものだ。", "explanation": "〈レシピ〉の説明。ドラマは料理の手順を書いたものではない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37933, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はドラマを主演して、有名になった。", "corrected_sentence": "彼はドラマで主演して、有名になった。", "error_description": "『主演する』は『で』と組むので『を』は誤り。正しくは『ドラマで主演して』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
