INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37934, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お話を動く映像と音で見せる、見て楽しむ作品です。", "primary_collocate": null, "pronunciation": "えいが", "ipa": "eːɡa", "syllable_count": 3, "sentences": [{"text": "日曜日に、家族みんなで映画を見に行った。", "target_word": "映画", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に、家族[かぞく]みんなで映画[えいが]を見[み]に行[い]った。", "sentence_source": "generated"}, {"text": "この映画は、子どもでも分かるやさしい話だ。", "target_word": "映画", "complexity_tier": "T3", "furigana": "この映画[えいが]は、子[こ]どもでも分[わ]かるやさしい話[はなし]だ。", "sentence_source": "generated"}, {"text": "雨の日は外で遊べないので、家で映画を見る。", "target_word": "映画", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]で遊[あそ]べないので、家[いえ]で映画[えいが]を見[み]る。", "sentence_source": "generated"}, {"text": "映画の途中で、赤ちゃんが泣き出してしまった。", "target_word": "映画", "complexity_tier": "T3", "furigana": "映画[えいが]の途中[とちゅう]で、赤[あか]ちゃんが泣[な]き出[だ]してしまった。", "sentence_source": "generated"}, {"text": "友だちと映画の感想を話しながら帰った。", "target_word": "映画", "complexity_tier": "T3", "furigana": "友[とも]だちと映画[えいが]の感想[かんそう]を話[はな]しながら帰[かえ]った。", "sentence_source": "generated"}, {"text": "昨日見た映画は、最後に主人公が笑って終わった。", "target_word": "映画", "complexity_tier": "T3", "furigana": "昨日[きのう]見[み]た映画[えいが]は、最後[さいご]に主人公[しゅじんこう]が笑[わら]って終[お]わった。", "sentence_source": "generated"}, {"text": "姉は映画が好きで、毎週一本は見ている。", "target_word": "映画", "complexity_tier": "T3", "furigana": "姉[あね]は映画[えいが]が好[す]きで、毎週[まいしゅう]一本[いっぽん]は見[み]ている。", "sentence_source": "generated"}, {"text": "この映画は長すぎて、最後まで見る前に寝てしまった。", "target_word": "映画", "complexity_tier": "T3", "furigana": "この映画[えいが]は長[なが]すぎて、最後[さいご]まで見[み]る前[まえ]に寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "動物が出てくる映画なら、弟もおとなしく見る。", "target_word": "映画", "complexity_tier": "T3", "furigana": "動物[どうぶつ]が出[で]てくる映画[えいが]なら、弟[おとうと]もおとなしく見[み]る。", "sentence_source": "generated"}, {"text": "映画を見たあとで、原作の本を読んだ。", "target_word": "映画", "complexity_tier": "T3", "furigana": "映画[えいが]を見[み]たあとで、原作[げんさく]の本[ほん]を読[よ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "映画", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "お話を動く絵と音で見せる、見て楽しむもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37934, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "映画", "is_correct": true, "explanation": "「見に行く」の対象になり、家族で出かける娯楽として文に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は見に行くものではないので合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は見に行くものではなく、家族で出かける文脈に合わない。"}, {"text": "帳簿", "is_correct": false, "explanation": "帳簿は見に行くものではないので合わない。"}], "explanations": {"映画": "「見に行く」の対象になり、家族で出かける娯楽として文に合う。", "洗濯": "洗濯は見に行くものではないので合わない。", "掃除": "掃除は見に行くものではなく、家族で出かける文脈に合わない。", "帳簿": "帳簿は見に行くものではないので合わない。"}, "sentence_index": 0, "correct_answer": "映画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は、家族の笑顔を一枚に収めている。", "explanation": "ここは〈写真〉の意味。映画は動く映像で、笑顔を一枚の画像に収めるものではないので合わない。"}, {"text": "この映画は、子どもが眠る前に読むお話だ。", "explanation": "ここは〈絵本〉の意味。映画は見るもので、眠る前に読む絵入りの本ではないので合わない。"}, {"text": "この映画は、週刊誌に連載されて人気を集めた。", "explanation": "ここは〈漫画〉の意味。映画は雑誌に連載されるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37934, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "映画", "is_correct": true, "explanation": "好きで毎週見ている対象として文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は毎週一本見るものではないので合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は見て楽しむ対象ではなく、文の意味が通らない。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は見る対象ではないので合わない。"}], "explanations": {"映画": "好きで毎週見ている対象として文に合う。", "雨": "雨は毎週一本見るものではないので合わない。", "天井": "天井は見て楽しむ対象ではなく、文の意味が通らない。", "玄関": "玄関は見る対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "映画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この映画は、遠くの友だちに送るため、封筒に入れて切手を貼った。", "explanation": "ここは〈手紙〉の意味。映画は見るもので、封筒に入れて切手を貼って送るものではないので合わない。"}, {"text": "この映画は三人で協力して遊ぶので、休日に盛り上がる。", "explanation": "ここは〈ゲーム〉の意味。映画は見るもので、三人で協力して遊ぶものではないので合わない。"}, {"text": "この映画は町の店の場所をすべて示しているので、旅行に便利だ。", "explanation": "ここは〈地図〉の意味。映画は場所を示す地図ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37934, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎晩、古い映画が一本だけ見て眠る。", "corrected_sentence": "祖父は毎晩、古い映画を一本だけ見て眠る。", "error_description": "「見る」の目的語には「を」を使う。「が」は主語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37934, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちは、昨日映画を洗って、結末を熱心に語ってくれた。", "corrected_sentence": "友だちは、昨日映画を見て、結末を熱心に語ってくれた。", "error_description": "「映画」を受ける動詞は「見る」。「洗う」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37935, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「完成させる」の目的語を示す「を」。監督が完成させた作品なので文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や結果を表す。「完成させる」の目的語には使わないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。映画は完成させられる側なので、主語にはならず合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。映画は向かう先ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「完成させる」の目的語を示す「を」。監督が完成させた作品なので文に合う。", "に": "「に」は相手や結果を表す。「完成させる」の目的語には使わないので合わない。", "が": "「が」は主語を示す。映画は完成させられる側なので、主語にはならず合わない。", "へ": "「へ」は方向を表す。映画は向かう先ではないので合わない。"}, "error_tags": {"に": "相手", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37935, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「映画の予告編」と名詞をつなぐ「の」。映画に属する予告編を表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「映画を予告編」とすると二つの名詞がつながらず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「映画に予告編を見て」は対象と動作の関係が成り立たず、文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。映画へ向かって予告編を見るという文にはならず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「映画の予告編」と名詞をつなぐ「の」。映画に属する予告編を表し、文に合う。", "を": "「映画を予告編」とすると二つの名詞がつながらず、文が成り立たない。", "に": "「映画に予告編を見て」は対象と動作の関係が成り立たず、文として不自然。", "へ": "「へ」は方向を表す。映画へ向かって予告編を見るという文にはならず、不自然。"}, "error_tags": {"を": "対象", "に": "場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37935, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "劇場などで上映される、物語を映像と音声で表現した作品。", "primary_collocate": null, "pronunciation": "えいが", "ipa": "eːɡa", "syllable_count": 3, "sentences": [{"text": "その映画は、来月から全国の劇場で上映される。", "target_word": "映画", "complexity_tier": "T3", "furigana": "その映画[えいが]は、来月[らいげつ]から全国[ぜんこく]の劇場[げきじょう]で上映[じょうえい]される。", "sentence_source": "generated"}, {"text": "監督は十年かけて、この映画を完成させた。", "target_word": "映画", "complexity_tier": "T3", "furigana": "監督[かんとく]は十年[じゅうねん]かけて、この映画[えいが]を完成[かんせい]させた。", "sentence_source": "generated"}, {"text": "大きなスクリーンで見ると、映画の迫力がよく分かる。", "target_word": "映画", "complexity_tier": "T3", "furigana": "大[おお]きなスクリーンで見[み]ると、映画[えいが]の迫力[はくりょく]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "この映画は小説を原作にしており、公開前から話題になった。", "target_word": "映画", "complexity_tier": "T3", "furigana": "この映画[えいが]は小説[しょうせつ]を原作[げんさく]にしており、公開[こうかい]前[まえ]から話題[わだい]になった。", "sentence_source": "generated"}, {"text": "彼女はその映画での演技が評価され、賞を受けた。", "target_word": "映画", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はその映画[えいが]での演技[えんぎ]が評価[ひょうか]され、賞[しょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "映画の公開初日には、劇場の前に長い列ができた。", "target_word": "映画", "complexity_tier": "T3", "furigana": "映画[えいが]の公開[こうかい]初日[しょにち]には、劇場[げきじょう]の前[まえ]に長[なが]い列[れつ]ができた。", "sentence_source": "generated"}, {"text": "戦争を題材にした映画が、海外で高く評価された。", "target_word": "映画", "complexity_tier": "T3", "furigana": "戦争[せんそう]を題材[だいざい]にした映画[えいが]が、海外[かいがい]で高[たか]く評価[ひょうか]された。", "sentence_source": "generated"}, {"text": "映画の予告編を見て、公開日を楽しみに待っている。", "target_word": "映画", "complexity_tier": "T3", "furigana": "映画[えいが]の予告編[よこくへん]を見[み]て、公開日[こうかいび]を楽[たの]しみに待[ま]っている。", "sentence_source": "generated"}, {"text": "映画を一本作るには、多くの人の協力が必要だ。", "target_word": "映画", "complexity_tier": "T3", "furigana": "映画[えいが]を一本[いっぽん]作[つく]るには、多[おお]くの人[ひと]の協力[きょうりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "最近は、配信で映画を見る人も増えている。", "target_word": "映画", "complexity_tier": "T3", "furigana": "最近[さいきん]は、配信[はいしん]で映画[えいが]を見[み]る人[ひと]も増[ふ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "映画", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "劇場で上映される、映像と音声で物語を表現した作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37935, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "映画", "is_correct": true, "explanation": "劇場で上映される作品なので、文の主語として合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は劇場で上映されるものではないので合わない。"}, {"text": "料金", "is_correct": false, "explanation": "料金は上映されるものではないので合わない。"}, {"text": "野球", "is_correct": false, "explanation": "野球は劇場で上映される作品ではないので合わない。"}], "explanations": {"映画": "劇場で上映される作品なので、文の主語として合う。", "天気": "天気は劇場で上映されるものではないので合わない。", "料金": "料金は上映されるものではないので合わない。", "野球": "野球は劇場で上映される作品ではないので合わない。"}, "sentence_index": 0, "correct_answer": "映画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カメラに映画を入れて、旅行の写真を現像に出した。", "explanation": "ここは〈フィルム〉の意味。写真を撮るための感光材を指し、映画作品のことではないので合わない。"}, {"text": "この映画は、毎週月曜日に雑誌で続きが載る。", "explanation": "ここは〈漫画〉の意味。雑誌に連載される絵の物語で、映画は雑誌に載るものではないので合わない。"}, {"text": "この映画は、毎朝六時に鳴るように時刻を合わせた。", "explanation": "ここは〈目覚まし時計〉の意味。映画は時刻を合わせて鳴らす機械ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37935, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "映画", "is_correct": true, "explanation": "戦争を題材にした作品として、海外で評価される対象になる。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は題材にできる作品ではないので合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は題材にした作品ではないので、文に合わない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤は作品の題材になって評価されるものではないので合わない。"}], "explanations": {"映画": "戦争を題材にした作品として、海外で評価される対象になる。", "寝具": "寝具は題材にできる作品ではないので合わない。", "砂糖": "砂糖は題材にした作品ではないので、文に合わない。", "洗剤": "洗剤は作品の題材になって評価されるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "映画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近は、配信で映画を読む人も増えている。", "explanation": "ここは〈雑誌〉の意味。雑誌は読むものだが、映画は見るものなので「読む」とは合わないので誤り。"}, {"text": "最近は、配信で映画を聴く人も増えている。", "explanation": "ここは〈音楽〉の意味。音楽は聴くものだが、映画は見るものなので「聴く」とは合わないので誤り。"}, {"text": "最近は、配信で映画を確認する人も増えている。", "explanation": "ここは〈天気予報〉の意味。天気予報は確認するものだが、映画は確認するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37935, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この映画を、子どもたちの間で大きな話題になった。", "corrected_sentence": "この映画が、子どもたちの間で大きな話題になった。", "error_description": "「話題になる」の主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37935, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、昨夜の映画を一人で食べて、すぐに眠ってしまった。", "corrected_sentence": "彼は、昨夜の映画を一人で見て、すぐに眠ってしまった。", "error_description": "「映画」を受ける動詞は「見る」。「食べる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
