INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37936, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "インターネットで、人が情報を出したり、話したりする場所です。", "primary_collocate": null, "pronunciation": "えすえぬえす", "ipa": "esɯenɯesɯ", "syllable_count": 6, "sentences": [{"text": "友だちの写真を、 SNS で見た。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "友[とも]だちの写真[しゃしん]を、 SNS で見[み]た。", "sentence_source": "generated"}, {"text": "姉は毎晩、 SNS に今日のできごとを書いている。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "姉[あね]は毎晩[まいばん]、 SNS に今日[きょう]のできごとを書[か]いている。", "sentence_source": "generated"}, {"text": "SNS では、知らない人とも話すことができる。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "SNS では、知[し]らない人[ひと]とも話[はな]すことができる。", "sentence_source": "generated"}, {"text": "私は旅行の写真を SNS にのせた。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "私[わたし]は旅行[りょこう]の写真[しゃしん]を SNS にのせた。", "sentence_source": "generated"}, {"text": "祖父も SNS を始めて、孫の写真を楽しんでいる。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "祖父[そふ]も SNS を始[はじ]めて、孫[まご]の写真[しゃしん]を楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "SNS を見すぎて、勉強の時間が少なくなった。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "SNS を見[み]すぎて、勉強[べんきょう]の時間[じかん]が少[すく]なくなった。", "sentence_source": "generated"}, {"text": "学校では、 SNS に名前や住所を書かないように教わる。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "学校[がっこう]では、 SNS に名前[なまえ]や住所[じゅうしょ]を書[か]かないように教[おそ]わる。", "sentence_source": "generated"}, {"text": "兄は SNS で、同じ趣味の友だちを見つけた。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "兄[あに]は SNS で、同[おな]じ趣味[しゅみ]の友[とも]だちを見[み]つけた。", "sentence_source": "generated"}, {"text": "夜遅くまで SNS を見ていると、目が疲れる。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "夜[よる]遅[おそ]くまで SNS を見[み]ていると、目[め]が疲[つか]れる。", "sentence_source": "generated"}, {"text": "SNS に書いたことは、世界中の人に見られるかもしれない。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "SNS に書[か]いたことは、世界中[せかいじゅう]の人[ひと]に見[み]られるかもしれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "SNS", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ネット上で写真や言葉を出し、人と話す場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37936, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "SNS", "is_correct": true, "explanation": "「友だちの写真を、SNSで見た」の空所に入る正解。SNSを通じて写真を見たという意味になる。"}, {"text": "友だち", "is_correct": false, "explanation": "「友だちで見た」では人が見る手段になってしまい、意味が通らない。"}, {"text": "手袋", "is_correct": false, "explanation": "「手袋で見た」は身につける物で写真を見たという意味になり、不自然で合わない。"}, {"text": "昨日", "is_correct": false, "explanation": "「昨日で見た」は時間の語を手段として使うことになり、文として成り立たない。"}], "explanations": {"SNS": "「友だちの写真を、SNSで見た」の空所に入る正解。SNSを通じて写真を見たという意味になる。", "友だち": "「友だちで見た」では人が見る手段になってしまい、意味が通らない。", "手袋": "「手袋で見た」は身につける物で写真を見たという意味になり、不自然で合わない。", "昨日": "「昨日で見た」は時間の語を手段として使うことになり、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "SNS"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "SNSを一口食べたら、甘くておいしかった。", "explanation": "ここは〈菓子〉の意味。SNSは食べられるものではないので、菓子を食べる意味では合わない。"}, {"text": "旅行の計画は、SNSで飛行機の予約を済ませた。", "explanation": "ここは〈予約サイト〉の意味。飛行機の予約は予約サイトや旅行会社で行うもので、SNSは予約の窓口ではないので合わない。"}, {"text": "わからない漢字は、SNSで引いて調べた。", "explanation": "ここは〈辞書〉の意味。辞書は言葉を引いて調べるもので、SNSは引く道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37936, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "SNS", "is_correct": true, "explanation": "「学校では、SNSに名前や住所を書かないように教わる」の空所に入る正解。書き込み先としてのSNSを指す。"}, {"text": "天気", "is_correct": false, "explanation": "「天気に名前や住所を書かない」は意味が通らず、書く対象にならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼けに名前を書く」は意味が通らず、文として不自然。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩に名前を書く」は行為の場所にならず、文脈に合わない。"}], "explanations": {"SNS": "「学校では、SNSに名前や住所を書かないように教わる」の空所に入る正解。書き込み先としてのSNSを指す。", "天気": "「天気に名前や住所を書かない」は意味が通らず、書く対象にならない。", "夕焼け": "「夕焼けに名前を書く」は意味が通らず、文として不自然。", "散歩": "「散歩に名前を書く」は行為の場所にならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "SNS"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、SNSを広げて記事を読んでいる。", "explanation": "ここは〈新聞〉の意味。新聞は紙を広げて読むが、SNSは広げて読むものではないので合わない。"}, {"text": "急用があったので、友だちにSNSをかけた。", "explanation": "ここは〈電話〉の意味。電話は相手に「かける」ものだが、SNSは相手にかける道具ではないので合わない。"}, {"text": "撮った写真を、SNSに現像してもらった。", "explanation": "ここは〈写真屋〉の意味。フィルムの写真を店で現像するもので、SNSは現像サービスではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37936, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日の夜、友だちが SNS から 新しい写真をのせた。", "corrected_sentence": "昨日の夜、友だちが SNS に 新しい写真をのせた。", "error_description": "助詞の誤り。写真をのせる先を表す「に」が正しいが、出どころを表す「から」になっている。「SNSに写真をのせる」が自然な形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37936, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は授業の連絡を SNS を 生徒たちに送った。", "corrected_sentence": "先生は授業の連絡を SNS で 生徒たちに送った。", "error_description": "助詞の誤り。手段を表す「で」が正しいが、「を」が二つ重なっている。「連絡を」と「SNSを」が同時に目的語になり不自然。「SNSで連絡を送る」が自然な形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
