INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37937, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ソーシャル・ネットワーキング・サービスの略称で、インターネット上でユーザー同士が交流や情報共有を行うためのプラットフォーム。", "primary_collocate": null, "pronunciation": "えすえぬえす", "ipa": "esɯenɯesɯ", "syllable_count": 6, "sentences": [{"text": "企業は、 SNS を使って新商品の情報を広めている。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "企業[きぎょう]は、 SNS を使[つか]って新商品[しんしょうひん]の情報[じょうほう]を広[ひろ]めている。", "sentence_source": "generated"}, {"text": "SNS の普及で、人々の交流の方法が大きく変わった。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "SNS の普及[ふきゅう]で、人々[ひとびと]の交流[こうりゅう]の方法[ほうほう]が大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "災害時には、 SNS で被害の情報が共有されることもある。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "災害時[さいがいじ]には、 SNS で被害[ひがい]の情報[じょうほう]が共有[きょうゆう]されることもある。", "sentence_source": "generated"}, {"text": "この会社では、 SNS の運用を専門のチームが担当している。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]では、 SNS の運用[うんよう]を専門[せんもん]のチームが担当[たんとう]している。", "sentence_source": "generated"}, {"text": "SNS で誤った情報が広がり、店が迷惑を受けた。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "SNS で誤[あやま]った情報[じょうほう]が広[ひろ]がり、店[みせ]が迷惑[めいわく]を受[う]けた。", "sentence_source": "generated"}, {"text": "利用者同士が気軽に交流できる SNS が人気を集めている。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "利用者[りようしゃ]同士[どうし]が気軽[きがる]に交流[こうりゅう]できる SNS が人気[にんき]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "彼女は SNS のフォロワーが百万人を超える有名人だ。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は SNS のフォロワーが百万人[ひゃくまんにん]を超[こ]える有名人[ゆうめいじん]だ。", "sentence_source": "generated"}, {"text": "就職活動では、 SNS の使い方に注意するべきだ。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "就職[しゅうしょく]活動[かつどう]では、 SNS の使[つか]い方[かた]に注意[ちゅうい]するべきだ。", "sentence_source": "generated"}, {"text": "新しい SNS が登場し、若者の間で急に流行った。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "新[あたら]しい SNS が登場[とうじょう]し、若者[わかもの]の間[あいだ]で急[きゅう]に流行[はや]った。", "sentence_source": "generated"}, {"text": "政府は、 SNS を通じて国民に情報を発信している。", "target_word": "SNS", "complexity_tier": "T3", "furigana": "政府[せいふ]は、 SNS を通[つう]じて国民[こくみん]に情報[じょうほう]を発信[はっしん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "SNS", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ユーザー同士の交流や情報共有のためのネット上のサービス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37937, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "SNS", "is_correct": true, "explanation": "「企業は、SNSを使って新商品の情報を広めている」の空所に入る正解。情報を広める手段のサービスを指す。"}, {"text": "悲しみ", "is_correct": false, "explanation": "「悲しみを使って」は気持ちを道具として使うことになり、意味が通らない。"}, {"text": "深呼吸", "is_correct": false, "explanation": "「深呼吸を使って」は行為を道具として使うことになり、情報を広める手段にならない。"}, {"text": "友情", "is_correct": false, "explanation": "「友情を使って」は抽象的な感情を手段にしており、情報を広める方法として合わない。"}], "explanations": {"SNS": "「企業は、SNSを使って新商品の情報を広めている」の空所に入る正解。情報を広める手段のサービスを指す。", "悲しみ": "「悲しみを使って」は気持ちを道具として使うことになり、意味が通らない。", "深呼吸": "「深呼吸を使って」は行為を道具として使うことになり、情報を広める手段にならない。", "友情": "「友情を使って」は抽象的な感情を手段にしており、情報を広める方法として合わない。"}, "sentence_index": 0, "correct_answer": "SNS"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新商品の部品を、SNSで作っている。", "explanation": "ここは〈工場〉の意味。部品を作るのは工場で、SNSは物を作る場所ではないので合わない。"}, {"text": "熱が出たので、SNSで注射を受けた。", "explanation": "ここは〈病院〉の意味。注射を受けるのは病院で、SNSは医療を受ける場所ではないので合わない。"}, {"text": "給料を、SNSで下ろした。", "explanation": "ここは〈銀行〉の意味。お金を下ろすのは銀行で、SNSはお金を下ろす場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37937, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "SNS", "is_correct": true, "explanation": "「彼女はSNSのフォロワーが百万人を超える有名人だ」の空所に入る正解。SNSのフォロワーという意味になる。"}, {"text": "天井", "is_correct": false, "explanation": "「天井のフォロワー」は意味が通らず、フォロワーを持つ対象にならない。"}, {"text": "給料", "is_correct": false, "explanation": "「給料のフォロワー」は意味が通らず、フォロワーの対象として合わない。"}, {"text": "湖", "is_correct": false, "explanation": "「湖のフォロワー」は意味が通らず、フォロワーを持つ対象として合わない。"}], "explanations": {"SNS": "「彼女はSNSのフォロワーが百万人を超える有名人だ」の空所に入る正解。SNSのフォロワーという意味になる。", "天井": "「天井のフォロワー」は意味が通らず、フォロワーを持つ対象にならない。", "給料": "「給料のフォロワー」は意味が通らず、フォロワーの対象として合わない。", "湖": "「湖のフォロワー」は意味が通らず、フォロワーを持つ対象として合わない。"}, "sentence_index": 6, "correct_answer": "SNS"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来客に、SNSを入れた。", "explanation": "ここは〈お茶〉の意味。お茶は「入れる」ものだが、SNSは入れる飲み物ではないので合わない。"}, {"text": "出かける前に、SNSを履いた。", "explanation": "ここは〈靴〉の意味。靴は「履く」ものだが、SNSは身につける物ではないので合わない。"}, {"text": "毎週、SNSで本を借りている。", "explanation": "ここは〈図書館〉の意味。本を借りるのは図書館などで、SNSは本を貸す場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37937, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は SNS を 新しい客を集めた。", "corrected_sentence": "店は SNS で 新しい客を集めた。", "error_description": "助詞の誤り。手段を表す「で」が正しいが、「を」になっている。「を」を付けると「SNSを新しい客」と目的語が二つになり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37937, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店は SNS を 使いに 新商品を紹介した。", "corrected_sentence": "店は SNS を 使って 新商品を紹介した。", "error_description": "活用の誤り。「SNSを」に続く連用形「使って」が正しいが、「使いに」になっている。「SNSを使って紹介する」が自然な形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37938, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「聞く」の目的語を示す「を」。患者が話す話を聞いたという文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手を表す。ナラティブは聞く相手ではないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。ナラティブは聞かれる対象で、主語にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。ナラティブは向かう先ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「聞く」の目的語を示す「を」。患者が話す話を聞いたという文に合う。", "に": "「に」は相手を表す。ナラティブは聞く相手ではないので合わない。", "が": "「が」は主語を示す。ナラティブは聞かれる対象で、主語にはならないので合わない。", "へ": "「へ」は方向を表す。ナラティブは向かう先ではないので合わない。"}, "error_tags": {"に": "相手", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37938, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「聞く」の目的語を示す「を」。友だちのナラティブを聞くという文に合う。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。ナラティブを比べる文脈ではないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。後に動詞の「聞いて」が続くので、目的語にはならず合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並べたり引用したりする。ここでは「聞く」の対象を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「聞く」の目的語を示す「を」。友だちのナラティブを聞くという文に合う。", "より": "「より」は比較を表す。ナラティブを比べる文脈ではないので合わない。", "の": "「の」は名詞をつなぐ。後に動詞の「聞いて」が続くので、目的語にはならず合わない。", "と": "「と」は並べたり引用したりする。ここでは「聞く」の対象を示せず、文が成り立たない。"}, "error_tags": {"より": "比較", "の": "所有", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37938, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これは、誰かが話したり書いたりするお話のことです。", "primary_collocate": null, "pronunciation": "ならてぃぶ", "ipa": "naɾatibɯ", "syllable_count": 4, "sentences": [{"text": "祖母が語るナラティブには、戦争の記憶が深く残っている。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "祖母[そぼ]が語[かた]るナラティブには、戦争[せんそう]の記憶[きおく]が深[ふか]く残[のこ]っている。", "sentence_source": "generated"}, {"text": "医者は、患者が話すナラティブをていねいに聞いた。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、患者[かんじゃ]が話[はな]すナラティブをていねいに聞[き]いた。", "sentence_source": "generated"}, {"text": "彼は旅で見たことを、短いナラティブに書いた。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "彼[かれ]は旅[たび]で見[み]たことを、短[みじか]いナラティブに書[か]いた。", "sentence_source": "generated"}, {"text": "先生は生徒に、自分の家族についてのナラティブを書かせた。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、自分[じぶん]の家族[かぞく]についてのナラティブを書[か]かせた。", "sentence_source": "generated"}, {"text": "老人のナラティブは長いが、聞く人を飽きさせない。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "老人[ろうじん]のナラティブは長[なが]いが、聞[き]く人[ひと]を飽[あ]きさせない。", "sentence_source": "generated"}, {"text": "同じ事件でも、人によってナラティブが違うことがある。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "同[おな]じ事件[じけん]でも、人[ひと]によってナラティブが違[ちが]うことがある。", "sentence_source": "generated"}, {"text": "母は、子どもの成長を記録したナラティブをブログに載せている。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "母[はは]は、子[こ]どもの成長[せいちょう]を記録[きろく]したナラティブをブログに載[の]せている。", "sentence_source": "generated"}, {"text": "この授業では、友だちのナラティブを聞いて感想を言う。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]では、友[とも]だちのナラティブを聞[き]いて感想[かんそう]を言[い]う。", "sentence_source": "generated"}, {"text": "難民の少年が語ったナラティブは、多くの人の心を動かした。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "難民[なんみん]の少年[しょうねん]が語[かた]ったナラティブは、多[おお]くの人[ひと]の心[こころ]を動[うご]かした。", "sentence_source": "generated"}, {"text": "彼女のナラティブは最初の一行から読者をひきつけた。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のナラティブは最初[さいしょ]の一行[いちぎょう]から読者[どくしゃ]をひきつけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ナラティブ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が話したり書いたりして語る、個人の体験や出来事のお話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37938, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ナラティブ", "is_correct": true, "explanation": "「語る」の対象になり、祖母が話す体験の語りを表す。文の意味に合う。"}, {"text": "計算", "is_correct": false, "explanation": "「語る」は話や物語を目的語にとる。計算は語るものではないので合わない。"}, {"text": "数式", "is_correct": false, "explanation": "「語る数式」は文として成り立たない。数式は語られる話ではない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は語るものではなく、戦争の記憶を語るという文脈に合わない。"}], "explanations": {"ナラティブ": "「語る」の対象になり、祖母が話す体験の語りを表す。文の意味に合う。", "計算": "「語る」は話や物語を目的語にとる。計算は語るものではないので合わない。", "数式": "「語る数式」は文として成り立たない。数式は語られる話ではない。", "時刻表": "時刻表は語るものではなく、戦争の記憶を語るという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ナラティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この実験のナラティブは、三回とも同じ結果を示した。", "explanation": "ここは〈記録〉の意味。ナラティブは人に語られる話のことで、実験の経過や数値の記録は指さないので合わない。"}, {"text": "その写真は、裁判で有力なナラティブとして採用された。", "explanation": "ここは〈証拠〉の意味。ナラティブは語られる話で、裁判で事実を示す証拠の意味では使わないので合わない。"}, {"text": "この料理のナラティブは、材料と手順が詳しく書かれている。", "explanation": "ここは〈レシピ〉の意味。材料と手順を書いた作り方はナラティブとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37938, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ナラティブ", "is_correct": true, "explanation": "「記録した」の対象になり、子どもの成長を語る話を指す。ブログに載せる内容としても合う。"}, {"text": "眠気", "is_correct": false, "explanation": "「記録した眠気」は文の意味が通らない。ブログに載せる成長の記録にもならない。"}, {"text": "夕立", "is_correct": false, "explanation": "「記録した夕立」は成長の記録にならず、ブログに載せる内容としても意味が通らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「記録した砂糖」は成長の記録として合わない。"}], "explanations": {"ナラティブ": "「記録した」の対象になり、子どもの成長を語る話を指す。ブログに載せる内容としても合う。", "眠気": "「記録した眠気」は文の意味が通らない。ブログに載せる成長の記録にもならない。", "夕立": "「記録した夕立」は成長の記録にならず、ブログに載せる内容としても意味が通らない。", "砂糖": "「記録した砂糖」は成長の記録として合わない。"}, "sentence_index": 6, "correct_answer": "ナラティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このナラティブは、店の場所を矢印で示している。", "explanation": "ここは〈看板〉の意味。ナラティブは語られる話で、場所を矢印で示す案内ではないので合わない。"}, {"text": "このナラティブは、売上の変化を表で整理している。", "explanation": "ここは〈報告書〉の意味。ナラティブは語りの話で、数値を表にまとめた資料ではないので合わない。"}, {"text": "このナラティブは、持ち主の名前がはっきり書かれている。", "explanation": "ここは〈名札〉の意味。ナラティブは人に語られる話で、名前を書いて持ち主を示す札ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37938, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、戦地での体験を長いナラティブに語ってくれた。", "corrected_sentence": "祖父は、戦地での体験を長いナラティブで語ってくれた。", "error_description": "「語る」で話の形式を示すときは「で」を使う。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37938, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作家は、主人公の過去を少しずつ明かすナラティブを食べて、読者を引きつけた。", "corrected_sentence": "作家は、主人公の過去を少しずつ明かすナラティブを書いて、読者を引きつけた。", "error_description": "「ナラティブ」を作る動詞は「書く」。「食べる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37939, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「説明する」の手段を示す「で」。ナラティブという語り口で政策を伝えた、という意味に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。ナラティブは向かう先ではないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「政策を」がすでにあり、「を」を続けると目的語が二つになって文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を表す。ナラティブは説明の相手でも場所でもないので合わない。"}], "correct_answer": "で", "explanations": {"で": "「説明する」の手段を示す「で」。ナラティブという語り口で政策を伝えた、という意味に合う。", "へ": "「へ」は方向を表す。ナラティブは向かう先ではないので合わない。", "を": "「政策を」がすでにあり、「を」を続けると目的語が二つになって文が成り立たない。", "に": "「に」は相手や場所を表す。ナラティブは説明の相手でも場所でもないので合わない。"}, "error_tags": {"へ": "方向", "を": "対象", "に": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37939, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37939, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際にあったことのように語られる物語や、語り手の視点を通して表現される話のことを指します。", "primary_collocate": null, "pronunciation": "ならてぃぶ", "ipa": "naɾatibɯ", "syllable_count": 4, "sentences": [{"text": "この小説は、語り手の視点で進むナラティブが魅力だ。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、語[かた]り手[て]の視点[してん]で進[すす]むナラティブが魅力[みりょく]だ。", "sentence_source": "generated"}, {"text": "政治家は、国民に分かりやすいナラティブで政策を説明した。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "政治家[せいじか]は、国民[こくみん]に分[わ]かりやすいナラティブで政策[せいさく]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "事実に見えても、報道はひとつのナラティブにすぎない。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "事実[じじつ]に見[み]えても、報道[ほうどう]はひとつのナラティブにすぎない。", "sentence_source": "generated"}, {"text": "ゲームは、プレイヤーが選ぶことでナラティブが変わる。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "ゲームは、プレイヤーが選[えら]ぶことでナラティブが変[か]わる。", "sentence_source": "generated"}, {"text": "歴史は勝った側のナラティブで語られることが多い。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "歴史[れきし]は勝[か]った側[がわ]のナラティブで語[かた]られることが多[おお]い。", "sentence_source": "generated"}, {"text": "彼女は自分の失敗を、成長のナラティブに変えて話した。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の失敗[しっぱい]を、成長[せいちょう]のナラティブに変[か]えて話[はな]した。", "sentence_source": "generated"}, {"text": "創業者のナラティブは、会社の印象を作る。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "創業者[そうぎょうしゃ]のナラティブは、会社[かいしゃ]の印象[いんしょう]を作[つく]る。", "sentence_source": "generated"}, {"text": "同じ出来事でも、語り手が変わればナラティブも変わる。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "同[おな]じ出来事[できごと]でも、語[かた]り手[て]が変[か]わればナラティブも変[か]わる。", "sentence_source": "generated"}, {"text": "このドキュメンタリーは、現地の人々のナラティブを丁寧に伝えている。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "このドキュメンタリーは、現地[げんち]の人々[ひとびと]のナラティブを丁寧[ていねい]に伝[つた]えている。", "sentence_source": "generated"}, {"text": "広告は商品より、客が共感できるナラティブを売っている。", "target_word": "ナラティブ", "complexity_tier": "T3", "furigana": "広告[こうこく]は商品[しょうひん]より、客[きゃく]が共感[きょうかん]できるナラティブを売[う]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ナラティブ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "語り手の視点で組み立てられ、実際の出来事のように語られる物語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37939, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ナラティブ", "is_correct": true, "explanation": "「進む」の主語になり、語り手の視点で展開される話を指す。文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「語り手の視点で進む天気」は文が成り立たない。天気は話の展開を表さない。"}, {"text": "料金", "is_correct": false, "explanation": "「進む料金」は話の展開を表さず、小説の魅力を述べる文に合わない。"}, {"text": "表紙", "is_correct": false, "explanation": "「進む表紙」は意味が通らない。表紙は小説の展開を表すものではない。"}], "explanations": {"ナラティブ": "「進む」の主語になり、語り手の視点で展開される話を指す。文の意味に合う。", "天気": "「語り手の視点で進む天気」は文が成り立たない。天気は話の展開を表さない。", "料金": "「進む料金」は話の展開を表さず、小説の魅力を述べる文に合わない。", "表紙": "「進む表紙」は意味が通らない。表紙は小説の展開を表すものではない。"}, "sentence_index": 0, "correct_answer": "ナラティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このゲームのナラティブは、勝つための規則を定めている。", "explanation": "ここは〈ルール〉の意味。ナラティブは語られる話で、勝ち方を決める規則のことではないので合わない。"}, {"text": "このゲームのナラティブは、ボタン一つで動く仕組みになっている。", "explanation": "ここは〈仕組み〉の意味。ナラティブは語りの話で、機械やゲームを動かす仕組みの意味では使わないので合わない。"}, {"text": "このゲームのナラティブは、コントローラーの操作方法を説明している。", "explanation": "ここは〈操作方法〉の意味。ナラティブは語られる話で、ボタンの使い方を説明するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37939, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ナラティブ", "is_correct": true, "explanation": "創業者が語る物語を指し、会社の印象を作るという文に合う。"}, {"text": "落ち葉", "is_correct": false, "explanation": "「落ち葉」は会社の印象を作るものではなく、主語として文が成り立たない。"}, {"text": "雑草", "is_correct": false, "explanation": "「雑草は会社の印象を作る」は意味が通らず、主語として合わない。"}, {"text": "座席", "is_correct": false, "explanation": "座席は会社の印象を作る話題ではなく、主語として不自然。"}], "explanations": {"ナラティブ": "創業者が語る物語を指し、会社の印象を作るという文に合う。", "落ち葉": "「落ち葉」は会社の印象を作るものではなく、主語として文が成り立たない。", "雑草": "「雑草は会社の印象を作る」は意味が通らず、主語として合わない。", "座席": "座席は会社の印象を作る話題ではなく、主語として不自然。"}, "sentence_index": 6, "correct_answer": "ナラティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店では、ナラティブで代金を払える。", "explanation": "ここは〈電子マネー〉の意味。ナラティブは語りの話で、代金を払うための金銭的な価値を持つものではないので合わない。"}, {"text": "このナラティブは、持ち主の名前がはっきり書かれている。", "explanation": "ここは〈名札〉の意味。ナラティブは人に語られる話で、名前を書いて持ち主を示す札ではないので合わない。"}, {"text": "このナラティブは、有効期限が三日間です。", "explanation": "ここは〈切符〉の意味。ナラティブは語りの話で、有効期限のある券ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37939, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この映画は、主人公の視点で語られるナラティブを印象的だ。", "corrected_sentence": "この映画は、主人公の視点で語られるナラティブが印象的だ。", "error_description": "「印象的だ」の主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37939, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、家族の歴史を一つのナラティブに切った。", "corrected_sentence": "彼は、家族の歴史を一つのナラティブにまとめた。", "error_description": "話や歴史を一つにまとめる動詞は「まとめる」。「切る」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
