INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37940, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "同じように。", "primary_collocate": null, "pronunciation": "どうよう", "ipa": "doːjoː", "syllable_count": 2, "sentences": [{"text": "私も兄と同様に、朝早く起きて走っています。", "target_word": "同様", "complexity_tier": "T3", "furigana": "私(わたし)も兄(あに)と同様(どうよう)に、朝(あさ)早(はや)く起(お)きて走(はし)っています。", "sentence_source": "generated"}, {"text": "この店では、日本人も外国人も同様に扱われます。", "target_word": "同様", "complexity_tier": "T3", "furigana": "この店(みせ)では、日本人(にほんじん)も外国人(がいこくじん)も同様(どうよう)に扱(あつか)われます。", "sentence_source": "generated"}, {"text": "先月と同様に、今月も雨の日が多いです。", "target_word": "同様", "complexity_tier": "T3", "furigana": "先月(せんげつ)と同様(どうよう)に、今月(こんげつ)も雨(あめ)の日(ひ)が多(おお)いです。", "sentence_source": "generated"}, {"text": "田中さんは先生と同様に、いつも丁寧に話します。", "target_word": "同様", "complexity_tier": "T3", "furigana": "田中(たなか)さんは先生(せんせい)と同様(どうよう)に、いつも丁寧(ていねい)に話(はな)します。", "sentence_source": "generated"}, {"text": "子どもたちも大人と同様に、ルールを守らなければなりません。", "target_word": "同様", "complexity_tier": "T3", "furigana": "子(こ)どもたちも大人(おとな)と同様(どうよう)に、ルールを守(まも)らなければなりません。", "sentence_source": "generated"}, {"text": "昨日の会議と同様に、今日も意見が分かれました。", "target_word": "同様", "complexity_tier": "T3", "furigana": "昨日(きのう)の会議(かいぎ)と同様(どうよう)に、今日(きょう)も意見(いけん)が分(わ)かれました。", "sentence_source": "generated"}, {"text": "姉は母と同様に、料理がとても上手です。", "target_word": "同様", "complexity_tier": "T3", "furigana": "姉(あね)は母(はは)と同様(どうよう)に、料理(りょうり)がとても上手(じょうず)です。", "sentence_source": "generated"}, {"text": "犬も人間と同様に毎日散歩する。", "target_word": "同様", "complexity_tier": "T3", "furigana": "犬(いぬ)も人間(にんげん)と同様(どうよう)に毎日(まいにち)散歩(さんぽ)する。", "sentence_source": "generated"}, {"text": "北の町でも、南の町と同様に、雪が降りました。", "target_word": "同様", "complexity_tier": "T3", "furigana": "北(きた)の町(まち)でも、南(みなみ)の町(まち)と同様(どうよう)に、雪(ゆき)が降(ふ)りました。", "sentence_source": "generated"}, {"text": "去年と同様に、今年も夏祭りに行くつもりです。", "target_word": "同様", "complexity_tier": "T3", "furigana": "去年(きょねん)と同様(どうよう)に、今年(ことし)も夏祭(なつまつ)りに行(い)くつもりです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "同様だ", "label": "断定形"}, {"form": "同様に", "label": "連用形"}, {"form": "同様の", "label": "連体形"}, {"form": "同様で", "label": "中止形"}], "register": "neutral", "sense_fingerprint": "同様に: 別のものと同じやり方・同じ状態で（副詞的に使う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37940, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同様", "is_correct": true, "explanation": "「私も兄と同様に、朝早く起きて走っています」の空所に入る正解。兄と同じように、という意味になる。"}, {"text": "乱暴", "is_correct": false, "explanation": "「兄と乱暴に」では、兄との比較として意味が通らない。"}, {"text": "便利", "is_correct": false, "explanation": "「兄と便利に」は比較の意味にならず、朝早く起きる様子と合わない。"}, {"text": "大胆", "is_correct": false, "explanation": "「兄と大胆に」は兄との比較として意味が通らず、文脈に合わない。"}], "explanations": {"同様": "「私も兄と同様に、朝早く起きて走っています」の空所に入る正解。兄と同じように、という意味になる。", "乱暴": "「兄と乱暴に」では、兄との比較として意味が通らない。", "便利": "「兄と便利に」は比較の意味にならず、朝早く起きる様子と合わない。", "大胆": "「兄と大胆に」は兄との比較として意味が通らず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "同様"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同様と一緒に昼ご飯を食べた。", "explanation": "ここは〈同僚〉の意味。同僚は人を指すが、同様は人を表さないので合わない。"}, {"text": "祖父は同様を読んでいる。", "explanation": "ここは〈本〉の意味。本は読むものだが、同様は読めるものではないので合わない。"}, {"text": "リンゴを同様三つ買った。", "explanation": "ここは〈個〉の意味。同様は数を数える言葉ではないので、数量の後には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37940, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同様", "is_correct": true, "explanation": "「姉は母と同様に、料理がとても上手です」の空所に入る正解。母と同じように、という意味になる。"}, {"text": "鮮明", "is_correct": false, "explanation": "「母と鮮明に」は比較として意味が通らず、料理の上手さと合わない。"}, {"text": "豪快", "is_correct": false, "explanation": "「母と豪快に」は比較の意味にならず、料理が上手という文脈に合わない。"}, {"text": "無謀", "is_correct": false, "explanation": "「母と無謀に」は意味が通らず、料理が上手という文と合わない。"}], "explanations": {"同様": "「姉は母と同様に、料理がとても上手です」の空所に入る正解。母と同じように、という意味になる。", "鮮明": "「母と鮮明に」は比較として意味が通らず、料理の上手さと合わない。", "豪快": "「母と豪快に」は比較の意味にならず、料理が上手という文脈に合わない。", "無謀": "「母と無謀に」は意味が通らず、料理が上手という文と合わない。"}, "sentence_index": 6, "correct_answer": "同様"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公園の同様で、子どもたちが遊んでいた。", "explanation": "ここは〈広場〉の意味。子どもが遊ぶ場所を指すが、同様は場所を表さないので合わない。"}, {"text": "試合は五対五の同様で終わった。", "explanation": "ここは〈同点〉の意味。得点が等しいことは同点と言い、同様は似た様子を表すので合わない。"}, {"text": "明日の同様は晴れだと予報されている。", "explanation": "ここは〈天気〉の意味。天気の予報には天気を使い、同様は天気を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37940, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は父と同様の、毎日ジョギングしています。", "corrected_sentence": "私は父と同様に、毎日ジョギングしています。", "error_description": "活用の誤り。後ろの動詞を修飾する連用形「同様に」が正しいが、連体形「同様の」になっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "同様に", "is_correct": true, "explanation": "「同様に扱われます」と後ろの動詞を修飾する連用形で、正解。"}, {"text": "同様の", "is_correct": false, "explanation": "連体形のため名詞を修飾する形で、「扱われます」の直前には使えない。"}, {"text": "同様で", "is_correct": false, "explanation": "中止形のため、動詞を修飾する形にはならず、文が成り立たない。"}, {"text": "同様だ", "is_correct": false, "explanation": "断定形のため、動詞を修飾できず、「扱われます」に続かない。"}], "correct_form": "同様に", "base_form": "同様", "form_label": "連用形", "sentence_index": 1, "explanations": {"同様に": "「同様に扱われます」と後ろの動詞を修飾する連用形で、正解。", "同様の": "連体形のため名詞を修飾する形で、「扱われます」の直前には使えない。", "同様で": "中止形のため、動詞を修飾する形にはならず、文が成り立たない。", "同様だ": "断定形のため、動詞を修飾できず、「扱われます」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37940, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月と同様を、今月も雨が続いた。", "corrected_sentence": "先月と同様に、今月も雨が続いた。", "error_description": "助詞の誤り。形状詞「同様」には「を」は付かず、副詞として「同様に」の「に」が正しい。「先月と同様に」が自然な形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "同様に", "is_correct": true, "explanation": "「人間と同様に毎日散歩する」と後ろの動詞を修飾する連用形で、正解。"}, {"text": "同様です", "is_correct": false, "explanation": "述語で終わるため、後ろの動詞「散歩する」に直接つながらず文が崩れる。"}, {"text": "同様な", "is_correct": false, "explanation": "連体形のため名詞を修飾し、動詞の前には置けない。"}, {"text": "同様であった", "is_correct": false, "explanation": "過去の述語形のため、動詞を修飾できず文が成り立たない。"}], "correct_form": "同様に", "base_form": "同様", "form_label": "連用形", "sentence_index": 7, "explanations": {"同様に": "「人間と同様に毎日散歩する」と後ろの動詞を修飾する連用形で、正解。", "同様です": "述語で終わるため、後ろの動詞「散歩する」に直接つながらず文が崩れる。", "同様な": "連体形のため名詞を修飾し、動詞の前には置けない。", "同様であった": "過去の述語形のため、動詞を修飾できず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
