INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37941, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "あるものと別のものが、状態ややり方において同じであることを示す言葉。", "primary_collocate": null, "pronunciation": "どうよう", "ipa": "doːjoː", "syllable_count": 2, "sentences": [{"text": "この問題は、前の問題と同様の方法で解けます。", "target_word": "同様", "complexity_tier": "T3", "furigana": "この問題(もんだい)は、前(まえ)の問題(もんだい)と同様(どうよう)の方法(ほうほう)で解(と)けます。", "sentence_source": "generated"}, {"text": "新しい家の広さは、前の家とほぼ同様です。", "target_word": "同様", "complexity_tier": "T3", "furigana": "新(あたら)しい家(いえ)の広(ひろ)さは、前(まえ)の家(いえ)とほぼ同様(どうよう)です。", "sentence_source": "generated"}, {"text": "彼の失敗は、私の失敗と同様のものでした。", "target_word": "同様", "complexity_tier": "T3", "furigana": "彼(かれ)の失敗(しっぱい)は、私(わたし)の失敗(しっぱい)と同様(どうよう)のものでした。", "sentence_source": "generated"}, {"text": "中古品でも、使えるなら新品と同様だと思います。", "target_word": "同様", "complexity_tier": "T3", "furigana": "中古品(ちゅうこひん)でも、使(つか)えるなら新品(しんぴん)と同様(どうよう)だと思(おも)います。", "sentence_source": "generated"}, {"text": "今回の事故も、三年前の事故と同様の原因で起きた。", "target_word": "同様", "complexity_tier": "T3", "furigana": "今回(こんかい)の事故(じこ)も、三年前(さんねんまえ)の事故(じこ)と同様(どうよう)の原因(げんいん)で起(お)きた。", "sentence_source": "generated"}, {"text": "約束を忘れたのは、約束を破ったのと同様である。", "target_word": "同様", "complexity_tier": "T3", "furigana": "約束(やくそく)を忘(わす)れたのは、約束(やくそく)を破(やぶ)ったのと同様(どうよう)である。", "sentence_source": "generated"}, {"text": "駅前の店は、どこも同様の値段で売っている。", "target_word": "同様", "complexity_tier": "T3", "furigana": "駅前(えきまえ)の店(みせ)は、どこも同様(どうよう)の値段(ねだん)で売(う)っている。", "sentence_source": "generated"}, {"text": "手紙の返事が来ないのは、断られたのと同様だ。", "target_word": "同様", "complexity_tier": "T3", "furigana": "手紙(てがみ)の返事(へんじ)が来(こ)ないのは、断(ことわ)られたのと同様(どうよう)だ。", "sentence_source": "generated"}, {"text": "結果は予想と同様で、私たちのチームが勝った。", "target_word": "同様", "complexity_tier": "T3", "furigana": "結果(けっか)は予想(よそう)と同様(どうよう)で、私(わたし)たちのチームが勝(か)った。", "sentence_source": "generated"}, {"text": "この薬は、あの薬と同様の効果があります。", "target_word": "同様", "complexity_tier": "T3", "furigana": "この薬(くすり)は、あの薬(くすり)と同様(どうよう)の効果(こうか)があります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "同様だ", "label": "断定形"}, {"form": "同様の", "label": "連体形"}, {"form": "同様で", "label": "中止形"}, {"form": "同様です", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "同様だ・同様の: AとBの状態ややり方が同じである（述語・連体修飾で使う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37941, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同様", "is_correct": true, "explanation": "「この問題は、前の問題と同様の方法で解けます」の空所に入る正解。前の問題と同じ、という意味になる。"}, {"text": "陽気", "is_correct": false, "explanation": "「前の問題と陽気の方法」は意味が通らず、比べる状態として合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "「前の問題と頑丈の方法」は意味が通らず、解き方の比較として合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "「前の問題と清潔の方法」は意味が通らず、解き方の比較として合わない。"}], "explanations": {"同様": "「この問題は、前の問題と同様の方法で解けます」の空所に入る正解。前の問題と同じ、という意味になる。", "陽気": "「前の問題と陽気の方法」は意味が通らず、比べる状態として合わない。", "頑丈": "「前の問題と頑丈の方法」は意味が通らず、解き方の比較として合わない。", "清潔": "「前の問題と清潔の方法」は意味が通らず、解き方の比較として合わない。"}, "sentence_index": 0, "correct_answer": "同様"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お腹が空いたので、同様を食べた。", "explanation": "ここは〈ケーキ〉の意味。ケーキは食べるものだが、同様は食べ物ではないので合わない。"}, {"text": "部屋が寒いので、同様を閉めた。", "explanation": "ここは〈窓〉の意味。窓は閉めるものだが、同様は物ではないので合わない。"}, {"text": "明日の同様は悪いらしい。", "explanation": "ここは〈天気〉の意味。天気は悪いと言えるが、同様は天気を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37941, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同様", "is_correct": true, "explanation": "「どこも同様の値段で売っている」の空所に入る正解。どこも同じ値段、という意味になる。"}, {"text": "静か", "is_correct": false, "explanation": "「どこも静かの値段」は意味が通らず、値段を表す語として合わない。"}, {"text": "堂々", "is_correct": false, "explanation": "「どこも堂々の値段」は意味が通らず、値段を比べる表現として合わない。"}, {"text": "健全", "is_correct": false, "explanation": "「どこも健全の値段」は意味が通らず、値段の状態として合わない。"}], "explanations": {"同様": "「どこも同様の値段で売っている」の空所に入る正解。どこも同じ値段、という意味になる。", "静か": "「どこも静かの値段」は意味が通らず、値段を表す語として合わない。", "堂々": "「どこも堂々の値段」は意味が通らず、値段を比べる表現として合わない。", "健全": "「どこも健全の値段」は意味が通らず、値段の状態として合わない。"}, "sentence_index": 6, "correct_answer": "同様"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の同様の上に本を置いた。", "explanation": "ここは〈棚〉の意味。本を置く場所は棚などで、同様は場所を表さないので合わない。"}, {"text": "彼は同様が速い。", "explanation": "ここは〈足〉の意味。足が速いと言うが、同様は体の部分を表さないので合わない。"}, {"text": "同様になると寒くなる。", "explanation": "ここは〈夜〉の意味。夜になると寒くなると言うが、同様は時間を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37941, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の資料は、前回と同様に形式で作成した。", "corrected_sentence": "会議の資料は、前回と同様の形式で作成した。", "error_description": "活用の誤り。後ろの名詞「形式」を修飾する連体形「同様の」が正しいが、連用形「同様に」になっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "同様です", "is_correct": true, "explanation": "「ほぼ同様です」と文末で述語になる丁寧形で、正解。"}, {"text": "同様の", "is_correct": false, "explanation": "連体形のため、文末の述語にはならない。"}, {"text": "同様で", "is_correct": false, "explanation": "中止形のため、文末に置くと文が途中で終わって成り立たない。"}, {"text": "同様なら", "is_correct": false, "explanation": "仮定の形のため、「広さは同様です」という事実を述べる文と合わない。"}], "correct_form": "同様です", "base_form": "同様", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"同様です": "「ほぼ同様です」と文末で述語になる丁寧形で、正解。", "同様の": "連体形のため、文末の述語にはならない。", "同様で": "中止形のため、文末に置くと文が途中で終わって成り立たない。", "同様なら": "仮定の形のため、「広さは同様です」という事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37941, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は、旧型と同様性能を持つ。", "corrected_sentence": "この機械は、旧型と同様の性能を持つ。", "error_description": "助詞の誤り。後ろの名詞「性能」を修飾する「の」が抜けている。「同様の性能」として名詞を修飾する形が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "同様だ", "is_correct": true, "explanation": "「断られたのと同様だ」と文末で述語になる断定形で、正解。"}, {"text": "同様なら", "is_correct": false, "explanation": "仮定の形のため、文末に置くと条件だけで文が途切れ、成り立たない。"}, {"text": "同様に", "is_correct": false, "explanation": "連用形のため、文末の述語にはならず、文が成り立たない。"}, {"text": "同様であった", "is_correct": false, "explanation": "過去の形のため、現在の状況を述べる文と時制が合わない。"}], "correct_form": "同様だ", "base_form": "同様", "form_label": "断定形", "sentence_index": 7, "explanations": {"同様だ": "「断られたのと同様だ」と文末で述語になる断定形で、正解。", "同様なら": "仮定の形のため、文末に置くと条件だけで文が途切れ、成り立たない。", "同様に": "連用形のため、文末の述語にはならず、文が成り立たない。", "同様であった": "過去の形のため、現在の状況を述べる文と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37942, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「防ぐ」の目的語として「伝播を」を取る。「伝播を防ぐ」で目的語の関係が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「防ぐ」の主語は手を洗うなど人の行為なので、伝播を主語にすると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「防ぐ」は相手に向かう動詞ではないので、伝播に向かう「に」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示すが、伝播と防ぐという組み合わせは成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「防ぐ」の目的語として「伝播を」を取る。「伝播を防ぐ」で目的語の関係が成り立つ。", "が": "「防ぐ」の主語は手を洗うなど人の行為なので、伝播を主語にすると文が成り立たない。", "に": "「防ぐ」は相手に向かう動詞ではないので、伝播に向かう「に」は合わない。", "と": "「と」は共同の相手を示すが、伝播と防ぐという組み合わせは成り立たない。"}, "error_tags": {"が": "主語", "に": "相手", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37942, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "伝播を話題として示し、「止めるのが難しい」と続けて評判の広がりを述べる文になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すが、伝播に止めるという関係にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すが、伝播と止めるが結びつく文にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、伝播を出発点として止めるという意味にはならない。"}], "correct_answer": "は", "explanations": {"は": "伝播を話題として示し、「止めるのが難しい」と続けて評判の広がりを述べる文になる。", "に": "「に」は相手や方向を示すが、伝播に止めるという関係にはならない。", "と": "「と」は並列や共同を示すが、伝播と止めるが結びつく文にはならない。", "から": "「から」は起点を示すが、伝播を出発点として止めるという意味にはならない。"}, "error_tags": {"に": "方向・相手", "と": "共同", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37942, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることが広く伝わること。", "primary_collocate": null, "pronunciation": "でんぱ", "ipa": "dempa", "syllable_count": 3, "sentences": [{"text": "噂の伝播は速く、一日で町中に広まった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "噂(うわさ)の伝播(でんぱ)は速(はや)く、一日(いちにち)で町中(まちじゅう)に広(ひろ)まった。", "sentence_source": "generated"}, {"text": "病気の伝播を防ぐために、手を洗いましょう。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "病気(びょうき)の伝播(でんぱ)を防(ふせ)ぐために、手(て)を洗(あら)いましょう。", "sentence_source": "generated"}, {"text": "新しい技術の伝播により、世界中で使われるようになった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "新(あたら)しい技術(ぎじゅつ)の伝播(でんぱ)により、世界中(せかいじゅう)で使(つか)われるようになった。", "sentence_source": "generated"}, {"text": "ニュースの伝播がこんなに速いとは思わなかった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "ニュースの伝播(でんぱ)がこんなに速(はや)いとは思(おも)わなかった。", "sentence_source": "generated"}, {"text": "山に囲まれた村では、情報の伝播が遅かった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "山(やま)に囲(かこ)まれた村(むら)では、情報(じょうほう)の伝播(でんぱ)が遅(おそ)かった。", "sentence_source": "generated"}, {"text": "仏教の伝播によって、アジアの文化は大きく変わった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "仏教(ぶっきょう)の伝播(でんぱ)によって、アジアの文化(ぶんか)は大(おお)きく変(か)わった。", "sentence_source": "generated"}, {"text": "ウイルスの伝播を調べるために、研究者が集まった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "ウイルスの伝播(でんぱ)を調(しら)べるために、研究者(けんきゅうしゃ)が集(あつ)まった。", "sentence_source": "generated"}, {"text": "悪い評判の伝播は、止めるのが難しい。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "悪(わる)い評判(ひょうばん)の伝播(でんぱ)は、止(と)めるのが難(むずか)しい。", "sentence_source": "generated"}, {"text": "言葉の伝播は、地域によって速さが違う。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "言葉(ことば)の伝播(でんぱ)は、地域(ちいき)によって速(はや)さが違(ちが)う。", "sentence_source": "generated"}, {"text": "災害情報の伝播が遅れて、避難が間に合わなかった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "災害情報(さいがいじょうほう)の伝播(でんぱ)が遅(おく)れて、避難(ひなん)が間(ま)に合(あ)わなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝播する", "label": "基本形"}, {"form": "伝播した", "label": "過去形"}, {"form": "伝播して", "label": "て形"}, {"form": "伝播しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "伝播: うわさ・情報・病気・文化などが広い範囲に伝わり広がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37942, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝播", "is_correct": true, "explanation": "「噂が広く伝わって広がる」という意味に合い、噂を主語にした文の中心語として自然に入る。"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の熱のことで、噂の広がりを表す語としては成り立たない。"}, {"text": "収入", "is_correct": false, "explanation": "収入は金銭を得ることを指し、噂が速く広まる様子には当てはまらない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は空模様のことで、噂の速さを述べる主語にはならない。"}], "explanations": {"伝播": "「噂が広く伝わって広がる」という意味に合い、噂を主語にした文の中心語として自然に入る。", "体温": "体温は人の体の熱のことで、噂の広がりを表す語としては成り立たない。", "収入": "収入は金銭を得ることを指し、噂が速く広まる様子には当てはまらない。", "天候": "天候は空模様のことで、噂の速さを述べる主語にはならない。"}, "sentence_index": 0, "correct_answer": "伝播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社長の決定は、担当の一人にだけ伝播した。", "explanation": "ここは〈伝達〉の意味。特定の相手に知らせる場合は伝達を使い、伝播は広い範囲へ広がることに使うので合わない。"}, {"text": "祖父は、この踊りを一晩で伝播して覚えた。", "explanation": "ここは〈覚える〉の意味。自分が身につける場合は覚えると言い、伝播は情報や文化が人から人へ広まる意味なので合わない。"}, {"text": "雨がやみ、地面の水たまりが一瞬で伝播した。", "explanation": "伝播は情報・病気・文化などが人から人へ広がる意味。水が地面に広がる場合は広がるを使うので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37942, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝播", "is_correct": true, "explanation": "ウイルスが広がっていく過程を指し、調べる対象として自然に入る。"}, {"text": "価格", "is_correct": false, "explanation": "価格はものの値段のことで、ウイルスを調べる対象にはならない。"}, {"text": "給料", "is_correct": false, "explanation": "給料は働いた対価の金額で、ウイルスの調査対象にはならない。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人や生き物の高さのことで、ウイルスには使えない。"}], "explanations": {"伝播": "ウイルスが広がっていく過程を指し、調べる対象として自然に入る。", "価格": "価格はものの値段のことで、ウイルスを調べる対象にはならない。", "給料": "給料は働いた対価の金額で、ウイルスの調査対象にはならない。", "身長": "身長は人や生き物の高さのことで、ウイルスには使えない。"}, "sentence_index": 6, "correct_answer": "伝播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は部屋で一人、夜通し伝播していた。", "explanation": "ここは〈練習〉の意味。一人で繰り返し覚える場合は練習と言い、伝播は人から人へ広がる意味なので合わない。"}, {"text": "祖父は、家宝の時計を孫に伝播した。", "explanation": "ここは〈譲る〉の意味。物を相手に渡す場合は譲ると言い、伝播は情報や文化が広まる意味なので合わない。"}, {"text": "彼は約束を、一度も伝播しなかった。", "explanation": "ここは〈守る〉の意味。約束は相手との取り決めなので守るを使い、伝播は広く広がるものに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37942, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい噂の伝播を、一日で町中に広まった。", "corrected_sentence": "新しい噂の伝播は、一日で町中に広まった。", "error_description": "伝播の直後の助詞が「を」になっている。伝播は話題の主語なので「は」を使い、「広まった」と自然に結ぶ。「を」だと目的語になり、自動詞の「広まる」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37942, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "災害情報の伝播を遅れたため、避難が間に合わなかった。", "corrected_sentence": "災害情報の伝播が遅れたため、避難が間に合わなかった。", "error_description": "伝播の直後の助詞が「を」になっている。「遅れる」は自動詞で、主語の伝播は「が」で示す。「を」では目的語になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
