INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37943, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37943, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "情報や考え、文化などが、人から人へと広まっていくこと。また、広めること。", "primary_collocate": null, "pronunciation": "でんぱ", "ipa": "dempa", "syllable_count": 3, "sentences": [{"text": "流行は、友達から友達へと伝播していく。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "流行(りゅうこう)は、友達(ともだち)から友達(ともだち)へと伝播(でんぱ)していく。", "sentence_source": "generated"}, {"text": "祭りの文化は、移住した人々によって他の地域へ伝播した。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "祭(まつ)りの文化(ぶんか)は、移住(いじゅう)した人々(ひとびと)によって他(ほか)の地域(ちいき)へ伝播(でんぱ)した。", "sentence_source": "generated"}, {"text": "SNSのおかげで、新しい考え方の伝播が速くなった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "SNSのおかげで、新(あたら)しい考(かんが)え方(かた)の伝播(でんぱ)が速(はや)くなった。", "sentence_source": "generated"}, {"text": "彼は自分の経験を伝播させるために、本を書いた。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "彼(かれ)は自分(じぶん)の経験(けいけん)を伝播(でんぱ)させるために、本(ほん)を書(か)いた。", "sentence_source": "generated"}, {"text": "方言は人の移動とともに伝播する。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "方言(ほうげん)は人(ひと)の移動(いどう)とともに伝播(でんぱ)する。", "sentence_source": "generated"}, {"text": "習慣の伝播には、家族や友人の影響が大きい。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "習慣(しゅうかん)の伝播(でんぱ)には、家族(かぞく)や友人(ゆうじん)の影響(えいきょう)が大(おお)きい。", "sentence_source": "generated"}, {"text": "料理の作り方が口コミで伝播し、店は有名になった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "料理(りょうり)の作(つく)り方(かた)が口(くち)コミで伝播(でんぱ)し、店(みせ)は有名(ゆうめい)になった。", "sentence_source": "generated"}, {"text": "先生の熱意は生徒たちに伝播して、教室が明るくなった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "先生(せんせい)の熱意(ねつい)は生徒(せいと)たちに伝播(でんぱ)して、教室(きょうしつ)が明(あか)るくなった。", "sentence_source": "generated"}, {"text": "笑いの伝播は不思議で、一人が笑うとみんなも笑う。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "笑(わら)いの伝播(でんぱ)は不思議(ふしぎ)で、一人(ひとり)が笑(わら)うとみんなも笑(わら)う。", "sentence_source": "generated"}, {"text": "昔の物語は、人から人へ伝播するうちに少しずつ変わった。", "target_word": "伝播", "complexity_tier": "T3", "furigana": "昔(むかし)の物語(ものがたり)は、人(ひと)から人(ひと)へ伝播(でんぱ)するうちに少(すこ)しずつ変(か)わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝播する", "label": "基本形"}, {"form": "伝播した", "label": "過去形"}, {"form": "伝播させる", "label": "使役形"}, {"form": "伝播して", "label": "て形"}], "register": "formal", "sense_fingerprint": "伝播: 情報・考え・文化・感情が人から人へ次々と伝わって広まる（広める）こと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37943, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝播", "is_correct": true, "explanation": "人から人へ広がっていく過程を表し、「していく」と合って流行の広がりを述べる。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まりを解くことで、流行が広がる動きには合わない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は調べて確かめることで、人の間を流行が広がる様子は表せない。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分が抜けることで、人から人への広がりには使えない。"}], "explanations": {"伝播": "人から人へ広がっていく過程を表し、「していく」と合って流行の広がりを述べる。", "解散": "解散は集まりを解くことで、流行が広がる動きには合わない。", "点検": "点検は調べて確かめることで、人の間を流行が広がる様子は表せない。", "乾燥": "乾燥は水分が抜けることで、人から人への広がりには使えない。"}, "sentence_index": 0, "correct_answer": "伝播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は生徒一人ひとりに、計算の仕方を伝播した。", "explanation": "ここは〈教える〉の意味。一人ずつ丁寧に教える場合は教えると言い、伝播は広く広がる意味なので合わない。"}, {"text": "この店は、新商品を一日で二百個伝播した。", "explanation": "ここは〈販売〉の意味。品物を売った数は販売と言い、伝播は情報や文化が人から人へ広まる意味なので合わない。"}, {"text": "この町のごみは、毎年伝播して増えている。", "explanation": "ここは〈増える〉の意味。数量が増える場合は増えるを使い、伝播は情報や文化が人から人へ広まる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37943, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝播", "is_correct": true, "explanation": "口コミで料理の作り方が広まる動きを表し、「伝播し」と続けて自然に入る。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は光がついたり消えたりすることで、口コミで広がる文脈には合わない。"}, {"text": "停止", "is_correct": false, "explanation": "停止は動きが止まることで、口コミで作り方が広がるという内容と逆になる。"}, {"text": "座礁", "is_correct": false, "explanation": "座礁は船が浅瀬に乗り上げることで、料理の作り方には使えない。"}], "explanations": {"伝播": "口コミで料理の作り方が広まる動きを表し、「伝播し」と続けて自然に入る。", "点滅": "点滅は光がついたり消えたりすることで、口コミで広がる文脈には合わない。", "停止": "停止は動きが止まることで、口コミで作り方が広がるという内容と逆になる。", "座礁": "座礁は船が浅瀬に乗り上げることで、料理の作り方には使えない。"}, "sentence_index": 6, "correct_answer": "伝播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は、昔の出来事を日記に伝播した。", "explanation": "ここは〈記録する〉の意味。文字に書き残して保存する場合は記録すると言い、伝播は人から人へ広まる意味なので合わない。"}, {"text": "そのバス路線は、毎朝駅まで伝播している。", "explanation": "ここは〈通じる〉の意味。道や路線が行き着く先を指す場合は通じると言い、伝播は広がる意味なので合わない。"}, {"text": "友達に本を伝播して、一週間貸した。", "explanation": "ここは〈貸す〉の意味。物を一時的に相手へ渡す場合は貸すと言い、伝播は情報や文化が広まる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37943, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その噂は、町の人々の間に伝播ていった。", "corrected_sentence": "その噂は、町の人々の間に伝播していった。", "error_description": "「伝播」に続く「し」が抜けている。サ変動詞「する」の連用形「し」を補い、「伝播していった」の形にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37943, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その話の伝播を速かった。", "corrected_sentence": "その話の伝播は速かった。", "error_description": "伝播の直後の助詞が「を」になっている。伝播は話題の主語なので「は」を使う。形容詞「速かった」は主語の様子を述べるので、「を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37946, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37946, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「三角の旗」で、三角が旗を修飾する形で連なる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は所在や結果を表し、旗を修飾する形にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、旗を修飾する形には使えない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、旗の形を示す修飾にはならない。"}], "correct_answer": "の", "explanations": {"の": "「三角の旗」で、三角が旗を修飾する形で連なる。", "に": "「に」は所在や結果を表し、旗を修飾する形にはならない。", "から": "「から」は起点を表し、旗を修飾する形には使えない。", "より": "「より」は比較を表し、旗の形を示す修飾にはならない。"}, "error_tags": {"に": "result/location", "から": "source", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37946, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "さんかくは、かどが三つあるかたちです。", "primary_collocate": null, "pronunciation": "さんかく", "ipa": "saŋkakɯ", "syllable_count": 4, "sentences": [{"text": "母が三角のおにぎりを作ってくれました。", "target_word": "三角", "complexity_tier": "T3", "furigana": "母[はは]が三角[さんかく]のおにぎりを作[つく]ってくれました。", "sentence_source": "generated"}, {"text": "この家は屋根が三角なので、すぐ分かります。", "target_word": "三角", "complexity_tier": "T3", "furigana": "この家[いえ]は屋根[やね]が三角[さんかく]なので、すぐ分[わ]かります。", "sentence_source": "generated"}, {"text": "三角の帽子をかぶると、パーティーの気分になる。", "target_word": "三角", "complexity_tier": "T3", "furigana": "三角[さんかく]の帽子[ぼうし]をかぶると、パーティーの気分[きぶん]になる。", "sentence_source": "generated"}, {"text": "紙を半分に折ると、三角になります。", "target_word": "三角", "complexity_tier": "T3", "furigana": "紙[かみ]を半分[はんぶん]に折[お]ると、三角[さんかく]になります。", "sentence_source": "generated"}, {"text": "三角のサンドイッチは食べやすいので、子どもに人気です。", "target_word": "三角", "complexity_tier": "T3", "furigana": "三角[さんかく]のサンドイッチは食[た]べやすいので、子[こ]どもに人気[にんき]です。", "sentence_source": "generated"}, {"text": "この道には、赤くて三角の標識が立っていた。", "target_word": "三角", "complexity_tier": "T3", "furigana": "この道[みち]には、赤[あか]くて三角[さんかく]の標識[ひょうしき]が立[た]っていた。", "sentence_source": "generated"}, {"text": "皿の上に、三角に切ったチーズが並んでいる。", "target_word": "三角", "complexity_tier": "T3", "furigana": "皿[さら]の上[うえ]に、三角[さんかく]に切[き]ったチーズが並[なら]んでいる。", "sentence_source": "generated"}, {"text": "三角の旗を、運動会のかざりに使いました。", "target_word": "三角", "complexity_tier": "T3", "furigana": "三角[さんかく]の旗[はた]を、運動会[うんどうかい]のかざりに使[つか]いました。", "sentence_source": "generated"}, {"text": "あのテントは三角なので、雨が降っても水が流れ落ちる。", "target_word": "三角", "complexity_tier": "T3", "furigana": "あのテントは三角[さんかく]なので、雨[あめ]が降[ふ]っても水[みず]が流[なが]れ落[お]ちる。", "sentence_source": "generated"}, {"text": "ケーキを三角に切ると、八人で分けられます。", "target_word": "三角", "complexity_tier": "T3", "furigana": "ケーキを三角[さんかく]に切[き]ると、八人[はちにん]で分[わ]けられます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "三角", "label": "基本形"}, {"form": "三角の", "label": "連体修飾"}, {"form": "三角に", "label": "連用修飾"}], "register": "neutral", "sense_fingerprint": "everyday shape with three corners, as seen in food, roofs, hats and signs", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37946, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三角", "is_correct": true, "explanation": "かどが三つある形の意味で、「三角のおにぎり」に合う。"}, {"text": "テレビ", "is_correct": false, "explanation": "テレビは家電で、おにぎりの形容として使えない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "ピアノは楽器で、おにぎりの形を表す語にはならない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は雨具で、おにぎりの形容に使う語ではない。"}], "explanations": {"三角": "かどが三つある形の意味で、「三角のおにぎり」に合う。", "テレビ": "テレビは家電で、おにぎりの形容として使えない。", "ピアノ": "ピアノは楽器で、おにぎりの形を表す語にはならない。", "傘": "傘は雨具で、おにぎりの形容に使う語ではない。"}, "sentence_index": 0, "correct_answer": "三角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の三角は、いつも行列ができるほど人気だ。", "explanation": "ここは〈三角〉を店の人気の意味で使っている。〈三角〉はかどが三つある形なので、この使い方には合わない。"}, {"text": "この会社の三角は、社員の給料を上げる力がある。", "explanation": "ここは〈三角〉を会社の力の意味で使っている。〈三角〉は形を表す語なので、この使い方はできない。"}, {"text": "月が三角に光っている。", "explanation": "ここは丸い月の形を表す場面。三角の形で光る表現は、定義の形と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37946, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三角", "is_correct": true, "explanation": "かどが三つある形に切る意味で、「三角に切ったチーズ」に合う。"}, {"text": "布団", "is_correct": false, "explanation": "布団は寝具で、チーズを切る形の語にはならない。"}, {"text": "ペン", "is_correct": false, "explanation": "ペンは筆記具で、食べ物を切る形を表さない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通信機器で、チーズを切る形の表現に使えない。"}], "explanations": {"三角": "かどが三つある形に切る意味で、「三角に切ったチーズ」に合う。", "布団": "布団は寝具で、チーズを切る形の語にはならない。", "ペン": "ペンは筆記具で、食べ物を切る形を表さない。", "電話": "電話は通信機器で、チーズを切る形の表現に使えない。"}, "sentence_index": 6, "correct_answer": "三角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国の三角は、貿易で大きな利益を得た。", "explanation": "ここは〈三角〉を国の意味で使っている。〈三角〉はかどが三つある形なので、国を指す使い方はない。"}, {"text": "ケーキを三角に食べると、八人が喜ぶ。", "explanation": "ここは〈切る〉の場面。三角は食べ方ではなく、切った形を表すので合わない。"}, {"text": "この箱の三角を開けると、おもちゃが出てくる。", "explanation": "ここは箱のふたを指す場面。かどが三つある形の意味では、箱の一部を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37946, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この家の屋根は三角に、雨水がよく流れます。", "corrected_sentence": "この家の屋根は三角なので、雨水がよく流れます。", "error_description": "誤: 「三角に」／正: 「三角なので」。「三角」は名詞なので、後に続ける形は「な」を付けた「なので」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37946, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ケーキを三角へ切って、お客さんに配りました。", "corrected_sentence": "ケーキを三角に切って、お客さんに配りました。", "error_description": "誤: 「三角へ」／正: 「三角に」。切った形を表すには「に」で様子を示す。「へ」は方向を示すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
