INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37947, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "三つの直線で囲まれた、三つの角を持つ図形。", "primary_collocate": null, "pronunciation": "さんかく", "ipa": "saŋkakɯ", "syllable_count": 4, "sentences": [{"text": "黒板に大きな三角を描いて、角の数を数えました。", "target_word": "三角", "complexity_tier": "T3", "furigana": "黒板[こくばん]に大[おお]きな三角[さんかく]を描[か]いて、角[かど]の数[かず]を数[かぞ]えました。", "sentence_source": "generated"}, {"text": "図の三角は底辺が四センチ、高さが三センチなので、面積は六平方センチだ。", "target_word": "三角", "complexity_tier": "T3", "furigana": "図の三角[さんかく]は底辺が四センチ、高さが三センチなので、面積は六平方センチだ。", "sentence_source": "generated"}, {"text": "三本の線を引くと、小さな三角ができる。", "target_word": "三角", "complexity_tier": "T3", "furigana": "三本[さんぼん]の線[せん]を引[ひ]くと、小[ちい]さな三角[さんかく]ができる。", "sentence_source": "generated"}, {"text": "数学の授業で、どの三角でも内角を全部足すと同じ数になると習った。", "target_word": "三角", "complexity_tier": "T3", "furigana": "数学の授業で、どの三角[さんかく]でも内角を全部足すと同じ数になると習った。", "sentence_source": "generated"}, {"text": "定規で点を線で結んで、きれいな三角を作りなさい。", "target_word": "三角", "complexity_tier": "T3", "furigana": "定規[じょうぎ]で点[てん]を線[せん]で結[むす]んで、きれいな三角[さんかく]を作[つく]りなさい。", "sentence_source": "generated"}, {"text": "図の中に三角がいくつあるか、数えてみよう。", "target_word": "三角", "complexity_tier": "T3", "furigana": "図[ず]の中[なか]に三角[さんかく]がいくつあるか、数[かぞ]えてみよう。", "sentence_source": "generated"}, {"text": "直線を三本しか使わずに、三角を描いてください。", "target_word": "三角", "complexity_tier": "T3", "furigana": "直線[ちょくせん]を三本[さんぼん]しか使[つか]わずに、三角[さんかく]を描[か]いてください。", "sentence_source": "generated"}, {"text": "この三角は一つの角が直角なので、計算が簡単だ。", "target_word": "三角", "complexity_tier": "T3", "furigana": "この三角[さんかく]は一[ひと]つの角[かど]が直角[ちょっかく]なので、計算[けいさん]が簡単[かんたん]だ。", "sentence_source": "generated"}, {"text": "地図の上に三角を描いて、三つの町を線で結んだ。", "target_word": "三角", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]に三角[さんかく]を描[か]いて、三[みっ]つの町[まち]を線[せん]で結[むす]んだ。", "sentence_source": "generated"}, {"text": "ノートに三角を二つ描いて、大きさをくらべた。", "target_word": "三角", "complexity_tier": "T3", "furigana": "ノートに三角[さんかく]を二[ふた]つ描[か]いて、大[おお]きさをくらべた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "三角", "label": "基本形"}, {"form": "三角の", "label": "連体修飾"}, {"form": "三角を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "geometric figure enclosed by three straight lines, used in math contexts such as drawing, area and angles", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37947, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三角", "is_correct": true, "explanation": "正解。「描く」の目的語で、三本の直線で囲まれた図形を指す。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は書くもので描くものではないため、「大きな手紙を描いて」は成り立たない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は形がないので、黒板に描いて角の数を数える対象にならない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は形がないので、黒板に描く対象にならない。"}], "explanations": {"三角": "正解。「描く」の目的語で、三本の直線で囲まれた図形を指す。", "手紙": "手紙は書くもので描くものではないため、「大きな手紙を描いて」は成り立たない。", "音楽": "音楽は形がないので、黒板に描いて角の数を数える対象にならない。", "歌": "歌は形がないので、黒板に描く対象にならない。"}, "sentence_index": 0, "correct_answer": "三角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は二人の男性の間で三角に悩み、まだ答えを出せずにいる。", "explanation": "ここは「三角関係」（恋愛で三人が絡む関係）の意味。「三角」だけでは恋の三角関係を表さず、図形の意味でもないので合わない。"}, {"text": "けがをした指に三角をきつく巻いて、病院へ行った。", "explanation": "ここは「三角巾」（布製の三角形の包帯）の意味。「三角」だけでは包帯を指さないので合わない。"}, {"text": "机の三角に頭をぶつけて、とても痛かった。", "explanation": "ここは「角」の意味。「三角」は図形そのものを指し、物の角のことは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37947, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三角", "is_correct": true, "explanation": "正解。「描いてください」の目的語で、直線三本で作る図形を指す。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は直線三本で描ける図形ではなく、「描いてください」の対象にならない。"}, {"text": "新聞", "is_correct": false, "explanation": "新聞は図形ではないので、直線で描く対象として成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は物であり、直線三本で描く図形とは関係がない。"}], "explanations": {"三角": "正解。「描いてください」の目的語で、直線三本で作る図形を指す。", "冷蔵庫": "冷蔵庫は直線三本で描ける図形ではなく、「描いてください」の対象にならない。", "新聞": "新聞は図形ではないので、直線で描く対象として成り立たない。", "財布": "財布は物であり、直線三本で描く図形とは関係がない。"}, "sentence_index": 6, "correct_answer": "三角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この角は三角で、九十度より小さい。", "explanation": "ここは「鋭角」（九十度より小さい角）の意味。三角は図形の名前で、角の大きさは表さないので合わない。"}, {"text": "給食は三角で食べるように言われた。", "explanation": "ここは「三角食べ」（ご飯・おかず・汁を順番に食べる食べ方）の意味。「三角」だけでは食べ方の名前にならない。"}, {"text": "川の三角に新しい町ができた。", "explanation": "ここは「三角州」（河口に土砂が積もってできた地形）の意味。「三角」だけではその地形を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37947, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ノートに三角が描いて、三つの頂点に印をつけた。", "corrected_sentence": "ノートに三角を描いて、三つの頂点に印をつけた。", "error_description": "誤: 「三角が描いて」／正: 「三角を描いて」。「描く」は他動詞なので目的語の「を」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37947, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙に三角を描いで、頂点に名前を書いた。", "corrected_sentence": "紙に三角を描いて、頂点に名前を書いた。", "error_description": "「描く」のて形は「描いて」。「描いで」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37948, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「マークがあります」のように、マークを主語にして「あります」に続ける。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「あります」の主語になる位置では使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、存在する物の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すので、マーク一つが主語の文では合わない。"}], "correct_answer": "が", "explanations": {"が": "「マークがあります」のように、マークを主語にして「あります」に続ける。", "を": "「を」は目的語。「あります」の主語になる位置では使えない。", "へ": "「へ」は方向を表し、存在する物の主語にはならない。", "と": "「と」は並列を表すので、マーク一つが主語の文では合わない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "pairing"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37948, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「マークがあるので」のように、マークを主語にして存在を表す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、存在の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、ある物の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「あるので」の主語には使えない。"}], "correct_answer": "が", "explanations": {"が": "「マークがあるので」のように、マークを主語にして存在を表す。", "へ": "「へ」は方向を表し、存在の主語にはならない。", "から": "「から」は起点を表すので、ある物の主語にはならない。", "より": "「より」は比較を表し、「あるので」の主語には使えない。"}, "error_tags": {"へ": "direction", "から": "source", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37948, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "そのばしょやものをしめすしるしです。かたちやいろでわかります。", "primary_collocate": null, "pronunciation": "まーく", "ipa": "maːkɯ", "syllable_count": 3, "sentences": [{"text": "地図で赤いマークがついている場所が、駅です。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "地図[ちず]で赤[あか]いマークがついている場所[ばしょ]が、駅[えき]です。", "sentence_source": "generated"}, {"text": "トイレの入り口には、男の人と女の人のマークがあります。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "トイレの入[い]り口[ぐち]には、男[おとこ]の人[ひと]と女[おんな]の人[ひと]のマークがあります。", "sentence_source": "generated"}, {"text": "非常口には、緑色のマークがついています。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "非常口[ひじょうぐち]には、緑色[みどりいろ]のマークがついています。", "sentence_source": "generated"}, {"text": "駐車場の場所は、青いPのマークでわかります。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]の場所[ばしょ]は、青[あお]いPのマークでわかります。", "sentence_source": "generated"}, {"text": "この箱には、われものを知らせるグラスのマークがついています。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "この箱[はこ]には、われものを知[し]らせるグラスのマークがついています。", "sentence_source": "generated"}, {"text": "地図の星のマークは、私たちが泊まるホテルの場所です。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "地図[ちず]の星[ほし]のマークは、私[わたし]たちが泊[と]まるホテルの場所[ばしょ]です。", "sentence_source": "generated"}, {"text": "地面の黄色いマークは、ここに荷物を置く場所を示しています。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "地面[じめん]の黄色[きいろ]いマークは、ここに荷物[にもつ]を置[お]く場所[ばしょ]を示[しめ]しています。", "sentence_source": "generated"}, {"text": "駅の案内板に矢印のマークがあるので、出口がすぐにわかりました。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "駅[えき]の案内板[あんないばん]に矢印[やじるし]のマークがあるので、出口[でぐち]がすぐにわかりました。", "sentence_source": "generated"}, {"text": "この地図は、赤いマークが病院、青いマークが学校を表しています。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "この地図[ちず]は、赤[あか]いマークが病院[びょういん]、青[あお]いマークが学校[がっこう]を表[あらわ]しています。", "sentence_source": "generated"}, {"text": "子どもでもわかるように、図書室のドアに本のマークをつけました。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "子[こ]どもでもわかるように、図書室[としょしつ]のドアに本[ほん]のマークをつけました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マーク", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "場所や物を示す、形や色で分かるしるし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37948, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マーク", "is_correct": true, "explanation": "場所を示すしるしの意味で、「赤いマークがついている場所」に合う。"}, {"text": "ドア", "is_correct": false, "explanation": "ドアは出入口の建具で、地図につけて場所を示す印にはならない。"}, {"text": "ベッド", "is_correct": false, "explanation": "ベッドは寝る家具で、地図上の場所を示す印として使えない。"}, {"text": "スプーン", "is_correct": false, "explanation": "スプーンは食器で、地図に赤くつける印にはならない。"}], "explanations": {"マーク": "場所を示すしるしの意味で、「赤いマークがついている場所」に合う。", "ドア": "ドアは出入口の建具で、地図につけて場所を示す印にはならない。", "ベッド": "ベッドは寝る家具で、地図上の場所を示す印として使えない。", "スプーン": "スプーンは食器で、地図に赤くつける印にはならない。"}, "sentence_index": 0, "correct_answer": "マーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合のあと、色紙に選手のマークをもらいました。", "explanation": "ここは〈サイン〉（署名）の意味。マークは図形や記号のしるしで、名前の署名は指さないので合わない。"}, {"text": "発車のマークが鳴ったら、ドアが閉まります。", "explanation": "ここは〈合図〉の意味。マークは目で見るしるしなので、音が鳴る合図の代わりにはならない。"}, {"text": "テストの答えをマークしたら、満点だった。", "explanation": "ここは〈マークする〉（選択肢に印をつける）の動詞の使い方。名詞の〈マーク〉（場所や物を示すしるし）とは別の用法で、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37948, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マーク", "is_correct": true, "explanation": "床に置く場所を示すしるしの意味で、「地面の黄色いマーク」に合う。"}, {"text": "ボール", "is_correct": false, "explanation": "ボールは遊び道具で、地面に荷物を置く場所を示すことはない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "ハンカチは布製品で、地面に置いて場所を示す印にはならない。"}, {"text": "ベンチ", "is_correct": false, "explanation": "ベンチは座る設備で、場所を示すしるしとして地面にあるものではない。"}], "explanations": {"マーク": "床に置く場所を示すしるしの意味で、「地面の黄色いマーク」に合う。", "ボール": "ボールは遊び道具で、地面に荷物を置く場所を示すことはない。", "ハンカチ": "ハンカチは布製品で、地面に置いて場所を示す印にはならない。", "ベンチ": "ベンチは座る設備で、場所を示すしるしとして地面にあるものではない。"}, "sentence_index": 6, "correct_answer": "マーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "初めて会ったとき、あの人のマークがとても良かった。", "explanation": "ここは〈印象〉の意味。マークは図形や記号のしるしで、人に受ける感じは指さないので合わない。"}, {"text": "この箱には、中身の期限を書いたマークが貼ってある。", "explanation": "ここは〈ラベル〉の意味。文字で情報を書いた札で、絵や記号のマークは期限を書かない。"}, {"text": "転んで、ひざにマークができた。", "explanation": "ここは〈あざ・傷〉の意味。マークは図形や記号のしるしで、体の傷は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37948, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この箱には、こわれやすい物のマークをついています。", "corrected_sentence": "この箱には、こわれやすい物のマークがついています。", "error_description": "誤: 「マークをついています」／正: 「マークがついています」。「つく」は自動詞なので、目的語の「を」ではなく主語の「が」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37948, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この建物の屋根には、赤い三角のマークがつけています。", "corrected_sentence": "この建物の屋根には、赤い三角のマークがついています。", "error_description": "誤: 「つけています」／正: 「ついています」。マークが主語なので、他動詞「つける」ではなく自動詞「つく」の状態を表す「ついている」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37949, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この会社のマークは、～です」で、マークを話題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「です」の文では主題の位置に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や所在。主題を示す位置には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「～の形です」の文では成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「この会社のマークは、～です」で、マークを話題として示す。", "を": "「を」は目的語。「です」の文では主題の位置に合わない。", "に": "「に」は到着点や所在。主題を示す位置には合わない。", "へ": "「へ」は方向を表し、「～の形です」の文では成り立たない。"}, "error_tags": {"を": "object", "に": "direction/location", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37949, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「虫のマークをかいて」で、マークを目的語にして「かく」に続ける。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語。「かいて」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、かく対象の目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、かく対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「虫のマークをかいて」で、マークを目的語にして「かく」に続ける。", "が": "「が」は主語。「かいて」の目的語にはならない。", "へ": "「へ」は方向を表し、かく対象の目的語にはならない。", "から": "「から」は起点を表し、かく対象を示せない。"}, "error_tags": {"が": "subject", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37949, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人や物事を区別したり、目印にしたりするための図形や記号のこと。", "primary_collocate": null, "pronunciation": "まーく", "ipa": "maːkɯ", "syllable_count": 3, "sentences": [{"text": "自分のかばんがわかるように、犬のマークをつけました。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "自分[じぶん]のかばんがわかるように、犬[いぬ]のマークをつけました。", "sentence_source": "generated"}, {"text": "この会社のマークは、青い鳥の形です。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]のマークは、青[あお]い鳥[とり]の形[かたち]です。", "sentence_source": "generated"}, {"text": "同じ色のコップなので、名前の代わりに、花のマークで区別しています。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "同[おな]じ色[いろ]のコップなので、名前[なまえ]の代[か]わりに、花[はな]のマークで区別[くべつ]しています。", "sentence_source": "generated"}, {"text": "先生は、大切な言葉に黄色いペンで四角いマークをつけるように言いました。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "先生[せんせい]は、大切[たいせつ]な言葉[ことば]に黄色[きいろ]いペンで四角[しかく]いマークをつけるように言[い]いました。", "sentence_source": "generated"}, {"text": "みんなのぼうしに、ちがう動物のマークをつけて、自分のものがすぐわかるようにしました。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "みんなのぼうしに、ちがう動物[どうぶつ]のマークをつけて、自分[じぶん]のものがすぐわかるようにしました。", "sentence_source": "generated"}, {"text": "商品の包みにブランドのマークが入っているので、どこの製品か分かります。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "商品[しょうひん]の包[つつ]みにブランドのマークが入[はい]っているので、どこの製品[せいひん]か分[わ]かります。", "sentence_source": "generated"}, {"text": "このチームのマークは、ライオンの顔をデザインしたものです。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "このチームのマークは、ライオンの顔[かお]をデザインしたものです。", "sentence_source": "generated"}, {"text": "弟は、自分の持ち物に好きな虫のマークをかいて、ほかの人のものと区別しています。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "弟[おとうと]は、自分[じぶん]の持[も]ち物[もの]に好[す]きな虫[むし]のマークをかいて、ほかの人[ひと]のものと区別[くべつ]しています。", "sentence_source": "generated"}, {"text": "このシールは、古い書類と新しい書類を分けるための緑のマークです。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "このシールは、古[ふる]い書類[しょるい]と新[あたら]しい書類[しょるい]を分[わ]けるための緑[みどり]のマークです。", "sentence_source": "generated"}, {"text": "合格した書類には、あとで探しやすいように、丸いマークをつけておきます。", "target_word": "マーク", "complexity_tier": "T3", "furigana": "合格[ごうかく]した書類[しょるい]には、あとで探[さが]しやすいように、丸[まる]いマークをつけておきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マーク", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "人や物を区別する目印として使う図形や記号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37949, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マーク", "is_correct": true, "explanation": "区別のための目印の図形の意味で、「犬のマークをつけました」に合う。"}, {"text": "ラジオ", "is_correct": false, "explanation": "ラジオは受信機で、かばんの区別に付けて使う目印ではない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "ケーキは食べ物で、かばんに付けて区別する目印にはならない。"}, {"text": "スリッパ", "is_correct": false, "explanation": "スリッパは履物で、かばんに付けて目印にする物ではない。"}], "explanations": {"マーク": "区別のための目印の図形の意味で、「犬のマークをつけました」に合う。", "ラジオ": "ラジオは受信機で、かばんの区別に付けて使う目印ではない。", "ケーキ": "ケーキは食べ物で、かばんに付けて区別する目印にはならない。", "スリッパ": "スリッパは履物で、かばんに付けて目印にする物ではない。"}, "sentence_index": 0, "correct_answer": "マーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "色紙に、選手のマークを書いてもらった。", "explanation": "ここは〈サイン〉（署名）の意味。マークは図形や記号の区別なので、名前の署名の代わりにはならない。"}, {"text": "玄関のマークを鳴らしてください。", "explanation": "ここは〈ベル〉の意味。マークは図形なので、鳴らす対象にはならない。"}, {"text": "試合中、相手の選手にマークされて、シュートできなかった。", "explanation": "ここは〈マークする〉（相手を見張る）の意味。区別や目印の図形の意味とは別の語になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37949, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マーク", "is_correct": true, "explanation": "チームを表す図形の意味で、「このチームのマーク」に合う。"}, {"text": "ボトル", "is_correct": false, "explanation": "ボトルは飲み物の容器で、チームを表す図形にはならない。"}, {"text": "ベッド", "is_correct": false, "explanation": "ベッドは寝る家具で、チームの図案として使うものではない。"}, {"text": "ドア", "is_correct": false, "explanation": "ドアは建具で、チームを表すライオンの図形にはならない。"}], "explanations": {"マーク": "チームを表す図形の意味で、「このチームのマーク」に合う。", "ボトル": "ボトルは飲み物の容器で、チームを表す図形にはならない。", "ベッド": "ベッドは寝る家具で、チームの図案として使うものではない。", "ドア": "ドアは建具で、チームを表すライオンの図形にはならない。"}, "sentence_index": 6, "correct_answer": "マーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転んで、ひじにマークができた。", "explanation": "ここは〈あざ・傷〉の意味。マークは図形や記号のしるしで、体の傷は指さないので合わない。"}, {"text": "この箱には、中身を書いたマークを貼ってあります。", "explanation": "ここは〈ラベル〉の意味。文字で中身を書く札で、区別の図形とは別。"}, {"text": "雪の上に、子どもの歩いたマークが続いていた。", "explanation": "ここは〈足跡〉の意味。区別や目印のための図形とは別の語になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37949, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "わたしのノートには、自分だと分かる星のマークがつけました。", "corrected_sentence": "わたしのノートには、自分だと分かる星のマークをつけました。", "error_description": "誤: 「マークがつけました」／正: 「マークをつけました」。「つける」は他動詞なので目的語の「を」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37949, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このチームのマークを決まったのは、子どもたちです。", "corrected_sentence": "このチームのマークを決めたのは、子どもたちです。", "error_description": "誤: 「決まった」／正: 「決めた」。「決まる」は自動詞で目的語の「を」を取れないので、他動詞「決める」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37952, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「ごみを分けて」で、分ける対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ごみが分けてから」は主語になり、対象が消えて不自然。"}, {"text": "に", "is_correct": false, "explanation": "「ごみに分けて」は対象を示せず、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、分ける対象には使わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「ごみを分けて」で、分ける対象を示す。", "が": "「ごみが分けてから」は主語になり、対象が消えて不自然。", "に": "「ごみに分けて」は対象を示せず、成り立たない。", "へ": "方向を示す「へ」は、分ける対象には使わない。"}, "error_tags": {"が": "主語の格", "に": "相手・方向の格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37952, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37952, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ごみを、紙やびんなど、それぞれのなかまにわけること。", "primary_collocate": null, "pronunciation": "ごみをわける", "ipa": "gomi o wakeɾɯ", "syllable_count": 6, "sentences": [{"text": "朝、家族みんなでごみを分ける。", "target_word": "ごみを分ける", "complexity_tier": "T3", "furigana": "朝[あさ]、家族[かぞく]みんなでごみを分[わ]ける。", "sentence_source": "generated"}, {"text": "祖母は、台所でごみを分けてから、袋に入れている。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、台所[だいどころ]でごみを分[わ]けてから、袋[ふくろ]に入[い]れている。", "sentence_source": "generated"}, {"text": "ごみを分けると、リサイクルがしやすくなる。", "target_word": "ごみを分ける", "complexity_tier": "T3", "furigana": "ごみを分[わ]けると、リサイクルがしやすくなる。", "sentence_source": "generated"}, {"text": "町のきまりで、ごみを分けて出さなければならない。", "target_word": "ごみを分けて", "complexity_tier": "T3", "furigana": "町[まち]のきまりで、ごみを分[わ]けて出[だ]さなければならない。", "sentence_source": "generated"}, {"text": "弟にもごみを分ける方法を教えた。", "target_word": "ごみを分ける", "complexity_tier": "T3", "furigana": "弟[おとうと]にもごみを分[わ]ける方法[ほうほう]を教[おし]えた。", "sentence_source": "generated"}, {"text": "燃えるものと燃えないものに、ごみを分けた。", "target_word": "ごみを分けた", "complexity_tier": "T3", "furigana": "燃[も]えるものと燃[も]えないものに、ごみを分[わ]けた。", "sentence_source": "generated"}, {"text": "ごみを分けないと、収集の人が持っていってくれない。", "target_word": "ごみを分けない", "complexity_tier": "T3", "furigana": "ごみを分[わ]けないと、収集[しゅうしゅう]の人[ひと]が持[も]っていってくれない。", "sentence_source": "generated"}, {"text": "学校では、毎日、教室でごみを分ける時間がある。", "target_word": "ごみを分ける", "complexity_tier": "T3", "furigana": "学校[がっこう]では、毎日[まいにち]、教室[きょうしつ]でごみを分[わ]ける時間[じかん]がある。", "sentence_source": "generated"}, {"text": "ごみを分ける箱が、台所の横に三つ並んでいる。", "target_word": "ごみを分ける", "complexity_tier": "T3", "furigana": "ごみを分[わ]ける箱[はこ]が、台所[だいどころ]の横[よこ]に三[みっ]つ並[なら]んでいる。", "sentence_source": "generated"}, {"text": "面倒でも、ごみを分けるのは大切な習慣だ。", "target_word": "ごみを分ける", "complexity_tier": "T3", "furigana": "面倒[めんどう]でも、ごみを分[わ]けるのは大切[たいせつ]な習慣[しゅうかん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ごみを分ける", "label": "終止形"}, {"form": "ごみを分けます", "label": "丁寧形"}, {"form": "ごみを分けた", "label": "過去形"}, {"form": "ごみを分けて", "label": "て形"}, {"form": "ごみを分けない", "label": "否定形"}], "register": "普通体（日常）", "sense_fingerprint": "ごみを紙・びん・缶などの種類ごとに分別する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37952, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ごみを分ける", "is_correct": true, "explanation": "正解。「朝、家族みんなでごみを分ける」は、種類ごとに仕分けるという意味になる。"}, {"text": "霧を編む", "is_correct": false, "explanation": "「編む」は糸で編み物を作ること。霧を編むことは意味が通らない。"}, {"text": "風を縫う", "is_correct": false, "explanation": "「縫う」は布を糸で留めること。風を縫うとは言わない。"}, {"text": "空を畳む", "is_correct": false, "explanation": "「畳む」は布や紙を折りたたむこと。空を畳むという内容は成り立たない。"}], "explanations": {"ごみを分ける": "正解。「朝、家族みんなでごみを分ける」は、種類ごとに仕分けるという意味になる。", "霧を編む": "「編む」は糸で編み物を作ること。霧を編むことは意味が通らない。", "風を縫う": "「縫う」は布を糸で留めること。風を縫うとは言わない。", "空を畳む": "「畳む」は布や紙を折りたたむこと。空を畳むという内容は成り立たない。"}, "sentence_index": 0, "correct_answer": "ごみを分ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、家族みんなで、ワインびんを二つに分けて、ごみ袋に入れた。", "explanation": "ここは〈二等分する〉の意味。びんを半分ずつにすることで、種類ごとに仕分ける「分ける」とは別の意味になる。"}, {"text": "家族みんなで、空きかんを分けて、ぺちゃんこにした。", "explanation": "ここは〈潰す〉の意味。かんを押しつぶすことは「潰す」で、種類ごとに仕分ける「分ける」は合わない。"}, {"text": "家族みんなで、ごみ袋の口を分けて、出しに行った。", "explanation": "ここは〈縛る〉の意味。袋の口をくくることは「縛る」で、「分ける」は種類ごとに仕分ける行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37952, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ごみを分けない", "is_correct": true, "explanation": "正解。「ごみを分けないと、収集の人が持っていってくれない」で、分けないことで困る流れになる。"}, {"text": "雨を染める", "is_correct": false, "explanation": "「染める」は色を付けること。雨を染めるという内容は成り立たない。"}, {"text": "月を焼く", "is_correct": false, "explanation": "「焼く」は火で熱することで、月を焼くとは言えない。"}, {"text": "雷を磨く", "is_correct": false, "explanation": "「磨く」は表面を光らせることで、雷を磨く文は意味が通らない。"}], "explanations": {"ごみを分けない": "正解。「ごみを分けないと、収集の人が持っていってくれない」で、分けないことで困る流れになる。", "雨を染める": "「染める」は色を付けること。雨を染めるという内容は成り立たない。", "月を焼く": "「焼く」は火で熱することで、月を焼くとは言えない。", "雷を磨く": "「磨く」は表面を光らせることで、雷を磨く文は意味が通らない。"}, "sentence_index": 6, "correct_answer": "ごみを分けない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面倒でも、結んだひもを分けるのは大切な習慣だ。", "explanation": "ここは〈ほどく〉の意味。結び目を解くことは「ほどく」で、種類ごとに仕分ける「分ける」は合わない。"}, {"text": "面倒でも、ごみ箱のふたを分けるのは大切な習慣だ。", "explanation": "ここは〈取り外す〉の意味。ふたを本体から外すことは「外す」で、種類ごとに仕分ける「分ける」とは合わない。"}, {"text": "面倒でも、袋の穴を分けるのは大切な習慣だ。", "explanation": "ここは〈ふさぐ〉の意味。穴を塞ぐことは「ふさぐ」で、種類ごとに仕分ける「分ける」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37952, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は、流しでごみに分けてから、袋に入れている。", "corrected_sentence": "父は、流しでごみを分けてから、袋に入れている。", "error_description": "「分ける」は分けるもの（対象）を「を」で示す。「ごみに」は誤りで、正しくは「ごみを分けてから」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "分けて", "is_correct": true, "explanation": "正解。て形で、「袋に入れている」へつながる文になる。"}, {"text": "分けず", "is_correct": false, "explanation": "連用形の否定。「分けずから」とは続かず、文が成り立たない。"}, {"text": "分けろ", "is_correct": false, "explanation": "命令形。「分けろから」とは続かず、文が成り立たない。"}, {"text": "分けさせ", "is_correct": false, "explanation": "使役の連用形。「分けさせから」とは続かず、文が成り立たない。"}], "correct_form": "分けて", "base_form": "分ける", "form_label": "て形", "sentence_index": 1, "explanations": {"分けて": "正解。て形で、「袋に入れている」へつながる文になる。", "分けず": "連用形の否定。「分けずから」とは続かず、文が成り立たない。", "分けろ": "命令形。「分けろから」とは続かず、文が成り立たない。", "分けさせ": "使役の連用形。「分けさせから」とは続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37952, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ごみを分けるないと、収集日に袋を持っていってもらえない。", "corrected_sentence": "ごみを分けないと、収集日に袋を持っていってもらえない。", "error_description": "「分ける」の否定形は「分けない」。「分けるない」は活用の誤りで、正しくは「分けないと」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ごみを分ける", "is_correct": true, "explanation": "正解。終止形で、「時間がある」につながる文になる。"}, {"text": "ごみを分けろ", "is_correct": false, "explanation": "命令形。「分けろ時間がある」とは続かず、文が成り立たない。"}, {"text": "ごみを分けず", "is_correct": false, "explanation": "否定の連用形。分けないという意味になり、時間の説明が成り立たない。"}, {"text": "ごみを分けたく", "is_correct": false, "explanation": "希望の連用形。「分けたく時間がある」とは続かず、文が成り立たない。"}], "correct_form": "ごみを分ける", "base_form": "分ける", "form_label": "終止形", "sentence_index": 7, "explanations": {"ごみを分ける": "正解。終止形で、「時間がある」につながる文になる。", "ごみを分けろ": "命令形。「分けろ時間がある」とは続かず、文が成り立たない。", "ごみを分けず": "否定の連用形。分けないという意味になり、時間の説明が成り立たない。", "ごみを分けたく": "希望の連用形。「分けたく時間がある」とは続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
