INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37954, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「先生が手伝ってくれた」で、先生が手伝う主語を示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、手伝う主語を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、「先生と手伝ってくれた」では主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示し、動詞の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「先生が手伝ってくれた」で、先生が手伝う主語を示す。", "で": "「で」は手段や場所を示し、手伝う主語を示せないので合わない。", "と": "「と」は並列や相手を示し、「先生と手伝ってくれた」では主語にならない。", "の": "「の」は所属や修飾を示し、動詞の主語にはならない。"}, "error_tags": {"で": "手段・場所", "と": "並列・相手", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37954, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "誰かが、私のために、何かをします。", "primary_collocate": null, "pronunciation": "てつだってくれる", "ipa": "tetsɯdatte kɯɾeɾɯ", "syllable_count": 8, "sentences": [{"text": "引っ越しの日に、友だちが荷物を運ぶのを手伝ってくれた。", "target_word": "手伝ってくれた", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]に、友[とも]だちが荷物[にもつ]を運[はこ]ぶのを手伝[てつだ]ってくれた。", "sentence_source": "generated"}, {"text": "弟は毎日、夕食の後に皿を洗うのを手伝ってくれます。", "target_word": "手伝ってくれます", "complexity_tier": "T3", "furigana": "弟[おとうと]は毎日[まいにち]、夕食[ゆうしょく]の後[あと]に皿[さら]を洗[あら]うのを手伝[てつだ]ってくれます。", "sentence_source": "generated"}, {"text": "宿題が多くて困っていたら、姉が手伝ってくれました。", "target_word": "手伝ってくれました", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が多[おお]くて困[こま]っていたら、姉[あね]が手伝[てつだ]ってくれました。", "sentence_source": "generated"}, {"text": "重い荷物を持っていると、知らない人が手伝ってくれた。", "target_word": "手伝ってくれた", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を持[も]っていると、知[し]らない人[ひと]が手伝[てつだ]ってくれた。", "sentence_source": "generated"}, {"text": "明日の発表の準備を、だれか手伝ってくれませんか。", "target_word": "手伝ってくれません", "complexity_tier": "T3", "furigana": "明日[あした]の発表[はっぴょう]の準備[じゅんび]を、だれか手伝[てつだ]ってくれませんか。", "sentence_source": "generated"}, {"text": "引っ越しを手伝ってくれて、ありがとう。本当に助かったよ。", "target_word": "手伝ってくれて", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しを手伝[てつだ]ってくれて、ありがとう。本当[ほんとう]に助[たす]かったよ。", "sentence_source": "generated"}, {"text": "母は忙しいときでも、私の勉強を手伝ってくれる。", "target_word": "手伝ってくれる", "complexity_tier": "T3", "furigana": "母[はは]は忙[いそが]しいときでも、私[わたし]の勉強[べんきょう]を手伝[てつだ]ってくれる。", "sentence_source": "generated"}, {"text": "先生が手伝ってくれたので、作文が早く終わりました。", "target_word": "手伝ってくれた", "complexity_tier": "T3", "furigana": "先生[せんせい]が手伝[てつだ]ってくれたので、作文[さくぶん]が早[はや]く終[お]わりました。", "sentence_source": "generated"}, {"text": "田中さんが掃除を手伝ってくれたおかげで、部屋がきれいになった。", "target_word": "手伝ってくれた", "complexity_tier": "T3", "furigana": "田中[たなか]さんが掃除[そうじ]を手伝[てつだ]ってくれたおかげで、部屋[へや]がきれいになった。", "sentence_source": "generated"}, {"text": "一人では運べないから、だれか手伝ってくれると嬉しい。", "target_word": "手伝ってくれる", "complexity_tier": "T3", "furigana": "一人[ひとり]では運[はこ]べないから、だれか手伝[てつだ]ってくれると嬉[うれ]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手伝ってくれる", "label": "終止形"}, {"form": "手伝ってくれます", "label": "丁寧形"}, {"form": "手伝ってくれた", "label": "過去形"}, {"form": "手伝ってくれて", "label": "て形"}, {"form": "手伝ってくれない", "label": "否定形"}, {"form": "手伝ってくれました", "label": "丁寧過去形"}], "register": "neutral", "sense_fingerprint": "someone else helps the speaker with a task, a favor done for the speaker''s benefit", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37954, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手伝ってくれた", "is_correct": true, "explanation": "正解。過去の出来事を述べる「友だちが…手伝ってくれた」の形。"}, {"text": "手伝って", "is_correct": false, "explanation": "て形のままでは文が途中で切れ、述語として完結しない。"}, {"text": "手伝ってくれ", "is_correct": false, "explanation": "命令形になり、過去の出来事を述べる文に合わない。"}, {"text": "手伝おう", "is_correct": false, "explanation": "話し手の意志を表す形で、三人称の「友だちが」と合わない。"}], "explanations": {"手伝ってくれた": "正解。過去の出来事を述べる「友だちが…手伝ってくれた」の形。", "手伝って": "て形のままでは文が途中で切れ、述語として完結しない。", "手伝ってくれ": "命令形になり、過去の出来事を述べる文に合わない。", "手伝おう": "話し手の意志を表す形で、三人称の「友だちが」と合わない。"}, "sentence_index": 0, "correct_answer": "手伝ってくれた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "溺れかけた子を、知らない人が手伝ってくれた。", "explanation": "ここは「助ける」の意味。命の危険から救う場面は「手伝う」ではなく「助ける」で表すので合わない。"}, {"text": "信号を無視したら、知らない人が手伝ってくれた。", "explanation": "ここは「注意する」の意味。過ちを指摘して知らせる場面に「手伝う」は合わないので誤り。"}, {"text": "落ち込んでいた私の気持ちを、友だちがそっと手伝ってくれた。", "explanation": "ここは「慰める」（気持ちを支えて元気づける）の意味。「手伝う」は作業を助ける意味なので、気持ちに対しては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37954, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手伝ってくれる", "is_correct": true, "explanation": "正解。「母は…手伝ってくれる」という習慣を述べる非過去形。"}, {"text": "手伝ってくれず", "is_correct": false, "explanation": "連用形の否定で、文を言い切れず述語として完結しない。"}, {"text": "手伝わせ", "is_correct": false, "explanation": "使役形の語幹で、文の述語として完結しない。「母は…手伝わせ」は意味も合わない。"}, {"text": "手伝え", "is_correct": false, "explanation": "命令形になり、「母は」の習慣を述べる文に合わない。"}], "explanations": {"手伝ってくれる": "正解。「母は…手伝ってくれる」という習慣を述べる非過去形。", "手伝ってくれず": "連用形の否定で、文を言い切れず述語として完結しない。", "手伝わせ": "使役形の語幹で、文の述語として完結しない。「母は…手伝わせ」は意味も合わない。", "手伝え": "命令形になり、「母は」の習慣を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "手伝ってくれる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の日、父がスタンドから大きな声で手伝ってくれた。", "explanation": "ここは「応援する」（声をかけて力づける）の意味。「手伝う」は作業を助ける意味で、声援の場面には合わないので誤り。"}, {"text": "私の体調を、母がとても手伝ってくれた。", "explanation": "ここは「心配する」の意味。体調を気にかける気持ちは「手伝う」では表さないので合わない。"}, {"text": "旅立つ私の背中を、友だちが手伝ってくれた。", "explanation": "ここは「見送る」（去っていく人を見届ける）の意味。背中は見届けるもので、「手伝う」では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37954, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、兄が部屋の掃除を手伝ってくれます。", "corrected_sentence": "先週、兄が部屋の掃除を手伝ってくれた。", "error_description": "「先週」の過去の出来事に非過去の「ます」形を使っている。正しくは過去形の「手伝ってくれた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "手伝ってくれます", "is_correct": true, "explanation": "正解。「毎日」の習慣を丁寧に述べる非過去の丁寧形。"}, {"text": "手伝ってくれれば", "is_correct": false, "explanation": "仮定形で、文を言い切れず「毎日」の習慣を述べる述語にならない。"}, {"text": "手伝ってくれて", "is_correct": false, "explanation": "て形のままでは文が完結せず、「毎日」の習慣を述べる述語にならない。"}, {"text": "手伝ってくれました", "is_correct": false, "explanation": "丁寧過去形で、「毎日」の習慣を述べる文の時制と合わない。"}], "correct_form": "手伝ってくれます", "base_form": "手伝ってくれる", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"手伝ってくれます": "正解。「毎日」の習慣を丁寧に述べる非過去の丁寧形。", "手伝ってくれれば": "仮定形で、文を言い切れず「毎日」の習慣を述べる述語にならない。", "手伝ってくれて": "て形のままでは文が完結せず、「毎日」の習慣を述べる述語にならない。", "手伝ってくれました": "丁寧過去形で、「毎日」の習慣を述べる文の時制と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37954, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹が買い物に手伝ってくれた。", "corrected_sentence": "妹が買い物を手伝ってくれた。", "error_description": "「手伝う」が取る対象は「を」で示す。「買い物に」の「に」は誤りで、正しくは「買い物を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "手伝ってくれた", "is_correct": true, "explanation": "正解。「先生が…手伝ってくれたので」と、過去の出来事の理由を述べる形。"}, {"text": "手伝ってくれろ", "is_correct": false, "explanation": "命令形の一種で、理由節の述語として合わない。"}, {"text": "手伝ってくれるな", "is_correct": false, "explanation": "禁止の命令形で、過去の出来事を述べる文に合わない。"}, {"text": "手伝ってくれて", "is_correct": false, "explanation": "て形のため「ので」に続かず、文として成り立たない。"}], "correct_form": "手伝ってくれた", "base_form": "手伝ってくれる", "form_label": "過去形", "sentence_index": 7, "explanations": {"手伝ってくれた": "正解。「先生が…手伝ってくれたので」と、過去の出来事の理由を述べる形。", "手伝ってくれろ": "命令形の一種で、理由節の述語として合わない。", "手伝ってくれるな": "禁止の命令形で、過去の出来事を述べる文に合わない。", "手伝ってくれて": "て形のため「ので」に続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37956, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「空を見る」で、見る対象の空を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示し、「見る」の対象を示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。見る対象を示す文にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示し、見る対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「空を見る」で、見る対象の空を示す。", "に": "「に」は到達点や相手を示し、「見る」の対象を示せないので合わない。", "へ": "「へ」は方向を示す。見る対象を示す文にはならない。", "と": "「と」は並列を示し、見る対象を示せないので合わない。"}, "error_tags": {"に": "到達・相手", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37956, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「寝顔を見る」で、見る対象の寝顔を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、見る対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、比べる対象がないので成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「寝顔が見る」では見る動作の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「寝顔を見る」で、見る対象の寝顔を示す。", "と": "「と」は並列や相手を示し、見る対象を示せないので合わない。", "より": "「より」は比較を示し、比べる対象がないので成り立たない。", "が": "「が」は主語を示すが、「寝顔が見る」では見る動作の対象にならない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37956, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目で何かを見ること。", "primary_collocate": null, "pronunciation": "みると", "ipa": "miɾɯto", "syllable_count": 3, "sentences": [{"text": "窓の外を見ると、雪が降っていました。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]を見[み]ると、雪[ゆき]が降[ふ]っていました。", "sentence_source": "generated"}, {"text": "空を見ると、大きな虹が出ていた。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "空[そら]を見[み]ると、大[おお]きな虹[にじ]が出[で]ていた。", "sentence_source": "generated"}, {"text": "時計を見ると、もう十時でした。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "時計[とけい]を見[み]ると、もう十時[じゅうじ]でした。", "sentence_source": "generated"}, {"text": "箱の中を見ると、小さな猫が寝ていた。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]を見[み]ると、小[ちい]さな猫[ねこ]が寝[ね]ていた。", "sentence_source": "generated"}, {"text": "地図を見ると、駅はここからとても近いと分かる。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、駅[えき]はここからとても近[ちか]いと分[わ]かる。", "sentence_source": "generated"}, {"text": "鏡を見ると、顔にご飯がついていた。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "鏡[かがみ]を見[み]ると、顔[かお]にご飯[はん]がついていた。", "sentence_source": "generated"}, {"text": "高い山の上から見ると、町は小さな箱のようだ。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "高[たか]い山[やま]の上[うえ]から見[み]ると、町[まち]は小[ちい]さな箱[はこ]のようだ。", "sentence_source": "generated"}, {"text": "子どもの寝顔を見ると、一日の疲れがなくなります。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "子[こ]どもの寝顔[ねがお]を見[み]ると、一日[いちにち]の疲[つか]れがなくなります。", "sentence_source": "generated"}, {"text": "父の手を見ると、長い仕事の苦労が分かる。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "父[ちち]の手[て]を見[み]ると、長[なが]い仕事[しごと]の苦労[くろう]が分[わ]かる。", "sentence_source": "generated"}, {"text": "古い写真を見ると、いつも夏休みを思い出す。", "target_word": "見ると", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を見[み]ると、いつも夏休[なつやす]みを思[おも]い出[だ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見る", "label": "終止形"}, {"form": "見ると", "label": "条件形"}, {"form": "見て", "label": "て形"}, {"form": "見た", "label": "過去形"}, {"form": "見ない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "when one looks at something with the eyes, what is seen or noticed follows as the result", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37956, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見ると", "is_correct": true, "explanation": "正解。「見ると」は見た結果、雪が降っていたと続く条件の形。"}, {"text": "見ろ", "is_correct": false, "explanation": "命令形で、後ろの「雪が降っていました」と文として続かない。"}, {"text": "見ます", "is_correct": false, "explanation": "丁寧な非過去形で、「見ます、雪が降っていました」と時制・文の続き方が合わない。"}, {"text": "見よう", "is_correct": false, "explanation": "意志の形で、見た結果の雪の情景と続かない。"}], "explanations": {"見ると": "正解。「見ると」は見た結果、雪が降っていたと続く条件の形。", "見ろ": "命令形で、後ろの「雪が降っていました」と文として続かない。", "見ます": "丁寧な非過去形で、「見ます、雪が降っていました」と時制・文の続き方が合わない。", "見よう": "意志の形で、見た結果の雪の情景と続かない。"}, "sentence_index": 0, "correct_answer": "見ると"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアを見ると、ひんやりと冷たかった。", "explanation": "ここは「触る」の意味。冷たさは触って分かるもので、見て分かるとは言わないので合わない。"}, {"text": "花を見ると、甘い香りがした。", "explanation": "ここは「嗅ぐ」の意味。香りは見ても分からないので、「見る」では表せない。"}, {"text": "スープを見ると、ほどよい塩味がした。", "explanation": "ここは「味わう」（舌で味を感じる）の意味。目で見ても味は分からないので、「見る」では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37956, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見ると", "is_correct": true, "explanation": "正解。「高い山の上から見ると」で、視点から見た結果の町の様子を述べる条件の形。"}, {"text": "見なさい", "is_correct": false, "explanation": "命令形で、「町は小さな箱のようだ」と続く条件節にならない。"}, {"text": "見るな", "is_correct": false, "explanation": "禁止の命令形で、条件節として成り立たない。"}, {"text": "見たい", "is_correct": false, "explanation": "願望の形で、「見たい、町は…」と文の条件節として続かない。"}], "explanations": {"見ると": "正解。「高い山の上から見ると」で、視点から見た結果の町の様子を述べる条件の形。", "見なさい": "命令形で、「町は小さな箱のようだ」と続く条件節にならない。", "見るな": "禁止の命令形で、条件節として成り立たない。", "見たい": "願望の形で、「見たい、町は…」と文の条件節として続かない。"}, "sentence_index": 6, "correct_answer": "見ると"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ペンを見ると、字が書けた。", "explanation": "ここは「書く」（ペンで字を書く）の意味。見ただけでは字は書けないので、「見る」では合わない。"}, {"text": "太鼓を見ると、大きな音が響いた。", "explanation": "ここは「叩く」の意味。音が出るのは叩いたときで、見ただけでは音は出ないので合わない。"}, {"text": "ボタンを見ると、ドアが開いた。", "explanation": "ここは「押す」の意味。ドアが開くのはボタンを押す動作によるもので、見るだけでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37956, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の外に見ると、もう夜が明けていた。", "corrected_sentence": "窓の外を見ると、もう夜が明けていた。", "error_description": "「見る」は目的語に「を」を取る。「窓の外に」の「に」は誤りで、正しくは「窓の外を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見ると", "is_correct": true, "explanation": "正解。「空を見ると」で、見た結果に大きな虹が出ていたと続く条件の形。"}, {"text": "見ない", "is_correct": false, "explanation": "否定形で、空を見ていたという条件の文と合わない。"}, {"text": "見ます", "is_correct": false, "explanation": "丁寧な非過去形で、条件節として「見ると」の意味にならない。"}, {"text": "見よう", "is_correct": false, "explanation": "意志の形で、見た結果を述べる条件節にならない。"}], "correct_form": "見ると", "base_form": "見る", "form_label": "条件形", "sentence_index": 1, "explanations": {"見ると": "正解。「空を見ると」で、見た結果に大きな虹が出ていたと続く条件の形。", "見ない": "否定形で、空を見ていたという条件の文と合わない。", "見ます": "丁寧な非過去形で、条件節として「見ると」の意味にならない。", "見よう": "意志の形で、見た結果を述べる条件節にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37956, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕焼けに見ると、一日の疲れが消える。", "corrected_sentence": "夕焼けを見ると、一日の疲れが消える。", "error_description": "誤: 「夕焼けに見ると」／正: 「夕焼けを見ると」。「見る」の対象は「を」で示す。「に」は到達点や相手を示すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見ると", "is_correct": true, "explanation": "正解。「子どもの寝顔を見ると」で、見た結果に疲れがなくなると続く条件の形。"}, {"text": "見ろ", "is_correct": false, "explanation": "命令形で、「疲れがなくなります」と条件として続かない。"}, {"text": "見るな", "is_correct": false, "explanation": "禁止の命令形で、条件節として成り立たない。"}, {"text": "見ます", "is_correct": false, "explanation": "丁寧形で、条件を表す「と」がないため「見ます、」では続かない。"}], "correct_form": "見ると", "base_form": "見る", "form_label": "条件形", "sentence_index": 7, "explanations": {"見ると": "正解。「子どもの寝顔を見ると」で、見た結果に疲れがなくなると続く条件の形。", "見ろ": "命令形で、「疲れがなくなります」と条件として続かない。", "見るな": "禁止の命令形で、条件節として成り立たない。", "見ます": "丁寧形で、条件を表す「と」がないため「見ます、」では続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37958, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ビンを洗う」で、洗う対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「ビンに水で洗う」では場所や相手の意味になり、洗う対象が示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、洗う動作の対象にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表すので、ビンを道具として洗うことになり不自然。"}], "correct_answer": "を", "explanations": {"を": "「ビンを洗う」で、洗う対象を表す。", "に": "「ビンに水で洗う」では場所や相手の意味になり、洗う対象が示せない。", "へ": "「へ」は移動の方向を表すので、洗う動作の対象にはならない。", "で": "「で」は手段を表すので、ビンを道具として洗うことになり不自然。"}, "error_tags": {"を": "対象", "に": "場所・相手", "へ": "方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37958, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ビンを入れる」で、入れる対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「ビンが入れる」ではビンが動作主になり、入れる対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「ビンで入れる」は手段の意味になり、この文では不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、ビンから入れるという意味になり不自然。"}], "correct_answer": "を", "explanations": {"を": "「ビンを入れる」で、入れる対象を表す。", "が": "「ビンが入れる」ではビンが動作主になり、入れる対象にならない。", "で": "「ビンで入れる」は手段の意味になり、この文では不自然。", "から": "「から」は起点を表すので、ビンから入れるという意味になり不自然。"}, "error_tags": {"を": "対象", "が": "主語", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37958, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もえるごみではなく、もやすことができない、かたいごみのことです。", "primary_collocate": null, "pronunciation": "びん", "ipa": "biɴ", "syllable_count": 2, "sentences": [{"text": "ビンは燃えないごみの日に出します。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "ビンは燃[も]えないごみの日[ひ]に出[だ]します。", "sentence_source": "generated"}, {"text": "空のビンを水で洗ってから捨てた。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "空[から]のビンを水[みず]で洗[あら]ってから捨[す]てた。", "sentence_source": "generated"}, {"text": "ビンは燃やせないので、燃えるごみには入れません。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "ビンは燃[も]やせないので、燃[も]えるごみには入[い]れません。", "sentence_source": "generated"}, {"text": "割れたビンは危ないから、紙に包んで捨てよう。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "割[わ]れたビンは危[あぶ]ないから、紙[かみ]に包[つつ]んで捨[す]てよう。", "sentence_source": "generated"}, {"text": "食べ終わったジャムのビンは、ふたを外してから出してください。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "食[た]べ終[お]わったジャムのビンは、ふたを外[はず]してから出[だ]してください。", "sentence_source": "generated"}, {"text": "兄はビンを出す前に、ふたを外して中を洗った。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "兄[あに]はビンを出[だ]す前[まえ]に、ふたを外[はず]して中[なか]を洗[あら]った。", "sentence_source": "generated"}, {"text": "このビンは重いので、袋を二つに分けた。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "このビンは重[おも]いので、袋[ふくろ]を二[ふた]つに分[わ]けた。", "sentence_source": "generated"}, {"text": "燃えるごみの袋にビンを入れてはいけません。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "燃[も]えるごみの袋[ふくろ]にビンを入[い]れてはいけません。", "sentence_source": "generated"}, {"text": "火曜日はビンとかんを集める日です。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "火曜日[かようび]はビンとかんを集[あつ]める日[ひ]です。", "sentence_source": "generated"}, {"text": "古いビンを捨てる前に、ラベルをはがした。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "古[ふる]いビンを捨[す]てる前[まえ]に、ラベルをはがした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ビン", "label": "基本形"}, {"form": "ビンは", "label": "主題"}, {"form": "ビンを", "label": "目的語"}, {"form": "ビンが", "label": "主語"}], "register": "neutral", "sense_fingerprint": "燃えないごみとして捨てる、ガラスのびん", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37958, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ビン", "is_correct": true, "explanation": "燃えないごみの日に出す、ガラスのびんを指す。文の主語として自然。"}, {"text": "燃えるごみ", "is_correct": false, "explanation": "燃えるごみは燃えないごみの日には出さないので、文が成り立たない。"}, {"text": "生ごみ", "is_correct": false, "explanation": "生ごみは燃えるごみに入れるもので、燃えないごみの日に出すとする文と矛盾する。"}, {"text": "紙くず", "is_correct": false, "explanation": "紙くずは燃えるごみに分類されるので、燃えないごみの日に出すとする文と合わない。"}], "explanations": {"ビン": "燃えないごみの日に出す、ガラスのびんを指す。文の主語として自然。", "燃えるごみ": "燃えるごみは燃えないごみの日には出さないので、文が成り立たない。", "生ごみ": "生ごみは燃えるごみに入れるもので、燃えないごみの日に出すとする文と矛盾する。", "紙くず": "紙くずは燃えるごみに分類されるので、燃えないごみの日に出すとする文と合わない。"}, "sentence_index": 0, "correct_answer": "ビン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は弟の頭にビンを食らわせた。", "explanation": "ここは〈ビンタ〉の意味の取り違え。ビンタは平手で打つことで、容器のビンとは別の語なので誤り。"}, {"text": "ジュースのビンは、缶切りで開けてから中身を出す。", "explanation": "ここは〈缶〉の感覚。缶は缶切りで開けるが、ガラスのビンは栓抜きで開けるので合わない。"}, {"text": "ビンは水を入れてつぶしてから、燃えないごみに出してください。", "explanation": "ここは〈ペットボトル〉の感覚で使っている。つぶして出すのはペットボトルで、ガラスのビンは割れるのでつぶさない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37958, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ビン", "is_correct": true, "explanation": "重い容器として、このビンは重いので袋を分けたという文に合う。"}, {"text": "時間", "is_correct": false, "explanation": "時間は重さを持たないので、「この時間は重い」と袋を分ける文脈に合わない。"}, {"text": "意見", "is_correct": false, "explanation": "意見は物理的に重さを持たず、袋を二つに分ける理由にならない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は物理的な重さを持たず、袋を分けた行動とつながらない。"}], "explanations": {"ビン": "重い容器として、このビンは重いので袋を分けたという文に合う。", "時間": "時間は重さを持たないので、「この時間は重い」と袋を分ける文脈に合わない。", "意見": "意見は物理的に重さを持たず、袋を二つに分ける理由にならない。", "夢": "夢は物理的な重さを持たず、袋を分けた行動とつながらない。"}, "sentence_index": 6, "correct_answer": "ビン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉛筆のビンは、先を削ってから筆箱に入れる。", "explanation": "ここは〈筆記具〉の感覚。鉛筆は先を削って使うが、硬いビンは削れないので合わない。"}, {"text": "ビンが三つ並んだら、景品をもらえる。", "explanation": "ここは〈ビンゴ〉の意味で、ゲームの「ビンゴ」を指す。容器のビンの意味ではないので誤り。"}, {"text": "ビンは、中身を出してから平らにして出す。", "explanation": "ここは〈段ボール〉の感覚。段ボールは平らにして出すが、ガラスのビンは平らにできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37958, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空のビンに水で洗ってから、燃えないごみに出した。", "corrected_sentence": "空のビンを水で洗ってから、燃えないごみに出した。", "error_description": "「洗う」の対象を表す「を」が「に」になっている。正しくは「ビンを洗う」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37958, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いビンで捨てる前に、ラベルを全部はがした。", "corrected_sentence": "古いビンを捨てる前に、ラベルを全部はがした。", "error_description": "「捨てる」の対象を表す「を」が「で」になっている。正しくは「ビンを捨てる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37959, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ビンは店に返すと」で、ビンを主題として示す。"}, {"text": "で", "is_correct": false, "explanation": "「ビンで店に返す」は手段の意味になり、ビンを返す対象として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ビンの位置関係を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、ビンを主題として示す文に合わない。"}], "correct_answer": "は", "explanations": {"は": "「ビンは店に返すと」で、ビンを主題として示す。", "で": "「ビンで店に返す」は手段の意味になり、ビンを返す対象として不自然。", "へ": "「へ」は方向を表すので、ビンの位置関係を示せない。", "から": "「から」は起点を表すので、ビンを主題として示す文に合わない。"}, "error_tags": {"は": "主題", "で": "手段", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37959, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ビンを持って来る」で、持って来る対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「ビンに持って来る」では持って来る対象を示せず、「に」は方向や到達点を表すので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「ビンの持って来ると」は名詞を修飾する形で、動詞の対象にならないので文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「ビンより持って来る」は比較の意味になり、持って来る対象を示さない。"}], "correct_answer": "を", "explanations": {"を": "「ビンを持って来る」で、持って来る対象を表す。", "に": "「ビンに持って来る」では持って来る対象を示せず、「に」は方向や到達点を表すので不自然。", "の": "「ビンの持って来ると」は名詞を修飾する形で、動詞の対象にならないので文が成り立たない。", "より": "「ビンより持って来る」は比較の意味になり、持って来る対象を示さない。"}, "error_tags": {"を": "対象", "に": "方向・帰着", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37959, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "資源として再利用できる、ガラスや金属などでできた容器や包装の総称。", "primary_collocate": null, "pronunciation": "びん", "ipa": "biɴ", "syllable_count": 2, "sentences": [{"text": "ビンは資源として回収され、また新しいビンになる。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "ビンは資源[しげん]として回収[かいしゅう]され、また新[あたら]しいビンになる。", "sentence_source": "generated"}, {"text": "飲み終わったビンは店に返すと、再利用される。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "飲[の]み終[お]わったビンは店[みせ]に返[かえ]すと、再利用[さいりよう]される。", "sentence_source": "generated"}, {"text": "ガラスのビンは何度も洗って使えるので、環境にやさしい。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "ガラスのビンは何度[なんど]も洗[あら]って使[つか]えるので、環境[かんきょう]にやさしい。", "sentence_source": "generated"}, {"text": "町の回収所に、色別にビンを分けて出した。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "町[まち]の回収所[かいしゅうじょ]に、色別[いろべつ]にビンを分[わ]けて出[だ]した。", "sentence_source": "generated"}, {"text": "祖父の家では、牛乳のビンを毎朝店の人が回収していく。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "祖父[そふ]の家[いえ]では、牛乳[ぎゅうにゅう]のビンを毎朝[まいあさ]店[みせ]の人[ひと]が回収[かいしゅう]していく。", "sentence_source": "generated"}, {"text": "資源ごみのビンはふたを取ってから出してください。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "資源[しげん]ごみのビンはふたを取[と]ってから出[だ]してください。", "sentence_source": "generated"}, {"text": "ビンをリサイクルすれば、ごみが少なくなる。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "ビンをリサイクルすれば、ごみが少[すく]なくなる。", "sentence_source": "generated"}, {"text": "この店では、ビンを持って来ると少しお金が戻る。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "この店[みせ]では、ビンを持[も]って来[く]ると少[すこ]しお金[かね]が戻[もど]る。", "sentence_source": "generated"}, {"text": "使ったビンを洗って、もう一度ジュースを入れた。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "使[つか]ったビンを洗[あら]って、もう一度[いちど]ジュースを入[い]れた。", "sentence_source": "generated"}, {"text": "昔はビールのビンを酒屋に返すのがふつうだった。", "target_word": "ビン", "complexity_tier": "T3", "furigana": "昔[むかし]はビールのビンを酒屋[さかや]に返[かえ]すのがふつうだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ビン", "label": "基本形"}, {"form": "ビンを", "label": "目的語"}, {"form": "ビンは", "label": "主題"}, {"form": "ビンに", "label": "方向・結果"}], "register": "neutral", "sense_fingerprint": "回収して再利用できる資源としてのガラスのびん", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37959, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ビン", "is_correct": true, "explanation": "資源として回収され、新しいビンになるという文の主体として自然。"}, {"text": "生ごみ", "is_correct": false, "explanation": "生ごみは資源として回収されて新しい生ごみになるとは言えず、文が成り立たない。"}, {"text": "燃えるごみ", "is_correct": false, "explanation": "燃えるごみは資源として回収されない。新しい燃えるごみになるという文も不自然。"}, {"text": "粗大ごみ", "is_correct": false, "explanation": "粗大ごみを資源として回収して新しい粗大ごみにする、という内容は文脈に合わない。"}], "explanations": {"ビン": "資源として回収され、新しいビンになるという文の主体として自然。", "生ごみ": "生ごみは資源として回収されて新しい生ごみになるとは言えず、文が成り立たない。", "燃えるごみ": "燃えるごみは資源として回収されない。新しい燃えるごみになるという文も不自然。", "粗大ごみ": "粗大ごみを資源として回収して新しい粗大ごみにする、という内容は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ビン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牛乳のビンは、切り開いてから洗う。", "explanation": "ここは〈紙パック〉の感覚。紙パックは切り開いて洗うが、ガラスのビンは切り開けないので合わない。"}, {"text": "ビールのビンは、缶切りで開けてから飲む。", "explanation": "ここは〈缶〉の感覚の取り違え。缶は缶切りで開けるが、ビールのビンは栓抜きで開けるので合わない。"}, {"text": "ゲーム大会で、ビンを三つ揃えて一等をもらった。", "explanation": "ここは〈ビンゴ〉の意味の取り違え。ゲームのビンゴは数字を揃える遊びで、容器のビンとは別の語なので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37959, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ビン", "is_correct": true, "explanation": "ビンをリサイクルすれば、ごみが少なくなるという文に合う。"}, {"text": "夢", "is_correct": false, "explanation": "夢はリサイクルできないので、「夢をリサイクルすれば」は成り立たない。"}, {"text": "時間", "is_correct": false, "explanation": "時間はリサイクルの対象にならず、ごみが減る文脈と合わない。"}, {"text": "愛", "is_correct": false, "explanation": "愛はリサイクルの対象にならず、ごみが減る文脈と合わない。"}], "explanations": {"ビン": "ビンをリサイクルすれば、ごみが少なくなるという文に合う。", "夢": "夢はリサイクルできないので、「夢をリサイクルすれば」は成り立たない。", "時間": "時間はリサイクルの対象にならず、ごみが減る文脈と合わない。", "愛": "愛はリサイクルの対象にならず、ごみが減る文脈と合わない。"}, "sentence_index": 6, "correct_answer": "ビン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は弟にビンを一発食らわせた。", "explanation": "ここは〈ビンタ〉の意味の取り違え。平手打ちはビンとは言わない。"}, {"text": "ジャムのビンは、最後まで絞って使い切る。", "explanation": "ここは〈チューブ〉の感覚。チューブは絞って使うが、硬いビンは絞れないので合わない。"}, {"text": "段ボールのビンは、中身を出してから平らに折りたたむ。", "explanation": "ここは〈箱〉の感覚。箱は折りたたんで出せるが、ガラスのビンは折りたためないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37959, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ビンを資源として回収され、新しいビンに作り直される。", "corrected_sentence": "ビンは資源として回収され、新しいビンに作り直される。", "error_description": "主題を示す「は」が「を」になっている。「ビンを回収され」では、ビンが回収の対象になり文意が崩れる。正しくは「ビンは回収され」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37959, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ビンをリサイクルしれば、ごみがずっと少なくなる。", "corrected_sentence": "ビンをリサイクルすれば、ごみがずっと少なくなる。", "error_description": "サ変動詞「する」の仮定形は「すれば」で、「しれば」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
