INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37960, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "まちがっていないこと。ただしいこと。", "primary_collocate": null, "pronunciation": "ただしい", "ipa": "tadaɕiː", "syllable_count": 4, "sentences": [{"text": "この答えは正しいです。", "target_word": "正しい", "complexity_tier": "T3", "furigana": "この答[こた]えは正[ただ]しいです。", "sentence_source": "generated"}, {"text": "正しい道を教えてくれて、ありがとう。", "target_word": "正しい", "complexity_tier": "T3", "furigana": "正[ただ]しい道[みち]を教[おし]えてくれて、ありがとう。", "sentence_source": "generated"}, {"text": "先生は私の答えが正しいかどうかを確かめた。", "target_word": "正しい", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の答[こた]えが正[ただ]しいかどうかを確[たし]かめた。", "sentence_source": "generated"}, {"text": "日本語の正しい書き方を、辞書で調べた。", "target_word": "正しい", "complexity_tier": "T3", "furigana": "日本語[にほんご]の正[ただ]しい書[か]き方[かた]を、辞書[じしょ]で調[しら]べた。", "sentence_source": "generated"}, {"text": "彼の話は正しかったので、みんなが信じた。", "target_word": "正しかった", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は正[ただ]しかったので、みんなが信[しん]じた。", "sentence_source": "generated"}, {"text": "ラジオの正しい時刻に合わせて、時計を直した。", "target_word": "正しい", "complexity_tier": "T3", "furigana": "ラジオの正[ただ]しい時刻[じこく]に合[あ]わせて、時計[とけい]を直[なお]した。", "sentence_source": "generated"}, {"text": "正しい姿勢で座ると、背中が痛くならない。", "target_word": "正しい", "complexity_tier": "T3", "furigana": "正[ただ]しい姿勢[しせい]で座[すわ]ると、背中[せなか]が痛[いた]くならない。", "sentence_source": "generated"}, {"text": "自分が正しいと思っても、人の意見を聞こう。", "target_word": "正しい", "complexity_tier": "T3", "furigana": "自分[じぶん]が正[ただ]しいと思[おも]っても、人[ひと]の意見[いけん]を聞[き]こう。", "sentence_source": "generated"}, {"text": "薬は正しく使わないと、体に悪いです。", "target_word": "正しく", "complexity_tier": "T3", "furigana": "薬[くすり]は正[ただ]しく使[つか]わないと、体[からだ]に悪[わる]いです。", "sentence_source": "generated"}, {"text": "正しければ丸を、間違いならバツを書いてください。", "target_word": "正しければ", "complexity_tier": "T3", "furigana": "正[ただ]しければ丸[まる]を、間違[まちが]いならバツを書[か]いてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "正しい", "label": "基本形"}, {"form": "正しく", "label": "連用形"}, {"form": "正しかった", "label": "過去形"}, {"form": "正しくない", "label": "否定形"}, {"form": "正しければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "答え・方法・行いなどがまちがっていない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37960, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正しい", "is_correct": true, "explanation": "「この答えは正しいです」で、述語として「です」に続く形容詞の基本形。"}, {"text": "正しく", "is_correct": false, "explanation": "連用形の副詞形で、「です」に続けて述語にすることができない。"}, {"text": "正しかろう", "is_correct": false, "explanation": "推量の形で、「です」に続けると文が成り立たない。"}, {"text": "正しけれ", "is_correct": false, "explanation": "文語的な仮定の形で、現代語の「です」の文には合わない。"}], "explanations": {"正しい": "「この答えは正しいです」で、述語として「です」に続く形容詞の基本形。", "正しく": "連用形の副詞形で、「です」に続けて述語にすることができない。", "正しかろう": "推量の形で、「です」に続けると文が成り立たない。", "正しけれ": "文語的な仮定の形で、現代語の「です」の文には合わない。"}, "sentence_index": 0, "correct_answer": "正しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は正しく辛い。", "explanation": "ここは〈程度が強い〉の感覚。正しいは答えや方法が誤っていないことを表し、味の強さには使わないので誤り。"}, {"text": "空が正しく晴れた。", "explanation": "ここは〈はっきり〉の感覚の取り違え。正しく は答えや方法について使い、天気には使わない。"}, {"text": "このかばんは正しく大きい。", "explanation": "ここは〈ちょうどの〉の意味。正しいは答えや方法が誤っていないことを表し、大きさの程度には使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37960, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正しい", "is_correct": true, "explanation": "「正しい姿勢」で、名詞「姿勢」を修飾する連体形。"}, {"text": "正しければ", "is_correct": false, "explanation": "仮定形で、名詞「姿勢」を修飾できない。"}, {"text": "正しさ", "is_correct": false, "explanation": "名詞化した形で、「正しさ姿勢」では成り立たない。"}, {"text": "正しかったら", "is_correct": false, "explanation": "仮定の形で、名詞「姿勢」を修飾する形にはならない。"}], "explanations": {"正しい": "「正しい姿勢」で、名詞「姿勢」を修飾する連体形。", "正しければ": "仮定形で、名詞「姿勢」を修飾できない。", "正しさ": "名詞化した形で、「正しさ姿勢」では成り立たない。", "正しかったら": "仮定の形で、名詞「姿勢」を修飾する形にはならない。"}, "sentence_index": 6, "correct_answer": "正しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "清潔なタオルの代わりに、正しいタオルで手を拭いた。", "explanation": "ここは〈衛生的〉の意味の取り違え。正しいは答えや方法の正誤に使い、きれいさには使わないので誤り。"}, {"text": "右手の代わりに、正しい手で箸を持った。", "explanation": "ここは〈利き手〉の感覚。正しいは答えや方法の正誤を表し、手の左右には使わないので誤り。"}, {"text": "雨が正しく降っている。", "explanation": "ここは〈激しく〉の感覚の取り違え。正しく は降り方の強さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37960, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の説明は正しいかったので、みんなが納得した。", "corrected_sentence": "彼の説明は正しかったので、みんなが納得した。", "error_description": "形容詞「正しい」の過去形は「正しかった」で、「正しいかった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "正しい", "is_correct": true, "explanation": "連体形で、名詞「道」を修飾している。"}, {"text": "正しく", "is_correct": false, "explanation": "連用形で、名詞を直接修飾することはできない。"}, {"text": "正しいだろう", "is_correct": false, "explanation": "推量の形で、名詞「道」を修飾できず、文が成り立たない。"}, {"text": "正しければ", "is_correct": false, "explanation": "仮定形で、名詞を修飾する形にはならない。"}], "correct_form": "正しい", "base_form": "正しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"正しい": "連体形で、名詞「道」を修飾している。", "正しく": "連用形で、名詞を直接修飾することはできない。", "正しいだろう": "推量の形で、名詞「道」を修飾できず、文が成り立たない。", "正しければ": "仮定形で、名詞を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37960, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "正しく丸を、間違いならバツを付けてください。", "corrected_sentence": "正しければ丸を、間違いならバツを付けてください。", "error_description": "条件を表す「正しければ」が必要なところで、副詞の「正しく」を使っている。「正しく丸を」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "正しい", "is_correct": true, "explanation": "終止形で、「と思う」の前で文の内容を言い切っている。"}, {"text": "正しさ", "is_correct": false, "explanation": "名詞化した形で、動詞「思う」の内容を表す形にはならない。"}, {"text": "正しき", "is_correct": false, "explanation": "文語の連体形で、現代語の「と思っても」の文には不自然。"}, {"text": "正しくて", "is_correct": false, "explanation": "て形で、「と思っても」の前で文が成り立たない。"}], "correct_form": "正しい", "base_form": "正しい", "form_label": "終止形", "sentence_index": 7, "explanations": {"正しい": "終止形で、「と思う」の前で文の内容を言い切っている。", "正しさ": "名詞化した形で、動詞「思う」の内容を表す形にはならない。", "正しき": "文語の連体形で、現代語の「と思っても」の文には不自然。", "正しくて": "て形で、「と思っても」の前で文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37962, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ある", "is_correct": true, "explanation": "有る（ある）は、存在しないことを表す「無い」の対義語。"}, {"text": "消える", "is_correct": false, "explanation": "消えるは存在がなくなる動作で、無いの対義語ではない。"}, {"text": "残る", "is_correct": false, "explanation": "残るは存在し続ける意味で、無いの対義語として辞書に載らない。"}, {"text": "来る", "is_correct": false, "explanation": "来るは場所への移動の意味で、無いの対義語ではない。"}], "correct_answer": "ある", "explanations": {"ある": "有る（ある）は、存在しないことを表す「無い」の対義語。", "消える": "消えるは存在がなくなる動作で、無いの対義語ではない。", "残る": "残るは存在し続ける意味で、無いの対義語として辞書に載らない。", "来る": "来るは場所への移動の意味で、無いの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37962, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ある", "is_correct": true, "explanation": "有る（ある）は、存在しないことを表す「無い」の対義語。"}, {"text": "増える", "is_correct": false, "explanation": "増えるは数や量が多くなる意味で、無いの対義語ではない。"}, {"text": "生まれる", "is_correct": false, "explanation": "生まれるは誕生の意味で、存在しない状態の対義語ではない。"}, {"text": "始まる", "is_correct": false, "explanation": "始まるは開始の意味で、無いの対義語として辞書に載らない。"}], "correct_answer": "ある", "explanations": {"ある": "有る（ある）は、存在しないことを表す「無い」の対義語。", "増える": "増えるは数や量が多くなる意味で、無いの対義語ではない。", "生まれる": "生まれるは誕生の意味で、存在しない状態の対義語ではない。", "始まる": "始まるは開始の意味で、無いの対義語として辞書に載らない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37962, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "あるはずのものが存在しない、見当たらない状態。", "primary_collocate": null, "pronunciation": "ない", "ipa": "nai", "syllable_count": 2, "sentences": [{"text": "昨日は財布に入っていたお金が、今日は無かった。", "target_word": "無かった", "complexity_tier": "T3", "furigana": "昨日[きのう]は財布[さいふ]に入[はい]っていたお金[かね]が、今日[きょう]は無[な]かった。", "sentence_source": "generated"}, {"text": "昨日まであった本が、今日は無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "昨日[きのう]まであった本[ほん]が、今日[きょう]は無[な]い。", "sentence_source": "generated"}, {"text": "机の上に置いたかぎが無いので、探しています。", "target_word": "無い", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に置[お]いたかぎが無[な]いので、探[さが]しています。", "sentence_source": "generated"}, {"text": "冷蔵庫にあったケーキが無かったから、弟に聞いた。", "target_word": "無かった", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]にあったケーキが無[な]かったから、弟[おとうと]に聞[き]いた。", "sentence_source": "generated"}, {"text": "さっきまであった傘が無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "さっきまであった傘[かさ]が無[な]い。", "sentence_source": "generated"}, {"text": "店に行ったが、ほしい色はもう無かった。", "target_word": "無かった", "complexity_tier": "T3", "furigana": "店[みせ]に行[い]ったが、ほしい色[いろ]はもう無[な]かった。", "sentence_source": "generated"}, {"text": "駅の前にあった古い店は、もう無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]にあった古[ふる]い店[みせ]は、もう無[な]い。", "sentence_source": "generated"}, {"text": "かばんに入れておいた財布が、無かった。", "target_word": "無かった", "complexity_tier": "T3", "furigana": "かばんに入[い]れておいた財布[さいふ]が、無[な]かった。", "sentence_source": "generated"}, {"text": "去年まであった公園のベンチが、今年は無かった。", "target_word": "無かった", "complexity_tier": "T3", "furigana": "去年[きょねん]まであった公園[こうえん]のベンチが、今年[ことし]は無[な]かった。", "sentence_source": "generated"}, {"text": "朝は庭にあった自転車が、夕方には無くて驚いた。", "target_word": "無くて", "complexity_tier": "T3", "furigana": "朝[あさ]は庭[にわ]にあった自転車[じてんしゃ]が、夕方[ゆうがた]には無[な]くて驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無い", "label": "基本形"}, {"form": "無く", "label": "連用形"}, {"form": "無かった", "label": "過去形"}, {"form": "無くて", "label": "て形"}, {"form": "無ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "あるはずのものが存在しない、見当たらない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37962, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無かった", "is_correct": true, "explanation": "「今日は無かった」で、昨日あったお金が今日は存在しなかったという過去の状態を表す。"}, {"text": "無く", "is_correct": false, "explanation": "連用形で、文末に置いて文を終えることができない。"}, {"text": "無くて", "is_correct": false, "explanation": "て形で、文を言い切れないので「今日は」の後に続かない。"}, {"text": "無ければ", "is_correct": false, "explanation": "仮定形で、文を言い切る形にはならない。"}], "explanations": {"無かった": "「今日は無かった」で、昨日あったお金が今日は存在しなかったという過去の状態を表す。", "無く": "連用形で、文末に置いて文を終えることができない。", "無くて": "て形で、文を言い切れないので「今日は」の後に続かない。", "無ければ": "仮定形で、文を言い切る形にはならない。"}, "sentence_index": 0, "correct_answer": "無かった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社長は昨日、会社に無かったので、会議を延期した。", "explanation": "ここは〈不在〉の意味の取り違え。人については「いない」を使い、「無い」は物事に使うので誤り。"}, {"text": "庭に猫が無かったので、子どもたちは探した。", "explanation": "ここは〈いる〉の感覚の取り違え。動物がいないことは「いない」で表すので、「無い」は合わない。"}, {"text": "教室に子どもが無かったので、先生は困った。", "explanation": "ここは〈いる〉の感覚の取り違え。人がいないことには「いない」を使うので、「無い」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37962, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無い", "is_correct": true, "explanation": "「もう無い」で、店が存在しないことを言い切っている。"}, {"text": "無き", "is_correct": false, "explanation": "文語の連体形で、「もう無き」は現代語の文末として不自然。"}, {"text": "無くて", "is_correct": false, "explanation": "て形で、文を言い切れないので文末に置けない。"}, {"text": "無さ", "is_correct": false, "explanation": "名詞化した形で、「もう無さ」では文が成り立たない。"}], "explanations": {"無い": "「もう無い」で、店が存在しないことを言い切っている。", "無き": "文語の連体形で、「もう無き」は現代語の文末として不自然。", "無くて": "て形で、文を言い切れないので文末に置けない。", "無さ": "名詞化した形で、「もう無さ」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "無い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店長は朝から無くて、お客さんが困った。", "explanation": "ここは〈不在〉の意味の取り違え。人については「いない」を使い、「無い」は物事に使うので誤り。"}, {"text": "庭の犬が無かったので、子どもたちは喜んだ。", "explanation": "ここは〈いる〉の感覚の取り違え。動物がいないことは「いない」で表すので、「無い」は合わない。"}, {"text": "公園に子どもが無かったので、先生は静かに待った。", "explanation": "ここは〈いる〉の感覚の取り違え。人がいないことには「いない」を使うので、「無い」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37962, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冷蔵庫にあったケーキを無かったので、弟に聞いた。", "corrected_sentence": "冷蔵庫にあったケーキが無かったので、弟に聞いた。", "error_description": "「無い」の主語を示す「が」が「を」になっている。正しくは「ケーキが無かった」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無い", "is_correct": true, "explanation": "終止形で、「今日は無い」と文を言い切っている。"}, {"text": "無く", "is_correct": false, "explanation": "連用形で、文末に置いて文を終えることができない。"}, {"text": "無くて", "is_correct": false, "explanation": "て形で、文を言い切れない。"}, {"text": "無ければ", "is_correct": false, "explanation": "仮定形で、文を言い切る形にはならない。"}], "correct_form": "無い", "base_form": "無い", "form_label": "終止形", "sentence_index": 1, "explanations": {"無い": "終止形で、「今日は無い」と文を言い切っている。", "無く": "連用形で、文末に置いて文を終えることができない。", "無くて": "て形で、文を言い切れない。", "無ければ": "仮定形で、文を言い切る形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37962, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝は玄関にあった傘が、夕方には無いくなっていた。", "corrected_sentence": "朝は玄関にあった傘が、夕方には無くなっていた。", "error_description": "形容詞「無い」の連用形は「無く」。「なくなる」の「無く」の部分を「無いく」とするのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無かった", "is_correct": true, "explanation": "過去形で、財布が過去の時点で存在しなかったことを表す。"}, {"text": "無かったら", "is_correct": false, "explanation": "仮定形で、「無かったら」と条件を述べて文が終わらないので、文末には置けない。"}, {"text": "無き", "is_correct": false, "explanation": "文語の連体形で、現代語の述語としては不自然。"}, {"text": "無さそう", "is_correct": false, "explanation": "推量の形で、「無さそう」だけでは文を言い切れず、財布が無いという事実を表せない。"}], "correct_form": "無かった", "base_form": "無い", "form_label": "過去形", "sentence_index": 7, "explanations": {"無かった": "過去形で、財布が過去の時点で存在しなかったことを表す。", "無かったら": "仮定形で、「無かったら」と条件を述べて文が終わらないので、文末には置けない。", "無き": "文語の連体形で、現代語の述語としては不自然。", "無さそう": "推量の形で、「無さそう」だけでは文を言い切れず、財布が無いという事実を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
