INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37964, 3, 'prompt1_core', '{"pos": "助動詞", "semantic_class": "function", "definition": "「だ」は、「です」のやさしい言い方です。文の終わりに使います。", "primary_collocate": null, "pronunciation": "だ", "ipa": "da", "syllable_count": 1, "sentences": [{"text": "これは私の本だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "これは私[わたし]の本[ほん]だ。", "sentence_source": "generated"}, {"text": "今日は日曜日だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "今日[きょう]は日曜日[にちようび]だ。", "sentence_source": "generated"}, {"text": "彼は学生だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "彼[かれ]は学生[がくせい]だ。", "sentence_source": "generated"}, {"text": "あの人は私の先生だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "あの人[ひと]は私[わたし]の先生[せんせい]だ。", "sentence_source": "generated"}, {"text": "ここは静かな図書館だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "ここは静[しず]かな図書館[としょかん]だ。", "sentence_source": "generated"}, {"text": "明日は雨だと思う。", "target_word": "だ", "complexity_tier": "T3", "furigana": "明日[あした]は雨[あめ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "この犬は大きいが、やさしい犬だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "この犬[いぬ]は大[おお]きいが、やさしい犬[いぬ]だ。", "sentence_source": "generated"}, {"text": "駅から近くて、便利な町だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "駅[えき]から近[ちか]くて、便利[べんり]な町[まち]だ。", "sentence_source": "generated"}, {"text": "私の兄は医者だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "私[わたし]の兄[あに]は医者[いしゃ]だ。", "sentence_source": "generated"}, {"text": "窓の外は、もう夜だ。", "target_word": "だ", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]は、もう夜[よる]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "だ", "label": "終止形"}, {"form": "だった", "label": "過去形"}, {"form": "だろう", "label": "推量形"}, {"form": "で", "label": "連用形"}, {"form": "なら", "label": "仮定形"}], "register": "casual", "sense_fingerprint": "名詞のあとに付いて文を言い切る、「です」の普通体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37964, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "だ", "is_correct": true, "explanation": "名詞「本」に付いて「である」と言い切る、「です」の普通体。ここで正しい。"}, {"text": "ます", "is_correct": false, "explanation": "丁寧の助動詞で、動詞の連用形に付く。名詞「本」の後には続かない。"}, {"text": "ない", "is_correct": false, "explanation": "打ち消しの助動詞で、動詞や形容詞に付く。名詞「本」の後には続かない。"}, {"text": "たい", "is_correct": false, "explanation": "願望の助動詞で、動詞の連用形に付く。名詞「本」の後には続かない。"}], "explanations": {"だ": "名詞「本」に付いて「である」と言い切る、「です」の普通体。ここで正しい。", "ます": "丁寧の助動詞で、動詞の連用形に付く。名詞「本」の後には続かない。", "ない": "打ち消しの助動詞で、動詞や形容詞に付く。名詞「本」の後には続かない。", "たい": "願望の助動詞で、動詞の連用形に付く。名詞「本」の後には続かない。"}, "sentence_index": 0, "correct_answer": "だ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ご注文の商品は、明日の午前中の配達だ。", "explanation": "ここは〈です〉の丁寧な言い方（客への連絡）。「だ」は普通体なので、客への文章では使わない。"}, {"text": "先生、明日の授業は休みだ。", "explanation": "ここは〈です〉の丁寧な言い方（目上の人への話）。「だ」は普通体なので、目上の人には使わない。"}, {"text": "ご来場の皆様、出口はあちらだ。", "explanation": "ここは〈です〉の丁寧な言い方（場内の案内）。「だ」は普通体なので、公の案内では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37964, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "だ", "is_correct": true, "explanation": "名詞「犬」に付いて「である」と言い切る、「です」の普通体。ここで正しい。"}, {"text": "せる", "is_correct": false, "explanation": "使役の助動詞で、動詞の未然形に付く。名詞「犬」の後には続かない。"}, {"text": "れる", "is_correct": false, "explanation": "受身や可能の助動詞で、動詞に付く。名詞「犬」の後には続かない。"}, {"text": "ぬ", "is_correct": false, "explanation": "古い打ち消しの助動詞で、動詞に付く。名詞「犬」の後には続かない。"}], "explanations": {"だ": "名詞「犬」に付いて「である」と言い切る、「です」の普通体。ここで正しい。", "せる": "使役の助動詞で、動詞の未然形に付く。名詞「犬」の後には続かない。", "れる": "受身や可能の助動詞で、動詞に付く。名詞「犬」の後には続かない。", "ぬ": "古い打ち消しの助動詞で、動詞に付く。名詞「犬」の後には続かない。"}, "sentence_index": 6, "correct_answer": "だ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お客様へのお知らせ、本日は臨時休業だ。", "explanation": "ここは〈です〉の丁寧な言い方（お知らせ）。「だ」は普通体なので、お客様向けの文章では使わない。"}, {"text": "部長、明日の会議は中止だ。", "explanation": "ここは〈です〉の丁寧な言い方（目上への話）。「だ」は普通体なので、部長には使わない。"}, {"text": "お客様、お会計はこちらだ。", "explanation": "ここは〈です〉の丁寧な言い方（接客）。「だ」は普通体なので、店で客に話す場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37964, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は医者だだと言った。", "corrected_sentence": "彼は医者だと言った。", "error_description": "断定の「だ」を重ねた誤り。「医者だだ」と「だ」が二つ続くのは不自然で、正しくは「医者だと」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37964, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日は休みだたと言った。", "corrected_sentence": "昨日は休みだったと言った。", "error_description": "過去の「だった」を「だた」と誤った。「だ」の過去形は「だった」で、「だた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37966, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「シカを見掛ける」で、見かける対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「シカが」は主語になり、「よく見掛ける」の対象が消えてしまう。"}, {"text": "に", "is_correct": false, "explanation": "「シカによく見掛ける」は不自然で、対象を示す格ではない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、見るものを表す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「シカを見掛ける」で、見かける対象を示す。", "が": "「シカが」は主語になり、「よく見掛ける」の対象が消えてしまう。", "に": "「シカによく見掛ける」は不自然で、対象を示す格ではない。", "へ": "方向を示す「へ」は、見るものを表す文には合わない。"}, "error_tags": {"が": "主語の格", "に": "相手・対象の格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37966, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「歌手を見掛けて」で、見かけた対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「歌手で見掛けて」は成り立たず、対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、見かけた対象には使えない。"}, {"text": "の", "is_correct": false, "explanation": "「歌手の見掛けて」は文法的に不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「歌手を見掛けて」で、見かけた対象を示す。", "で": "「歌手で見掛けて」は成り立たず、対象を示せない。", "から": "起点を示す「から」は、見かけた対象には使えない。", "の": "「歌手の見掛けて」は文法的に不自然。"}, "error_tags": {"で": "手段・場所の格", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37966, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "偶然、人やものが目に入って見えること。", "primary_collocate": null, "pronunciation": "みかける", "ipa": "mikakeɾɯ", "syllable_count": 4, "sentences": [{"text": "駅の近くで、先生を見掛けた。", "target_word": "見掛けた", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くで、先生[せんせい]を見掛[みか]けた。", "sentence_source": "generated"}, {"text": "この辺りでは、野生のシカをよく見掛ける。", "target_word": "見掛ける", "complexity_tier": "T3", "furigana": "この辺[あた]りでは、野生[やせい]のシカをよく見掛[みか]ける。", "sentence_source": "generated"}, {"text": "昨日、友だちが公園を歩いているのを見掛けた。", "target_word": "見掛けた", "complexity_tier": "T3", "furigana": "昨日[きのう]、友[とも]だちが公園[こうえん]を歩[ある]いているのを見掛[みか]けた。", "sentence_source": "generated"}, {"text": "最近、あの店の前で、犬を連れた男の人を見掛けない。", "target_word": "見掛けない", "complexity_tier": "T3", "furigana": "最近[さいきん]、あの店[みせ]の前[まえ]で、犬[いぬ]を連[つ]れた男[おとこ]の人[ひと]を見掛[みか]けない。", "sentence_source": "generated"}, {"text": "朝の電車で、同じ人を見掛けることが多い。", "target_word": "見掛ける", "complexity_tier": "T3", "furigana": "朝[あさ]の電車[でんしゃ]で、同[おな]じ人[ひと]を見掛[みか]けることが多[おお]い。", "sentence_source": "generated"}, {"text": "知らない人が家の前に立っているのを見掛けて、少し心配になった。", "target_word": "見掛けて", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]が家[いえ]の前[まえ]に立[た]っているのを見掛[みか]けて、少[すこ]し心配[しんぱい]になった。", "sentence_source": "generated"}, {"text": "山の道では、リスを見掛けることがある。", "target_word": "見掛ける", "complexity_tier": "T3", "furigana": "山[やま]の道[みち]では、リスを見掛[みか]けることがある。", "sentence_source": "generated"}, {"text": "町で有名な歌手を見掛けて、びっくりした。", "target_word": "見掛けて", "complexity_tier": "T3", "furigana": "町[まち]で有名[ゆうめい]な歌手[かしゅ]を見掛[みか]けて、びっくりした。", "sentence_source": "generated"}, {"text": "田舎では、トラクターを見掛ける機会が多い。", "target_word": "見掛ける", "complexity_tier": "T3", "furigana": "田舎[いなか]では、トラクターを見掛[みか]ける機会[きかい]が多[おお]い。", "sentence_source": "generated"}, {"text": "最近はこのチラシを街でよく見掛ける。", "target_word": "見掛ける", "complexity_tier": "T3", "furigana": "最近[さいきん]はこのチラシを街[まち]でよく見掛[みか]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見掛ける", "label": "終止形"}, {"form": "見掛けます", "label": "丁寧形"}, {"form": "見掛けた", "label": "過去形"}, {"form": "見掛けて", "label": "て形"}, {"form": "見掛けない", "label": "否定形"}], "register": "普通体（日常）", "sense_fingerprint": "人やものを偶然目にする、ふと見かける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37966, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見掛けた", "is_correct": true, "explanation": "正解。「先生を見掛けた」は、駅の近くで偶然目にしたという意味になる。"}, {"text": "沸かした", "is_correct": false, "explanation": "「沸かす」は湯などを熱くすること。人を沸かすとは言えず、文として成り立たない。"}, {"text": "煮込んだ", "is_correct": false, "explanation": "「煮込む」は食材を長く煮ること。先生を煮込むという内容は意味が通らない。"}, {"text": "乾かした", "is_correct": false, "explanation": "「乾かす」は濡れたものを乾燥させること。先生を乾かすとは言わない。"}], "explanations": {"見掛けた": "正解。「先生を見掛けた」は、駅の近くで偶然目にしたという意味になる。", "沸かした": "「沸かす」は湯などを熱くすること。人を沸かすとは言えず、文として成り立たない。", "煮込んだ": "「煮込む」は食材を長く煮ること。先生を煮込むという内容は意味が通らない。", "乾かした": "「乾かす」は濡れたものを乾燥させること。先生を乾かすとは言わない。"}, "sentence_index": 0, "correct_answer": "見掛けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日、駅前で友だちを見掛ける約束をした。", "explanation": "ここは〈会う〉の意味。前もって約束して会うことには「見掛ける」は使わず、偶然目に入ったときに使う。"}, {"text": "新聞の記事を隅々まで見掛けてから、会議に出た。", "explanation": "ここは〈読む・目を通す〉の意味。隅々まで意図して読む行為は、偶然目にするという「見掛ける」とは合わない。"}, {"text": "研究者は、鳥の行動を一年間見掛けて記録した。", "explanation": "ここは〈観察する〉の意味。計画して続けて見る観察には「見掛ける」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37966, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見掛ける", "is_correct": true, "explanation": "正解。「リスを見掛けることがある」で、山道で偶然リスを目にすることがあるという意味になる。"}, {"text": "磨く", "is_correct": false, "explanation": "「磨く」は表面をこすって光らせること。リスを磨くという文は不自然。"}, {"text": "砕く", "is_correct": false, "explanation": "「砕く」は固いものを細かくすること。生きたリスを砕くという内容は合わない。"}, {"text": "織る", "is_correct": false, "explanation": "「織る」は糸で布を作ること。リスを織るとは言えない。"}], "explanations": {"見掛ける": "正解。「リスを見掛けることがある」で、山道で偶然リスを目にすることがあるという意味になる。", "磨く": "「磨く」は表面をこすって光らせること。リスを磨くという文は不自然。", "砕く": "「砕く」は固いものを細かくすること。生きたリスを砕くという内容は合わない。", "織る": "「織る」は糸で布を作ること。リスを織るとは言えない。"}, "sentence_index": 6, "correct_answer": "見掛ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜どおし、病室で赤ちゃんを見掛けて、そばに付いていた。", "explanation": "ここは〈見守る〉の意味。ずっとそばで気にかけて見守ることは「見守る」で、偶然目に入る「見掛ける」とは合わない。"}, {"text": "届いた部品を一つずつ見掛けて、点検した。", "explanation": "ここは〈点検する〉の意味。一つずつ確かめる行為は「見掛ける」とは言わない。"}, {"text": "夕暮れの海を三時間ほど見掛けて、ゆっくり過ごした。", "explanation": "ここは〈眺める〉の意味。長い時間ゆっくり味わって見ることは「眺める」で、偶然目に入る「見掛ける」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37966, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "図書館の前で、昔の同級生に見掛けた。", "corrected_sentence": "図書館の前で、昔の同級生を見掛けた。", "error_description": "「見掛ける」は見たもの（対象）を「を」で示す。「に」は誤りで、正しくは「同級生を見掛けた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見掛ける", "is_correct": true, "explanation": "正解。終止形で、習慣的な事柄を述べている。"}, {"text": "見掛けて", "is_correct": false, "explanation": "て形。文末に置けず、「よく」の習慣を述べる文が成り立たない。"}, {"text": "見掛けず", "is_correct": false, "explanation": "連用形。文末に置けず、文が成り立たない。"}, {"text": "見掛けろ", "is_correct": false, "explanation": "命令形。「よく」の述語として平叙文に使えず、文が成り立たない。"}], "correct_form": "見掛ける", "base_form": "見掛ける", "form_label": "終止形", "sentence_index": 1, "explanations": {"見掛ける": "正解。終止形で、習慣的な事柄を述べている。", "見掛けて": "て形。文末に置けず、「よく」の習慣を述べる文が成り立たない。", "見掛けず": "連用形。文末に置けず、文が成り立たない。", "見掛けろ": "命令形。「よく」の述語として平叙文に使えず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37966, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、川沿いの道で珍しい鳥を見掛ける。", "corrected_sentence": "昨日、川沿いの道で珍しい鳥を見掛けた。", "error_description": "「昨日」という過去の出来事なので過去形「見掛けた」が正しい。現在形「見掛ける」は時制が合わない誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見掛けて", "is_correct": true, "explanation": "正解。て形で、「びっくりした」へつながる文になる。"}, {"text": "見掛けている", "is_correct": false, "explanation": "継続を表す形。一度の出来事を述べる文には合わない。"}, {"text": "見掛けよう", "is_correct": false, "explanation": "意志形。「見掛けよう、びっくりした」とは続かず、文が成り立たない。"}, {"text": "見掛けてしまう", "is_correct": false, "explanation": "しまう形は後悔や完了の意味を加えるため、この文の驚きの流れに合わない。"}], "correct_form": "見掛けて", "base_form": "見掛ける", "form_label": "て形", "sentence_index": 7, "explanations": {"見掛けて": "正解。て形で、「びっくりした」へつながる文になる。", "見掛けている": "継続を表す形。一度の出来事を述べる文には合わない。", "見掛けよう": "意志形。「見掛けよう、びっくりした」とは続かず、文が成り立たない。", "見掛けてしまう": "しまう形は後悔や完了の意味を加えるため、この文の驚きの流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37968, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "汚い", "is_correct": true, "explanation": "〈きれい〉（よごれがない）の対義語。ものが〈よごれている〉状態を表す。"}, {"text": "静か", "is_correct": false, "explanation": "音や様子が穏やかなこと。よごれの有無とは反対の関係ではない。"}, {"text": "便利", "is_correct": false, "explanation": "使いやすいこと。清潔さの対義語ではない。"}, {"text": "丈夫", "is_correct": false, "explanation": "壊れにくいこと。よごれとは関係がなく、対義語ではない。"}], "correct_answer": "汚い", "explanations": {"汚い": "〈きれい〉（よごれがない）の対義語。ものが〈よごれている〉状態を表す。", "静か": "音や様子が穏やかなこと。よごれの有無とは反対の関係ではない。", "便利": "使いやすいこと。清潔さの対義語ではない。", "丈夫": "壊れにくいこと。よごれとは関係がなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37968, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "汚い", "is_correct": true, "explanation": "〈きれい〉（よごれがない）の対義語。ものが〈よごれている〉状態を表す。"}, {"text": "派手", "is_correct": false, "explanation": "色や目立ち方が強いこと。清潔さの対義語ではない。"}, {"text": "賑やか", "is_correct": false, "explanation": "人が多く活気があること。よごれの有無とは反対の関係ではない。"}, {"text": "大切", "is_correct": false, "explanation": "重んじるべきこと。よごれとは関係がなく、対義語ではない。"}], "correct_answer": "汚い", "explanations": {"汚い": "〈きれい〉（よごれがない）の対義語。ものが〈よごれている〉状態を表す。", "派手": "色や目立ち方が強いこと。清潔さの対義語ではない。", "賑やか": "人が多く活気があること。よごれの有無とは反対の関係ではない。", "大切": "重んじるべきこと。よごれとは関係がなく、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37968, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ものが、よごれていないこと。きれいなこと。", "primary_collocate": null, "pronunciation": "きれい", "ipa": "kiɾeː", "syllable_count": 3, "sentences": [{"text": "部屋をそうじして、きれいになった。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "部屋[へや]をそうじして、きれいになった。", "sentence_source": "generated"}, {"text": "きれいな水で手を洗ってください。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "きれいな水[みず]で手[て]を洗[あら]ってください。", "sentence_source": "generated"}, {"text": "毎日お風呂に入って、体をきれいにする。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "毎日[まいにち]お風呂[ふろ]に入[はい]って、体[からだ]をきれいにする。", "sentence_source": "generated"}, {"text": "このタオルは洗ったばかりで、きれいだ。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "このタオルは洗[あら]ったばかりで、きれいだ。", "sentence_source": "generated"}, {"text": "汚れた服をきれいに洗った。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "汚[よご]れた服[ふく]をきれいに洗[あら]った。", "sentence_source": "generated"}, {"text": "雨のあと、窓をふいたら、ガラスがきれいになった。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "雨[あめ]のあと、窓[まど]をふいたら、ガラスがきれいになった。", "sentence_source": "generated"}, {"text": "台所はいつもきれいにしておきたい。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "台所[だいどころ]はいつもきれいにしておきたい。", "sentence_source": "generated"}, {"text": "きれいなコップがないので、洗ってから使った。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "きれいなコップがないので、洗[あら]ってから使[つか]った。", "sentence_source": "generated"}, {"text": "川の水がきれいだから、魚がたくさんいる。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]がきれいだから、魚[さかな]がたくさんいる。", "sentence_source": "generated"}, {"text": "食べたあとは、テーブルをきれいにふきます。", "target_word": "きれい", "complexity_tier": "T3", "furigana": "食[た]べたあとは、テーブルをきれいにふきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "きれい", "label": "語幹"}, {"form": "きれいだ", "label": "終止形"}, {"form": "きれいに", "label": "連用形"}, {"form": "きれいな", "label": "連体形"}, {"form": "きれいだった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "よごれがなく清潔である", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37968, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "きれい", "is_correct": true, "explanation": "語幹の形で「になった」に続き、「きれいになった」となる。ここで正しい。"}, {"text": "きれいな", "is_correct": false, "explanation": "連体形で名詞の前に付く。「になった」の前には入らない。"}, {"text": "きれいだ", "is_correct": false, "explanation": "終止形で文を言い切る形。「になった」には続かない。"}, {"text": "きれいで", "is_correct": false, "explanation": "連用形の「で」。「になった」には続かず、「きれいでになった」は不自然。"}], "explanations": {"きれい": "語幹の形で「になった」に続き、「きれいになった」となる。ここで正しい。", "きれいな": "連体形で名詞の前に付く。「になった」の前には入らない。", "きれいだ": "終止形で文を言い切る形。「になった」には続かない。", "きれいで": "連用形の「で」。「になった」には続かず、「きれいでになった」は不自然。"}, "sentence_index": 0, "correct_answer": "きれい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は、きれいな声で歌った。", "explanation": "ここは〈美しい〉の意味（声の美しさ）。〈よごれがない〉の意味では、声の美しさは表せない。"}, {"text": "彼は試験で、きれいに全問正解した。", "explanation": "ここは〈残らず・完全に〉の意味（全問正解）。〈よごれがない〉の意味では、正解の数は表せない。"}, {"text": "彼女は、きれいな字を書いた。", "explanation": "ここは〈整っている〉の意味（字の整い）。〈よごれがない〉の意味では、字の整いは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37968, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "きれい", "is_correct": true, "explanation": "「きれいにしておきたい」の形で正しい。「きれいに」は連用形で、この文の形に合う。"}, {"text": "きれいなら", "is_correct": false, "explanation": "仮定形。「きれいなら」は仮定の文で使い、この文の形には合わない。"}, {"text": "きれいでした", "is_correct": false, "explanation": "丁寧な過去形。「きれいでしたにしておきたい」と続かず、文が成り立たない。"}, {"text": "きれいだろう", "is_correct": false, "explanation": "推量形。「きれいだろうにしておきたい」と続かず、文が成り立たない。"}], "explanations": {"きれい": "「きれいにしておきたい」の形で正しい。「きれいに」は連用形で、この文の形に合う。", "きれいなら": "仮定形。「きれいなら」は仮定の文で使い、この文の形には合わない。", "きれいでした": "丁寧な過去形。「きれいでしたにしておきたい」と続かず、文が成り立たない。", "きれいだろう": "推量形。「きれいだろうにしておきたい」と続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "きれい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、きれいな発音で話した。", "explanation": "ここは〈正確で明瞭な〉の意味（発音の明瞭さ）。〈よごれがない〉の意味では、発音の明瞭さは表せない。"}, {"text": "彼は負けを認めて、きれいに引き下がった。", "explanation": "ここは〈潔い〉の意味（態度の潔さ）。〈よごれがない〉の意味では、態度の潔さは表せない。"}, {"text": "彼女は、きれいな笑顔で答えた。", "explanation": "ここは〈美しい・すてきな〉の意味（笑顔の印象）。〈よごれがない〉の意味では、笑顔の印象は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37968, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗濯物がきれいなりました。", "corrected_sentence": "洗濯物がきれいになりました。", "error_description": "形容動詞「きれい」の連用形「きれいに」の「に」が抜けた誤り。「きれいなりました」は誤りで、正しくは「きれいになりました」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "きれい", "is_correct": true, "explanation": "連体形「きれいな」の語幹部分。名詞「水」を修飾する形で、ここで正しい。"}, {"text": "きれいに", "is_correct": false, "explanation": "連用形。動詞を修飾するときの形で、名詞「水」の前には使えない。"}, {"text": "きれいだ", "is_correct": false, "explanation": "終止形。文を言い切る形で、名詞の前には使えない。"}, {"text": "きれいだった", "is_correct": false, "explanation": "過去形。名詞の前には使えず、ここでは形が合わない。"}], "correct_form": "きれい", "base_form": "きれいだ", "form_label": "語幹", "sentence_index": 1, "explanations": {"きれい": "連体形「きれいな」の語幹部分。名詞「水」を修飾する形で、ここで正しい。", "きれいに": "連用形。動詞を修飾するときの形で、名詞「水」の前には使えない。", "きれいだ": "終止形。文を言い切る形で、名詞の前には使えない。", "きれいだった": "過去形。名詞の前には使えず、ここでは形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37968, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お風呂をきれいだ洗いました。", "corrected_sentence": "お風呂をきれいに洗いました。", "error_description": "動詞「洗う」を修飾する形は連用形「きれいに」。「きれいだ」は誤りで、正しくは「きれいに」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "きれい", "is_correct": true, "explanation": "連体形「きれいな」の語幹部分。名詞「コップ」を修飾する形で、ここで正しい。"}, {"text": "きれいでした", "is_correct": false, "explanation": "丁寧な過去形。名詞の前には使えず、ここでは形が合わない。"}, {"text": "きれいなら", "is_correct": false, "explanation": "仮定形。文の条件を示す形で、名詞の前には使えない。"}, {"text": "きれいだろう", "is_correct": false, "explanation": "推量形。名詞の前には使えず、ここでは形が合わない。"}], "correct_form": "きれい", "base_form": "きれいだ", "form_label": "語幹", "sentence_index": 7, "explanations": {"きれい": "連体形「きれいな」の語幹部分。名詞「コップ」を修飾する形で、ここで正しい。", "きれいでした": "丁寧な過去形。名詞の前には使えず、ここでは形が合わない。", "きれいなら": "仮定形。文の条件を示す形で、名詞の前には使えない。", "きれいだろう": "推量形。名詞の前には使えず、ここでは形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37970, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「町を作りたい」で、町を目的語にして「作る」に続ける。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、作る対象は示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は修飾を示し、「町の作りたい」では述語にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「町を作りたい」で、町を目的語にして「作る」に続ける。", "と": "「と」は並列や相手を表し、目的語にはならない。", "へ": "「へ」は方向を表し、作る対象は示せない。", "の": "「の」は修飾を示し、「町の作りたい」では述語にならず不自然。"}, "error_tags": {"と": "pairing", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37970, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「町を作る」で、町を目的語にして作る行為を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や所在を表し、作る対象は示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、作る対象の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を表し、作る対象の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「町を作る」で、町を目的語にして作る行為を示す。", "に": "「に」は到着点や所在を表し、作る対象は示せない。", "より": "「より」は比較を表し、作る対象の目的語にはならない。", "の": "「の」は所属や修飾を表し、作る対象の目的語にはならない。"}, "error_tags": {"に": "direction/location", "より": "comparison", "の": "modifier"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37970, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "みんなでくらすところを、もっとすてきにすること。", "primary_collocate": null, "pronunciation": "まちをつくる", "ipa": "matɕi o tsɯkɯɾɯ", "syllable_count": 6, "sentences": [{"text": "みんなで話し合って、子どもが安心して遊べる町を作ります。", "target_word": "町を作ります", "complexity_tier": "T3", "furigana": "みんなで話[はな]し合[あ]って、子[こ]どもが安心[あんしん]して遊[あそ]べる町[まち]を作[つく]ります。", "sentence_source": "generated"}, {"text": "わたしたちは、お年寄りにもやさしい町を作りたいです。", "target_word": "町を作りたい", "complexity_tier": "T3", "furigana": "わたしたちは、お年寄[としよ]りにもやさしい町[まち]を作[つく]りたいです。", "sentence_source": "generated"}, {"text": "町の人が力を合わせて、花のきれいな町を作った。", "target_word": "町を作った", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]が力[ちから]を合[あ]わせて、花[はな]のきれいな町[まち]を作[つく]った。", "sentence_source": "generated"}, {"text": "駅の近くに店が少ないので、もっとにぎやかな町を作ろう。", "target_word": "町を作ろう", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに店[みせ]が少[すく]ないので、もっとにぎやかな町[まち]を作[つく]ろう。", "sentence_source": "generated"}, {"text": "古い家をなおしながら、昔のよさが残る町を作っている。", "target_word": "町を作っている", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]をなおしながら、昔[むかし]のよさが残[のこ]る町[まち]を作[つく]っている。", "sentence_source": "generated"}, {"text": "大人も子どもも意見を出して、みんなが住みたい町を作ってほしい。", "target_word": "町を作って", "complexity_tier": "T3", "furigana": "大人[おとな]も子[こ]どもも意見[いけん]を出[だ]して、みんなが住[す]みたい町[まち]を作[つく]ってほしい。", "sentence_source": "generated"}, {"text": "ごみを拾う人が増えて、前よりきれいな町を作ることができた。", "target_word": "町を作る", "complexity_tier": "T3", "furigana": "ごみを拾[ひろ]う人[ひと]が増[ふ]えて、前[まえ]よりきれいな町[まち]を作[つく]ることができた。", "sentence_source": "generated"}, {"text": "一人ではできないが、みんなで町を作るのは楽しい。", "target_word": "町を作る", "complexity_tier": "T3", "furigana": "一人[ひとり]ではできないが、みんなで町[まち]を作[つく]るのは楽[たの]しい。", "sentence_source": "generated"}, {"text": "市長は、自然を大切にする町を作ると約束した。", "target_word": "町を作る", "complexity_tier": "T3", "furigana": "市長[しちょう]は、自然[しぜん]を大切[たいせつ]にする町[まち]を作[つく]ると約束[やくそく]した。", "sentence_source": "generated"}, {"text": "この学校では、住みやすい町を作る方法を勉強します。", "target_word": "町を作る", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、住[す]みやすい町[まち]を作[つく]る方法[ほうほう]を勉強[べんきょう]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "町を作る", "label": "終止形"}, {"form": "町を作ります", "label": "丁寧形"}, {"form": "町を作った", "label": "過去形"}, {"form": "町を作っている", "label": "継続形"}, {"form": "町を作りたい", "label": "願望形"}, {"form": "町を作ろう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "people living together build or improve their community to make it a better place", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37970, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "町を作ります", "is_correct": true, "explanation": "住みやすい場所を良くする意味で、「子どもが安心して遊べる町を作ります」に合う。"}, {"text": "町を壊します", "is_correct": false, "explanation": "壊すは反対の行為で、「安心して遊べる」文脈と矛盾する。"}, {"text": "町を食べます", "is_correct": false, "explanation": "食べるは口に入れる行為で、町は食べられないので合わない。"}, {"text": "町を汚します", "is_correct": false, "explanation": "汚すは悪くする行為で、「安心して遊べる」の文脈と合わない。"}], "explanations": {"町を作ります": "住みやすい場所を良くする意味で、「子どもが安心して遊べる町を作ります」に合う。", "町を壊します": "壊すは反対の行為で、「安心して遊べる」文脈と矛盾する。", "町を食べます": "食べるは口に入れる行為で、町は食べられないので合わない。", "町を汚します": "汚すは悪くする行為で、「安心して遊べる」の文脈と合わない。"}, "sentence_index": 0, "correct_answer": "町を作ります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は夏休みに、模型の町を作ると言って材料を買った。", "explanation": "ここは〈作る〉＝模型を組み立てて形にするの意味。住みやすくするという意味ではないので誤り。"}, {"text": "妹は、ブロックで町を作って遊んでいる。", "explanation": "ここは〈作る〉＝ブロックなどで形を組み立てるの意味。まちを良くする意味ではないので誤り。"}, {"text": "わたしは宿題のために町を組み立ててしまい、先生に怒られた。", "explanation": "ここは〈組み立てる〉の意味。町は部品のように組み立てるものではなく、〈作る〉の良くするという意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37970, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "町を作る", "is_correct": true, "explanation": "住みやすくする意味で、「前よりきれいな町を作ることができた」に合う。"}, {"text": "町を忘れる", "is_correct": false, "explanation": "忘れるは記憶に関する動作で、町を良くする文脈と合わない。"}, {"text": "町を見捨てる", "is_correct": false, "explanation": "見捨てるは放り出す行為で、きれいにする文脈と逆になる。"}, {"text": "町を眠らせる", "is_correct": false, "explanation": "眠らせるは寝かせる意味で、町をきれいにする行為にはならない。"}], "explanations": {"町を作る": "住みやすくする意味で、「前よりきれいな町を作ることができた」に合う。", "町を忘れる": "忘れるは記憶に関する動作で、町を良くする文脈と合わない。", "町を見捨てる": "見捨てるは放り出す行為で、きれいにする文脈と逆になる。", "町を眠らせる": "眠らせるは寝かせる意味で、町をきれいにする行為にはならない。"}, "sentence_index": 6, "correct_answer": "町を作る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は、庭で小さな町を育てて、毎日水をやっている。", "explanation": "ここは〈育てる〉の意味。町は植物のように育てるものではないので、〈作る〉の代わりには使えない。"}, {"text": "この川は、町を作るので、いつも水がきれいだ。", "explanation": "ここは〈作る〉＝生み出すの意味。川が町を生み出すという使い方は、住みやすくするという定義と合わない。"}, {"text": "友だちと、町を壊す約束をやぶってしまった。", "explanation": "ここは〈壊す〉の意味。作るの定義（良くする）とは反対の行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37970, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この学校では、みんなで町に作ることを学びます。", "corrected_sentence": "この学校では、みんなで町を作ることを学びます。", "error_description": "誤: 「町に作る」／正: 「町を作る」。「作る」は目的語に「を」を取るので、町に「を」を付ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "町を作りたい", "is_correct": true, "explanation": "「作りたいです」の願望形で、文の意味に合う。"}, {"text": "町を作ります", "is_correct": false, "explanation": "丁寧形で、願望を表さない。"}, {"text": "町を作った", "is_correct": false, "explanation": "過去形で、これからの願望と時制が合わない。"}, {"text": "町を作っている", "is_correct": false, "explanation": "継続形で、まだ行っていない願望の文と合わない。"}], "correct_form": "町を作りたい", "base_form": "町を作る", "form_label": "願望形", "sentence_index": 1, "explanations": {"町を作りたい": "「作りたいです」の願望形で、文の意味に合う。", "町を作ります": "丁寧形で、願望を表さない。", "町を作った": "過去形で、これからの願望と時制が合わない。", "町を作っている": "継続形で、まだ行っていない願望の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37970, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市長は、住みやすい町に作る計画を発表した。", "corrected_sentence": "市長は、住みやすい町を作る計画を発表した。", "error_description": "誤: 「町に作る」／正: 「町を作る」。「作る」は目的語に「を」を取るので、町に「に」ではなく「を」を付ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "町を作る", "is_correct": true, "explanation": "基本形で、「作るのは楽しい」の主語として正しい形。"}, {"text": "町を作ろう", "is_correct": false, "explanation": "意志形で、「のは楽しい」と続く名詞句にならず不自然。"}, {"text": "町を作れば", "is_correct": false, "explanation": "仮定形で、「～するのは楽しい」の名詞句として成り立たない。"}, {"text": "町を作って", "is_correct": false, "explanation": "て形で、名詞句として使えず文が続かない。"}], "correct_form": "町を作る", "base_form": "町を作る", "form_label": "基本形", "sentence_index": 7, "explanations": {"町を作る": "基本形で、「作るのは楽しい」の主語として正しい形。", "町を作ろう": "意志形で、「のは楽しい」と続く名詞句にならず不自然。", "町を作れば": "仮定形で、「～するのは楽しい」の名詞句として成り立たない。", "町を作って": "て形で、名詞句として使えず文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
