INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37972, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "だいじなことです。それがなければ、よくないことになります。", "primary_collocate": null, "pronunciation": "だいじ", "ipa": "daidʑi", "syllable_count": 3, "sentences": [{"text": "健康が一番大事です。", "target_word": "大事です", "complexity_tier": "T3", "furigana": "健康[けんこう]が一番[いちばん]大事[だいじ]です。", "sentence_source": "generated"}, {"text": "毎日の朝ごはんは大事です。", "target_word": "大事です", "complexity_tier": "T3", "furigana": "毎日[まいにち]の朝[あさ]ごはんは大事[だいじ]です。", "sentence_source": "generated"}, {"text": "約束を守ることは大事だと思います。", "target_word": "大事", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]ることは大事[だいじ]だと思[おも]います。", "sentence_source": "generated"}, {"text": "これは大事な書類なので、なくさないでください。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "これは大事[だいじ]な書類[しょるい]なので、なくさないでください。", "sentence_source": "generated"}, {"text": "試験の前に、よく寝ることが大事です。", "target_word": "大事です", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、よく寝[ね]ることが大事[だいじ]です。", "sentence_source": "generated"}, {"text": "家族との時間は私にとって大事です。", "target_word": "大事です", "complexity_tier": "T3", "furigana": "家族[かぞく]との時間[じかん]は私[わたし]にとって大事[だいじ]です。", "sentence_source": "generated"}, {"text": "大事な話があるので、あとで電話します。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "大事[だいじ]な話[はなし]があるので、あとで電話[でんわ]します。", "sentence_source": "generated"}, {"text": "先生は「基本を学ぶことが大事だ」と言いました。", "target_word": "大事だ", "complexity_tier": "T3", "furigana": "先生[せんせい]は「基本[きほん]を学[まな]ぶことが大事[だいじ]だ」と言[い]いました。", "sentence_source": "generated"}, {"text": "最初の一歩が大事で、そのあとは楽になります。", "target_word": "大事で", "complexity_tier": "T3", "furigana": "最初[さいしょ]の一歩[いっぽ]が大事[だいじ]で、そのあとは楽[らく]になります。", "sentence_source": "generated"}, {"text": "友達の意見を聞くのも大事です。", "target_word": "大事です", "complexity_tier": "T3", "furigana": "友達[ともだち]の意見[いけん]を聞[き]くのも大事[だいじ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大事です", "label": "丁寧形"}, {"form": "大事だ", "label": "終止形"}, {"form": "大事な", "label": "連体形"}, {"form": "大事で", "label": "連用形"}], "register": "丁寧", "sense_fingerprint": "重要で欠かせないこと。ないと困る・よくない結果になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37972, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大事です", "is_correct": true, "explanation": "丁寧形で、「健康が一番」の後に来て文を言い切る。ここで正しい。"}, {"text": "大事な", "is_correct": false, "explanation": "連体形で、名詞の前に付く。ここでは文を言い切れない。"}, {"text": "大事で", "is_correct": false, "explanation": "連用形。「一番大事で。」と言い切れず、文が成り立たない。"}, {"text": "大事に", "is_correct": false, "explanation": "副詞的な形で、「一番大事に」と言い切れない。"}], "explanations": {"大事です": "丁寧形で、「健康が一番」の後に来て文を言い切る。ここで正しい。", "大事な": "連体形で、名詞の前に付く。ここでは文を言い切れない。", "大事で": "連用形。「一番大事で。」と言い切れず、文が成り立たない。", "大事に": "副詞的な形で、「一番大事に」と言い切れない。"}, "sentence_index": 0, "correct_answer": "大事です"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は大事を取って、今日は休んだ。", "explanation": "ここは慣用句〈大事を取る〉の意味（用心する）。〈重要で欠かせない〉の意味では、用心の意味は表せない。"}, {"text": "事故は大事に至らずに済んだ。", "explanation": "ここは〈重大な事態〉の意味（事態の深刻さ）。〈重要で欠かせない〉の意味では、事態の深刻さは表せない。"}, {"text": "彼は大事を起こして、責任を問われた。", "explanation": "ここは名詞〈重大な事件〉の意味。〈重要で欠かせない〉の意味では、事件は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37972, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大事な", "is_correct": true, "explanation": "連体形で、名詞「話」を修飾する形。ここで正しい。"}, {"text": "大事です", "is_correct": false, "explanation": "丁寧形で、名詞の前には使えない。「大事です話」は成り立たない。"}, {"text": "大事で", "is_correct": false, "explanation": "連用形。「大事で話」と名詞に続かず、文が成り立たない。"}, {"text": "大事なら", "is_correct": false, "explanation": "仮定形。「大事なら話」と名詞に続かず、文が成り立たない。"}], "explanations": {"大事な": "連体形で、名詞「話」を修飾する形。ここで正しい。", "大事です": "丁寧形で、名詞の前には使えない。「大事です話」は成り立たない。", "大事で": "連用形。「大事で話」と名詞に続かず、文が成り立たない。", "大事なら": "仮定形。「大事なら話」と名詞に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "大事な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大事を取って、一日中家にいた。", "explanation": "ここは慣用句〈大事を取る〉の意味（用心する）。〈重要で欠かせない〉の意味では、用心の意味は表せない。"}, {"text": "その病気は大事に至らずに済んだ。", "explanation": "ここは〈重大な事態〉の意味（病状の深刻さ）。〈重要で欠かせない〉の意味では、深刻さは表せない。"}, {"text": "その町で大事が起き、住民が避難した。", "explanation": "ここは名詞〈重大な事件〉の意味。〈重要で欠かせない〉の意味では、事件の発生は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37972, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "返事は大事だです。", "corrected_sentence": "返事は大事です。", "error_description": "形状詞「大事」に丁寧の「です」を付けるときに「だ」を入れた誤り。正しくは「大事です」で、「大事だです」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大事です", "is_correct": true, "explanation": "丁寧形。文末で「です」と言い切る形で、ここで正しい。"}, {"text": "大事に", "is_correct": false, "explanation": "副詞的な形（「大事にする」の「に」）。文末で言い切れず、ここでは文が成り立たない。"}, {"text": "大事な", "is_correct": false, "explanation": "連体形で、名詞の前に付く。文を言い切る位置には入らない。"}, {"text": "大事で", "is_correct": false, "explanation": "連用形。文を言い切れず、ここでは形が合わない。"}], "correct_form": "大事です", "base_form": "大事だ", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"大事です": "丁寧形。文末で「です」と言い切る形で、ここで正しい。", "大事に": "副詞的な形（「大事にする」の「に」）。文末で言い切れず、ここでは文が成り立たない。", "大事な": "連体形で、名詞の前に付く。文を言い切る位置には入らない。", "大事で": "連用形。文を言い切れず、ここでは形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37972, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大事の書類を、なくさないでください。", "corrected_sentence": "大事な書類を、なくさないでください。", "error_description": "形状詞「大事」が名詞を修飾するときは「な」。「大事の書類」は誤りで、正しくは「大事な書類」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "大事だ", "is_correct": true, "explanation": "終止形で、「基本を学ぶことが大事だ」と文を言い切る。ここで正しい。"}, {"text": "大事なら", "is_correct": false, "explanation": "仮定形で、「大事なら」と条件を述べて引用の文が終わらないので、言い切りにならない。"}, {"text": "大事さ", "is_correct": false, "explanation": "名詞形で、「大事さ」だけでは「大事だ」の言い切りにならず、引用の文が成り立たない。"}, {"text": "大事だと", "is_correct": false, "explanation": "引用の接続形で、「大事だと」と続くため引用の中の文が終わらず、「と言いました」に直接つながらない。"}], "correct_form": "大事だ", "base_form": "大事だ", "form_label": "終止形", "sentence_index": 7, "explanations": {"大事だ": "終止形で、「基本を学ぶことが大事だ」と文を言い切る。ここで正しい。", "大事なら": "仮定形で、「大事なら」と条件を述べて引用の文が終わらないので、言い切りにならない。", "大事さ": "名詞形で、「大事さ」だけでは「大事だ」の言い切りにならず、引用の文が成り立たない。", "大事だと": "引用の接続形で、「大事だと」と続くため引用の中の文が終わらず、「と言いました」に直接つながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37974, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "係助詞で、「矢印」を主題として示す。文の「図の中の矢印は」に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格助詞。「矢印を、水の流れを表しています」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す格助詞。「矢印に、水の流れを表しています」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格助詞。「矢印へ、水の流れを表しています」では意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "係助詞で、「矢印」を主題として示す。文の「図の中の矢印は」に合う。", "を": "目的語を示す格助詞。「矢印を、水の流れを表しています」では文が成り立たない。", "に": "位置や相手を示す格助詞。「矢印に、水の流れを表しています」では意味が通らない。", "へ": "方向を示す格助詞。「矢印へ、水の流れを表しています」では意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37974, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す格助詞。「矢印をつけました」の目的語として正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す格助詞。「矢印がつけました」では目的語が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示す格助詞。「矢印とつけました」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格助詞。「矢印へつけました」では、付ける対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す格助詞。「矢印をつけました」の目的語として正しい。", "が": "主語を示す格助詞。「矢印がつけました」では目的語が合わない。", "と": "並列や共同を示す格助詞。「矢印とつけました」では意味が通らない。", "へ": "方向を示す格助詞。「矢印へつけました」では、付ける対象として不自然。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37974, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをさす、やじるしのような形の記号です。", "primary_collocate": null, "pronunciation": "やじるし", "ipa": "jaʑiɾɯɕi", "syllable_count": 4, "sentences": [{"text": "画面の右に、小さい矢印が出ています。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "画面[がめん]の右[みぎ]に、小[ちい]さい矢印[やじるし]が出[で]ています。", "sentence_source": "generated"}, {"text": "図の中の矢印は、水の流れを表しています。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "図[ず]の中[なか]の矢印[やじるし]は、水[みず]の流[なが]れを表[あらわ]しています。", "sentence_source": "generated"}, {"text": "先生は黒板に赤い矢印を書きました。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に赤[あか]い矢印[やじるし]を書[か]きました。", "sentence_source": "generated"}, {"text": "マウスを動かすと、矢印も一緒に動きます。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "マウスを動[うご]かすと、矢印[やじるし]も一緒[いっしょ]に動[うご]きます。", "sentence_source": "generated"}, {"text": "地図の矢印が指す場所に、駅があります。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "地図[ちず]の矢印[やじるし]が指[さ]す場所[ばしょ]に、駅[えき]があります。", "sentence_source": "generated"}, {"text": "この矢印を見れば、どの言葉の説明かすぐ分かります。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "この矢印[やじるし]を見[み]れば、どの言葉[ことば]の説明[せつめい]かすぐ分[わ]かります。", "sentence_source": "generated"}, {"text": "矢印が上を向いているので、上のボタンを押してください。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "矢印[やじるし]が上[うえ]を向[む]いているので、上[うえ]のボタンを押[お]してください。", "sentence_source": "generated"}, {"text": "ノートの大事なところに、矢印をつけました。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "ノートの大事[だいじ]なところに、矢印[やじるし]をつけました。", "sentence_source": "generated"}, {"text": "矢印の先に答えが書いてあります。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "矢印[やじるし]の先[さき]に答[こた]えが書[か]いてあります。", "sentence_source": "generated"}, {"text": "文章の途中に矢印を書いて、原因から結果への関係を示しました。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "文章[ぶんしょう]の途中[とちゅう]に矢印[やじるし]を書[か]いて、原因[げんいん]から結果[けっか]への関係[かんけい]を示[しめ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "矢印", "label": "基本形"}, {"form": "矢印を", "label": "目的格"}, {"form": "矢印が", "label": "主格"}], "register": "中立", "sense_fingerprint": "図・画面・ノートなどで特定のものを指し示す矢の形の記号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37974, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矢印", "is_correct": true, "explanation": "画面に出る、ものを指す記号。「小さい矢印が出ています」と自然につながる。"}, {"text": "ごはん", "is_correct": false, "explanation": "食べ物。「小さいごはんが出ています」は画面の表示として成り立たない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食べ物の一種。「小さい砂糖が出ています」は画面の表示として成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の区分。「小さい季節が出ています」は画面の表示として成り立たない。"}], "explanations": {"矢印": "画面に出る、ものを指す記号。「小さい矢印が出ています」と自然につながる。", "ごはん": "食べ物。「小さいごはんが出ています」は画面の表示として成り立たない。", "砂糖": "食べ物の一種。「小さい砂糖が出ています」は画面の表示として成り立たない。", "季節": "一年の区分。「小さい季節が出ています」は画面の表示として成り立たない。"}, "sentence_index": 0, "correct_answer": "矢印"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弓で矢印を射って、的に当てた。", "explanation": "矢印は方向を示す記号なので、弓で射ることはできない。"}, {"text": "彼は矢印を食べて、お腹をいっぱいにした。", "explanation": "矢印は記号なので、食べることはできない。"}, {"text": "先生は、矢印の重さを量って、記録した。", "explanation": "矢印は記号なので、重さを量ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37974, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矢印", "is_correct": true, "explanation": "上を向く、ものを指す記号。「矢印が上を向いているので」と自然につながる。"}, {"text": "砂糖", "is_correct": false, "explanation": "食べ物の一種。「砂糖が上を向いているので」は意味が通らない。"}, {"text": "試験", "is_correct": false, "explanation": "学力を測るもの。「試験が上を向いているので」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "空の様子。「天気が上を向いているので」は意味が通らない。"}], "explanations": {"矢印": "上を向く、ものを指す記号。「矢印が上を向いているので」と自然につながる。", "砂糖": "食べ物の一種。「砂糖が上を向いているので」は意味が通らない。", "試験": "学力を測るもの。「試験が上を向いているので」は意味が通らない。", "天気": "空の様子。「天気が上を向いているので」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "矢印"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は矢印を飲み込んで、のどを痛めた。", "explanation": "矢印は記号なので、飲み込むことはできない。"}, {"text": "彼女は矢印を歌って、会場を沸かせた。", "explanation": "矢印は記号なので、歌うことはできない。"}, {"text": "選手は矢印をゴールに蹴り入れた。", "explanation": "矢印は記号なので、蹴ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37974, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の案内に、矢印を書いてあります。", "corrected_sentence": "駅の案内に、矢印が書いてあります。", "error_description": "「書いてあります」の主語には「が」を使う。「を」は目的語を示すので誤り。正しくは「矢印が書いてあります」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37974, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床に、矢印の描いてあります。", "corrected_sentence": "床に、矢印が描いてあります。", "error_description": "「描いてあります」の主語には「が」を使う。「の」は名詞をつなぐ助詞で、ここでは誤り。正しくは「矢印が描いてあります」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37975, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「描いてある」の主語を示す「が」で、白い矢印が描かれていることを表す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、描かれている状態の対象に向かう方向ではないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すが、矢印が描かれた出どころを示す文脈ではないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。比べる対象がここにはないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「描いてある」の主語を示す「が」で、白い矢印が描かれていることを表す。", "へ": "「へ」は方向を表すが、描かれている状態の対象に向かう方向ではないので合わない。", "から": "「から」は起点を表すが、矢印が描かれた出どころを示す文脈ではないので合わない。", "より": "「より」は比較を表す。比べる対象がここにはないので合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
