INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37975, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "方向や位置を示すために使われる、矢の形をした記号やしるし。", "primary_collocate": null, "pronunciation": "やじるし", "ipa": "jaʑiɾɯɕi", "syllable_count": 4, "sentences": [{"text": "駅の出口に、右を示す矢印があります。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "駅[えき]の出口[でぐち]に、右[みぎ]を示[しめ]す矢印[やじるし]があります。", "sentence_source": "generated"}, {"text": "道に白い矢印が描いてあるので、その方向に進んでください。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "道[みち]に白[しろ]い矢印[やじるし]が描[か]いてあるので、その方向[ほうこう]に進[すす]んでください。", "sentence_source": "generated"}, {"text": "矢印の通りに歩いたら、トイレに着きました。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "矢印[やじるし]の通[とお]りに歩[ある]いたら、トイレに着[つ]きました。", "sentence_source": "generated"}, {"text": "非常口の矢印は、外へ出る道を教えてくれます。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "非常口[ひじょうぐち]の矢印[やじるし]は、外[そと]へ出[で]る道[みち]を教[おし]えてくれます。", "sentence_source": "generated"}, {"text": "床の矢印に沿って並んでください。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "床[ゆか]の矢印[やじるし]に沿[そ]って並[なら]んでください。", "sentence_source": "generated"}, {"text": "矢印が二つあって、どちらに行けばいいか迷いました。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "矢印[やじるし]が二[ふた]つあって、どちらに行[い]けばいいか迷[まよ]いました。", "sentence_source": "generated"}, {"text": "山道の木に、矢印が描いてありました。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "山道[やまみち]の木[き]に、矢印[やじるし]が描[か]いてありました。", "sentence_source": "generated"}, {"text": "駐車場の矢印は、車が進む向きを示しています。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]の矢印[やじるし]は、車[くるま]が進[すす]む向[む]きを示[しめ]しています。", "sentence_source": "generated"}, {"text": "この矢印は、入り口が左側だという意味です。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "この矢印[やじるし]は、入[はい]り口[ぐち]が左側[ひだりがわ]だという意味[いみ]です。", "sentence_source": "generated"}, {"text": "矢印を見落として、反対の方向へ行ってしまいました。", "target_word": "矢印", "complexity_tier": "T3", "furigana": "矢印[やじるし]を見落[みお]として、反対[はんたい]の方向[ほうこう]へ行[い]ってしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "矢印", "label": "基本形"}, {"form": "矢印の", "label": "連体格"}, {"form": "矢印を", "label": "目的格"}], "register": "中立", "sense_fingerprint": "道・床・標識などで進む向きや位置を知らせる矢の形のしるし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37975, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矢印", "is_correct": true, "explanation": "「右を示す」ものとして、駅の出口にある方向の標示に合う。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車や入場の証明で、方向を示す役目がないので「右を示す」に合わない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は発車時刻を示すもので、方向を示さないので「右を示す」に合わない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は昇り降りする設備で、右を示すしるしにはならないので合わない。"}], "explanations": {"矢印": "「右を示す」ものとして、駅の出口にある方向の標示に合う。", "切符": "切符は乗車や入場の証明で、方向を示す役目がないので「右を示す」に合わない。", "時刻表": "時刻表は発車時刻を示すもので、方向を示さないので「右を示す」に合わない。", "階段": "階段は昇り降りする設備で、右を示すしるしにはならないので合わない。"}, "sentence_index": 0, "correct_answer": "矢印"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "道に迷ったら、コンビニを矢印にしよう。", "explanation": "ここは〈目印〉の意味。目印は場所を覚えるための対象を指すが、矢印は進む向きを示す記号なので、場所そのものを目印にはできない。"}, {"text": "有名な俳優に、矢印をもらいました。", "explanation": "ここは〈サイン〉の意味。サインは本人が書いた名前を指すが、矢印は記号なので人からもらう対象にはならない。"}, {"text": "弓で的に矢印を当てました。", "explanation": "ここは〈矢〉の意味。矢は射る武器だが、矢印は道しるべの記号なので、射る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37975, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矢印", "is_correct": true, "explanation": "木に描かれて道の向きを示すしるしとして自然に合う。"}, {"text": "空気", "is_correct": false, "explanation": "空気は目に見えない気体で、木の表面に描いて示すものではないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、木に描く対象にはならないので合わない。"}, {"text": "水道", "is_correct": false, "explanation": "水道は水を送る設備で、描いて道を示すものではないので合わない。"}], "explanations": {"矢印": "木に描かれて道の向きを示すしるしとして自然に合う。", "空気": "空気は目に見えない気体で、木の表面に描いて示すものではないので合わない。", "天気": "天気は空の状態で、木に描く対象にはならないので合わない。", "水道": "水道は水を送る設備で、描いて道を示すものではないので合わない。"}, "sentence_index": 6, "correct_answer": "矢印"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三年後の夢は、矢印に向かって毎日努力を続けることです。", "explanation": "ここは〈目標〉の意味。目標は到達したい先の目的を指すが、矢印は向きを示す記号なので、努力の先にはならない。"}, {"text": "この料理は、時間の矢印が書いてあります。", "explanation": "ここは〈目安〉の意味。時間の目安は大体の長さを指すが、矢印は時間の長さを表せないので合わない。"}, {"text": "お礼のしるしに、矢印を贈りました。", "explanation": "ここは〈しるし〉の意味。しるしは気持ちを表すものを指すが、矢印は向きを示す記号なので、お礼の気持ちは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37975, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "矢印を従って歩くと、トイレがあります。", "corrected_sentence": "矢印に従って歩くと、トイレがあります。", "error_description": "誤った形は「矢印を従って」、正しい形は「矢印に従って」。「従う」は助詞「に」を取るので、矢印に付く「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37975, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "矢印を聞いて、道を選びました。", "corrected_sentence": "矢印を見て、道を選びました。", "error_description": "誤った動詞は「聞いて」、正しくは「見て」。矢印は目で確認する記号なので、「聞く」は「矢印」の動詞として合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
