INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37976, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "ものが同じ向きへ何度も続けて回るようすを表す擬態語。", "primary_collocate": null, "pronunciation": "ぐるぐる", "ipa": "ɡɯɾɯɡɯɾɯ", "syllable_count": 4, "sentences": [{"text": "子どもが輪になって、ぐるぐる回っています。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "子[こ]どもが輪[わ]になって、ぐるぐる回[まわ]っています。", "sentence_source": "generated"}, {"text": "洗濯機の中で、服がぐるぐる回っています。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]の中[なか]で、服[ふく]がぐるぐる回[まわ]っています。", "sentence_source": "generated"}, {"text": "犬は自分のしっぽを追いかけて、ぐるぐる回りました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "犬[いぬ]は自分[じぶん]のしっぽを追[お]いかけて、ぐるぐる回[まわ]りました。", "sentence_source": "generated"}, {"text": "風車が風でぐるぐる回るのを、じっと見ていました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "風車[かざぐるま]が風[かぜ]でぐるぐる回[まわ]るのを、じっと見[み]ていました。", "sentence_source": "generated"}, {"text": "遊園地のコーヒーカップがぐるぐる回って、目が回りました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "遊園地[ゆうえんち]のコーヒーカップがぐるぐる回[まわ]って、目[め]が回[まわ]りました。", "sentence_source": "generated"}, {"text": "先生は鉛筆を指でぐるぐる回しながら話しています。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "先生[せんせい]は鉛筆[えんぴつ]を指[ゆび]でぐるぐる回[まわ]しながら話[はな]しています。", "sentence_source": "generated"}, {"text": "台所で、スプーンでスープをぐるぐると混ぜます。", "target_word": "ぐるぐると", "complexity_tier": "T3", "furigana": "台所[だいどころ]で、スプーンでスープをぐるぐると混[ま]ぜます。", "sentence_source": "generated"}, {"text": "扇風機の羽が、ぐるぐると速く回っています。", "target_word": "ぐるぐると", "complexity_tier": "T3", "furigana": "扇風機[せんぷうき]の羽[はね]が、ぐるぐると速[はや]く回[まわ]っています。", "sentence_source": "generated"}, {"text": "妹は椅子に座って、ぐるぐる回って遊んでいます。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "妹[いもうと]は椅子[いす]に座[すわ]って、ぐるぐる回[まわ]って遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "回転ドアがぐるぐる回って、なかなか入れませんでした。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "回転[かいてん]ドアがぐるぐる回[まわ]って、なかなか入[はい]れませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ぐるぐる", "label": "基本形"}, {"form": "ぐるぐると", "label": "と付き形"}], "register": "中立", "sense_fingerprint": "ものが軸を中心に何度も続けて回転するようすを表す擬態語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37976, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ぐるぐる", "is_correct": true, "explanation": "同じ向きに何度も回る様子を表し、子どもが輪になって回る動きに合う。"}, {"text": "ぽつんと", "is_correct": false, "explanation": "ひとつだけ離れてある様子を表すので、回る動きには合わない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "はっきり決める様子を表すので、回転の動きを表さず合わない。"}, {"text": "しんと", "is_correct": false, "explanation": "物音がなく静まる様子を表すので、回る動作とは合わない。"}], "explanations": {"ぐるぐる": "同じ向きに何度も回る様子を表し、子どもが輪になって回る動きに合う。", "ぽつんと": "ひとつだけ離れてある様子を表すので、回る動きには合わない。", "きっぱり": "はっきり決める様子を表すので、回転の動きを表さず合わない。", "しんと": "物音がなく静まる様子を表すので、回る動作とは合わない。"}, "sentence_index": 0, "correct_answer": "ぐるぐる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒さで、体がぐるぐる震えました。", "explanation": "ここは〈震え〉の意味。ぐるぐるは回転の動きを表すので、ふるえの様子には使えない。"}, {"text": "船が港まで一直線にぐるぐる進みました。", "explanation": "ここは〈まっすぐ〉の意味。ぐるぐるは同じ場所を回る様子で、一直線に進む移動には合わない。"}, {"text": "椅子がぐるぐる止まっています。", "explanation": "ここは〈静止〉の意味。ぐるぐるは回転の動きを表すので、止まっている状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37976, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ぐるぐると", "is_correct": true, "explanation": "スープを同じ向きに何度も混ぜる様子を表し、ここに合う形。"}, {"text": "ひそひそと", "is_correct": false, "explanation": "小声で話す様子を表すので、混ぜる動作とは合わない。"}, {"text": "きょとんと", "is_correct": false, "explanation": "驚いて目を丸くする様子を表すので、動作には合わない。"}, {"text": "うつらうつらと", "is_correct": false, "explanation": "眠気でうとうとする様子を表すので、混ぜる動作とは合わない。"}], "explanations": {"ぐるぐると": "スープを同じ向きに何度も混ぜる様子を表し、ここに合う形。", "ひそひそと": "小声で話す様子を表すので、混ぜる動作とは合わない。", "きょとんと": "驚いて目を丸くする様子を表すので、動作には合わない。", "うつらうつらと": "眠気でうとうとする様子を表すので、混ぜる動作とは合わない。"}, "sentence_index": 6, "correct_answer": "ぐるぐると"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一瞬の間に、ぐるぐる回りました。", "explanation": "ここは〈一瞬〉の意味。ぐるぐるは何度も続けて回る様子なので、一瞬で終わる動きには合わない。"}, {"text": "ボールが上下にぐるぐる跳ねました。", "explanation": "ここは〈上下〉の意味。ぐるぐるは円を描くように回る様子で、上下に跳ねる動きには使えない。"}, {"text": "強い風で、船がぐるぐると揺れました。", "explanation": "ここは〈揺れ〉の意味。ぐるぐるは回る動きを表すので、左右に揺れる様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37976, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールを手でぐるぐるで回しています。", "corrected_sentence": "ボールを手でぐるぐると回しています。", "error_description": "誤った形は「ぐるぐるで」、正しい形は「ぐるぐると」。「ぐるぐるで」は助詞「で」が不自然で、「ぐるぐると」にすると動詞を修飾する形として自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37976, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風邪で、頭がぐるぐる光っています。", "corrected_sentence": "風邪で、頭がぐるぐる回っています。", "error_description": "誤った動詞は「光って」、正しくは「回って」。頭に「光る」は合わないが、頭が回るのは目が回るような状態として自然に成り立つ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
