INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37977, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "同じ場所を何度も回り続けて、先へ進まないようすを表す副詞。", "primary_collocate": null, "pronunciation": "ぐるぐる", "ipa": "ɡɯɾɯɡɯɾɯ", "syllable_count": 4, "sentences": [{"text": "道に迷って、同じ場所をぐるぐる歩き回りました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]って、同[おな]じ場所[ばしょ]をぐるぐる歩[ある]き回[まわ]りました。", "sentence_source": "generated"}, {"text": "駐車場の中を、車でぐるぐる回って空いた所を探しました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]の中[なか]を、車[くるま]でぐるぐる回[まわ]って空[あ]いた所[ところ]を探[さが]しました。", "sentence_source": "generated"}, {"text": "鳥が山の上をぐるぐると飛び続けています。", "target_word": "ぐるぐると", "complexity_tier": "T3", "furigana": "鳥[とり]が山[やま]の上[うえ]をぐるぐると飛[と]び続[つづ]けています。", "sentence_source": "generated"}, {"text": "悩みごとが頭の中でぐるぐる回って、眠れません。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "悩[なや]みごとが頭[あたま]の中[なか]でぐるぐる回[まわ]って、眠[ねむ]れません。", "sentence_source": "generated"}, {"text": "犬が部屋の中をぐるぐる走り続けています。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "犬[いぬ]が部屋[へや]の中[なか]をぐるぐる走[はし]り続[つづ]けています。", "sentence_source": "generated"}, {"text": "地図がなくて、駅のまわりをぐるぐる回っていました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "地図[ちず]がなくて、駅[えき]のまわりをぐるぐる回[まわ]っていました。", "sentence_source": "generated"}, {"text": "同じ心配が、頭の中をぐるぐる回って離れません。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "同[おな]じ心配[しんぱい]が、頭[あたま]の中[なか]をぐるぐる回[まわ]って離[はな]れません。", "sentence_source": "generated"}, {"text": "店を探して、町をぐるぐる回ったのに見つかりませんでした。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "店[みせ]を探[さが]して、町[まち]をぐるぐる回[まわ]ったのに見[み]つかりませんでした。", "sentence_source": "generated"}, {"text": "迷路の中で、ぐるぐる同じ道を回っていました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "迷路[めいろ]の中[なか]で、ぐるぐる同[おな]じ道[みち]を回[まわ]っていました。", "sentence_source": "generated"}, {"text": "彼は怒って、部屋をぐるぐる歩き続けました。", "target_word": "ぐるぐる", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[おこ]って、部屋[へや]をぐるぐる歩[ある]き続[つづ]けました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ぐるぐる", "label": "基本形"}, {"form": "ぐるぐると", "label": "と付き形"}], "register": "中立", "sense_fingerprint": "同じ場所や同じ範囲を何度も繰り返し回り続けて先へ進まないようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e0634e1-f153-4d90-ad1c-4cf31663d5f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37977, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ぐるぐる", "is_correct": true, "explanation": "同じ場所を繰り返し歩き回って先へ進まない様子に合う。"}, {"text": "ぎっしり", "is_correct": false, "explanation": "物が隙間なく詰まる様子を表すので、歩き回る動きには合わない。"}, {"text": "ぴったり", "is_correct": false, "explanation": "ぴたりと合う様子を表すので、移動の仕方を表さず合わない。"}, {"text": "ばたんと", "is_correct": false, "explanation": "戸などが勢いよく閉まる音や様子を表すので、歩き回る動作とは合わない。"}], "explanations": {"ぐるぐる": "同じ場所を繰り返し歩き回って先へ進まない様子に合う。", "ぎっしり": "物が隙間なく詰まる様子を表すので、歩き回る動きには合わない。", "ぴったり": "ぴたりと合う様子を表すので、移動の仕方を表さず合わない。", "ばたんと": "戸などが勢いよく閉まる音や様子を表すので、歩き回る動作とは合わない。"}, "sentence_index": 0, "correct_answer": "ぐるぐる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "道を一直線にぐるぐる進んで、駅に着きました。", "explanation": "ここは〈まっすぐ〉の意味。ぐるぐるは同じ場所を回り続ける様子で、一直線に進む移動には合わない。"}, {"text": "寒さで、体がぐるぐる震えました。", "explanation": "ここは〈震え〉の意味。ぐるぐるは同じ所を回り続ける様子で、ふるえには使えない。"}, {"text": "ドアが閉まったまま、ぐるぐる動きません。", "explanation": "ここは〈静止〉の意味。ぐるぐるは動き続ける様子を表すので、動かない状態を修飾するとは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37977, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ぐるぐる", "is_correct": true, "explanation": "頭の中で同じ心配が回り続ける様子に合う。"}, {"text": "きれいに", "is_correct": false, "explanation": "整っている様子を表すので、回り続ける動きを表さず合わない。"}, {"text": "ぱっと", "is_correct": false, "explanation": "一瞬で広がったり明るくなったりする様子を表すので、回り続ける動きとは合わない。"}, {"text": "からから", "is_correct": false, "explanation": "乾いた音や様子を表すので、回り続ける動きには合わない。"}], "explanations": {"ぐるぐる": "頭の中で同じ心配が回り続ける様子に合う。", "きれいに": "整っている様子を表すので、回り続ける動きを表さず合わない。", "ぱっと": "一瞬で広がったり明るくなったりする様子を表すので、回り続ける動きとは合わない。", "からから": "乾いた音や様子を表すので、回り続ける動きには合わない。"}, "sentence_index": 6, "correct_answer": "ぐるぐる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一本道を、ぐるぐると歩いて帰りました。", "explanation": "ここは〈てくてく〉の意味。てくてくは一定の速さで先へ進む様子を指すが、ぐるぐるは同じ所を回る様子なので、一本道を進む歩き方とは合わない。"}, {"text": "一瞬でぐるぐる走り抜けました。", "explanation": "ここは〈一瞬〉の意味。ぐるぐるは長く回り続ける様子なので、一瞬で終わる動作には合わない。"}, {"text": "エレベーターが上下にぐるぐる動きました。", "explanation": "ここは〈上下〉の意味。ぐるぐるは円を描くように回る様子で、上下の往復には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37977, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同じ場所をぐるぐるで歩いています。", "corrected_sentence": "同じ場所をぐるぐると歩いています。", "error_description": "誤った形は「ぐるぐるで」、正しい形は「ぐるぐると」。「ぐるぐるで」は助詞「で」が不自然で、「ぐるぐると」にすると動詞を修飾する形として自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37977, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ場所をぐるぐるに歩き回ったのに、出口が見つかりません。", "corrected_sentence": "同じ場所をぐるぐると歩き回ったのに、出口が見つかりません。", "error_description": "「ぐるぐるに」は「歩き回る」に合わない誤り。同じ場所を回り続ける動作を修飾するには「ぐるぐると」が自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df23cad5-342a-436a-a042-357333883758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37978, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「回ると」の「と」。回る動作を条件として後ろの文につなぐ。"}, {"text": "を", "is_correct": false, "explanation": "自動詞「回る」は目的語をとらないので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、回る動作と条件の関係を作れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」だが、この文には行き先がない。"}], "correct_answer": "と", "explanations": {"と": "「回ると」の「と」。回る動作を条件として後ろの文につなぐ。", "を": "自動詞「回る」は目的語をとらないので、「を」は合わない。", "で": "手段や場所を示す「で」は、回る動作と条件の関係を作れない。", "へ": "方向を示す「へ」だが、この文には行き先がない。"}, "error_tags": {"を": "目的語（自動詞は不可）", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37978, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37978, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものがくるくる回ること。", "primary_collocate": null, "pronunciation": "まわる", "ipa": "mawaɾɯ", "syllable_count": 3, "sentences": [{"text": "風が強くて、風車がくるくる回っている。", "target_word": "回って", "complexity_tier": "T3", "furigana": "風(かぜ)が強(つよ)くて、風車(ふうしゃ)がくるくる回(まわ)っている。", "sentence_source": "generated"}, {"text": "コマは勢いよく回ると、長い間たおれない。", "target_word": "回る", "complexity_tier": "T3", "furigana": "コマは勢(いきお)いよく回(まわ)ると、長(なが)い間(あいだ)たおれない。", "sentence_source": "generated"}, {"text": "洗濯機の中で、服がぐるぐる回っている。", "target_word": "回って", "complexity_tier": "T3", "furigana": "洗濯機(せんたくき)の中(なか)で、服(ふく)がぐるぐる回(まわ)っている。", "sentence_source": "generated"}, {"text": "公園の遊具は、押すとくるくる回る。", "target_word": "回る", "complexity_tier": "T3", "furigana": "公園(こうえん)の遊具(ゆうぐ)は、押(お)すとくるくる回(まわ)る。", "sentence_source": "generated"}, {"text": "スイッチを入れると、プロペラが回り始めた。", "target_word": "回り", "complexity_tier": "T3", "furigana": "スイッチを入(い)れると、プロペラが回(まわ)り始(はじ)めた。", "sentence_source": "generated"}, {"text": "ベビーカーの車輪が、ゆっくりくるくる回っている。", "target_word": "回っている", "complexity_tier": "T3", "furigana": "ベビーカーの車輪[しゃりん]が、ゆっくりくるくる回[まわ]っている。", "sentence_source": "generated"}, {"text": "扇風機の羽が速く回ると、涼しい風が出る。", "target_word": "回る", "complexity_tier": "T3", "furigana": "扇風機(せんぷうき)の羽(はね)が速(はや)く回(まわ)ると、涼(すず)しい風(かぜ)が出(で)る。", "sentence_source": "generated"}, {"text": "壊れたおもちゃは、ねじを直したらまた回るようになった。", "target_word": "回る", "complexity_tier": "T3", "furigana": "壊(こわ)れたおもちゃは、ねじを直(なお)したらまた回(まわ)るようになった。", "sentence_source": "generated"}, {"text": "遊園地で、大きな観覧車が静かに回っていた。", "target_word": "回って", "complexity_tier": "T3", "furigana": "遊園地(ゆうえんち)で、大(おお)きな観覧車(かんらんしゃ)が静(しず)かに回(まわ)っていた。", "sentence_source": "generated"}, {"text": "コマが回らないのは、ひもの巻き方が悪いからだ。", "target_word": "回らない", "complexity_tier": "T3", "furigana": "コマが回(まわ)らないのは、ひもの巻(ま)き方(かた)が悪(わる)いからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回る", "label": "辞書形"}, {"form": "回ります", "label": "ます形"}, {"form": "回って", "label": "て形"}, {"form": "回った", "label": "た形"}, {"form": "回らない", "label": "ない形"}, {"form": "回れば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "物がその場でくるくる回転する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: たおれ (Zipf 1.74)']::text[], '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37978, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回って", "is_correct": true, "explanation": "「回っている」の「回って」。て形に「いる」をつけて、風車が回転している状態を表す。"}, {"text": "回り", "is_correct": false, "explanation": "連用形の「回り」に「ている」は続かず、「回りている」は不自然。"}, {"text": "回した", "is_correct": false, "explanation": "他動詞「回す」の形。風車が自分で回る文に、目的語のない「回した」は合わない。"}, {"text": "回れ", "is_correct": false, "explanation": "命令形。「ている」とつながらず、状態を述べる文に合わない。"}], "explanations": {"回って": "「回っている」の「回って」。て形に「いる」をつけて、風車が回転している状態を表す。", "回り": "連用形の「回り」に「ている」は続かず、「回りている」は不自然。", "回した": "他動詞「回す」の形。風車が自分で回る文に、目的語のない「回した」は合わない。", "回れ": "命令形。「ている」とつながらず、状態を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "回って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな音で、窓ガラスがびりびり回った。", "explanation": "ここは〈震える〉の意味。窓ガラスは振動で震えるもので、くるくる回るとは言わない。"}, {"text": "ボールが地面で弾んで、高く回った。", "explanation": "ここは〈弾む〉の意味。地面で跳ね上がる動きは、軸を中心に円を描く回るとは別物なので合わない。"}, {"text": "夕方になって、空がだんだん暗く回った。", "explanation": "ここは〈暗くなる〉の意味。空が暗くなる変化は、くるくる回る動きとは無関係なので回るでは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37978, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回る", "is_correct": true, "explanation": "「回ると」の辞書形。「と」で条件を表し、羽が回る動作を述べる。"}, {"text": "回して", "is_correct": false, "explanation": "て形の「回して」は「と」に続かず、条件の文が成り立たない。"}, {"text": "回せ", "is_correct": false, "explanation": "命令形の「回せ」は「と」に続かず、羽が回る事実を述べる文にならない。"}, {"text": "回そう", "is_correct": false, "explanation": "意志形の「回そう」は「と」の前に来ると意図の文になり、羽が自然に回る条件を表さない。"}], "explanations": {"回る": "「回ると」の辞書形。「と」で条件を表し、羽が回る動作を述べる。", "回して": "て形の「回して」は「と」に続かず、条件の文が成り立たない。", "回せ": "命令形の「回せ」は「と」に続かず、羽が回る事実を述べる文にならない。", "回そう": "意志形の「回そう」は「と」の前に来ると意図の文になり、羽が自然に回る条件を表さない。"}, "sentence_index": 6, "correct_answer": "回る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールが壁に当たって、元の場所に回った。", "explanation": "ここは〈戻る〉の意味。回るは円を描く動きで、元の位置へ帰る様子には合わない。"}, {"text": "ぶつけた足首が大きく回った。", "explanation": "ここは〈腫れる〉の意味。ぶつけた部分がふくれ上がる変化は回るでは表せない。"}, {"text": "雨で服が一気に回った。", "explanation": "ここは〈ぬれる〉の意味。雨で服が濡れる変化は、軸を中心にした回転の意味の回るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37978, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗面器の水が渦を巻いて回りている。", "corrected_sentence": "洗面器の水が渦を巻いて回っている。", "error_description": "「回る」のて形は「回って」。「回りている」は動詞の活用として誤りで、正しくは「回っている」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "回る", "is_correct": true, "explanation": "「回ると」の辞書形。「と」で条件を表すので辞書形が正しい。"}, {"text": "回って", "is_correct": false, "explanation": "て形では「回ってと」と続かず、条件の文が成立しない。"}, {"text": "回り", "is_correct": false, "explanation": "連用形では「回りと」と続かず、文が成立しない。"}, {"text": "回れ", "is_correct": false, "explanation": "命令形の「回れ」は「と」に続かず、条件の文が成立しない。"}], "correct_form": "回る", "base_form": "回る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"回る": "「回ると」の辞書形。「と」で条件を表すので辞書形が正しい。", "回って": "て形では「回ってと」と続かず、条件の文が成立しない。", "回り": "連用形では「回りと」と続かず、文が成立しない。", "回れ": "命令形の「回れ」は「と」に続かず、条件の文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37978, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風車がゆっくり回ったてから止まった。", "corrected_sentence": "風車がゆっくり回ってから止まった。", "error_description": "「回ってから」のて形を「回ったて」と誤っている。正しくは「回ってから」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "回る", "is_correct": true, "explanation": "「回るようになった」の辞書形。「ようになる」の前は辞書形になる。"}, {"text": "回れ", "is_correct": false, "explanation": "命令形の「回れ」は「ようになった」に続かず、文が成立しない。"}, {"text": "回ろう", "is_correct": false, "explanation": "意志形の「回ろう」は「ようになった」に続かず、不自然になる。"}, {"text": "回れば", "is_correct": false, "explanation": "仮定形の「回れば」は「ようになった」に続かず、文が成立しない。"}], "correct_form": "回る", "base_form": "回る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"回る": "「回るようになった」の辞書形。「ようになる」の前は辞書形になる。", "回れ": "命令形の「回れ」は「ようになった」に続かず、文が成立しない。", "回ろう": "意志形の「回ろう」は「ようになった」に続かず、不自然になる。", "回れば": "仮定形の「回れば」は「ようになった」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
