INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37979, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「回ると」の「と」。歯車が回る動作を条件として後ろにつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "自動詞「回る」は目的語をとらないので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、回る動作と条件の関係を作れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」だが、この文には行き先がない。"}], "correct_answer": "と", "explanations": {"と": "「回ると」の「と」。歯車が回る動作を条件として後ろにつなぐ。", "を": "自動詞「回る」は目的語をとらないので、「を」は合わない。", "で": "手段や場所を示す「で」は、回る動作と条件の関係を作れない。", "へ": "方向を示す「へ」だが、この文には行き先がない。"}, "error_tags": {"を": "目的語（自動詞は不可）", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37979, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物が軸を中心にして、円を描くように動くこと。", "primary_collocate": null, "pronunciation": "まわる", "ipa": "mawaɾɯ", "syllable_count": 3, "sentences": [{"text": "地球は一日に一度、自分の軸を中心にして回っている。", "target_word": "回っている", "complexity_tier": "T3", "furigana": "地球[ちきゅう]は一日[いちにち]に一度[いちど]、自分[じぶん]の軸[じく]を中心[ちゅうしん]にして回[まわ]っている。", "sentence_source": "generated"}, {"text": "ドリルの先端が、金属に穴をあけながら速く回る。", "target_word": "回る", "complexity_tier": "T3", "furigana": "ドリルの先端[せんたん]が、金属[きんぞく]に穴[あな]をあけながら速[はや]く回[まわ]る。", "sentence_source": "generated"}, {"text": "時計の針は、決まった方向に回る。", "target_word": "回る", "complexity_tier": "T3", "furigana": "時計(とけい)の針(はり)は、決(き)まった方向(ほうこう)に回(まわ)る。", "sentence_source": "generated"}, {"text": "タイヤが回ると、自動車は前に進む。", "target_word": "回る", "complexity_tier": "T3", "furigana": "タイヤが回(まわ)ると、自動車(じどうしゃ)は前(まえ)に進(すす)む。", "sentence_source": "generated"}, {"text": "水車は川の水の力で回っている。", "target_word": "回って", "complexity_tier": "T3", "furigana": "水車(すいしゃ)は川(かわ)の水(みず)の力(ちから)で回(まわ)っている。", "sentence_source": "generated"}, {"text": "ろくろは、足で踏むと軸を中心にして回る。", "target_word": "回る", "complexity_tier": "T3", "furigana": "ろくろは、足[あし]で踏[ふ]むと軸[じく]を中心[ちゅうしん]にして回[まわ]る。", "sentence_source": "generated"}, {"text": "回転ドアが回る音が、ロビーに小さく聞こえた。", "target_word": "回る", "complexity_tier": "T3", "furigana": "回転(かいてん)ドアが回(まわ)る音(おと)が、ロビーに小(ちい)さく聞(き)こえた。", "sentence_source": "generated"}, {"text": "歯車が一つ回ると、ほかの歯車も同時に回る。", "target_word": "回る", "complexity_tier": "T3", "furigana": "歯車(はぐるま)が一(ひと)つ回(まわ)ると、ほかの歯車(はぐるま)も同時(どうじ)に回(まわ)る。", "sentence_source": "generated"}, {"text": "軸が曲がっていると、この車輪はうまく回らない。", "target_word": "回らない", "complexity_tier": "T3", "furigana": "軸(じく)が曲(ま)がっていると、この車輪(しゃりん)はうまく回(まわ)らない。", "sentence_source": "generated"}, {"text": "このダイヤルは軸を中心にして回り、音量を変える。", "target_word": "回り", "complexity_tier": "T3", "furigana": "このダイヤルは軸[じく]を中心[ちゅうしん]にして回[まわ]り、音量[おんりょう]を変[か]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回る", "label": "辞書形"}, {"form": "回ります", "label": "ます形"}, {"form": "回って", "label": "て形"}, {"form": "回った", "label": "た形"}, {"form": "回らない", "label": "ない形"}, {"form": "回れば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "軸や中心のまわりを円を描いて動く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37979, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回っている", "is_correct": true, "explanation": "地球が自分で回り続けている状態を表す「回っている」。"}, {"text": "回らせている", "is_correct": false, "explanation": "使役の形で、地球が他に回らせる意味になり、地球が自ら回る文に合わない。"}, {"text": "回された", "is_correct": false, "explanation": "受身の形で、地球を主語にした自然な文にならない。"}, {"text": "回らず", "is_correct": false, "explanation": "連用中止形で、文を終えられず、軸を中心に回る文として成立しない。"}], "explanations": {"回っている": "地球が自分で回り続けている状態を表す「回っている」。", "回らせている": "使役の形で、地球が他に回らせる意味になり、地球が自ら回る文に合わない。", "回された": "受身の形で、地球を主語にした自然な文にならない。", "回らず": "連用中止形で、文を終えられず、軸を中心に回る文として成立しない。"}, "sentence_index": 0, "correct_answer": "回っている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアを開けると、カーテンが大きく回った。", "explanation": "ここは〈揺れる〉の意味。カーテンは風や動きで揺れるもので、円を描いて回るとは言わない。"}, {"text": "熟したりんごが木から回った。", "explanation": "ここは〈落ちる〉の意味。回るは円を描く動きなので、下へ落ちる様子には合わない。"}, {"text": "風が吹くと、木の葉が一斉に回った。", "explanation": "ここは〈散る〉の意味。木の葉が風に吹かれて散る様子は、軸を中心にした回転とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37979, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回る", "is_correct": true, "explanation": "「回る音」の辞書形。音を修飾する形として自然で、回転ドアの音を表す。"}, {"text": "回って", "is_correct": false, "explanation": "「回って音」は続かず、名詞を修飾できない。"}, {"text": "回り", "is_correct": false, "explanation": "連用形の「回り音」は不自然で、名詞修飾にならない。"}, {"text": "回した", "is_correct": false, "explanation": "他動詞「回す」の形で、ドアが主語の自然な文にならない。"}], "explanations": {"回る": "「回る音」の辞書形。音を修飾する形として自然で、回転ドアの音を表す。", "回って": "「回って音」は続かず、名詞を修飾できない。", "回り": "連用形の「回り音」は不自然で、名詞修飾にならない。", "回した": "他動詞「回す」の形で、ドアが主語の自然な文にならない。"}, "sentence_index": 6, "correct_answer": "回る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "おもちゃ箱から、ビーズが床に一面に回った。", "explanation": "ここは〈散らばる〉の意味。ビーズが床に広く散る様子を回るで表すのは誤り。"}, {"text": "風鈴が風を受けて回る。", "explanation": "ここは〈揺れる〉の意味。風鈴は揺れて音を出すもので、円を描いて回るとは言わない。"}, {"text": "布を洗ったら、セーターがすぐ回った。", "explanation": "ここは〈縮む〉の意味。洗濯で布が縮む変化は回るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37979, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "コンパスの針が、ひとりでに回らって止まった。", "corrected_sentence": "コンパスの針が、ひとりでに回って止まった。", "error_description": "「回る」のて形は「回って」。「回らって」は活用として誤りで、正しくは「回って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "回る", "is_correct": true, "explanation": "文末で文を終える辞書形。「速く回る。」の形。"}, {"text": "回って", "is_correct": false, "explanation": "て形では文が終わらず、文として成立しない。"}, {"text": "回り", "is_correct": false, "explanation": "連用形では文が終わらず、不自然。"}, {"text": "回らせ", "is_correct": false, "explanation": "使役の連用形で文が終わらず、文として成立しない。"}], "correct_form": "回る", "base_form": "回る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"回る": "文末で文を終える辞書形。「速く回る。」の形。", "回って": "て形では文が終わらず、文として成立しない。", "回り": "連用形では文が終わらず、不自然。", "回らせ": "使役の連用形で文が終わらず、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37979, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "時計の長針がゆっくり回られると、一時間が過ぎる。", "corrected_sentence": "時計の長針がゆっくり回ると、一時間が過ぎる。", "error_description": "「回る」は自動詞なので受身「回られる」にはできない。正しくは「回ると」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "回る", "is_correct": true, "explanation": "文末で文を終える辞書形。「同時に回る。」の形。"}, {"text": "回れば", "is_correct": false, "explanation": "仮定形の「回れば」は後ろに文が続く必要があり、ここで文を終えられない。"}, {"text": "回らないと", "is_correct": false, "explanation": "「回らないと」は条件の形で、文末では文が完結せず成立しない。"}, {"text": "回らなくて", "is_correct": false, "explanation": "て形の「回らなくて」は文を終えられず、文として成立しない。"}], "correct_form": "回る", "base_form": "回る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"回る": "文末で文を終える辞書形。「同時に回る。」の形。", "回れば": "仮定形の「回れば」は後ろに文が続く必要があり、ここで文を終えられない。", "回らないと": "「回らないと」は条件の形で、文末では文が完結せず成立しない。", "回らなくて": "て形の「回らなくて」は文を終えられず、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
