INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37981, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "力を入れる対象を示す。「リサイクルに力を入れる」で正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「リサイクルを力を入れる」と二つ並ぶ形になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「リサイクルへ力を入れる」では対象を表せず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「リサイクルから力を入れる」では、力を入れる対象にならない。"}], "correct_answer": "に", "explanations": {"に": "力を入れる対象を示す。「リサイクルに力を入れる」で正しい。", "を": "目的語を示す。「リサイクルを力を入れる」と二つ並ぶ形になり不自然。", "へ": "方向を示す。「リサイクルへ力を入れる」では対象を表せず、意味が通らない。", "から": "起点を示す。「リサイクルから力を入れる」では、力を入れる対象にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37981, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "リサイクルとは、使わなくなったものを新しく別の製品に作り変えることです。ゴミを減らすために行われます。", "primary_collocate": null, "pronunciation": "りさいくる", "ipa": "ɾisaikɯɾɯ", "syllable_count": 5, "sentences": [{"text": "ペットボトルは、リサイクルされて服の材料になる。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "ペットボトルは、リサイクルされて服[ふく]の材料[ざいりょう]になる。", "sentence_source": "generated"}, {"text": "古い新聞紙をリサイクルして、トイレットペーパーを作っている。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "古[ふる]い新聞紙[しんぶんし]をリサイクルして、トイレットペーパーを作[つく]っている。", "sentence_source": "generated"}, {"text": "集めたアルミ缶は、リサイクルによって新しい缶に生まれ変わる。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "集[あつ]めたアルミ缶[かん]は、リサイクルによって新[あたら]しい缶[かん]に生[う]まれ変[か]わる。", "sentence_source": "generated"}, {"text": "ごみを減らすために、工場でリサイクルが行われている。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "ごみを減[へ]らすために、工場[こうじょう]でリサイクルが行[おこな]われている。", "sentence_source": "generated"}, {"text": "リサイクルの技術が進んで、古い服から新しい糸ができる。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "リサイクルの技術[ぎじゅつ]が進[すす]んで、古[ふる]い服[ふく]から新[あたら]しい糸[いと]ができる。", "sentence_source": "generated"}, {"text": "この文房具は、リサイクルした紙で作られている。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "この文房具[ぶんぼうぐ]は、リサイクルした紙[かみ]で作[つく]られている。", "sentence_source": "generated"}, {"text": "古い家電をリサイクルすると、金属を取り出して使える。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "古[ふる]い家電[かでん]をリサイクルすると、金属[きんぞく]を取[と]り出[だ]して使[つか]える。", "sentence_source": "generated"}, {"text": "市はごみを減らすため、リサイクルに力を入れている。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "市[し]はごみを減[へ]らすため、リサイクルに力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "リサイクルしたガラスから、きれいなコップができた。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "リサイクルしたガラスから、きれいなコップができた。", "sentence_source": "generated"}, {"text": "使えなくなったタイヤをリサイクルして、道路の材料にする。", "target_word": "リサイクル", "complexity_tier": "T3", "furigana": "使[つか]えなくなったタイヤをリサイクルして、道路[どうろ]の材料[ざいりょう]にする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リサイクル", "label": "基本形"}, {"form": "リサイクルする", "label": "動詞形"}], "register": "neutral", "sense_fingerprint": "不要になったものを原料にして別の新製品に作り変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37981, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リサイクル", "is_correct": true, "explanation": "使い終わった物を原料にして別の製品に作り変える流れに合う。"}, {"text": "焼却", "is_correct": false, "explanation": "燃やす意味で、服の材料にはならないので合わない。"}, {"text": "破棄", "is_correct": false, "explanation": "捨てる意味で、材料として生かす文脈と逆になる。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにしておく意味で、材料になる流れと合わない。"}], "explanations": {"リサイクル": "使い終わった物を原料にして別の製品に作り変える流れに合う。", "焼却": "燃やす意味で、服の材料にはならないので合わない。", "破棄": "捨てる意味で、材料として生かす文脈と逆になる。", "放置": "そのままにしておく意味で、材料になる流れと合わない。"}, "sentence_index": 0, "correct_answer": "リサイクル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ごみは、燃えるものと燃えないものにリサイクルして出す。", "explanation": "ここは〈分別〉の意味。リサイクルは別の製品に作り変えることで、種類ごとに仕分けることではない。"}, {"text": "古い椅子は、リサイクルの名で燃やされて灰になった。", "explanation": "ここは〈焼却〉の意味。リサイクルは材料を別の製品に作り変えることで、燃やして灰にする意味ではない。"}, {"text": "古い家を、家族に合わせてリサイクルした。", "explanation": "ここは〈リフォーム（改築）〉の意味。リサイクルは使わなくなったものを別の製品に作り変えることで、家を改築して住み続ける意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37981, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リサイクル", "is_correct": true, "explanation": "家電から金属を取り出して使う、材料に戻す文脈に合う。"}, {"text": "精算", "is_correct": false, "explanation": "支払いを済ませる意味で、金属を取り出す流れに合わない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味で、金属を取り出すことには関係しない。"}, {"text": "鑑賞", "is_correct": false, "explanation": "見て楽しむ意味で、金属を取り出して使う文脈とは合わない。"}], "explanations": {"リサイクル": "家電から金属を取り出して使う、材料に戻す文脈に合う。", "精算": "支払いを済ませる意味で、金属を取り出す流れに合わない。", "施錠": "鍵をかける意味で、金属を取り出すことには関係しない。", "鑑賞": "見て楽しむ意味で、金属を取り出して使う文脈とは合わない。"}, "sentence_index": 6, "correct_answer": "リサイクル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ごみは、リサイクルして灰にする。", "explanation": "ここは〈焼却〉の意味。リサイクルは材料を別の製品に作り変えることで、燃やして灰にする意味ではない。"}, {"text": "使わない布団は、リサイクルの名で、ごみ袋に入れて捨てる。", "explanation": "ここは〈廃棄〉の意味。リサイクルは材料を別の製品に作り変えることで、ただ捨てることではない。"}, {"text": "使わない道具は、リサイクルの代わりに、森の中へ埋める。", "explanation": "ここは〈埋め立て〉の意味。リサイクルは作り変えることで、埋めて処分することではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37981, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いびんは、リサイクルを新しいコップになる。", "corrected_sentence": "古いびんは、リサイクルによって新しいコップになる。", "error_description": "「リサイクルによって」の「によって」が正しい。「を」は目的語を示すので、材料から新しい製品になる手段を表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37981, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い鍋は、リサイクルできれて、新しい皿になる。", "corrected_sentence": "古い鍋は、リサイクルできて、新しい皿になる。", "error_description": "「できて」の形が正しい。「できれて」は可能の「できる」に余計な「れ」が入った誤りで、標準の形ではない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
