INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37982, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "相手や状況を思いやり、「さぞ〜だろう」と推し量る副詞。", "primary_collocate": null, "pronunciation": "さぞ", "ipa": "sazo", "syllable_count": 2, "sentences": [{"text": "長い旅だったから、さぞ疲れたでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "長(なが)い旅(たび)だったから、さぞ疲(つか)れたでしょう。", "sentence_source": "generated"}, {"text": "試合に負けて、さぞ悔しかったでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "試合(しあい)に負(ま)けて、さぞ悔(くや)しかったでしょう。", "sentence_source": "generated"}, {"text": "一人で暮らすのは、さぞ寂しいことでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "一人(ひとり)で暮(く)らすのは、さぞ寂(さび)しいことでしょう。", "sentence_source": "generated"}, {"text": "合格の知らせを聞いて、ご両親もさぞ喜ばれたことでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "合格(ごうかく)の知(し)らせを聞(き)いて、ご両親(りょうしん)もさぞ喜(よろこ)ばれたことでしょう。", "sentence_source": "generated"}, {"text": "こんなに暑い日に外で働くのは、さぞ大変だったでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "こんなに暑(あつ)い日(ひ)に外(そと)で働(はたら)くのは、さぞ大変(たいへん)だったでしょう。", "sentence_source": "generated"}, {"text": "あの店は有名だから、さぞ人気があるでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "あの店(みせ)は有名(ゆうめい)だから、さぞ人気(にんき)があるでしょう。", "sentence_source": "generated"}, {"text": "山の上から見る景色は、さぞきれいでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)から見(み)る景色(けしき)は、さぞきれいでしょう。", "sentence_source": "generated"}, {"text": "毎日残業が続いて、さぞ眠いことでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "毎日(まいにち)残業(ざんぎょう)が続(つづ)いて、さぞ眠(ねむ)いことでしょう。", "sentence_source": "generated"}, {"text": "子どもが遠くへ行って、母親はさぞ心配しているでしょう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "子(こ)どもが遠(とお)くへ行(い)って、母親(ははおや)はさぞ心配(しんぱい)しているでしょう。", "sentence_source": "generated"}, {"text": "初めての海外生活は、さぞ不安だったでしょうね。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "初(はじ)めての海外生活(かいがいせいかつ)は、さぞ不安(ふあん)だったでしょうね。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘸", "label": "基本形"}, {"form": "さぞ", "label": "かな表記"}], "register": "neutral", "sense_fingerprint": "相手の気持ちや状況を思いやって推し量る副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37982, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "さぞ", "is_correct": true, "explanation": "相手の状況や気持ちを思いやって推し量る副詞。「さぞ疲れたでしょう」の形に合う。"}, {"text": "ぜひ", "is_correct": false, "explanation": "強い願望を表す副詞で、疲れたという推量の文には合わない。"}, {"text": "さっそく", "is_correct": false, "explanation": "「すぐに」の意味で、疲労を推し量る文には合わない。"}, {"text": "ついに", "is_correct": false, "explanation": "「ようやく」の意味で、推量の文の流れに合わない。"}], "explanations": {"さぞ": "相手の状況や気持ちを思いやって推し量る副詞。「さぞ疲れたでしょう」の形に合う。", "ぜひ": "強い願望を表す副詞で、疲れたという推量の文には合わない。", "さっそく": "「すぐに」の意味で、疲労を推し量る文には合わない。", "ついに": "「ようやく」の意味で、推量の文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "さぞ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "さぞ、昨日の会議は中止になった。", "explanation": "ここは〈事実の断定〉の意味。さぞは推量の副詞なので、確定した事実を述べる文には合わない。"}, {"text": "つい寝坊して、さぞ遅刻してしまった。", "explanation": "ここは〈思わず・うっかり〉の意味。さぞは他人の状況を推し量る語で、自分の失敗には合わない。"}, {"text": "さぞ早く来てください。", "explanation": "ここは〈ぜひ（強く求める）〉の意味。さぞは推量の副詞で、依頼の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37982, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "さぞ", "is_correct": true, "explanation": "景色の様子を推し量る副詞。「さぞきれいでしょう」の形に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「ぐっすり」は深く眠るさまを表す副詞で、景色の推量の文には合わない。"}, {"text": "こっそり", "is_correct": false, "explanation": "「こっそり」は人に知られないようにするさまで、景色の推量には合わない。"}, {"text": "じっくり", "is_correct": false, "explanation": "「じっくり」は時間をかけて丁寧に行うさまで、「きれいでしょう」の推量には合わない。"}], "explanations": {"さぞ": "景色の様子を推し量る副詞。「さぞきれいでしょう」の形に合う。", "ぐっすり": "「ぐっすり」は深く眠るさまを表す副詞で、景色の推量の文には合わない。", "こっそり": "「こっそり」は人に知られないようにするさまで、景色の推量には合わない。", "じっくり": "「じっくり」は時間をかけて丁寧に行うさまで、「きれいでしょう」の推量には合わない。"}, "sentence_index": 6, "correct_answer": "さぞ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "さぞ本当だとは思わなかった。", "explanation": "ここは〈まさか（意外さ）〉の意味。さぞは推量の副詞で、意外に思う気持ちは表せない。"}, {"text": "さぞ試合に勝った。", "explanation": "ここは〈ついに（ようやく）〉の意味。確かな結果を述べる文に、推量のさぞは合わない。"}, {"text": "さぞ一口だけでも食べてください。", "explanation": "ここは〈せめて（最低限）〉の意味。さぞは推量の副詞で、依頼の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37982, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩遅くまで働いて、さぞと疲れているでしょう。", "corrected_sentence": "毎晩遅くまで働いて、さぞ疲れているでしょう。", "error_description": "「さぞ」に格助詞「と」をつけたのが誤り。さぞは副詞なので、後ろに「と」は直接つかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37982, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い冬の夜、さぞを心細かったでしょう。", "corrected_sentence": "寒い冬の夜、さぞ心細かったでしょう。", "error_description": "「さぞ」の後ろに格助詞「を」をつけたのが誤り。副詞のさぞには格助詞は続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
