INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37983, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "相手や過去の状況を思いやり、「さぞ〜であろう」と推し量る文語的な副詞。", "primary_collocate": null, "pronunciation": "さぞ", "ipa": "sazo", "syllable_count": 2, "sentences": [{"text": "長い年月を思えば、故郷の人々もさぞ待ちわびたことであろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "長(なが)い年月(としつき)を思(おも)えば、故郷(こきょう)の人々(ひとびと)もさぞ待(ま)ちわびたことであろう。", "sentence_source": "generated"}, {"text": "戦のあとの村は、さぞ荒れ果てていたことであろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "戦(いくさ)のあとの村(むら)は、さぞ荒(あ)れ果(は)てていたことであろう。", "sentence_source": "generated"}, {"text": "山深い里の冬は、さぞ厳しかったことだろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "山深(やまふか)い里(さと)の冬(ふゆ)は、さぞ厳(きび)しかったことだろう。", "sentence_source": "generated"}, {"text": "久しぶりの帰郷に、母はさぞ喜んだであろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "久(ひさ)しぶりの帰郷(ききょう)に、母(はは)はさぞ喜(よろこ)んだであろう。", "sentence_source": "generated"}, {"text": "旅人は、さぞ喉が渇いていたに違いない。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "旅人(たびびと)は、さぞ喉(のど)が渇(かわ)いていたに違(ちが)いない。", "sentence_source": "generated"}, {"text": "昔の人々は、満月をさぞ美しいと眺めたことだろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "昔(むかし)の人々(ひとびと)は、満月(まんげつ)をさぞ美(うつく)しいと眺(なが)めたことだろう。", "sentence_source": "generated"}, {"text": "嵐の夜を過ごした船乗りは、さぞ心細かったであろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "嵐(あらし)の夜(よる)を過(す)ごした船乗(ふなの)りは、さぞ心細(こころぼそ)かったであろう。", "sentence_source": "generated"}, {"text": "老僧は、遠い都のことをさぞ懐かしく思ったことだろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "老僧(ろうそう)は、遠(とお)い都(みやこ)のことをさぞ懐(なつ)かしく思(おも)ったことだろう。", "sentence_source": "generated"}, {"text": "雪に閉ざされた峠では、行商人はさぞ難儀したことだろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "雪(ゆき)に閉(と)ざされた峠(とうげ)では、行商人(ぎょうしょうにん)はさぞ難儀(なんぎ)したことだろう。", "sentence_source": "generated"}, {"text": "若き日の父は、この道をさぞ急いで歩いたことであろう。", "target_word": "さぞ", "complexity_tier": "T3", "furigana": "若(わか)き日(ひ)の父(ちち)は、この道(みち)をさぞ急(いそ)いで歩(ある)いたことであろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘸", "label": "基本形"}, {"form": "さぞ", "label": "かな表記"}], "register": "literary", "sense_fingerprint": "文語的な文体で推量を示す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 心細かっ (Zipf 1.76)']::text[], '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37983, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "さぞ", "is_correct": true, "explanation": "相手の心情を思いやって推量する副詞。「さぞ待ちわびた」の形に合う。"}, {"text": "ぜひ", "is_correct": false, "explanation": "強い願望を表す語で、推量の文には合わない。"}, {"text": "ついに", "is_correct": false, "explanation": "「とうとう」の意味で、推量の文の流れに合わない。"}, {"text": "さっそく", "is_correct": false, "explanation": "「すぐに」の意味で、心情の推量には合わない。"}], "explanations": {"さぞ": "相手の心情を思いやって推量する副詞。「さぞ待ちわびた」の形に合う。", "ぜひ": "強い願望を表す語で、推量の文には合わない。", "ついに": "「とうとう」の意味で、推量の文の流れに合わない。", "さっそく": "「すぐに」の意味で、心情の推量には合わない。"}, "sentence_index": 0, "correct_answer": "さぞ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "さぞ彼が来ようとは思わなかった。", "explanation": "ここは〈まさか（意外さ）〉の意味。さぞは推量の副詞で、意外さを表す文には合わない。"}, {"text": "さぞ口を滑らせてしまった。", "explanation": "ここは〈つい（思わず）〉の意味。さぞは他人の心情を推し量る語で、自分の失言には合わない。"}, {"text": "さぞ一度おいでください。", "explanation": "ここは〈ぜひ（強い願い）〉の意味。さぞは推量の副詞で、誘いの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37983, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "さぞ", "is_correct": true, "explanation": "船乗りの心細さを推し量る副詞。「さぞ心細かったであろう」の形に合う。"}, {"text": "うっかり", "is_correct": false, "explanation": "「うっかり」は不注意でするさまを表す副詞で、船乗りの心細さを推し量る文には合わない。"}, {"text": "そっと", "is_correct": false, "explanation": "「そっと」は静かにするさまで、心細さの推量には合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「ぐっすり」は深く眠るさまで、心細さを推し量る文には合わない。"}], "explanations": {"さぞ": "船乗りの心細さを推し量る副詞。「さぞ心細かったであろう」の形に合う。", "うっかり": "「うっかり」は不注意でするさまを表す副詞で、船乗りの心細さを推し量る文には合わない。", "そっと": "「そっと」は静かにするさまで、心細さの推量には合わない。", "ぐっすり": "「ぐっすり」は深く眠るさまで、心細さを推し量る文には合わない。"}, "sentence_index": 6, "correct_answer": "さぞ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "さぞ一目会いたかった。", "explanation": "ここは〈せめて（最低限）〉の意味。さぞは推量の副詞で、最低限の願いを表す文には合わない。"}, {"text": "さぞ雨が降れば、道はぬかるむであろう。", "explanation": "ここは〈もし（仮定）〉の意味。さぞは推量の副詞で、仮定の条件を述べる文には合わない。"}, {"text": "さぞ彼は約束を守った。", "explanation": "ここは〈たしかに（確認）〉の意味。さぞは推量で、確かな事実の確認には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37983, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "戦に敗れた兵は、さぞと無念であったであろう。", "corrected_sentence": "戦に敗れた兵は、さぞ無念であったであろう。", "error_description": "「さぞ」に格助詞「と」をつけたのが誤り。さぞは副詞なので、後ろに「と」は直接つかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37983, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "嵐の晩に外にいた旅人は、さぞを寒かったことであろう。", "corrected_sentence": "嵐の晩に外にいた旅人は、さぞ寒かったことであろう。", "error_description": "「さぞ」の後ろに格助詞「を」をつけたのが誤り。副詞のさぞには格助詞は続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37987, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37987, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は目的語を示し、「古い縁をたどって」と縁を目的語にする関係を作る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、縁がたどるという関係は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すが、縁にたどるとは続かず不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同を示すが、縁とたどるという組み合わせは成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「を」は目的語を示し、「古い縁をたどって」と縁を目的語にする関係を作る。", "が": "「が」は主語を示すが、縁がたどるという関係は成り立たない。", "に": "「に」は方向や相手を示すが、縁にたどるとは続かず不自然になる。", "と": "「と」は共同を示すが、縁とたどるという組み合わせは成り立たない。"}, "error_tags": {"が": "主語", "に": "方向", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37987, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物事の間にある、つながりや関係。", "primary_collocate": null, "pronunciation": "えん", "ipa": "eɴ", "syllable_count": 2, "sentences": [{"text": "二人は結婚して、夫婦の縁で結ばれた。", "target_word": "縁", "complexity_tier": "T3", "furigana": "二人(ふたり)は結婚(けっこん)して、夫婦(ふうふ)の縁(えん)で結(むす)ばれた。", "sentence_source": "generated"}, {"text": "縁あって、この学校で働くことになりました。", "target_word": "縁", "complexity_tier": "T3", "furigana": "縁(えん)あって、この学校(がっこう)で働(はたら)くことになりました。", "sentence_source": "generated"}, {"text": "長年の友人との縁を大切にしている。", "target_word": "縁", "complexity_tier": "T3", "furigana": "長年(ながねん)の友人(ゆうじん)との縁(えん)を大切(たいせつ)にしている。", "sentence_source": "generated"}, {"text": "親戚とは縁が薄く、会うことはほとんどない。", "target_word": "縁", "complexity_tier": "T3", "furigana": "親戚(しんせき)とは縁(えん)が薄(うす)く、会(あ)うことはほとんどない。", "sentence_source": "generated"}, {"text": "出会いも縁だと思って、誘いを受けた。", "target_word": "縁", "complexity_tier": "T3", "furigana": "出会(であ)いも縁(えん)だと思(おも)って、誘(さそ)いを受(う)けた。", "sentence_source": "generated"}, {"text": "喧嘩をして以来、彼との縁は切れたままだ。", "target_word": "縁", "complexity_tier": "T3", "furigana": "喧嘩(けんか)をして以来(いらい)、彼(かれ)との縁(えん)は切(き)れたままだ。", "sentence_source": "generated"}, {"text": "この仕事を通じて、多くの人と縁ができた。", "target_word": "縁", "complexity_tier": "T3", "furigana": "この仕事(しごと)を通(つう)じて、多(おお)くの人(ひと)と縁(えん)ができた。", "sentence_source": "generated"}, {"text": "古い縁をたどって、昔の先生に連絡した。", "target_word": "縁", "complexity_tier": "T3", "furigana": "古(ふる)い縁(えん)をたどって、昔(むかし)の先生(せんせい)に連絡(れんらく)した。", "sentence_source": "generated"}, {"text": "縁がなかったと思って、あきらめるしかない。", "target_word": "縁", "complexity_tier": "T3", "furigana": "縁(えん)がなかったと思(おも)って、あきらめるしかない。", "sentence_source": "generated"}, {"text": "人と人の縁は、思いがけないところでつながっている。", "target_word": "縁", "complexity_tier": "T3", "furigana": "人(ひと)と人(ひと)の縁(えん)は、思(おも)いがけないところでつながっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "縁", "label": "基本形"}, {"form": "縁が", "label": "主格形"}, {"form": "縁を", "label": "目的格形"}], "register": "neutral", "sense_fingerprint": "縁: 人と人、人と物事を結びつける巡り合わせ・関係（縁を切る／縁を大切にする）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3341fe39-513f-44b0-a106-ff7ae65fce28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37987, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "縁", "is_correct": true, "explanation": "夫婦となる巡り合わせを指し、「夫婦の縁で結ばれた」に合う。"}, {"text": "報酬", "is_correct": false, "explanation": "報酬は働いた対価の金銭のことで、夫婦の結びつきには合わない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は調理道具のことで、夫婦の結びつきを表すことはできない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さのことで、人と人の結びつきとは関係がない。"}], "explanations": {"縁": "夫婦となる巡り合わせを指し、「夫婦の縁で結ばれた」に合う。", "報酬": "報酬は働いた対価の金銭のことで、夫婦の結びつきには合わない。", "包丁": "包丁は調理道具のことで、夫婦の結びつきを表すことはできない。", "体重": "体重は体の重さのことで、人と人の結びつきとは関係がない。"}, "sentence_index": 0, "correct_answer": "縁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この仕事の縁は、一日一万円だ。", "explanation": "ここは〈報酬〉の意味。仕事への対価は報酬と言い、縁は人や物事の間のつながりを表すので合わない。"}, {"text": "息子は親に縁を果たすよう求められた。", "explanation": "ここは〈義務〉の意味。課せられた務めは義務を果たすと言い、縁は人や物事の巡り合わせを表すので合わない。"}, {"text": "今年の運勢は縁が良い。", "explanation": "ここは〈縁起〉の意味。運の良し悪しは縁起が良いと言い、縁は人や物事のつながりを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37987, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "縁", "is_correct": true, "explanation": "人との結びつきが生まれる意味で、「多くの人と縁ができた」に合う。"}, {"text": "機械", "is_correct": false, "explanation": "機械は動力で動く道具のことで、人との結びつきとは合わない。"}, {"text": "財産", "is_correct": false, "explanation": "財産は持っている資産のことで、人との縁ができたとは言えない。"}, {"text": "汚れ", "is_correct": false, "explanation": "汚れは付着した汚い部分のことで、人との縁を表すことはできない。"}], "explanations": {"縁": "人との結びつきが生まれる意味で、「多くの人と縁ができた」に合う。", "機械": "機械は動力で動く道具のことで、人との結びつきとは合わない。", "財産": "財産は持っている資産のことで、人との縁ができたとは言えない。", "汚れ": "汚れは付着した汚い部分のことで、人との縁を表すことはできない。"}, "sentence_index": 6, "correct_answer": "縁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転んで膝に縁ができた。", "explanation": "ここは〈傷〉の意味。体にできた傷は傷ができたと言い、縁は人や物事のつながりを表すので合わない。"}, {"text": "彼女は計算の縁がとても高い。", "explanation": "ここは〈能力〉の意味。計算の力は能力や才能が高いと言い、縁は人や物事の巡り合わせを表すので合わない。"}, {"text": "今朝の試験の縁は、とても難しかった。", "explanation": "ここは〈出題〉の意味。試験の内容は問題や出題と言い、縁は人や物事のつながりを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37987, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人との縁を深まった。", "corrected_sentence": "友人との縁が深まった。", "error_description": "「縁」の後の助詞が「を」になっている。「深まる」は自動詞なので、主語の縁を「が」で示す。「を」では目的語になり、自動詞と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37987, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その人との縁が、少しずつ深めていった。", "corrected_sentence": "その人との縁が、少しずつ深まっていった。", "error_description": "主語「縁が」に他動詞「深める」を付けている。縁は自然に深まるものなので、自動詞「深まる」に直す必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a82d39fa-2dd0-4646-8b07-b3dbe39c16e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
