INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37991, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37991, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを危険や損害から守ること。また、その状態。", "primary_collocate": null, "pronunciation": "ほご", "ipa": "hoɡo", "syllable_count": 2, "sentences": [{"text": "絶滅しそうな動物を保護するために、法律が作られた。", "target_word": "保護", "complexity_tier": "T3", "furigana": "絶滅(ぜつめつ)しそうな動物(どうぶつ)を保護(ほご)するために、法律(ほうりつ)が作(つく)られた。", "sentence_source": "generated"}, {"text": "迷子の子どもは、警察に保護された。", "target_word": "保護", "complexity_tier": "T3", "furigana": "迷子(まいご)の子(こ)どもは、警察(けいさつ)に保護(ほご)された。", "sentence_source": "generated"}, {"text": "けがをした鳥を見つけて、保護して病院に連れていった。", "target_word": "保護", "complexity_tier": "T3", "furigana": "けがをした鳥(とり)を見(み)つけて、保護(ほご)して病院(びょういん)に連(つ)れていった。", "sentence_source": "generated"}, {"text": "自然を保護する活動に、毎年参加している。", "target_word": "保護", "complexity_tier": "T3", "furigana": "自然(しぜん)を保護(ほご)する活動(かつどう)に、毎年(まいとし)参加(さんか)している。", "sentence_source": "generated"}, {"text": "個人の情報を保護することは、会社の大切な責任だ。", "target_word": "保護", "complexity_tier": "T3", "furigana": "個人(こじん)の情報(じょうほう)を保護(ほご)することは、会社(かいしゃ)の大切(たいせつ)な責任(せきにん)だ。", "sentence_source": "generated"}, {"text": "親を亡くした子猫を保護して、家で育てている。", "target_word": "保護", "complexity_tier": "T3", "furigana": "親(おや)を亡(な)くした子猫(こねこ)を保護(ほご)して、家(いえ)で育(そだ)てている。", "sentence_source": "generated"}, {"text": "台風の間、住民は安全な学校に保護された。", "target_word": "保護", "complexity_tier": "T3", "furigana": "台風(たいふう)の間(あいだ)、住民(じゅうみん)は安全(あんぜん)な学校(がっこう)に保護(ほご)された。", "sentence_source": "generated"}, {"text": "消費者を保護する法律が、新しく決まった。", "target_word": "保護", "complexity_tier": "T3", "furigana": "消費者(しょうひしゃ)を保護(ほご)する法律(ほうりつ)が、新(あたら)しく決(き)まった。", "sentence_source": "generated"}, {"text": "山のサルは、国の保護のもとで数がふえた。", "target_word": "保護", "complexity_tier": "T3", "furigana": "山(やま)のサルは、国(くに)の保護(ほご)のもとで数(かず)がふえた。", "sentence_source": "generated"}, {"text": "川の水がきれいなのは、町が長い間保護してきたからだ。", "target_word": "保護", "complexity_tier": "T3", "furigana": "川(かわ)の水(みず)がきれいなのは、町(まち)が長(なが)い間(あいだ)保護(ほご)してきたからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保護", "label": "名詞形"}, {"form": "保護する", "label": "辞書形"}, {"form": "保護します", "label": "ます形"}, {"form": "保護して", "label": "て形"}, {"form": "保護した", "label": "た形"}, {"form": "保護しない", "label": "ない形"}, {"form": "保護される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "人・動物・自然などを危険や害から守る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37991, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保護", "is_correct": true, "explanation": "「保護するために」は、動物を危険から守る目的で、法律が作られた理由として文に合う。"}, {"text": "密輸", "is_correct": false, "explanation": "「密輸するために」は動物を不正に運ぶ行為で、絶滅を防ぐ法律の目的として合わない。"}, {"text": "撮影", "is_correct": false, "explanation": "「撮影するために」は映像を撮る行為で、絶滅しそうな動物を守る法律の目的に合わない。"}, {"text": "消毒", "is_correct": false, "explanation": "「消毒するために」は菌を殺す行為で、動物を守るための法律の目的として合わない。"}], "explanations": {"保護": "「保護するために」は、動物を危険から守る目的で、法律が作られた理由として文に合う。", "密輸": "「密輸するために」は動物を不正に運ぶ行為で、絶滅を防ぐ法律の目的として合わない。", "撮影": "「撮影するために」は映像を撮る行為で、絶滅しそうな動物を守る法律の目的に合わない。", "消毒": "「消毒するために」は菌を殺す行為で、動物を守るための法律の目的として合わない。"}, "sentence_index": 0, "correct_answer": "保護"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "授業のあと、先生に今日の出来事を保護した。", "explanation": "ここは〈報告〉の意味。出来事は守る対象ではなく知らせる内容なので、〈報告〉と混同した誤り。"}, {"text": "彼は約束の時間を保護して、駅で待っていた。", "explanation": "ここは〈守る〉の意味。時間は〈保護〉せず守る（時間を守る）ものなので、〈守る〉と混同した誤り。"}, {"text": "虫歯を保護するために、毎晩歯みがきをする。", "explanation": "ここは〈予防〉の意味。虫歯は守るものではなく防ぐものなので、〈予防〉と混同した誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37991, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保護", "is_correct": true, "explanation": "「安全な学校に保護された」は、住民が危険から守られて避難した状態を表し、文に合う。"}, {"text": "解散", "is_correct": false, "explanation": "「解散された」は集団が解かれる意味で、住民が学校に入る文脈に合わない。"}, {"text": "売却", "is_correct": false, "explanation": "「売却された」は売り渡される意味で、住民を学校に入れる文脈に合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去された」は取り除かれる意味で、住民が学校にいる文脈には合わない。"}], "explanations": {"保護": "「安全な学校に保護された」は、住民が危険から守られて避難した状態を表し、文に合う。", "解散": "「解散された」は集団が解かれる意味で、住民が学校に入る文脈に合わない。", "売却": "「売却された」は売り渡される意味で、住民を学校に入れる文脈に合わない。", "撤去": "「撤去された」は取り除かれる意味で、住民が学校にいる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "保護"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で予算の案を保護した。", "explanation": "ここは〈説明〉の意味。予算の案は守る対象ではなく説明する内容なので、〈説明〉と混同した誤り。"}, {"text": "体重を保護するために、毎朝走っている。", "explanation": "ここは〈維持〉の意味。体重は守るものではなく一定に保つものなので、〈維持〉と混同した誤り。"}, {"text": "ゴミの量を保護するために、分別を始めた。", "explanation": "ここは〈削減〉の意味。ゴミの量を減らすことは〈保護〉では言わないので、〈削減〉と混同した誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37991, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "野生の鳥を寒さから保護に活動を始めた。", "corrected_sentence": "野生の鳥を寒さから保護する活動を始めた。", "error_description": "「保護する活動」の「する」が「に」になっている。「保護」は「する」を伴って「保護する活動」と名詞を修飾する形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37991, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山で迷った登山者は、山小屋に保護られた。", "corrected_sentence": "山で迷った登山者は、山小屋に保護された。", "error_description": "受け身の形が「保護られた」になっている。サ変動詞「保護する」の受け身は「保護される」、過去形は「保護された」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
