INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37993, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「古い蔵を見る」の「を」で、見る対象を示し正しく使われている。"}, {"text": "に", "is_correct": false, "explanation": "「蔵に見る」は見る対象を示さず不自然で、文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「蔵と見る」は一緒に見る相手を示すことになり、見る対象として合わない。"}, {"text": "より", "is_correct": false, "explanation": "「蔵より見る」は比較の「より」になり、見る対象の意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「古い蔵を見る」の「を」で、見る対象を示し正しく使われている。", "に": "「蔵に見る」は見る対象を示さず不自然で、文に合わない。", "と": "「蔵と見る」は一緒に見る相手を示すことになり、見る対象として合わない。", "より": "「蔵より見る」は比較の「より」になり、見る対象の意味にならない。"}, "error_tags": {"に": "方向・位置", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37993, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「蔵」は、物を保管したり収納したりするための建造物や部屋のことです。", "primary_collocate": null, "pronunciation": "くら", "ipa": "kɯɾa", "syllable_count": 2, "sentences": [{"text": "町の北に、白いかべの蔵が三つならんでいる。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "町[まち]の北[きた]に、白[しろ]いかべの蔵[くら]が三[みっ]つならんでいる。", "sentence_source": "generated"}, {"text": "米を守るため、江戸時代の人は火に強い蔵を建てた。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "米[こめ]を守[まも]るため、江戸[えど]時代[じだい]の人[ひと]は火[ひ]に強[つよ]い蔵[くら]を建[た]てた。", "sentence_source": "generated"}, {"text": "蔵の二階には、古い着物や本が保管されている。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "蔵[くら]の二階[にかい]には、古[ふる]い着物[きもの]や本[ほん]が保管[ほかん]されている。", "sentence_source": "generated"}, {"text": "この蔵は百年前に建てられ、今は店として使われている。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "この蔵[くら]は百年前[ひゃくねんまえ]に建[た]てられ、今[いま]は店[みせ]として使[つか]われている。", "sentence_source": "generated"}, {"text": "地震で蔵のかべにひびが入ってしまった。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "地震[じしん]で蔵[くら]のかべにひびが入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "父は祖母の蔵を片づけて、古い写真を見つけた。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "父[ちち]は祖母[そぼ]の蔵[くら]を片[かた]づけて、古[ふる]い写真[しゃしん]を見[み]つけた。", "sentence_source": "generated"}, {"text": "厚いかべの蔵は、湿気が少なく、物をしまうのに向いている。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "厚[あつ]いかべの蔵[くら]は、湿気[しっけ]が少[すく]なく、物[もの]をしまうのに向[む]いている。", "sentence_source": "generated"}, {"text": "観光客が、古い蔵を見るために細い道を歩いている。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]が、古[ふる]い蔵[くら]を見[み]るために細[ほそ]い道[みち]を歩[ある]いている。", "sentence_source": "generated"}, {"text": "蔵の重い戸を開けると、ほこりのにおいがした。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "蔵[くら]の重[おも]い戸[と]を開[あ]けると、ほこりのにおいがした。", "sentence_source": "generated"}, {"text": "大切な書類は、火事に備えて蔵に入れておいた。", "target_word": "蔵", "complexity_tier": "T3", "furigana": "大切[たいせつ]な書類[しょるい]は、火事[かじ]に備[そな]えて蔵[くら]に入[い]れておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蔵", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "蔵：物を保管する建物や部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37993, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蔵", "is_correct": true, "explanation": "「白いかべの蔵が三つ」は、白い壁の保管用の建物が並ぶ意味で文に合う。"}, {"text": "寿司", "is_correct": false, "explanation": "「白いかべの寿司が三つ」は食べ物で、建物の並びを表せず合わない。"}, {"text": "雲", "is_correct": false, "explanation": "「白いかべの雲が三つ」は空の現象で、町の北の建物の並びとして合わない。"}, {"text": "魚", "is_correct": false, "explanation": "「白いかべの魚が三つ」は生き物で、かべに並ぶ建物としては合わない。"}], "explanations": {"蔵": "「白いかべの蔵が三つ」は、白い壁の保管用の建物が並ぶ意味で文に合う。", "寿司": "「白いかべの寿司が三つ」は食べ物で、建物の並びを表せず合わない。", "雲": "「白いかべの雲が三つ」は空の現象で、町の北の建物の並びとして合わない。", "魚": "「白いかべの魚が三つ」は生き物で、かべに並ぶ建物としては合わない。"}, "sentence_index": 0, "correct_answer": "蔵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、蔵に乗って会社へ行った。", "explanation": "ここは〈電車〉の意味（乗り物に乗る）。蔵には乗れないので、〈電車〉と混同した誤り。"}, {"text": "夕方、蔵に入って体を洗った。", "explanation": "ここは〈ふろ〉の意味。体を洗う場所は蔵ではなくふろなので合わない。"}, {"text": "今日は、蔵で髪を切ってもらった。", "explanation": "ここは〈美容院〉の意味。髪を切る場所は蔵ではなく美容院なので、〈美容院〉と混同した誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37993, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔵", "is_correct": true, "explanation": "「厚いかべの蔵」は物をしまう建物を指し、湿気が少なく物を保管するという説明に合う。"}, {"text": "窓", "is_correct": false, "explanation": "「厚いかべの窓」は光や風を入れる部分で、物をしまうのに向かないので合わない。"}, {"text": "柱", "is_correct": false, "explanation": "「厚いかべの柱」は建物を支える部分で、物をしまう場所としては合わない。"}, {"text": "階段", "is_correct": false, "explanation": "「厚いかべの階段」は上り下りの設備で、物をしまうのに向かず文に合わない。"}], "explanations": {"蔵": "「厚いかべの蔵」は物をしまう建物を指し、湿気が少なく物を保管するという説明に合う。", "窓": "「厚いかべの窓」は光や風を入れる部分で、物をしまうのに向かないので合わない。", "柱": "「厚いかべの柱」は建物を支える部分で、物をしまう場所としては合わない。", "階段": "「厚いかべの階段」は上り下りの設備で、物をしまうのに向かず文に合わない。"}, "sentence_index": 6, "correct_answer": "蔵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "患者さんは、蔵で医者の診察を受けた。", "explanation": "ここは〈病院〉の意味。診察を受ける場所は病院で、蔵では合わないので、〈病院〉と混同した誤り。"}, {"text": "生徒たちは、蔵で国語の授業を受けた。", "explanation": "ここは〈学校〉の意味。授業を受ける場所は蔵ではなく学校なので合わない。"}, {"text": "日曜日、蔵で祈った。", "explanation": "ここは〈教会〉の意味。祈る場所は蔵ではなく教会なので、〈教会〉と混同した誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37993, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の古い蔵が戸が、強い風でこわれた。", "corrected_sentence": "町の古い蔵の戸が、強い風でこわれた。", "error_description": "「蔵の戸」の「の」が「が」になっている。蔵と戸を所属でつなぐ「の」が正しく、「蔵が戸が」は文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37993, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明治時代の商人は、火事に強い蔵を立てた。", "corrected_sentence": "明治時代の商人は、火事に強い蔵を建てた。", "error_description": "「蔵を立てた」は「建てた」の誤り。建物を造る意味では「建てる」を使い、「立てる」は立たせる意味になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
