INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37994, 3, 'prompt1_core', '{"pos": "感動詞", "semantic_class": "function", "definition": "さようならという意味のことばだよ。", "primary_collocate": null, "pronunciation": "ばい", "ipa": "bai", "syllable_count": 2, "sentences": [{"text": "「じゃあ、また明日ね。バイ」と友達は手をふった。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「じゃあ、また明日[あした]ね。バイ」と友達[ともだち]は手[て]をふった。", "sentence_source": "generated"}, {"text": "「もう帰るよ。バイ」と弟は言って、玄関を出た。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「もう帰[かえ]るよ。バイ」と弟[おとうと]は言[い]って、玄関[げんかん]を出[で]た。", "sentence_source": "generated"}, {"text": "電話を切る前に、彼女は「バイ」と言った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "電話[でんわ]を切[き]る前[まえ]に、彼女[かのじょ]は「バイ」と言[い]った。", "sentence_source": "generated"}, {"text": "「バイ」と言って、子どもは先生に手をふった。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「バイ」と言[い]って、子[こ]どもは先生[せんせい]に手[て]をふった。", "sentence_source": "generated"}, {"text": "駅で友達に「バイ」と言って、改札に入った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "駅[えき]で友達[ともだち]に「バイ」と言[い]って、改札[かいさつ]に入[はい]った。", "sentence_source": "generated"}, {"text": "「そろそろ行くね。バイ」とメッセージを送った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「そろそろ行[い]くね。バイ」とメッセージを送[おく]った。", "sentence_source": "generated"}, {"text": "「バイ」と短く言って、彼は電話を切った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「バイ」と短[みじか]く言[い]って、彼[かれ]は電話[でんわ]を切[き]った。", "sentence_source": "generated"}, {"text": "学校の門の前で、みんなが「バイ」と言い合った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "学校[がっこう]の門[もん]の前[まえ]で、みんなが「バイ」と言[い]い合[あ]った。", "sentence_source": "generated"}, {"text": "友達の「バイ」という声が、遠くから聞こえた。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "友達[ともだち]の「バイ」という声[こえ]が、遠[とお]くから聞[き]こえた。", "sentence_source": "generated"}, {"text": "「ありがとう。バイ」と、妹は明るく言った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「ありがとう。バイ」と、妹[いもうと]は明[あか]るく言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バイ", "label": "base"}], "register": "くだけた", "sense_fingerprint": "別れ際に言う「さようなら」の短い言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37994, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バイ", "is_correct": true, "explanation": "「さようなら」の略で、別れ際に言う挨拶として文に合う。"}, {"text": "いただきます", "is_correct": false, "explanation": "食事の前に言う挨拶で、また明日と別れる場面には合わない。"}, {"text": "ごちそうさま", "is_correct": false, "explanation": "食事の後に言う挨拶で、別れの場面には合わない。"}, {"text": "おかえり", "is_correct": false, "explanation": "帰ってきた人を迎える言葉で、別れる場面には合わない。"}], "explanations": {"バイ": "「さようなら」の略で、別れ際に言う挨拶として文に合う。", "いただきます": "食事の前に言う挨拶で、また明日と別れる場面には合わない。", "ごちそうさま": "食事の後に言う挨拶で、別れの場面には合わない。", "おかえり": "帰ってきた人を迎える言葉で、別れる場面には合わない。"}, "sentence_index": 0, "correct_answer": "バイ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食卓に料理が並ぶと、父は「バイ」と言った。", "explanation": "ここは食事の前の〈いただきます〉の場面。バイは別れの言葉なので合わない。"}, {"text": "朝、教室に入ると、みんなに「バイ」と言った。", "explanation": "ここは朝の挨拶〈おはよう〉の場面。バイは別れ際に使う言葉なので合わない。"}, {"text": "家に着くと、玄関で「バイ」と言った。", "explanation": "ここは帰宅の挨拶〈ただいま〉の場面。バイは別れるときに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37994, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バイ", "is_correct": true, "explanation": "電話を切るときの別れの挨拶として、文に合う。"}, {"text": "いってきます", "is_correct": false, "explanation": "出かけるときの挨拶で、電話を切る場面には合わない。"}, {"text": "おじゃまします", "is_correct": false, "explanation": "人の家に入るときの挨拶で、電話を切る場面には合わない。"}, {"text": "こんにちは", "is_correct": false, "explanation": "会ったときの挨拶で、電話を切る場面には合わない。"}], "explanations": {"バイ": "電話を切るときの別れの挨拶として、文に合う。", "いってきます": "出かけるときの挨拶で、電話を切る場面には合わない。", "おじゃまします": "人の家に入るときの挨拶で、電話を切る場面には合わない。", "こんにちは": "会ったときの挨拶で、電話を切る場面には合わない。"}, "sentence_index": 6, "correct_answer": "バイ"}, "level_6": {"correct_sentence_index": 1, "wrong_sentences": [{"text": "プレゼントを受け取ると、彼女は「バイ」と言った。", "explanation": "ここはお礼の〈ありがとう〉の場面。バイは別れの言葉なので合わない。"}, {"text": "客が入ってくると、店員は「バイ」と言った。", "explanation": "ここは〈いらっしゃいませ〉の場面。バイは別れの言葉なので合わない。"}, {"text": "部屋に入るとき、彼は「バイ」と言った。", "explanation": "ここは入室の挨拶〈失礼します〉の場面。バイは別れ際の言葉なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37994, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は「バイ」を言って、教室を出た。", "corrected_sentence": "彼女は「バイ」と言って、教室を出た。", "error_description": "「言う」で言葉を引用するときは「と」を使う。ここの「を」は誤りで、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37994, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は「バイ」と言んで、電話を切った。", "corrected_sentence": "彼は「バイ」と言って、電話を切った。", "error_description": "「言う」のて形は「言って」。「言んで」は誤った活用で、正しくは「言って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
