INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37995, 3, 'prompt1_core', '{"pos": "感動詞", "semantic_class": "function", "definition": "別れる時や、何かを終わる時に使う挨拶の言葉。", "primary_collocate": null, "pronunciation": "ばい", "ipa": "bai", "syllable_count": 2, "sentences": [{"text": "配信の最後に、彼は「みなさん、バイ」とあいさつした。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "配信[はいしん]の最後[さいご]に、彼[かれ]は「みなさん、バイ」とあいさつした。", "sentence_source": "generated"}, {"text": "別れるとき、「バイ」と軽く手を上げた。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "別[わか]れるとき、「バイ」と軽[かる]く手[て]を上[あ]げた。", "sentence_source": "generated"}, {"text": "友達同士のチャットは、「バイ」で終わった。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "友達[ともだち]同士[どうし]のチャットは、「バイ」で終[お]わった。", "sentence_source": "generated"}, {"text": "「今日はここまで。バイ」と、司会者は番組を終えた。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「今日[きょう]はここまで。バイ」と、司会者[しかいしゃ]は番組[ばんぐみ]を終[お]えた。", "sentence_source": "generated"}, {"text": "彼女は「またね、バイ」と言って席を立った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は「またね、バイ」と言[い]って席[せき]を立[た]った。", "sentence_source": "generated"}, {"text": "帰る人たちは、口々に「バイ」と声をかけた。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "帰[かえ]る人[ひと]たちは、口々[くちぐち]に「バイ」と声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "話を切り上げたくて、「じゃあ、バイ」と言った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "話[はなし]を切[き]り上[あ]げたくて、「じゃあ、バイ」と言[い]った。", "sentence_source": "generated"}, {"text": "「バイ」は友達に使う、くだけた別れのあいさつだ。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "「バイ」は友達[ともだち]に使[つか]う、くだけた別[わか]れのあいさつだ。", "sentence_source": "generated"}, {"text": "返信は「バイ」とだけ書いてあった。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "返信[へんしん]は「バイ」とだけ書いてあった。", "sentence_source": "generated"}, {"text": "彼は笑って「バイ」と言い、エレベーターに乗った。", "target_word": "バイ", "complexity_tier": "T3", "furigana": "彼[かれ]は笑[わら]って「バイ」と言[い]い、エレベーターに乗[の]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バイ", "label": "base"}], "register": "くだけた", "sense_fingerprint": "別れや終わりに使うくだけたあいさつ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37995, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バイ", "is_correct": true, "explanation": "配信を締めくくる別れの挨拶として、文に合う。"}, {"text": "おはよう", "is_correct": false, "explanation": "朝の挨拶で、配信の終わりには合わない。"}, {"text": "いただきます", "is_correct": false, "explanation": "食事の前の挨拶で、配信の終わりには合わない。"}, {"text": "ただいま", "is_correct": false, "explanation": "帰宅時の挨拶で、配信の終わりには合わない。"}], "explanations": {"バイ": "配信を締めくくる別れの挨拶として、文に合う。", "おはよう": "朝の挨拶で、配信の終わりには合わない。", "いただきます": "食事の前の挨拶で、配信の終わりには合わない。", "ただいま": "帰宅時の挨拶で、配信の終わりには合わない。"}, "sentence_index": 0, "correct_answer": "バイ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議が始まると、部長は「バイ」と言った。", "explanation": "ここは会議を始める合図の〈始めましょう〉の場面。バイは終わりの言葉なので合わない。"}, {"text": "お客さんが入ってくると、店員は「バイ」と言った。", "explanation": "ここは入店時の挨拶〈いらっしゃいませ〉の場面。バイは終わりの挨拶なので合わない。"}, {"text": "教室のドアを開けるとき、彼は「バイ」と言った。", "explanation": "ここは入室の挨拶〈失礼します〉の場面。バイは別れ際の言葉なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37995, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バイ", "is_correct": true, "explanation": "話を終えるときの別れの言葉として、文に合う。"}, {"text": "こんばんは", "is_correct": false, "explanation": "夜の挨拶で、話を切り上げる場面には合わない。"}, {"text": "いってらっしゃい", "is_correct": false, "explanation": "出かける人を見送る言葉で、話を切り上げる場面には合わない。"}, {"text": "はじめまして", "is_correct": false, "explanation": "初対面の挨拶で、話を切り上げる文脈には合わない。"}], "explanations": {"バイ": "話を終えるときの別れの言葉として、文に合う。", "こんばんは": "夜の挨拶で、話を切り上げる場面には合わない。", "いってらっしゃい": "出かける人を見送る言葉で、話を切り上げる場面には合わない。", "はじめまして": "初対面の挨拶で、話を切り上げる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "バイ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "グラスを上げて、みんなは「バイ」と言った。", "explanation": "ここは乾杯の掛け声〈乾杯〉の場面。バイは別れの言葉なので合わない。"}, {"text": "ぶつかったとき、彼は「バイ」と言った。", "explanation": "ここは謝る言葉〈ごめんなさい〉の場面。バイは別れの言葉なので合わない。"}, {"text": "店で待たせた友達に、彼は「バイ」と言った。", "explanation": "ここは待たせたことを詫びる〈お待たせしました〉の場面。バイは別れの言葉なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37995, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は「バイ」に言って、教室を出た。", "corrected_sentence": "先生は「バイ」と言って、教室を出た。", "error_description": "「言う」で言葉を引用するときは「と」を使う。ここの「に」は誤りで、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37995, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家を出るとき、彼女は「バイ」と言んで手をふった。", "corrected_sentence": "家を出るとき、彼女は「バイ」と言って手をふった。", "error_description": "「言う」のて形は「言って」。「言んで」は誤った活用で、正しくは「言って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
