INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37996, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "ここは〈を〉。「洗濯を忘れて」は忘れた対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「洗濯が忘れて」だと主語になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「洗濯に忘れて」は場所や帰着点を表し、忘れる対象として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「洗濯へ忘れて」は方向を表し、忘れる対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "ここは〈を〉。「洗濯を忘れて」は忘れた対象を示す。", "が": "「洗濯が忘れて」だと主語になり、文が成り立たない。", "に": "「洗濯に忘れて」は場所や帰着点を表し、忘れる対象として合わない。", "へ": "「洗濯へ忘れて」は方向を表し、忘れる対象として不自然。"}, "error_tags": {"が": "主格", "に": "帰着点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37996, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "せんたくは、よごれたふくをきれいにする ことです。", "primary_collocate": null, "pronunciation": "せんたく", "ipa": "sentakɯ", "syllable_count": 4, "sentences": [{"text": "毎朝、起きてすぐに洗濯をします。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、起[お]きてすぐに洗濯[せんたく]をします。", "sentence_source": "generated"}, {"text": "雨が続くと、洗濯してもなかなかかわきません。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]くと、洗濯[せんたく]してもなかなかかわきません。", "sentence_source": "generated"}, {"text": "よごれたシャツを洗濯したら、きれいになりました。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "よごれたシャツを洗濯[せんたく]したら、きれいになりました。", "sentence_source": "generated"}, {"text": "洗濯が終わったら、ベランダにほしてください。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "洗濯[せんたく]が終[お]わったら、ベランダにほしてください。", "sentence_source": "generated"}, {"text": "日曜日は天気がいいので、洗濯をしようと思います。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は天気[てんき]がいいので、洗濯[せんたく]をしようと思[おも]います。", "sentence_source": "generated"}, {"text": "母は洗濯のあとで、ごはんを作ります。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "母[はは]は洗濯[せんたく]のあとで、ごはんを作[つく]ります。", "sentence_source": "generated"}, {"text": "運動したので、洗濯するふくがたくさんあります。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "運動[うんどう]したので、洗濯[せんたく]するふくがたくさんあります。", "sentence_source": "generated"}, {"text": "洗濯をわすれて、明日着るシャツがありません。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "洗濯[せんたく]をわすれて、明日[あした]着[き]るシャツがありません。", "sentence_source": "generated"}, {"text": "子どもの服はすぐよごれるので、毎日洗濯します。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "子[こ]どもの服[ふく]はすぐよごれるので、毎日[まいにち]洗濯[せんたく]します。", "sentence_source": "generated"}, {"text": "この白いくつ下は、洗濯しても色が変わりません。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "この白[しろ]いくつ下[した]は、洗濯[せんたく]しても色[いろ]が変[か]わりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗濯", "label": "基本形"}, {"form": "洗濯する", "label": "する動詞"}, {"form": "洗濯した", "label": "過去形"}, {"form": "洗濯して", "label": "て形"}], "register": "標準（丁寧体）", "sense_fingerprint": "せんたく：よごれた服を洗ってきれいにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: かわき (Zipf 1.96)','sentence 2 above tier T2: contains vocabulary far above tier T2: よごれ (Zipf 2.32)','sentence 8 above tier T2: contains vocabulary far above tier T2: よごれる (Zipf 1.26)','sentence 9 above tier T2: contains vocabulary far above tier T2: くつ下 (Zipf 2.21)']::text[], '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37996, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗濯", "is_correct": true, "explanation": "ここは〈洗濯〉。起きてすぐにする家事として自然で、文の意味にも合う。"}, {"text": "脱水", "is_correct": false, "explanation": "脱水は洗った衣類の水分を飛ばすこと。「起きてすぐに脱水をします」は不自然で、この空所には入らない。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は布の色を白くすること。朝の日常動作としての文脈に合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は乾かすこと。「起きてすぐに乾燥をします」では意味が通らない。"}], "explanations": {"洗濯": "ここは〈洗濯〉。起きてすぐにする家事として自然で、文の意味にも合う。", "脱水": "脱水は洗った衣類の水分を飛ばすこと。「起きてすぐに脱水をします」は不自然で、この空所には入らない。", "漂白": "漂白は布の色を白くすること。朝の日常動作としての文脈に合わない。", "乾燥": "乾燥は乾かすこと。「起きてすぐに乾燥をします」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "洗濯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は部屋の洗濯をして、床をぴかぴかにした。", "explanation": "ここは〈掃除〉の意味。洗濯は衣類や布製品を洗うことで、部屋全体をきれいにする意味では使わない。"}, {"text": "流し台にたまった食器を、洗濯して手早く片付けた。", "explanation": "ここは〈洗い物〉の意味。洗濯は衣類や布製品を洗うことで、食器を対象にしない。"}, {"text": "朝起きて顔を洗濯すると、目がさめる。", "explanation": "ここは〈洗顔〉の意味。洗濯は衣類などを洗う行為で、顔には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37996, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗濯", "is_correct": true, "explanation": "ここは〈洗濯〉。洗うふくがたくさんあるという文脈に合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食事を作ること。「料理するふくがたくさんあります」では意味が通らない。"}, {"text": "買い物", "is_correct": false, "explanation": "買い物は品物を買うこと。ふくに対して「買い物するふく」とは言わない。"}, {"text": "片付け", "is_correct": false, "explanation": "片付けは物を元の場所に戻すこと。「片付けするふく」は不自然で、この空所には入らない。"}], "explanations": {"洗濯": "ここは〈洗濯〉。洗うふくがたくさんあるという文脈に合う。", "料理": "料理は食事を作ること。「料理するふくがたくさんあります」では意味が通らない。", "買い物": "買い物は品物を買うこと。ふくに対して「買い物するふく」とは言わない。", "片付け": "片付けは物を元の場所に戻すこと。「片付けするふく」は不自然で、この空所には入らない。"}, "sentence_index": 6, "correct_answer": "洗濯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末は車を洗濯して、ぴかぴかにした。", "explanation": "ここは〈洗車〉の意味。洗濯は衣類や布製品を洗うことで、車には使わない。"}, {"text": "汚れた窓ガラスを洗濯して、外がよく見えるようになった。", "explanation": "ここは〈窓ふき〉の意味。洗濯は衣類や布製品を洗うことで、ガラスを拭く作業には使わない。"}, {"text": "コンタクトは専用の洗浄液で洗濯する。", "explanation": "ここは〈洗浄〉の意味。洗濯は衣類や布製品を洗う行為で、レンズには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37996, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汚れたシャツが洗濯して、きれいになりました。", "corrected_sentence": "汚れたシャツを洗濯して、きれいになりました。", "error_description": "洗濯の対象は〈を〉で示す。〈が〉は主語を表すため、「シャツが洗濯して」は不自然。正しくは「シャツを洗濯して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37996, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "帰ったらすぐ洗濯を、着替えた。", "corrected_sentence": "帰ったらすぐ洗濯して、着替えた。", "error_description": "洗濯は「する」を伴う動詞。「洗濯を」で文を止めると「して」が抜けて、後の「着替えた」とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
