INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37997, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "洗濯とは、衣服や布製品を水や洗剤を使って汚れを落とし、清潔にすること。", "primary_collocate": null, "pronunciation": "せんたく", "ipa": "sentakɯ", "syllable_count": 4, "sentences": [{"text": "汚れた衣服は、洗剤と水で洗濯するときれいになる。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "汚[よご]れた衣服[いふく]は、洗剤[せんざい]と水[みず]で洗濯[せんたく]するときれいになる。", "sentence_source": "generated"}, {"text": "毛布のような大きい布製品も、家で洗濯できる。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "毛布[もうふ]のような大[おお]きい布製品[ぬのせいひん]も、家[いえ]で洗濯[せんたく]できる。", "sentence_source": "generated"}, {"text": "この服は水に弱いので、洗濯してはいけない。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "この服[ふく]は水[みず]に弱[よわ]いので、洗濯[せんたく]してはいけない。", "sentence_source": "generated"}, {"text": "汗をかいたシャツは、その日のうちに洗濯した方がいい。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "汗[あせ]をかいたシャツは、その日[ひ]のうちに洗濯[せんたく]した方[ほう]がいい。", "sentence_source": "generated"}, {"text": "洗濯のとき、色のついた服は白い服と分けて洗う。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "洗濯[せんたく]のとき、色[いろ]のついた服[ふく]は白[しろ]い服[ふく]と分[わ]けて洗[あら]う。", "sentence_source": "generated"}, {"text": "洗濯したタオルは日光に当てると、清潔なにおいがする。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "洗濯[せんたく]したタオルは日光[にっこう]に当[あ]てると、清潔[せいけつ]なにおいがする。", "sentence_source": "generated"}, {"text": "旅行の三日目に、ホテルの近くで洗濯をした。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "旅行[りょこう]の三日目[みっかめ]に、ホテルの近[ちか]くで洗濯[せんたく]をした。", "sentence_source": "generated"}, {"text": "制服は毎週末に洗濯して、月曜日にきれいな状態で着る。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "制服[せいふく]は毎週末[まいしゅうまつ]に洗濯[せんたく]して、月曜日[げつようび]にきれいな状態[じょうたい]で着[き]る。", "sentence_source": "generated"}, {"text": "洗濯の回数が多いと、服が早くいたむことがある。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "洗濯[せんたく]の回数[かいすう]が多[おお]いと、服[ふく]が早[はや]くいたむことがある。", "sentence_source": "generated"}, {"text": "泥だらけになった運動着を洗濯すると、水が真っ茶色になった。", "target_word": "洗濯", "complexity_tier": "T3", "furigana": "泥[どろ]だらけになった運動着[うんどうぎ]を洗濯[せんたく]すると、水[みず]が真[ま]っ茶色[ちゃいろ]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗濯", "label": "基本形"}, {"form": "洗濯する", "label": "する動詞"}, {"form": "洗濯した", "label": "過去形"}, {"form": "洗濯して", "label": "て形"}], "register": "標準（常体）", "sense_fingerprint": "洗濯：衣服や布製品を水と洗剤で洗い清潔にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: いたむ (Zipf 1.49)']::text[], '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37997, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗濯", "is_correct": true, "explanation": "ここは〈洗濯〉。衣服を洗剤と水で洗うという文の意味に合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作ること。洗剤と水で料理するとは言わない。"}, {"text": "買い物", "is_correct": false, "explanation": "買い物は品物を買うこと。洗剤と水を使う行為ではない。"}, {"text": "勉強", "is_correct": false, "explanation": "勉強は学ぶこと。洗剤と水で勉強するとは言えず、文に合わない。"}], "explanations": {"洗濯": "ここは〈洗濯〉。衣服を洗剤と水で洗うという文の意味に合う。", "料理": "料理は食べ物を作ること。洗剤と水で料理するとは言わない。", "買い物": "買い物は品物を買うこと。洗剤と水を使う行為ではない。", "勉強": "勉強は学ぶこと。洗剤と水で勉強するとは言えず、文に合わない。"}, "sentence_index": 0, "correct_answer": "洗濯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の日に泥だらけになった革のブーツを、洗濯して乾かした。", "explanation": "ここは〈洗う〉の意味。洗濯は布製品を洗うことで、革のブーツのように布でないものには使わない。"}, {"text": "毎朝、髪を洗濯すると、頭がすっきりする。", "explanation": "ここは〈洗髪〉の意味。洗濯は布製品を洗うことで、髪には使わない。"}, {"text": "庭の洗濯をして、草むしりを終えた。", "explanation": "ここは〈手入れ〉の意味。洗濯は洗う行為で、庭の世話をする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37997, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗濯", "is_correct": true, "explanation": "ここは〈洗濯〉。旅行先で衣類を洗ったという文脈に合う。"}, {"text": "脱水", "is_correct": false, "explanation": "脱水は洗った衣類の水分を取ること。ホテルの近くでの出来事として場面に合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は布を白くすること。旅行先の行動として文に合わない。"}, {"text": "出産", "is_correct": false, "explanation": "出産は子どもを産むこと。洗濯の文脈に合わず、ここには入らない。"}], "explanations": {"洗濯": "ここは〈洗濯〉。旅行先で衣類を洗ったという文脈に合う。", "脱水": "脱水は洗った衣類の水分を取ること。ホテルの近くでの出来事として場面に合わない。", "漂白": "漂白は布を白くすること。旅行先の行動として文に合わない。", "出産": "出産は子どもを産むこと。洗濯の文脈に合わず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "洗濯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関の洗濯を念入りにした。", "explanation": "ここは〈掃除〉の意味。洗濯は衣類や布製品を洗うことで、玄関を掃除する意味では使わない。"}, {"text": "出かける前に、スマホを洗濯して、きれいにした。", "explanation": "ここは〈拭く〉の意味。洗濯は布製品を洗う行為で、スマホには使わない。"}, {"text": "食器は洗濯してから食洗機に入れる。", "explanation": "ここは〈水洗い〉の意味。洗濯は衣類などを洗う行為で、食器には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37997, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汚れた服は、洗剤と水に洗濯すればきれいになる。", "corrected_sentence": "汚れた服は、洗剤と水で洗濯すればきれいになる。", "error_description": "洗濯の手段は〈で〉で示す。〈に〉は場所や方向を表すため、「水に洗濯する」は不自然。正しくは「水で洗濯する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37997, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行の三日目に、ホテルの近くで洗濯て、服を乾かした。", "corrected_sentence": "旅行の三日目に、ホテルの近くで洗濯して、服を乾かした。", "error_description": "「洗濯」はサ変名詞なので「して」と続ける必要がある。「し」が抜けた「洗濯て」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37998, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合わせる", "is_correct": true, "explanation": "いくつかに分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。"}, {"text": "運ぶ", "is_correct": false, "explanation": "ものを別の場所へ移す動詞で、分けることの対義語ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "汚れを落とす動詞で、分けることと対になる語ではない。"}, {"text": "食べる", "is_correct": false, "explanation": "口に入れる動詞で、分けることの対義語ではない。"}], "correct_answer": "合わせる", "explanations": {"合わせる": "いくつかに分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。", "運ぶ": "ものを別の場所へ移す動詞で、分けることの対義語ではない。", "洗う": "汚れを落とす動詞で、分けることと対になる語ではない。", "食べる": "口に入れる動詞で、分けることの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37998, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「八つに分ける」の形で、分けた結果の数を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」にすると「八つを分けると」となり、文が不自然になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」にすると「八つが分けると」となり、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」で、「八つと分けると」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「八つに分ける」の形で、分けた結果の数を示す正しい助詞。", "を": "目的語の「を」にすると「八つを分けると」となり、文が不自然になる。", "が": "主語の「が」にすると「八つが分けると」となり、成り立たない。", "と": "並列や相手を示す「と」で、「八つと分けると」は意味が通らない。"}, "error_tags": {"を": "目的語を示す助詞", "が": "主語を示す助詞", "と": "並列・相手を示す助詞"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合わせる", "is_correct": true, "explanation": "いくつかに分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。"}, {"text": "乗せる", "is_correct": false, "explanation": "ものを上に置く動詞で、分けることの対義語ではない。"}, {"text": "叩く", "is_correct": false, "explanation": "強く打つ動詞で、分けることと対になる語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "寝ることを表す動詞で、分けることの対義語ではない。"}], "correct_answer": "合わせる", "explanations": {"合わせる": "いくつかに分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。", "乗せる": "ものを上に置く動詞で、分けることの対義語ではない。", "叩く": "強く打つ動詞で、分けることと対になる語ではない。", "眠る": "寝ることを表す動詞で、分けることの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37998, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものをいくつかにわけること。", "primary_collocate": null, "pronunciation": "わける", "ipa": "wakeɾɯ", "syllable_count": 3, "sentences": [{"text": "ケーキを四つに分けて、家族みんなで食べた。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "ケーキを四[よっ]つに分[わ]けて、家族[かぞく]みんなで食[た]べた。", "sentence_source": "generated"}, {"text": "母は集めた貝がらを大きさごとに小さな箱へ分けた。", "target_word": "分けた", "complexity_tier": "T3", "furigana": "母[はは]は集[あつ]めた貝[かい]がらを大[おお]きさごとに小[ちい]さな箱[はこ]へ分[わ]けた。", "sentence_source": "generated"}, {"text": "先生は生徒を三つのグループに分ける。", "target_word": "分ける", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]を三[みっ]つのグループに分[わ]ける。", "sentence_source": "generated"}, {"text": "給料の一部を、毎月貯金と生活費に分けている。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]の一部[いちぶ]を、毎月[まいつき]貯金[ちょきん]と生活費[せいかつひ]に分[わ]けている。", "sentence_source": "generated"}, {"text": "重いので、荷物を二回に分けて運ぶことにした。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "重[おも]いので、荷物[にもつ]を二回[にかい]に分[わ]けて運[はこ]ぶことにした。", "sentence_source": "generated"}, {"text": "姉はクッキーを弟と半分ずつに分けた。", "target_word": "分けた", "complexity_tier": "T3", "furigana": "姉[あね]はクッキーを弟[おとうと]と半分[はんぶん]ずつに分[わ]けた。", "sentence_source": "generated"}, {"text": "大きくなった苗を三つの鉢に分けて植えた。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "大[おお]きくなった苗[なえ]を三[みっ]つの鉢[はち]に分[わ]けて植[う]えた。", "sentence_source": "generated"}, {"text": "大きなピザを八つに分けると、ちょうど一人二切れだ。", "target_word": "分ける", "complexity_tier": "T3", "furigana": "大[おお]きなピザを八[やっ]つに分[わ]けると、ちょうど一人[ひとり]二切[ふたき]れだ。", "sentence_source": "generated"}, {"text": "農家の人は収穫した果物を、重さで三つの箱に分けた。", "target_word": "分けた", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は収穫[しゅうかく]した果物[くだもの]を、重[おも]さで三[みっ]つの箱[はこ]に分[わ]けた。", "sentence_source": "generated"}, {"text": "子どもたちはお菓子を同じ数になるように分けた。", "target_word": "分けた", "complexity_tier": "T3", "furigana": "子[こ]どもたちはお菓子[かし]を同[おな]じ数[かず]になるように分[わ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分ける", "label": "終止形"}, {"form": "分けた", "label": "過去形"}, {"form": "分けて", "label": "て形"}, {"form": "分けない", "label": "否定形"}, {"form": "分ければ", "label": "仮定形"}, {"form": "分けよう", "label": "意志形"}, {"form": "分けられる", "label": "可能形"}, {"form": "分けます", "label": "丁寧形"}], "register": "標準（常体）", "sense_fingerprint": "一つのものを切ったり配ったりして、いくつかに分ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 貝がら (Zipf 1.93)']::text[], '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37998, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分けて", "is_correct": true, "explanation": "「四つに分けて」の形で、切り分けて配る動作と文脈が合う。"}, {"text": "混ぜて", "is_correct": false, "explanation": "材料を合わせる動詞で、四つに分ける内容とは合わない。"}, {"text": "焼いて", "is_correct": false, "explanation": "加熱する動詞で、分ける動作とは結びつかない。"}, {"text": "冷やして", "is_correct": false, "explanation": "温度を下げる動詞で、分けることを表さない。"}], "explanations": {"分けて": "「四つに分けて」の形で、切り分けて配る動作と文脈が合う。", "混ぜて": "材料を合わせる動詞で、四つに分ける内容とは合わない。", "焼いて": "加熱する動詞で、分ける動作とは結びつかない。", "冷やして": "温度を下げる動詞で、分けることを表さない。"}, "sentence_index": 0, "correct_answer": "分けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "卵の殻を分けて、中身をボウルに入れた。", "explanation": "ここは〈割る〉の意味。殻は分けるのではなく割るものなので、この言い方はしない。"}, {"text": "りんごの皮を分けてから、薄く切った。", "explanation": "ここは〈剥く〉の意味。皮は分けるのではなく剥くものなので、この言い方はしない。"}, {"text": "寒かったので、コートのボタンを分けた。", "explanation": "ここは〈外す〉の意味。ボタンは分けるのではなく外すものなので、この言い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37998, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分けて", "is_correct": true, "explanation": "「三つの鉢に分けて」の形で、苗を分けて植える動作と文脈が合う。"}, {"text": "掘って", "is_correct": false, "explanation": "土を掘る動詞で、苗を鉢に分ける内容とは合わない。"}, {"text": "摘んで", "is_correct": false, "explanation": "葉や実を取る動詞で、鉢に分けて植えるという動作を表さない。"}, {"text": "刈って", "is_correct": false, "explanation": "草などを切る動詞で、苗の植えつけの文脈と合わない。"}], "explanations": {"分けて": "「三つの鉢に分けて」の形で、苗を分けて植える動作と文脈が合う。", "掘って": "土を掘る動詞で、苗を鉢に分ける内容とは合わない。", "摘んで": "葉や実を取る動詞で、鉢に分けて植えるという動作を表さない。", "刈って": "草などを切る動詞で、苗の植えつけの文脈と合わない。"}, "sentence_index": 6, "correct_answer": "分けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は答えを黒板に分けて、生徒に写させた。", "explanation": "ここは〈書く〉の意味。答えは分けるものではなく書くものなので、この言い方はしない。"}, {"text": "子どもたちは、お菓子を弱火でゆっくり分けた。", "explanation": "ここは〈煮る〉の意味。お菓子は分けるのではなく、火にかけて煮るものなので合わない。"}, {"text": "子どもたちはお菓子の味を分けた。", "explanation": "ここは〈味わう〉の意味。味は分けるものではなく味わうものなので、この言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37998, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "野菜を三つの袋に分ける、冷蔵庫に入れた。", "corrected_sentence": "野菜を三つの袋に分けて、冷蔵庫に入れた。", "error_description": "活用の誤り。「分ける」のままでは後ろに続かず、「分けて」の連用形にする必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "分けた", "is_correct": true, "explanation": "過去形で、母が分けた動作が済んだことを表し、文の述語として正しい。"}, {"text": "分ける", "is_correct": false, "explanation": "基本形（現在）で、過去の出来事を述べる文と合わない。"}, {"text": "分けて", "is_correct": false, "explanation": "て形で、この位置では文を終えられない。"}, {"text": "分けない", "is_correct": false, "explanation": "否定形で、分けなかったという反対の内容になってしまう。"}], "correct_form": "分けた", "base_form": "分ける", "form_label": "過去形", "sentence_index": 1, "explanations": {"分けた": "過去形で、母が分けた動作が済んだことを表し、文の述語として正しい。", "分ける": "基本形（現在）で、過去の出来事を述べる文と合わない。", "分けて": "て形で、この位置では文を終えられない。", "分けない": "否定形で、分けなかったという反対の内容になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37998, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宿題を三つのグループを分けて、班ごとに取り組んだ。", "corrected_sentence": "宿題を三つのグループに分けて、班ごとに取り組んだ。", "error_description": "助詞の誤り。分けた先は「に」で示す。「を」は目的語に使うので、「宿題を」とあわせて二つの「を」が重なり不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "分ける", "is_correct": true, "explanation": "基本形で、「と」の条件節の中で分けるという動作を表すので正しい。"}, {"text": "分けよう", "is_correct": false, "explanation": "意志形で、「分けると」の条件の形と合わない。"}, {"text": "分けない", "is_correct": false, "explanation": "否定形で、分けないという条件になり、八つに分けた結果の一人二切れとは意味がつながらない。"}, {"text": "分けます", "is_correct": false, "explanation": "丁寧形で、「と」に続く普通形の条件文と合わない。"}], "correct_form": "分ける", "base_form": "分ける", "form_label": "基本形", "sentence_index": 7, "explanations": {"分ける": "基本形で、「と」の条件節の中で分けるという動作を表すので正しい。", "分けよう": "意志形で、「分けると」の条件の形と合わない。", "分けない": "否定形で、分けないという条件になり、八つに分けた結果の一人二切れとは意味がつながらない。", "分けます": "丁寧形で、「と」に続く普通形の条件文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37999, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「内容ごとに分けて」の形で、分ける基準を示す正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」で、「内容ごとで分けて」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、後ろに動詞が続く形にならない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」にすると、「内容ごとが分けて」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「内容ごとに分けて」の形で、分ける基準を示す正しい助詞。", "で": "手段や場所を示す「で」で、「内容ごとで分けて」は不自然。", "の": "連体修飾の「の」で、後ろに動詞が続く形にならない。", "が": "主語の「が」にすると、「内容ごとが分けて」は文が成り立たない。"}, "error_tags": {"で": "手段・場所を示す助詞", "の": "連体修飾の助詞", "が": "主語を示す助詞"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "まとめる", "is_correct": true, "explanation": "分類して分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。"}, {"text": "眺める", "is_correct": false, "explanation": "見て楽しむ動詞で、分けることの対義語ではない。"}, {"text": "踏む", "is_correct": false, "explanation": "足で押さえる動詞で、分けることとは関係しない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出す動詞で、分けることの対義語ではない。"}], "correct_answer": "まとめる", "explanations": {"まとめる": "分類して分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。", "眺める": "見て楽しむ動詞で、分けることの対義語ではない。", "踏む": "足で押さえる動詞で、分けることとは関係しない。", "叫ぶ": "大きな声を出す動詞で、分けることの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37999, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "まとめる", "is_correct": true, "explanation": "分類して分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。"}, {"text": "寄せる", "is_correct": false, "explanation": "ものを近づける動詞で、分けることの対義語ではない。"}, {"text": "開く", "is_correct": false, "explanation": "閉じたものを広げる動詞で、分けることと対になる語ではない。"}, {"text": "噛む", "is_correct": false, "explanation": "歯で砕く動詞で、分けることの対義語ではない。"}], "correct_answer": "まとめる", "explanations": {"まとめる": "分類して分けることの対義語で、ばらばらのものを一つにまとめる意味を持つ。", "寄せる": "ものを近づける動詞で、分けることの対義語ではない。", "開く": "閉じたものを広げる動詞で、分けることと対になる語ではない。", "噛む": "歯で砕く動詞で、分けることの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37999, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "一つにまとまっているものを、いくつかの部分や種類に分けること。", "primary_collocate": null, "pronunciation": "わける", "ipa": "wakeɾɯ", "syllable_count": 3, "sentences": [{"text": "ごみは燃えるごみと燃えないごみに分けて出す決まりだ。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "ごみは燃[も]えるごみと燃[も]えないごみに分[わ]けて出[だ]す決[き]まりだ。", "sentence_source": "generated"}, {"text": "図書館では本を内容ごとに分けて、棚に並べている。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "図書館[としょかん]では本[ほん]を内容[ないよう]ごとに分[わ]けて、棚[たな]に並[なら]べている。", "sentence_source": "generated"}, {"text": "この店は商品を値段によって三つの種類に分けている。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "この店[みせ]は商品[しょうひん]を値段[ねだん]によって三[みっ]つの種類[しゅるい]に分[わ]けている。", "sentence_source": "generated"}, {"text": "先生は文章を前半と後半に分けて説明した。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "先生[せんせい]は文章[ぶんしょう]を前半[ぜんはん]と後半[こうはん]に分[わ]けて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "一日を朝、昼、夜に分けて、勉強の計画を立てた。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "一日[いちにち]を朝[あさ]、昼[ひる]、夜[よる]に分[わ]けて、勉強[べんきょう]の計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "この本は魚を海水魚と淡水魚に分けて紹介している。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "この本[ほん]は魚[さかな]を海水魚[かいすいぎょ]と淡水魚[たんすいぎょ]に分[わ]けて紹介[しょうかい]している。", "sentence_source": "generated"}, {"text": "洗濯物を色ごとに分けないと、色がうつることがある。", "target_word": "分けない", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]を色[いろ]ごとに分[わ]けないと、色[いろ]がうつることがある。", "sentence_source": "generated"}, {"text": "資料を年代別に分けたので、探しやすくなった。", "target_word": "分けた", "complexity_tier": "T3", "furigana": "資料[しりょう]を年代別[ねんだいべつ]に分[わ]けたので、探[さが]しやすくなった。", "sentence_source": "generated"}, {"text": "動物園では動物をすむ地域ごとに分けて展示している。", "target_word": "分けて", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では動物[どうぶつ]をすむ地域[ちいき]ごとに分[わ]けて展示[てんじ]している。", "sentence_source": "generated"}, {"text": "調査では、集めた意見を賛成と反対に分けた。", "target_word": "分けた", "complexity_tier": "T3", "furigana": "調査[ちょうさ]では、集[あつ]めた意見[いけん]を賛成[さんせい]と反対[はんたい]に分[わ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分ける", "label": "終止形"}, {"form": "分けた", "label": "過去形"}, {"form": "分けて", "label": "て形"}, {"form": "分けない", "label": "否定形"}, {"form": "分ければ", "label": "仮定形"}, {"form": "分けよう", "label": "意志形"}, {"form": "分けられる", "label": "可能形"}, {"form": "分けます", "label": "丁寧形"}], "register": "標準（常体）", "sense_fingerprint": "全体を部分や種類に区分けする、分類する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37999, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分けて", "is_correct": true, "explanation": "「種類ごとに分けて出す」の形で、ごみを分類する文脈に合う。"}, {"text": "燃やして", "is_correct": false, "explanation": "燃やす動作で、分類して出す決まりとは結びつかない。"}, {"text": "砕いて", "is_correct": false, "explanation": "細かくする動作で、分けて出す決まりとは合わない。"}, {"text": "乾かして", "is_correct": false, "explanation": "水分を抜く動作で、ごみの分類とは関係しない。"}], "explanations": {"分けて": "「種類ごとに分けて出す」の形で、ごみを分類する文脈に合う。", "燃やして": "燃やす動作で、分類して出す決まりとは結びつかない。", "砕いて": "細かくする動作で、分けて出す決まりとは合わない。", "乾かして": "水分を抜く動作で、ごみの分類とは関係しない。"}, "sentence_index": 0, "correct_answer": "分けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "プレゼントの包みを分けて、中身を取り出した。", "explanation": "ここは〈開ける〉の意味。包みは分けるのではなく、ほどいて開けるものなので合わない。"}, {"text": "先生は文章を前半と後半に数えて説明した。", "explanation": "ここは〈数える〉の意味。「前半と後半に」と区分する文脈に、数えるは合わない。"}, {"text": "その一点が、チームの絆を分けた。", "explanation": "ここは〈深める〉の意味。絆は分けるものではなく、深めるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37999, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分けない", "is_correct": true, "explanation": "「分けないと」の否定条件の形で、分けないことを条件として示す正しい形。"}, {"text": "分けた", "is_correct": false, "explanation": "過去形で、「〜ないと」の条件文の形と合わない。"}, {"text": "分けて", "is_correct": false, "explanation": "て形で、「〜ないと」に続く条件文として成り立たない。"}, {"text": "分けます", "is_correct": false, "explanation": "丁寧形で、条件表現の「ないと」に続かない。"}], "explanations": {"分けない": "「分けないと」の否定条件の形で、分けないことを条件として示す正しい形。", "分けた": "過去形で、「〜ないと」の条件文の形と合わない。", "分けて": "て形で、「〜ないと」に続く条件文として成り立たない。", "分けます": "丁寧形で、条件表現の「ないと」に続かない。"}, "sentence_index": 6, "correct_answer": "分けない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "調査では、集めた意見の味を賛成と反対に分けた。", "explanation": "ここは〈味わう〉の意味。意見の味は分けるものではなく、この言い方は合わない。"}, {"text": "調査では、集めた意見を英語に分けた。", "explanation": "ここは〈訳す〉の意味。意見は分けるのではなく訳すものなので、この言い方は合わない。"}, {"text": "調査では、集めた意見を、声に出して分けた。", "explanation": "ここは〈読む〉の意味。意見は分けるのではなく読むものなので、この言い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37999, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業を三つの工程に分ける、順番に進めた。", "corrected_sentence": "作業を三つの工程に分けて、順番に進めた。", "error_description": "活用の誤り。「分ける」のままでは後ろに続かず、「分けて」の連用形にする必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "分けて", "is_correct": true, "explanation": "て形で、後ろの「棚に並べている」へ続く文の形として正しい。"}, {"text": "分けた", "is_correct": false, "explanation": "過去形で、後ろの「並べている」と続く文の流れに合わない。"}, {"text": "分けない", "is_correct": false, "explanation": "否定形で、分けないという反対の内容になってしまう。"}, {"text": "分けられる", "is_correct": false, "explanation": "可能・受身の形で、文の意味が本を分けられるという別の内容になる。"}], "correct_form": "分けて", "base_form": "分ける", "form_label": "て形", "sentence_index": 1, "explanations": {"分けて": "て形で、後ろの「棚に並べている」へ続く文の形として正しい。", "分けた": "過去形で、後ろの「並べている」と続く文の流れに合わない。", "分けない": "否定形で、分けないという反対の内容になってしまう。", "分けられる": "可能・受身の形で、文の意味が本を分けられるという別の内容になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37999, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "書類を三つの箱を分けたので、探しやすくなった。", "corrected_sentence": "書類を三つの箱に分けたので、探しやすくなった。", "error_description": "助詞の誤り。分けた先は「に」で示す。「を」は目的語に使うので、「書類を」とあわせて二つの「を」が重なり不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "分けた", "is_correct": true, "explanation": "過去形で、資料を分けた動作が済んだことを表し、後ろの「探しやすくなった」と合う。"}, {"text": "分けよう", "is_correct": false, "explanation": "意志形で、過去の出来事を述べる文と合わない。"}, {"text": "分けて", "is_correct": false, "explanation": "て形で、「ので」に続く文の述語として完結しない。"}, {"text": "分けます", "is_correct": false, "explanation": "丁寧形で、普通体の文の中では合わない。"}], "correct_form": "分けた", "base_form": "分ける", "form_label": "過去形", "sentence_index": 7, "explanations": {"分けた": "過去形で、資料を分けた動作が済んだことを表し、後ろの「探しやすくなった」と合う。", "分けよう": "意志形で、過去の出来事を述べる文と合わない。", "分けて": "て形で、「ので」に続く文の述語として完結しない。", "分けます": "丁寧形で、普通体の文の中では合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
