INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38000, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "さがしていたものを、見つけること。", "primary_collocate": null, "pronunciation": "みつける", "ipa": "mitsɯkeɾɯ", "syllable_count": 4, "sentences": [{"text": "なくした鍵を、ソファの下で見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "なくした鍵[かぎ]を、ソファの下[した]で見付[みつ]けた。", "sentence_source": "generated"}, {"text": "長い時間さがして、ようやく眼鏡を見付けました。", "target_word": "見付けました", "complexity_tier": "T3", "furigana": "長[なが]い時間[じかん]さがして、ようやく眼鏡[めがね]を見付[みつ]けました。", "sentence_source": "generated"}, {"text": "なくした指輪を、引き出しの奥から見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "なくした指輪[ゆびわ]を、引[ひ]き出[だ]しの奥[おく]から見付(みつ)けた。", "sentence_source": "generated"}, {"text": "探していた本を、古本屋で見付けることができた。", "target_word": "見付ける", "complexity_tier": "T3", "furigana": "探[さが]していた本[ほん]を、古本屋[ふるほんや]で見付[みつ]けることができた。", "sentence_source": "generated"}, {"text": "財布を見付けたとき、ほっとして力がぬけた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "財布[さいふ]を見付[みつ]けたとき、ほっとして力[ちから]がぬけた。", "sentence_source": "generated"}, {"text": "子どもは、かくれていたボールをすぐに見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "子[こ]どもは、かくれていたボールをすぐに見付[みつ]けた。", "sentence_source": "generated"}, {"text": "かばんの中を探したが、定期券は見付けられなかった。", "target_word": "見付けられなかった", "complexity_tier": "T3", "furigana": "かばんの中[なか]を探[さが]したが、定期券[ていきけん]は見付[みつ]けられなかった。", "sentence_source": "generated"}, {"text": "落とした帽子を、犬が見付けてくれた。", "target_word": "見付けて", "complexity_tier": "T3", "furigana": "落[お]とした帽子[ぼうし]を、犬[いぬ]が見付[みつ]けてくれた。", "sentence_source": "generated"}, {"text": "大事な書類を見付けるまで、部屋じゅうを探した。", "target_word": "見付ける", "complexity_tier": "T3", "furigana": "大事[だいじ]な書類[しょるい]を見付[みつ]けるまで、部屋[へや]じゅうを探[さが]した。", "sentence_source": "generated"}, {"text": "なくした消しゴムを、机の下で見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "なくした消[け]しゴムを、机[つくえ]の下[した]で見付(みつ)けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見付ける", "label": "辞書形"}, {"form": "見付けます", "label": "ます形"}, {"form": "見付けて", "label": "て形"}, {"form": "見付けた", "label": "た形"}, {"form": "見付けない", "label": "ない形"}, {"form": "見付けられる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "みつける：さがしていた物を見つけ出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38000, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見付けた", "is_correct": true, "explanation": "ここは〈見付けた〉。なくした鍵を探し出したという過去の出来事として自然。"}, {"text": "洗った", "is_correct": false, "explanation": "洗うは汚れを落とす動作。なくした鍵を洗ったとは言わず、文に合わない。"}, {"text": "作った", "is_correct": false, "explanation": "作るは新しく形にすること。なくした鍵を作ったという意味にはならない。"}, {"text": "乾かした", "is_correct": false, "explanation": "乾かすは水分を飛ばすこと。ソファの下で鍵を乾かすとは言わない。"}], "explanations": {"見付けた": "ここは〈見付けた〉。なくした鍵を探し出したという過去の出来事として自然。", "洗った": "洗うは汚れを落とす動作。なくした鍵を洗ったとは言わず、文に合わない。", "作った": "作るは新しく形にすること。なくした鍵を作ったという意味にはならない。", "乾かした": "乾かすは水分を飛ばすこと。ソファの下で鍵を乾かすとは言わない。"}, "sentence_index": 0, "correct_answer": "見付けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の結果を最後まで見付けた。", "explanation": "ここは〈見届ける〉の意味。見付けるは探して出会うことで、結果を最後まで確かめる意味では使わない。"}, {"text": "帰り道、ふと昼寝を見付けて、そのまま眠った。", "explanation": "ここは〈取る〉の意味。見付けるは探して出会う行為で、昼寝をとる意味では使わない。"}, {"text": "朝から天気を見付けて、窓を何度も開けた。", "explanation": "ここは〈気にする〉の意味。見付けるは探して出会う行為で、天気を気にする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38000, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見付けられなかった", "is_correct": true, "explanation": "ここは〈見付けられなかった〉。定期券を探したが見つけられなかったという文脈に合う。"}, {"text": "洗えなかった", "is_correct": false, "explanation": "洗うは汚れを落とすこと。定期券を洗えなかったでは探索の文脈に合わない。"}, {"text": "乾かせなかった", "is_correct": false, "explanation": "乾かすは水分を飛ばすこと。定期券の探索の文脈に合わない。"}, {"text": "焼けなかった", "is_correct": false, "explanation": "焼くは熱で加工すること。探したが見つからなかったという文脈に合わない。"}], "explanations": {"見付けられなかった": "ここは〈見付けられなかった〉。定期券を探したが見つけられなかったという文脈に合う。", "洗えなかった": "洗うは汚れを落とすこと。定期券を洗えなかったでは探索の文脈に合わない。", "乾かせなかった": "乾かすは水分を飛ばすこと。定期券の探索の文脈に合わない。", "焼けなかった": "焼くは熱で加工すること。探したが見つからなかったという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "見付けられなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔の約束を見付けた。", "explanation": "ここは〈思い出す〉の意味。見付けるは探して出会う行為で、記憶を呼び戻す意味では使わない。"}, {"text": "彼の言葉を見付けて、待ち続けた。", "explanation": "ここは〈信じる〉の意味。見付けるは探して出会う行為で、相手を信頼する意味では使わない。"}, {"text": "しばらく歩いて頭を見付けた。", "explanation": "ここは〈冷やす〉の意味。見付けるは探して出会う行為で、頭を冷ます意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38000, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "なくした手袋を、ソファの下で見付けるた。", "corrected_sentence": "なくした手袋を、ソファの下で見付けた。", "error_description": "〈見付ける〉の過去形は〈見付けた〉。辞書形の「る」を残して「見付けるた」とするのは活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見付けました", "is_correct": true, "explanation": "ここは〈見付けました〉。ます形で、丁寧に結果を報告する文末に合う。"}, {"text": "見付けて", "is_correct": false, "explanation": "て形は文末に置けず、この文は成立しない。"}, {"text": "見付けない", "is_correct": false, "explanation": "否定形にすると見つからなかったという意味になり、ようやく見つけたという文と矛盾する。"}, {"text": "見付けられる", "is_correct": false, "explanation": "可能形は「見つけることができる」の意味で、既に見つけた事実の報告に合わない。"}], "correct_form": "見付けました", "base_form": "見付ける", "form_label": "ます形", "sentence_index": 1, "explanations": {"見付けました": "ここは〈見付けました〉。ます形で、丁寧に結果を報告する文末に合う。", "見付けて": "て形は文末に置けず、この文は成立しない。", "見付けない": "否定形にすると見つからなかったという意味になり、ようやく見つけたという文と矛盾する。", "見付けられる": "可能形は「見つけることができる」の意味で、既に見つけた事実の報告に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38000, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ポケットの中で財布に見付けた。", "corrected_sentence": "ポケットの中で財布を見付けた。", "error_description": "見付けるの対象は〈を〉で示す。〈に〉では対象を示せず、「財布に見付けた」は不自然。正しくは「財布を見付けた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見付けて", "is_correct": true, "explanation": "ここは〈見付けて〉。「〜てくれた」と続く形で、文の流れに合う。"}, {"text": "見付けよう", "is_correct": false, "explanation": "意志形は「見付けよう」と自分の意思を表すもので、犬が見付けた事実を述べる文には合わない。"}, {"text": "見付けなかった", "is_correct": false, "explanation": "否定の過去形は帽子を見付けなかったという意味になり、「くれた」と矛盾する。"}, {"text": "見付けられない", "is_correct": false, "explanation": "可能形の否定は見付けることができないという意味で、犬が帽子を見付けてくれた流れに合わない。"}], "correct_form": "見付けて", "base_form": "見付ける", "form_label": "て形", "sentence_index": 7, "explanations": {"見付けて": "ここは〈見付けて〉。「〜てくれた」と続く形で、文の流れに合う。", "見付けよう": "意志形は「見付けよう」と自分の意思を表すもので、犬が見付けた事実を述べる文には合わない。", "見付けなかった": "否定の過去形は帽子を見付けなかったという意味になり、「くれた」と矛盾する。", "見付けられない": "可能形の否定は見付けることができないという意味で、犬が帽子を見付けてくれた流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
