INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38001, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "探していたものや人に、出会うこと。", "primary_collocate": null, "pronunciation": "みつける", "ipa": "mitsɯkeɾɯ", "syllable_count": 4, "sentences": [{"text": "迷子になった子どもを、駅の前で見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "迷子[まいご]になった子[こ]どもを、駅[えき]の前[まえ]で見付[みつ]けた。", "sentence_source": "generated"}, {"text": "三か月かかって、やっと自分に合う仕事を見付けました。", "target_word": "見付けました", "complexity_tier": "T3", "furigana": "三[さん]か月[げつ]かかって、やっと自分[じぶん]に合[あ]う仕事[しごと]を見付[みつ]けました。", "sentence_source": "generated"}, {"text": "長い間さがしていた友だちを、ネットで見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]さがしていた友[とも]だちを、ネットで見付[みつ]けた。", "sentence_source": "generated"}, {"text": "町じゅうを回って、安くて広い部屋を見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "町[まち]じゅうを回[まわ]って、安[やす]くて広[ひろ]い部屋[へや]を見付[みつ]けた。", "sentence_source": "generated"}, {"text": "人が多かったが、ようやく妹を見付けて手をふった。", "target_word": "見付けて", "complexity_tier": "T3", "furigana": "人[ひと]が多[おお]かったが、ようやく妹[いもうと]を見付[みつ]けて手[て]をふった。", "sentence_source": "generated"}, {"text": "山で道に迷った人を、警察が見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]った人[ひと]を、警察[けいさつ]が見付[みつ]けた。", "sentence_source": "generated"}, {"text": "彼女はやっと理想の相手を見付けたと言っている。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はやっと理想[りそう]の相手[あいて]を見付[みつ]けたと言[い]っている。", "sentence_source": "generated"}, {"text": "空いている席を見付けて、すわりました。", "target_word": "見付けて", "complexity_tier": "T3", "furigana": "空[あ]いている席[せき]を見付[みつ]けて、すわりました。", "sentence_source": "generated"}, {"text": "探していた先生を、図書館の前で見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "探[さが]していた先生[せんせい]を、図書館[としょかん]の前[まえ]で見付[みつ]けた。", "sentence_source": "generated"}, {"text": "道に迷ったが、探していた駅をようやく見付けた。", "target_word": "見付けた", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]ったが、探[さが]していた駅[えき]をようやく見付(みつ)けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見付ける", "label": "辞書形"}, {"form": "見付けます", "label": "ます形"}, {"form": "見付けて", "label": "て形"}, {"form": "見付けた", "label": "た形"}, {"form": "見付けない", "label": "ない形"}, {"form": "見付けられる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "みつける：探していた人や物（仕事・部屋など）に出会うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81506354-4ff8-4906-8caa-62cedb51b23d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38001, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見付けた", "is_correct": true, "explanation": "ここは〈見付けた〉。迷子を探し出して出会ったという文脈に合う。"}, {"text": "焼いた", "is_correct": false, "explanation": "焼くは火で加熱すること。子どもを焼いたとは言わず、文に合わない。"}, {"text": "煮た", "is_correct": false, "explanation": "煮るは水で加熱すること。人を煮るという表現は文に合わない。"}, {"text": "叩いた", "is_correct": false, "explanation": "叩くは打つ動作。迷子を探し出す場面には合わない。"}], "explanations": {"見付けた": "ここは〈見付けた〉。迷子を探し出して出会ったという文脈に合う。", "焼いた": "焼くは火で加熱すること。子どもを焼いたとは言わず、文に合わない。", "煮た": "煮るは水で加熱すること。人を煮るという表現は文に合わない。", "叩いた": "叩くは打つ動作。迷子を探し出す場面には合わない。"}, "sentence_index": 0, "correct_answer": "見付けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末、友だちの体温を見付けて、映画館へ向かった。", "explanation": "ここは〈測る〉の意味。見付けるは探して出会う行為で、体温を計る意味では使わない。"}, {"text": "つらい試練を見付けた。", "explanation": "ここは〈乗り越える〉の意味。見付けるは探して出会うことで、困難を克服する意味では使わない。"}, {"text": "遅刻した後輩を、きつく見付けた。", "explanation": "ここは〈叱る〉の意味。見付けるは探して出会うことで、怒って注意する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38001, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見付けた", "is_correct": true, "explanation": "ここは〈見付けた〉。理想の相手に出会ったという報告の文脈に合う。"}, {"text": "乾かした", "is_correct": false, "explanation": "乾かすは水分を飛ばすこと。理想の相手を乾かしたとは言えない。"}, {"text": "洗った", "is_correct": false, "explanation": "洗うは汚れを落とすこと。人を洗ったとは言わず、文に合わない。"}, {"text": "磨いた", "is_correct": false, "explanation": "磨くは表面をなめらかにすること。理想の相手を磨いたとは言えず、文に合わない。"}], "explanations": {"見付けた": "ここは〈見付けた〉。理想の相手に出会ったという報告の文脈に合う。", "乾かした": "乾かすは水分を飛ばすこと。理想の相手を乾かしたとは言えない。", "洗った": "洗うは汚れを落とすこと。人を洗ったとは言わず、文に合わない。", "磨いた": "磨くは表面をなめらかにすること。理想の相手を磨いたとは言えず、文に合わない。"}, "sentence_index": 6, "correct_answer": "見付けた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの勝負を見付けた。", "explanation": "ここは〈諦める〉の意味。見付けるは探して出会う行為で、勝負を放棄する意味では使わない。"}, {"text": "彼女の冗談を見付けて、思わずため息をついた。", "explanation": "ここは〈呆れる〉の意味。見付けるは探して出会う行為で、相手の言動に呆れる意味では使わない。"}, {"text": "リズムに合わせて、ひざを見付けた。", "explanation": "ここは〈踊る〉の意味。見付けるは探して出会う行為で、体を動かす意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38001, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "迷子の子どもに、駅の前で見付けた。", "corrected_sentence": "迷子の子どもを、駅の前で見付けた。", "error_description": "見付けるの対象は〈を〉で示す。〈に〉では対象を示せず、「子どもに見付けた」は不自然。正しくは「子どもを見付けた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見付けました", "is_correct": true, "explanation": "ここは〈見付けました〉。ます形で、やっと仕事を見つけたという丁寧な報告の文末に合う。"}, {"text": "見付けて", "is_correct": false, "explanation": "て形は文末に置けず、この文は成立しない。"}, {"text": "見付けない", "is_correct": false, "explanation": "否定形にすると見つけられなかったという意味になり、やっと見つけたという文と矛盾する。"}, {"text": "見付けられる", "is_correct": false, "explanation": "可能形は「見つけることができる」の意味で、既に見つけた事実の報告に合わない。"}], "correct_form": "見付けました", "base_form": "見付ける", "form_label": "ます形", "sentence_index": 1, "explanations": {"見付けました": "ここは〈見付けました〉。ます形で、やっと仕事を見つけたという丁寧な報告の文末に合う。", "見付けて": "て形は文末に置けず、この文は成立しない。", "見付けない": "否定形にすると見つけられなかったという意味になり、やっと見つけたという文と矛盾する。", "見付けられる": "可能形は「見つけることができる」の意味で、既に見つけた事実の報告に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38001, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "帰り道、ようやく近道を見付けたて、安心した。", "corrected_sentence": "帰り道、ようやく近道を見付けて、安心した。", "error_description": "「見付ける」のて形は「見付けて」。「た」を付けた「見付けたて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見付けて", "is_correct": true, "explanation": "ここは〈見付けて〉。て形で、後ろの動作「すわりました」へ続く形に合う。"}, {"text": "見付けよう", "is_correct": false, "explanation": "意志形は「見付けよう」と自分の意思を表すもので、席を見つけた事実を述べる文には合わない。"}, {"text": "見付けなかった", "is_correct": false, "explanation": "否定の過去形は席を見付けなかったという意味になり、後に座った流れと矛盾する。"}, {"text": "見付けられない", "is_correct": false, "explanation": "可能形の否定は見付けることができないという意味で、席が見つかって座ったという流れに合わない。"}], "correct_form": "見付けて", "base_form": "見付ける", "form_label": "て形", "sentence_index": 7, "explanations": {"見付けて": "ここは〈見付けて〉。て形で、後ろの動作「すわりました」へ続く形に合う。", "見付けよう": "意志形は「見付けよう」と自分の意思を表すもので、席を見つけた事実を述べる文には合わない。", "見付けなかった": "否定の過去形は席を見付けなかったという意味になり、後に座った流れと矛盾する。", "見付けられない": "可能形の否定は見付けることができないという意味で、席が見つかって座ったという流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e5ebe6-bb05-4418-b1f3-cf8720b9fa55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
