INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38002, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『デザインを選んだ』の目的語を示す『を』。"}, {"text": "に", "is_correct": false, "explanation": "『デザインに選ぶ』とは言わない。選ぶ対象には『を』を使う。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表す。選ぶ対象には使えない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を表す。ここでは比べる文脈がない。"}], "correct_answer": "を", "explanations": {"を": "『デザインを選んだ』の目的語を示す『を』。", "に": "『デザインに選ぶ』とは言わない。選ぶ対象には『を』を使う。", "へ": "『へ』は方向を表す。選ぶ対象には使えない。", "より": "『より』は比較を表す。ここでは比べる文脈がない。"}, "error_tags": {"に": "対象ではない", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38002, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものの形や色を考えることです。", "primary_collocate": null, "pronunciation": "でざいん", "ipa": "dezaiɴ", "syllable_count": 4, "sentences": [{"text": "新しい服のデザインを考えるのが私の仕事です。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "新[あたら]しい服[ふく]のデザインを考[かんが]えるのが私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "このかばんは色もデザインもすてきなので、買いました。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "このかばんは色[いろ]もデザインもすてきなので、買[か]いました。", "sentence_source": "generated"}, {"text": "弟は絵がうまいので、ポスターのデザインをまかされた。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "弟[おとうと]は絵[え]がうまいので、ポスターのデザインをまかされた。", "sentence_source": "generated"}, {"text": "使いやすさを考えて、いすのデザインを変えました。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "使[つか]いやすさを考[かんが]えて、いすのデザインを変[か]えました。", "sentence_source": "generated"}, {"text": "デザインが気に入らなかったから、その靴は買わなかった。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "デザインが気[き]に入[い]らなかったから、その靴[くつ]は買[か]わなかった。", "sentence_source": "generated"}, {"text": "学校のロゴは、卒業生がデザインしたそうです。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "学校[がっこう]のロゴは、卒業生[そつぎょうせい]がデザインしたそうです。", "sentence_source": "generated"}, {"text": "形がおもしろいデザインのコップを友だちにもらった。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "形[かたち]がおもしろいデザインのコップを友[とも]だちにもらった。", "sentence_source": "generated"}, {"text": "部屋の雰囲気に合うよう、カーテンの色とデザインを選んだ。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "部屋[へや]の雰囲気[ふんいき]に合[あ]うよう、カーテンの色[いろ]とデザインを選[えら]んだ。", "sentence_source": "generated"}, {"text": "彼女は車のデザインを勉強するために留学した。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は車[くるま]のデザインを勉強[べんきょう]するために留学[りゅうがく]した。", "sentence_source": "generated"}, {"text": "見た目のデザインだけでなく、使いやすさも大事です。", "target_word": "デザイン", "complexity_tier": "T3", "furigana": "見[み]た目[め]のデザインだけでなく、使[つか]いやすさも大事[だいじ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "デザインする", "label": "dictionary form"}, {"form": "デザインします", "label": "polite form"}, {"form": "デザインして", "label": "te-form"}, {"form": "デザインした", "label": "past form"}, {"form": "デザインの", "label": "attributive form"}], "register": "neutral", "sense_fingerprint": "ものの形・色・見た目を考えて決めること、またその結果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: まかさ (Zipf 2.37)']::text[], 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38002, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "デザイン", "is_correct": true, "explanation": "『服のデザインを考える』の意味で、服の形や色を決める仕事として文に合う。"}, {"text": "予約", "is_correct": false, "explanation": "予約は前もって決めること。『服の予約を考える』とは言わない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は話し合いの場。『服の会議を考える』では意味が通らない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通話の道具。服について考える対象にはならない。"}], "explanations": {"デザイン": "『服のデザインを考える』の意味で、服の形や色を決める仕事として文に合う。", "予約": "予約は前もって決めること。『服の予約を考える』とは言わない。", "会議": "会議は話し合いの場。『服の会議を考える』では意味が通らない。", "電話": "電話は通話の道具。服について考える対象にはならない。"}, "sentence_index": 0, "correct_answer": "デザイン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "いすのデザインが壊れて、体を支えられなくなった。", "explanation": "ここは〈機能〉の意味。デザインは形や色のことで、壊れて体を支えられなくなるのは機能の問題。"}, {"text": "いすのデザインを味見した。", "explanation": "ここは〈味わう〉の意味。デザインは形や色のことで、食べ物の味を確かめる意味では使わない。"}, {"text": "いすのデザインを何度も洗って、きれいにした。", "explanation": "ここは〈掃除〉の意味。デザインは形や色で、洗って汚れを落とすものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38002, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "デザイン", "is_correct": true, "explanation": "『形がおもしろいデザイン』の意味で、コップの形や見た目を表して文に合う。"}, {"text": "材料", "is_correct": false, "explanation": "材料は作るための素材。『形がおもしろい材料』とは言わない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格。形を表す修飾には使えない。"}, {"text": "容量", "is_correct": false, "explanation": "容量は入る量。『形がおもしろい容量』では意味が通らない。"}], "explanations": {"デザイン": "『形がおもしろいデザイン』の意味で、コップの形や見た目を表して文に合う。", "材料": "材料は作るための素材。『形がおもしろい材料』とは言わない。", "値段": "値段は価格。形を表す修飾には使えない。", "容量": "容量は入る量。『形がおもしろい容量』では意味が通らない。"}, "sentence_index": 6, "correct_answer": "デザイン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このかばんは、デザインが安くて買いやすい。", "explanation": "ここは〈費用〉の意味。デザインは形や色で、値段の意味はない。"}, {"text": "このコップのデザインは、重くて割れにくい。", "explanation": "ここは〈強度〉の意味。デザインは形や色で、割れにくさを示すものではない。"}, {"text": "このいすのデザインは、とても軽くて運びやすい。", "explanation": "ここは〈重さ〉の意味。デザインは形や色のことで、重さを表すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38002, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい靴にデザインを考えるのが私の仕事です。", "corrected_sentence": "新しい靴のデザインを考えるのが私の仕事です。", "error_description": "『靴のデザイン』と所属を表す『の』が必要。『に』では意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38002, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいポスターのデザインをを作りました。", "corrected_sentence": "新しいポスターのデザインを作りました。", "error_description": "『デザインを作る』の目的語の『を』が二つ重なっている。『を』は一つだけが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38006, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「年代のもの」で、時代に属するものという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「年代をもの」は成り立たず、対象を示す格ではない。"}, {"text": "に", "is_correct": false, "explanation": "「年代にもの」は意味が通らず、位置を示す格としても合わない。"}, {"text": "で", "is_correct": false, "explanation": "「年代でもの」は場所や手段を示すことになり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「年代のもの」で、時代に属するものという意味になる。", "を": "「年代をもの」は成り立たず、対象を示す格ではない。", "に": "「年代にもの」は意味が通らず、位置を示す格としても合わない。", "で": "「年代でもの」は場所や手段を示すことになり、文が成り立たない。"}, "error_tags": {"を": "対象の格", "に": "位置・時点", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38006, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「その年代の人々」で、その時代の人々という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「その年代を人々は」では、「を」が受ける動詞がなく成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、時期を修飾する文脈には使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、比べる対象がないため文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「その年代の人々」で、その時代の人々という意味になる。", "を": "「その年代を人々は」では、「を」が受ける動詞がなく成り立たない。", "へ": "方向を示す「へ」は、時期を修飾する文脈には使えない。", "より": "比較の「より」は、比べる対象がないため文が成り立たない。"}, "error_tags": {"を": "対象の格", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38006, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その時代（じだい）のこと。", "primary_collocate": null, "pronunciation": "ねんだい", "ipa": "nendai", "syllable_count": 4, "sentences": [{"text": "父は、自分が若かった年代の音楽が今も好きだ。", "target_word": "年代", "complexity_tier": "T3", "furigana": "父[ちち]は、自分[じぶん]が若[わか]かった年代[ねんだい]の音楽[おんがく]が今[いま]も好[す]きだ。", "sentence_source": "generated"}, {"text": "この写真は、祖母が若かった年代のものだ。", "target_word": "年代", "complexity_tier": "T3", "furigana": "この写真[しゃしん]は、祖母[そぼ]が若[わか]かった年代[ねんだい]のものだ。", "sentence_source": "generated"}, {"text": "年代が違うと、流行した服もずいぶん違う。", "target_word": "年代", "complexity_tier": "T3", "furigana": "年代[ねんだい]が違[ちが]うと、流行[りゅうこう]した服[ふく]もずいぶん違[ちが]う。", "sentence_source": "generated"}, {"text": "あの年代は、まだ携帯電話がなかった。", "target_word": "年代", "complexity_tier": "T3", "furigana": "あの年代[ねんだい]は、まだ携帯電話[けいたいでんわ]がなかった。", "sentence_source": "generated"}, {"text": "映画のセットは、その年代の町並みをそのまま再現している。", "target_word": "年代", "complexity_tier": "T3", "furigana": "映画[えいが]のセットは、その年代[ねんだい]の町並[まちな]みをそのまま再現[さいげん]している。", "sentence_source": "generated"}, {"text": "祖父はあの年代に生まれたので、戦争の話をよく知っている。", "target_word": "年代", "complexity_tier": "T3", "furigana": "祖父[そふ]はあの年代[ねんだい]に生[う]まれたので、戦争[せんそう]の話[はなし]をよく知[し]っている。", "sentence_source": "generated"}, {"text": "この歌は、私が学生だった年代によく聞いた。", "target_word": "年代", "complexity_tier": "T3", "furigana": "この歌[うた]は、私[わたし]が学生[がくせい]だった年代[ねんだい]によく聞[き]いた。", "sentence_source": "generated"}, {"text": "その年代の人々は、手紙で連絡を取っていた。", "target_word": "年代", "complexity_tier": "T3", "furigana": "その年代[ねんだい]の人々[ひとびと]は、手紙[てがみ]で連絡[れんらく]を取[と]っていた。", "sentence_source": "generated"}, {"text": "古い雑誌を見ると、その年代の暮らしが分かる。", "target_word": "年代", "complexity_tier": "T3", "furigana": "古[ふる]い雑誌[ざっし]を見[み]ると、その年代[ねんだい]の暮[く]らしが分[わ]かる。", "sentence_source": "generated"}, {"text": "時計の形も、年代によって少しずつ変わってきた。", "target_word": "年代", "complexity_tier": "T3", "furigana": "時計[とけい]の形[かたち]も、年代[ねんだい]によって少[すこ]しずつ変[か]わってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年代", "label": "基本形"}, {"form": "年代の", "label": "連体"}], "register": "普通体（日常）", "sense_fingerprint": "ある時代、たとえば何十年代というひとまとまりの時期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38006, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正解。「若かった年代の音楽」で、その時代の音楽を指す。"}, {"text": "味覚", "is_correct": false, "explanation": "「味覚」は味を感じる感覚で、「若かった味覚の音楽」は意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重」は身体の重さで、「若かった体重の音楽」は成り立たない。"}, {"text": "居場所", "is_correct": false, "explanation": "「居場所」は人のいる場所で、時代を表す言葉としては合わない。"}], "explanations": {"年代": "正解。「若かった年代の音楽」で、その時代の音楽を指す。", "味覚": "「味覚」は味を感じる感覚で、「若かった味覚の音楽」は意味が通らない。", "体重": "「体重」は身体の重さで、「若かった体重の音楽」は成り立たない。", "居場所": "「居場所」は人のいる場所で、時代を表す言葉としては合わない。"}, "sentence_index": 0, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験を受けるには、年代が十八歳に届いていなければならない。", "explanation": "ここは〈年齢〉の意味。十八歳に届くのは年齢で、時期の区切りを指す「年代」では言わない。"}, {"text": "年代に、家族みんなで大掃除をした。", "explanation": "ここは〈年末〉の意味。大掃除をする時期は年末で、「年代」は時代の区切りを指すので合わない。"}, {"text": "目覚まし時計が、その年代に鳴った。", "explanation": "ここは〈時刻〉の意味。ある時点の時間は時刻で、「年代」は一定の期間を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38006, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正解。「私が学生だった年代によく聞いた」で、その時期によく聞いたという意味になる。"}, {"text": "寝具", "is_correct": false, "explanation": "「寝具」は布団などの道具で、「学生だった寝具」は時期を表せない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布」は金を入れるものなので、「学生だった財布によく聞いた」は意味が通らない。"}, {"text": "足首", "is_correct": false, "explanation": "「足首」は身体の部位で、時期を表す文脈には合わない。"}], "explanations": {"年代": "正解。「私が学生だった年代によく聞いた」で、その時期によく聞いたという意味になる。", "寝具": "「寝具」は布団などの道具で、「学生だった寝具」は時期を表せない。", "財布": "「財布」は金を入れるものなので、「学生だった財布によく聞いた」は意味が通らない。", "足首": "「足首」は身体の部位で、時期を表す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年代が増えて、生活が少しずつ楽になった。", "explanation": "ここは〈年収〉の意味。収入が増えるのは年収で、「年代」は増えるものではない。"}, {"text": "年代を書いて、友だちに送った。", "explanation": "ここは〈年賀状〉の意味。新年の挨拶として送るのは年賀状で、「年代」を書いて送ることはない。"}, {"text": "長い年代を積んで、腕のよい職人になった。", "explanation": "ここは〈年季〉の意味。職人として積み重ねた経験は年季で、「年代」は積むものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38006, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、若かった年代が写真を大切に持っている。", "corrected_sentence": "祖父は、若かった年代の写真を大切に持っている。", "error_description": "「年代の写真」と連体修飾にするのが正しい。「年代が」は主語になり、「写真」を修飾できず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38006, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "戦後の年代に、多くの人々を大学へ進んだ。", "corrected_sentence": "戦後の年代に、多くの人々が大学へ進んだ。", "error_description": "「進む」は自動詞のため、目的語に「を」は取れない。主語は「多くの人々が」と「が」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38007, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「年代を分けて」で、分ける対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「年代が分けて」は主語になり、分ける対象が消えて不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「年代と分けて」が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、分ける対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "正解。「年代を分けて」で、分ける対象を示す。", "が": "「年代が分けて」は主語になり、分ける対象が消えて不自然。", "と": "並列の「と」では「年代と分けて」が成り立たない。", "へ": "方向を示す「へ」は、分ける対象には使えない。"}, "error_tags": {"が": "主語の格", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38007, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「年代の順」で、年代に沿った順番という意味になる。"}, {"text": "で", "is_correct": false, "explanation": "「年代で順に並べられ」は手段の意味になり、文が不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、比べる対象がないため成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「年代から順に」となり、順番の意味が合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「年代の順」で、年代に沿った順番という意味になる。", "で": "「年代で順に並べられ」は手段の意味になり、文が不自然。", "より": "比較の「より」は、比べる対象がないため成り立たない。", "から": "起点の「から」では「年代から順に」となり、順番の意味が合わない。"}, "error_tags": {"で": "手段・場所の格", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38007, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある特定の時期。特に、歴史的な区分としての期間。", "primary_collocate": null, "pronunciation": "ねんだい", "ipa": "nendai", "syllable_count": 4, "sentences": [{"text": "この本は、十九世紀の年代を中心に、国の歴史を説明している。", "target_word": "年代", "complexity_tier": "T3", "furigana": "この本[ほん]は、十九[じゅうきゅう]世紀[せいき]の年代[ねんだい]を中心[ちゅうしん]に、国[くに]の歴史[れきし]を説明[せつめい]している。", "sentence_source": "generated"}, {"text": "歴史家は、百年ごとに年代を分けて、社会の変化を調べた。", "target_word": "年代", "complexity_tier": "T3", "furigana": "歴史家[れきしか]は、百年[ひゃくねん]ごとに年代[ねんだい]を分[わ]けて、社会[しゃかい]の変化[へんか]を調[しら]べた。", "sentence_source": "generated"}, {"text": "戦前の年代には、世界で大きな経済の変化があった。", "target_word": "年代", "complexity_tier": "T3", "furigana": "戦前[せんぜん]の年代[ねんだい]には、世界[せかい]で大[おお]きな経済[けいざい]の変化[へんか]があった。", "sentence_source": "generated"}, {"text": "年代ごとに町の地図を並べると、広がり方がよく分かる。", "target_word": "年代", "complexity_tier": "T3", "furigana": "年代[ねんだい]ごとに町[まち]の地図[ちず]を並[なら]べると、広[ひろ]がり方[かた]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "研究者は、遺跡を三つの年代に分けて説明した。", "target_word": "年代", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、遺跡[いせき]を三[みっ]つの年代[ねんだい]に分[わ]けて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "高度成長の年代には、日本で高速道路が次々に作られた。", "target_word": "年代", "complexity_tier": "T3", "furigana": "高度成長[こうどせいちょう]の年代[ねんだい]には、日本[にほん]で高速道路[こうそくどうろ]が次々[つぎつぎ]に作[つく]られた。", "sentence_source": "generated"}, {"text": "この年代の美術は、前の時代とまったく違う特徴を持つ。", "target_word": "年代", "complexity_tier": "T3", "furigana": "この年代[ねんだい]の美術[びじゅつ]は、前[まえ]の時代[じだい]とまったく違[ちが]う特徴[とくちょう]を持[も]つ。", "sentence_source": "generated"}, {"text": "博物館では、展示品が年代の順に並べられている。", "target_word": "年代", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、展示品[てんじひん]が年代[ねんだい]の順[じゅん]に並[なら]べられている。", "sentence_source": "generated"}, {"text": "戦後の年代について、授業で詳しく学んだ。", "target_word": "年代", "complexity_tier": "T3", "furigana": "戦後[せんご]の年代[ねんだい]について、授業[じゅぎょう]で詳[くわ]しく学[まな]んだ。", "sentence_source": "generated"}, {"text": "年代が変わるとともに、人々の考え方も大きく動いた。", "target_word": "年代", "complexity_tier": "T3", "furigana": "年代[ねんだい]が変[か]わるとともに、人々[ひとびと]の考[かんが]え方[かた]も大[おお]きく動[うご]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年代", "label": "基本形"}, {"form": "年代の", "label": "連体"}, {"form": "年代ごとに", "label": "区分"}], "register": "普通体（書き言葉・説明調）", "sense_fingerprint": "歴史を区切って考えるときの、ある特定の期間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38007, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正解。「十九世紀の年代を中心に」で、その時期を中心にという意味になる。"}, {"text": "花粉", "is_correct": false, "explanation": "「花粉」は植物の粉で、「十九世紀の花粉を中心に」は歴史の説明として成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "「石鹸」は洗浄剤で、歴史の時期を表す文脈には合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "「湿度」は空気の状態で、「十九世紀の湿度を中心に」は国の歴史の説明にならない。"}], "explanations": {"年代": "正解。「十九世紀の年代を中心に」で、その時期を中心にという意味になる。", "花粉": "「花粉」は植物の粉で、「十九世紀の花粉を中心に」は歴史の説明として成り立たない。", "石鹸": "「石鹸」は洗浄剤で、歴史の時期を表す文脈には合わない。", "湿度": "「湿度」は空気の状態で、「十九世紀の湿度を中心に」は国の歴史の説明にならない。"}, "sentence_index": 0, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の年代を三時に決めた。", "explanation": "ここは〈時刻〉の意味。ある時点の時間を指すのは時刻で、「年代」は区切られた期間を指す。"}, {"text": "年代が十八歳になったので、運転免許を申し込んだ。", "explanation": "ここは〈年齢〉の意味。十八歳に達するのは年齢で、「年代」では言わない。"}, {"text": "年代に、今年の家計を振り返った。", "explanation": "ここは〈年末〉の意味。一年を振り返る時期は年末で、「年代」では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38007, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正解。「この年代の美術」で、その時期の美術を指す。"}, {"text": "寝具", "is_correct": false, "explanation": "「寝具」は布団などの道具で、「この寝具の美術」は意味が通らない。"}, {"text": "薬品", "is_correct": false, "explanation": "「薬品」は薬の総称で、「この薬品の美術」は成り立たない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖」は食品で、「この砂糖の美術」は文として不自然。"}], "explanations": {"年代": "正解。「この年代の美術」で、その時期の美術を指す。", "寝具": "「寝具」は布団などの道具で、「この寝具の美術」は意味が通らない。", "薬品": "「薬品」は薬の総称で、「この薬品の美術」は成り立たない。", "砂糖": "「砂糖」は食品で、「この砂糖の美術」は文として不自然。"}, "sentence_index": 6, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年代が尽きるまで、人々は働き続けた。", "explanation": "ここは〈寿命〉の意味。尽きるのは寿命で、「年代」は尽きるものではない。"}, {"text": "年代が届いたので、返事を書いた。", "explanation": "ここは〈年賀状〉の意味。届いて返事を書くのは年賀状で、「年代」は届くものではない。"}, {"text": "年代が増えて、生活が楽になった。", "explanation": "ここは〈年収〉の意味。収入が増えるのは年収で、「年代」は増えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38007, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "戦後の年代に、新しい法律を次々に作られた。", "corrected_sentence": "戦後の年代に、新しい法律が次々に作られた。", "error_description": "「作られた」は受身で、主語を「が」で示す。「新しい法律を」の「を」は誤りで、「新しい法律が次々に作られた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38007, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "戦後の年代を、国内の産業が大きく発展した。", "corrected_sentence": "戦後の年代には、国内の産業が大きく発展した。", "error_description": "時期を表す「年代には」が正しい。「年代を」は対象を示す「を」で、「発展する」は目的語を取らないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
