INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38008, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "いちばん。多くの中で、一番えらばれるくらい、とてもたくさんあること。", "primary_collocate": null, "pronunciation": "もっとも", "ipa": "motːomo", "syllable_count": 4, "sentences": [{"text": "最も人気のある店です。", "target_word": "最も", "complexity_tier": "T2", "furigana": "最[もっと]も人気[にんき]のある店[みせ]です。", "sentence_source": "generated"}, {"text": "クラスで最も背が高い。", "target_word": "最も", "complexity_tier": "T3", "furigana": "クラスで最[もっと]も背[せ]が高[たか]い。", "sentence_source": "generated"}, {"text": "最も長い川だ。", "target_word": "最も", "complexity_tier": "T1", "furigana": "最[もっと]も長[なが]い川[かわ]だ。", "sentence_source": "generated"}, {"text": "私が最も好きな食べ物はすしだ。", "target_word": "最も", "complexity_tier": "T3", "furigana": "私[わたし]が最[もっと]も好[す]きな食[た]べ物[もの]はすしだ。", "sentence_source": "generated"}, {"text": "この中で最も多いのは赤色だ。", "target_word": "最も", "complexity_tier": "T3", "furigana": "この中[なか]で最[もっと]も多[おお]いのは赤色[あかいろ]だ。", "sentence_source": "generated"}, {"text": "最も近い駅まで歩いて十分かかる。", "target_word": "最も", "complexity_tier": "T4", "furigana": "最[もっと]も近[ちか]い駅[えき]まで歩[ある]いて十分[じゅっぷん]かかる。", "sentence_source": "generated"}, {"text": "彼が最も早く走りました。", "target_word": "最も", "complexity_tier": "T2", "furigana": "彼[かれ]が最[もっと]も早[はや]く走[はし]りました。", "sentence_source": "generated"}, {"text": "最も多く票を取った人が、会長になる。", "target_word": "最も", "complexity_tier": "T4", "furigana": "最[もっと]も多[おお]く票[ひょう]を取[と]った人[ひと]が、会長[かいちょう]になる。", "sentence_source": "generated"}, {"text": "夏休みの中で最も楽しかったのは、海へ行った日だ。", "target_word": "最も", "complexity_tier": "T5", "furigana": "夏休[なつやす]みの中[なか]で最[もっと]も楽[たの]しかったのは、海[うみ]へ行[い]った日[ひ]だ。", "sentence_source": "generated"}, {"text": "最も大きい箱を選んでください。", "target_word": "最も", "complexity_tier": "T3", "furigana": "最[もっと]も大[おお]きい箱[はこ]を選[えら]んでください。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | 多くの中で一番であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38008, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最も", "is_correct": true, "explanation": "「人気のある」を一番の程度で修飾し、文意に合う。"}, {"text": "ちっとも", "is_correct": false, "explanation": "形は合うが、打ち消しと使う語で、意味が合わない。"}, {"text": "めったに", "is_correct": false, "explanation": "形は合うが、頻度が低いことを表す語で、意味が合わない。"}, {"text": "決して", "is_correct": false, "explanation": "形は合うが、打ち消しと使う語で、意味が合わない。"}], "explanations": {"最も": "「人気のある」を一番の程度で修飾し、文意に合う。", "ちっとも": "形は合うが、打ち消しと使う語で、意味が合わない。", "めったに": "形は合うが、頻度が低いことを表す語で、意味が合わない。", "決して": "形は合うが、打ち消しと使う語で、意味が合わない。"}, "sentence_index": 0, "correct_answer": "最も"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は最も一冊の本を読んだ。", "explanation": "「最も」は程度の一番を表し、数を表す「一冊」と合わない。"}, {"text": "このカレーは最も少し辛い。", "explanation": "「最も」は一番を表すのに「少し」と並べると意味が矛盾する。"}, {"text": "クラスの全員が最も同じ服を着ている。", "explanation": "「同じ」は程度で比べる語ではなく、「最も」で修飾すると意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38008, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最も", "is_correct": true, "explanation": "「早く」を一番の程度で修飾し、文意に合う。"}, {"text": "もし", "is_correct": false, "explanation": "形は合うが、仮定を表す語で、意味が合わない。"}, {"text": "決して", "is_correct": false, "explanation": "打ち消しと使う語で、肯定の文には合わない。"}, {"text": "一向に", "is_correct": false, "explanation": "形は合うが、打ち消しと使う語で、意味が合わない。"}], "explanations": {"最も": "「早く」を一番の程度で修飾し、文意に合う。", "もし": "形は合うが、仮定を表す語で、意味が合わない。", "決して": "打ち消しと使う語で、肯定の文には合わない。", "一向に": "形は合うが、打ち消しと使う語で、意味が合わない。"}, "sentence_index": 6, "correct_answer": "最も"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は最も毎朝六時に起きる。", "explanation": "「最も」は頻度の「毎朝」を修飾できず、一番を表す使い方として誤り。"}, {"text": "箱を最も三つ運んでください。", "explanation": "「最も」は程度の一番を表し、数を表す「三つ」には使えない。"}, {"text": "友達は最も先月、引っ越した。", "explanation": "「最も」は時を表す語の前で使う語ではなく、意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38008, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この中で最もの大きい犬は太郎だ。", "corrected_sentence": "この中で最も大きい犬は太郎だ。", "error_description": "副詞の「最も」に「の」を付けて名詞のように使っている。「最も大きい」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38008, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私の家族で最もに年上なのは祖父だ。", "corrected_sentence": "私の家族で最も年上なのは祖父だ。", "error_description": "副詞の「最も」に不要な「に」が付いている。「最も年上」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
