INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38009, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "程度が他よりはるかに高いことを表す。形容詞や副詞に付いて、最上の程度を示す。", "primary_collocate": null, "pronunciation": "もっとも", "ipa": "motːomo", "syllable_count": 4, "sentences": [{"text": "それは、言葉を持たぬ者が自然と交わす、最も純粋な対話の形なのかもしれない。", "target_word": "最も", "complexity_tier": "T6", "furigana": "それは、言葉[ことば]を持[も]たぬ者[もの]が自然[しぜん]と交[か]わす、最[もっと]も純粋[じゅんすい]な対話[たいわ]の形[かたち]なのかもしれない。", "sentence_source": "mined"}, {"text": "最も大切なのは健康です。", "target_word": "最も", "complexity_tier": "T2", "furigana": "最[もっと]も大切[たいせつ]なのは健康[けんこう]です。", "sentence_source": "generated"}, {"text": "今日が最も暑い日だった。", "target_word": "最も", "complexity_tier": "T3", "furigana": "今日[きょう]が最[もっと]も暑[あつ]い日[ひ]だった。", "sentence_source": "generated"}, {"text": "最も高い山だ。", "target_word": "最も", "complexity_tier": "T1", "furigana": "最[もっと]も高[たか]い山[やま]だ。", "sentence_source": "generated"}, {"text": "最も早く着いたのは彼女だ。", "target_word": "最も", "complexity_tier": "T3", "furigana": "最[もっと]も早[はや]く着[つ]いたのは彼女[かのじょ]だ。", "sentence_source": "generated"}, {"text": "三つの案のうち、最も安いものを選んだ。", "target_word": "最も", "complexity_tier": "T4", "furigana": "三[みっ]つの案[あん]のうち、最[もっと]も安[やす]いものを選[えら]んだ。", "sentence_source": "generated"}, {"text": "彼は最も信頼できる人だ。", "target_word": "最も", "complexity_tier": "T3", "furigana": "彼[かれ]は最[もっと]も信頼[しんらい]できる人[ひと]だ。", "sentence_source": "generated"}, {"text": "最も難しい問題が解ければ、合格できる。", "target_word": "最も", "complexity_tier": "T4", "furigana": "最[もっと]も難[むずか]しい問題[もんだい]が解[と]ければ、合格[ごうかく]できる。", "sentence_source": "generated"}, {"text": "世界で最も古い図書館が、この小さな町にある。", "target_word": "最も", "complexity_tier": "T5", "furigana": "世界[せかい]で最[もっと]も古[ふる]い図書館[としょかん]が、この小[ちい]さな町[まち]にある。", "sentence_source": "generated"}, {"text": "最も好きな季節は秋です。", "target_word": "最も", "complexity_tier": "T2", "furigana": "最[もっと]も好[す]きな季節[きせつ]は秋[あき]です。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | 程度が他より最も高いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38009, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最も", "is_correct": true, "explanation": "「純粋な」を最上の程度で修飾し、文意に合う。"}, {"text": "もし", "is_correct": false, "explanation": "形は合うが、仮定を表す語で、程度を表す意味が合わない。"}, {"text": "決して", "is_correct": false, "explanation": "形は合うが、打ち消しと使う語で、意味が合わない。"}, {"text": "めったに", "is_correct": false, "explanation": "形は合うが、頻度が低いことを表す語で、意味が合わない。"}], "explanations": {"最も": "「純粋な」を最上の程度で修飾し、文意に合う。", "もし": "形は合うが、仮定を表す語で、程度を表す意味が合わない。", "決して": "形は合うが、打ち消しと使う語で、意味が合わない。", "めったに": "形は合うが、頻度が低いことを表す語で、意味が合わない。"}, "sentence_index": 0, "correct_answer": "最も"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は最も少し重い。", "explanation": "「最も」は最上を表すのに「少し」と並べると程度が矛盾する。"}, {"text": "兄は私より最も背が高い。", "explanation": "「より」は二者の比較で、三者以上の中の最上を表す「最も」とは合わない。"}, {"text": "りんごを最も三つ食べた。", "explanation": "「最も」は程度の最上を表し、数量の「三つ」を修飾する使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38009, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最も", "is_correct": true, "explanation": "「信頼できる」を最上の程度で修飾し、文意に合う。"}, {"text": "ちっとも", "is_correct": false, "explanation": "形は合うが、打ち消しと使う語で、意味が合わない。"}, {"text": "一向に", "is_correct": false, "explanation": "形は合うが、打ち消しと使う語で、意味が合わない。"}, {"text": "めったに", "is_correct": false, "explanation": "打ち消しと使う語で、肯定の文には合わない。"}], "explanations": {"最も": "「信頼できる」を最上の程度で修飾し、文意に合う。", "ちっとも": "形は合うが、打ち消しと使う語で、意味が合わない。", "一向に": "形は合うが、打ち消しと使う語で、意味が合わない。", "めったに": "打ち消しと使う語で、肯定の文には合わない。"}, "sentence_index": 6, "correct_answer": "最も"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は最も毎日、公園を走っている。", "explanation": "「最も」は頻度の「毎日」を修飾できず、程度の最上として使えない。"}, {"text": "私は最も先週、京都へ行った。", "explanation": "「最も」は時を表す語の前に置いて使う語ではなく、意味が通らない。"}, {"text": "彼女ほど最も親切な人はいない。", "explanation": "「ほど」で比べる文に「最も」を重ねると、最上の意味が二重になり誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38009, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山田さんは最もの親切な人だ。", "corrected_sentence": "山田さんは最も親切な人だ。", "error_description": "副詞の「最も」に「の」を付けて名詞のように使っている。「最も親切な」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38009, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一年の中で最もに寒いのは二月だ。", "corrected_sentence": "一年の中で最も寒いのは二月だ。", "error_description": "副詞の「最も」に不要な「に」が付いている。「最も寒い」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38010, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「願い」の直後に置き、「願いを聞く」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「願い」が聞く側になってしまい文が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すが、「聞く」は「願いに」とはつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「願いで聞いて」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「願い」の直後に置き、「願いを聞く」の目的語を示す。", "が": "「が」は主語を示すので、「願い」が聞く側になってしまい文が合わない。", "に": "「に」は相手や方向を示すが、「聞く」は「願いに」とはつながらない。", "で": "「で」は場所や手段を示すので、「願いで聞いて」は成り立たない。"}, "error_tags": {"が": "主語", "に": "相手・方向", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38010, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「願い」の直後の「は」が文の主題を示し、「～は…です」の文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「～は…です」の主題の文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、「願いの…です」の文は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主題の文には入らない。"}], "correct_answer": "は", "explanations": {"は": "「願い」の直後の「は」が文の主題を示し、「～は…です」の文に合う。", "を": "「を」は目的語を示すので、「～は…です」の主題の文には合わない。", "の": "「の」は所属や修飾を示すので、「願いの…です」の文は成り立たない。", "へ": "「へ」は方向を示すので、主題の文には入らない。"}, "error_tags": {"を": "対象", "の": "所属・修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38010, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "願いは、何かをしてほしいとか、こうなってほしいと思うことです。", "primary_collocate": null, "pronunciation": "ねがい", "ipa": "neɡai", "syllable_count": 3, "sentences": [{"text": "母の願いは、家族みんなが元気でいることです。", "target_word": "願い", "complexity_tier": "T3", "furigana": "母(はは)の願(ねが)いは、家族(かぞく)みんなが元気(げんき)でいることです。", "sentence_source": "generated"}, {"text": "友だちの願いを聞いて、いっしょに手伝いました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "友(とも)だちの願(ねが)いを聞(き)いて、いっしょに手伝(てつだ)いました。", "sentence_source": "generated"}, {"text": "先生はぼくの願いを聞いてくれて、宿題を少しへらしてくれました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "先生(せんせい)はぼくの願(ねが)いを聞(き)いてくれて、宿題(しゅくだい)を少(すこ)しへらしてくれました。", "sentence_source": "generated"}, {"text": "小さな願いでも、書いておくと忘れません。", "target_word": "願い", "complexity_tier": "T3", "furigana": "小(ちい)さな願(ねが)いでも、書(か)いておくと忘(わす)れません。", "sentence_source": "generated"}, {"text": "彼女の願いはかんたんで、ただ静かに本を読みたいだけです。", "target_word": "願い", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の願(ねが)いはかんたんで、ただ静(しず)かに本(ほん)を読(よ)みたいだけです。", "sentence_source": "generated"}, {"text": "犬を飼いたいという妹の願いは、ようやくかないました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "犬(いぬ)を飼(か)いたいという妹(いもうと)の願(ねが)いは、ようやくかないました。", "sentence_source": "generated"}, {"text": "社長は社員の願いを聞いて、休みを増やしました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "社長(しゃちょう)は社員(しゃいん)の願(ねが)いを聞(き)いて、休(やす)みを増(ふ)やしました。", "sentence_source": "generated"}, {"text": "私のひとつの願いは、早く日本語が上手になることです。", "target_word": "願い", "complexity_tier": "T3", "furigana": "私(わたし)のひとつの願(ねが)いは、早(はや)く日本語(にほんご)が上手(じょうず)になることです。", "sentence_source": "generated"}, {"text": "子どもの願いに、親は「もう少し待ってね」と答えました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "子(こ)どもの願(ねが)いに、親(おや)は「もう少(すこ)し待(ま)ってね」と答(こた)えました。", "sentence_source": "generated"}, {"text": "彼の願いは小さかったが、みんなが協力してくれた。", "target_word": "願い", "complexity_tier": "T3", "furigana": "彼(かれ)の願(ねが)いは小(ちい)さかったが、みんなが協力(きょうりょく)してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "願い", "label": "基本形"}, {"form": "お願い", "label": "丁寧形（接頭辞つき）"}], "register": "neutral", "sense_fingerprint": "everyday wish or request: something one wants to happen or wants someone to do", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: へらし (Zipf 1.54)']::text[], '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38010, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "願い", "is_correct": true, "explanation": "「家族みんなが元気でいてほしい」と望む意味で、母の望みを表す語として合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は書かれた文章のことで、「元気でいること」という望みの内容の主語にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、家族の望みを表す主語としては成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は金を入れる入れ物で、「元気でいること」の主語にはならない。"}], "explanations": {"願い": "「家族みんなが元気でいてほしい」と望む意味で、母の望みを表す語として合う。", "手紙": "手紙は書かれた文章のことで、「元気でいること」という望みの内容の主語にはならない。", "天気": "天気は空模様のことで、家族の望みを表す主語としては成り立たない。", "財布": "財布は金を入れる入れ物で、「元気でいること」の主語にはならない。"}, "sentence_index": 0, "correct_answer": "願い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の旅行の願いは、十万円までです。", "explanation": "ここは〈予算〉の意味。願いは心で望むことで、使える金額の上限は表さないので合わない。"}, {"text": "寒かったので、願いを着て外に出た。", "explanation": "ここは〈服〉の意味。着るのは服で、願いは身につけられないので合わない。"}, {"text": "鼻をかむために、願いを取り出した。", "explanation": "ここは〈ティッシュ〉の意味。取り出すのはティッシュで、願いは取り出せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38010, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "願い", "is_correct": true, "explanation": "「頼みごと・望み」の意味で、社員が望んだことを聞いて休みを増やした文に合う。"}, {"text": "写真", "is_correct": false, "explanation": "写真は画像のことで、社員から聞く対象にはならない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は場所のことで、聞く対象にはならない。"}, {"text": "絵画", "is_correct": false, "explanation": "絵画は作品のことで、社員の望みを聞く対象ではない。"}], "explanations": {"願い": "「頼みごと・望み」の意味で、社員が望んだことを聞いて休みを増やした文に合う。", "写真": "写真は画像のことで、社員から聞く対象にはならない。", "台所": "台所は場所のことで、聞く対象にはならない。", "絵画": "絵画は作品のことで、社員の望みを聞く対象ではない。"}, "sentence_index": 6, "correct_answer": "願い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で、東京までの願いを買った。", "explanation": "ここは〈切符〉の意味。乗車券は買うものだが、願いは買えないので合わない。"}, {"text": "一生懸命働いた分の願いを、もらった。", "explanation": "ここは〈報酬〉の意味。働いた対価として受け取るのは報酬で、願いをもらうとは言わない。"}, {"text": "カレーの願いを買いに行った。", "explanation": "ここは〈材料〉の意味。料理に使う食材を指すので、願いを買いに行くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38010, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は私の願いに聞いて、宿題を少しへらしてくれた。", "corrected_sentence": "先生は私の願いを聞いて、宿題を少しへらしてくれた。", "error_description": "「聞く」は「～を聞く」と助詞「を」をとる。「願いに」の「に」は誤りで、正しくは「願いを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38010, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社長は社員の願いを壊して、休みを一日増やしました。", "corrected_sentence": "社長は社員の願いを聞いて、休みを一日増やしました。", "error_description": "「願いを壊す」とは言わない。「願いを聞く」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38011, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「願い」の直後に置き、「願いをかける」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「願いがかける」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「願いでかけて」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、「願いのかけて」とは続けられない。"}], "correct_answer": "を", "explanations": {"を": "「願い」の直後に置き、「願いをかける」の目的語を示す。", "が": "「が」は主語を示すので、「願いがかける」は成り立たない。", "で": "「で」は場所や手段を示すので、「願いでかけて」は合わない。", "の": "「の」は所属や修飾を示すので、「願いのかけて」とは続けられない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38011, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「願い」の直後に置き、「願いを込める」の目的語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、「願いの込めている」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「願いへ込める」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や相手を示すので、「願いと込める」とは続かない。"}], "correct_answer": "を", "explanations": {"を": "「願い」の直後に置き、「願いを込める」の目的語を示す。", "の": "「の」は所属や修飾を示すので、「願いの込めている」とは続かない。", "へ": "「へ」は方向を示すので、「願いへ込める」は成り立たない。", "と": "「と」は引用や相手を示すので、「願いと込める」とは続かない。"}, "error_tags": {"の": "所属・修飾", "へ": "方向", "と": "引用・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38011, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "願いとは、心の中で強く望むこと。特に、現実には難しいことや、実現してほしいと思う内容を神や人に祈ったり期待したりする気持ちを指します。", "primary_collocate": null, "pronunciation": "ねがい", "ipa": "neɡai", "syllable_count": 3, "sentences": [{"text": "神社で、家族の健康を祈って願いを込めて手を合わせました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "神社(じんじゃ)で、家族(かぞく)の健康(けんこう)を祈(いの)って願(ねが)いを込(こ)めて手(て)を合(あ)わせました。", "sentence_source": "generated"}, {"text": "星に願いをかけて、夜空を見上げた。", "target_word": "願い", "complexity_tier": "T3", "furigana": "星(ほし)に願(ねが)いをかけて、夜空(よぞら)を見上(みあ)げた。", "sentence_source": "generated"}, {"text": "長い間の願いがかなって、涙が止まらなかった。", "target_word": "願い", "complexity_tier": "T3", "furigana": "長(なが)い間(あいだ)の願(ねが)いがかなって、涙(なみだ)が止(と)まらなかった。", "sentence_source": "generated"}, {"text": "七夕の短冊に、ひとつだけ願いを書きました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "七夕(たなばた)の短冊(たんざく)に、ひとつだけ願(ねが)いを書(か)きました。", "sentence_source": "generated"}, {"text": "病気の母が早く治るようにという願いは、神様に届いた。", "target_word": "願い", "complexity_tier": "T3", "furigana": "病気(びょうき)の母(はは)が早(はや)く治(なお)るようにという願(ねが)いは、神様(かみさま)に届(とど)いた。", "sentence_source": "generated"}, {"text": "流れ星に三回願いを言うと、かなうと言われている。", "target_word": "願い", "complexity_tier": "T3", "furigana": "流(なが)れ星(ぼし)に三回(さんかい)願(ねが)いを言(い)うと、かなうと言(い)われている。", "sentence_source": "generated"}, {"text": "平和への願いを込めて、子どもたちは千羽鶴を折った。", "target_word": "願い", "complexity_tier": "T3", "furigana": "平和(へいわ)への願(ねが)いを込(こ)めて、子(こ)どもたちは千羽鶴(せんばづる)を折(お)った。", "sentence_source": "generated"}, {"text": "祖父は毎朝、神棚に向かって、孫の合格という願いを込めている。", "target_word": "願い", "complexity_tier": "T3", "furigana": "祖父(そふ)は毎朝(まいあさ)、神棚(かみだな)に向(む)かって、孫(まご)の合格(ごうかく)という願(ねが)いを込(こ)めている。", "sentence_source": "generated"}, {"text": "「勝ちたい」という強い願いも届かず、試合は負けに終わった。", "target_word": "願い", "complexity_tier": "T3", "furigana": "「勝(か)ちたい」という強(つよ)い願(ねが)いも届(とど)かず、試合(しあい)は負(ま)けに終(お)わった。", "sentence_source": "generated"}, {"text": "新年の初詣で、今年の願いを神様に伝えました。", "target_word": "願い", "complexity_tier": "T3", "furigana": "新年(しんねん)の初詣(はつもうで)で、今年(ことし)の願(ねが)いを神様(かみさま)に伝(つた)えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "願い", "label": "基本形"}, {"form": "願いごと", "label": "複合語形"}], "register": "neutral", "sense_fingerprint": "strong heartfelt wish, often hard to realize, entrusted to gods, stars or prayer", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38011, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "願い", "is_correct": true, "explanation": "祈りや強い望みを心に込める対象として、「願いを込める」の形で合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、祈りを込める対象にはならない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち物で、祈りの気持ちを込める対象ではない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車券で、気持ちや祈りを込める対象ではない。"}], "explanations": {"願い": "祈りや強い望みを心に込める対象として、「願いを込める」の形で合う。", "天気": "天気は空模様のことで、祈りを込める対象にはならない。", "財布": "財布は持ち物で、祈りの気持ちを込める対象ではない。", "切符": "切符は乗車券で、気持ちや祈りを込める対象ではない。"}, "sentence_index": 0, "correct_answer": "願い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レストランで、店員に願いを注文した。", "explanation": "ここは〈注文〉の意味。料理や品物を頼むときに使い、願いを注文するとは言わない。"}, {"text": "風邪を治すために、願いを飲んだ。", "explanation": "ここは〈薬〉の意味。飲むのは薬で、望みや祈りは飲めないので合わない。"}, {"text": "道に迷ったので、願いを広げて場所を確かめた。", "explanation": "ここは〈地図〉の意味。広げて場所を確かめるのは地図で、願いは広げられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38011, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "願い", "is_correct": true, "explanation": "平和を祈る強い気持ちを込める対象として、「願いを込めて」の形で合う。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通信機器で、「込める」の対象にならない。"}, {"text": "写真", "is_correct": false, "explanation": "写真は画像のことで、平和を祈る気持ちを込める対象としては合わない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は場所のことで、気持ちを込める対象にはならない。"}], "explanations": {"願い": "平和を祈る強い気持ちを込める対象として、「願いを込めて」の形で合う。", "電話": "電話は通信機器で、「込める」の対象にならない。", "写真": "写真は画像のことで、平和を祈る気持ちを込める対象としては合わない。", "台所": "台所は場所のことで、気持ちを込める対象にはならない。"}, "sentence_index": 6, "correct_answer": "願い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英語の文章を、願いに訳した。", "explanation": "ここは〈翻訳〉の意味。文章を別の言語に直すもので、願いは訳す対象にならない。"}, {"text": "商品の願いを払った。", "explanation": "ここは〈代金〉の意味。払うのはお金で、願いを払うとは言わない。"}, {"text": "紙に絵を描いて、願いを塗った。", "explanation": "ここは〈絵の具〉の意味。塗るのは絵の具で、願いを塗ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38011, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "流れ星に願いを食べて、目をとじた。", "corrected_sentence": "流れ星に願いをかけて、目をとじた。", "error_description": "「願いを食べる」とは言わない。「願いをかける」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38011, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大会の前に、選手たちは勝利への願いを食べて、力強く走った。", "corrected_sentence": "大会の前に、選手たちは勝利への願いを込めて、力強く走った。", "error_description": "「願いを食べる」とは言わない。「願いを込める」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
