INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38012, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「元々」は、はじめのときのことです。たとえば、いまはちがうけど、むかしはそうだったというときに使います。", "primary_collocate": null, "pronunciation": "もともと", "ipa": "momotomo", "syllable_count": 4, "sentences": [{"text": "この町は、元々小さな漁村でした。", "target_word": "元々", "complexity_tier": "T3", "furigana": "この町(まち)は、元々(もともと)小(ちい)さな漁村(ぎょそん)でした。", "sentence_source": "generated"}, {"text": "私は元々野菜がきらいでしたが、今は毎日食べています。", "target_word": "元々", "complexity_tier": "T3", "furigana": "私(わたし)は元々(もともと)野菜(やさい)がきらいでしたが、今(いま)は毎日(まいにち)食(た)べています。", "sentence_source": "generated"}, {"text": "元々は静かな店だったのに、有名になって人が増えた。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)は静(しず)かな店(みせ)だったのに、有名(ゆうめい)になって人(ひと)が増(ふ)えた。", "sentence_source": "generated"}, {"text": "弟は元々泳げなかったが、練習してじょうずになった。", "target_word": "元々", "complexity_tier": "T3", "furigana": "弟(おとうと)は元々(もともと)泳(およ)げなかったが、練習(れんしゅう)してじょうずになった。", "sentence_source": "generated"}, {"text": "このかばんは元々父のものだったのを、私がもらいました。", "target_word": "元々", "complexity_tier": "T3", "furigana": "このかばんは元々(もともと)父(ちち)のものだったのを、私(わたし)がもらいました。", "sentence_source": "generated"}, {"text": "元々は医者になりたかったが、今は先生をしています。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)は医者(いしゃ)になりたかったが、今(いま)は先生(せんせい)をしています。", "sentence_source": "generated"}, {"text": "元々この道は広かったが、工事でせまくなった。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)この道(みち)は広(ひろ)かったが、工事(こうじ)でせまくなった。", "sentence_source": "generated"}, {"text": "彼女は元々北海道の人で、五年前に東京へ来ました。", "target_word": "元々", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は元々(もともと)北海道(ほっかいどう)の人(ひと)で、五年前(ごねんまえ)に東京(とうきょう)へ来(き)ました。", "sentence_source": "generated"}, {"text": "元々やせていた兄は、運動をやめて太ってしまった。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)やせていた兄(あに)は、運動(うんどう)をやめて太(ふと)ってしまった。", "sentence_source": "generated"}, {"text": "この公園は元々池だったと、祖母が話してくれた。", "target_word": "元々", "complexity_tier": "T3", "furigana": "この公園(こうえん)は元々(もともと)池(いけ)だったと、祖母(そぼ)が話(はな)してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "元々", "label": "基本形"}, {"form": "元々の", "label": "連体修飾（の）"}], "register": "neutral", "sense_fingerprint": "originally, at the start: the earlier state, in contrast with how things are now", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: せまく (Zipf 2.38)']::text[], '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38012, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元々", "is_correct": true, "explanation": "ここは〈はじめ・むかし〉の状態を表す意味。今とちがう昔の姿を述べる文に合う。"}, {"text": "全然", "is_correct": false, "explanation": "全然は打ち消しの語と一緒に使うので、肯定の文には入らない。"}, {"text": "最近", "is_correct": false, "explanation": "最近は近い時期を表すので、「むかしはそうだった」という文には合わない。"}, {"text": "毎年", "is_correct": false, "explanation": "毎年は繰り返しを表すので、むかしの状態を示す文には合わない。"}], "explanations": {"元々": "ここは〈はじめ・むかし〉の状態を表す意味。今とちがう昔の姿を述べる文に合う。", "全然": "全然は打ち消しの語と一緒に使うので、肯定の文には入らない。", "最近": "最近は近い時期を表すので、「むかしはそうだった」という文には合わない。", "毎年": "毎年は繰り返しを表すので、むかしの状態を示す文には合わない。"}, "sentence_index": 0, "correct_answer": "元々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の天気は、元々晴れるでしょう。", "explanation": "ここは〈たぶん〉の意味で使われているが、元々は昔の元の状態を表すので、未来の予報を推量する〈たぶん〉の意味にはならない。"}, {"text": "駅で元々先生に会って、びっくりした。", "explanation": "ここは〈偶然〉の意味。たまたま起きた一回の出来事を表すので、昔からの状態を述べる元々とは合わない。"}, {"text": "テストの結果が届いて、元々確認した。", "explanation": "ここは〈早速〉の意味。すぐに動くことを表すので、昔からの状態を表す元々とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38012, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元々", "is_correct": true, "explanation": "ここは〈むかしの状態〉の意味。今は変わった昔の道の様子を述べる文に合う。"}, {"text": "二度と", "is_correct": false, "explanation": "二度とは打ち消しの文で使うので、肯定の文には合わない。"}, {"text": "一度も", "is_correct": false, "explanation": "一度もは打ち消しの文で使うので、肯定の文には入らない。"}, {"text": "決して", "is_correct": false, "explanation": "決しては打ち消しの語と一緒に使うので、肯定の文には合わない。"}], "explanations": {"元々": "ここは〈むかしの状態〉の意味。今は変わった昔の道の様子を述べる文に合う。", "二度と": "二度とは打ち消しの文で使うので、肯定の文には合わない。", "一度も": "一度もは打ち消しの文で使うので、肯定の文には入らない。", "決して": "決しては打ち消しの語と一緒に使うので、肯定の文には合わない。"}, "sentence_index": 6, "correct_answer": "元々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "急に雨が降りだして、元々びっくりした。", "explanation": "ここは〈急に〉の意味。突然の変化を表すので、昔からの状態を表す元々とは合わない。"}, {"text": "電車が遅れて、元々ゆっくり手を振った。", "explanation": "ここは〈ゆっくり〉の意味。元々は昔からの状態を表すので、動作の速さを表す〈ゆっくり〉とは合わない。"}, {"text": "三回落ちた試験に、元々合格した。", "explanation": "ここは〈ついに〉の意味。長い努力の末の到達を表すので、昔からの状態を表す元々とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38012, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この島は元々が小さな漁村でした。", "corrected_sentence": "この島は元々小さな漁村でした。", "error_description": "「元々」に助詞「が」をつけるのは誤り。「元々小さな漁村でした」と続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38012, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は元々を古い倉庫だった。", "corrected_sentence": "この店は元々、古い倉庫だった。", "error_description": "「元々」の後に助詞「を」は続かない。正しくは「元々、」と読点で続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
