INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38013, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38013, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「元々」は、物事が最初に作られた目的や、もとの由来を表す副詞です。例文では、リサイクルマークが最初に作られたきっかけを説明しています。", "primary_collocate": null, "pronunciation": "もともと", "ipa": "momotomo", "syllable_count": 4, "sentences": [{"text": "リサイクルマークは、元々ごみを減らすために作られました。", "target_word": "元々", "complexity_tier": "T3", "furigana": "リサイクルマークは、元々(もともと)ごみを減(へ)らすために作(つく)られました。", "sentence_source": "generated"}, {"text": "この祭りは元々、春の豊作をいのる行事でした。", "target_word": "元々", "complexity_tier": "T3", "furigana": "この祭(まつ)りは元々(もともと)、春(はる)の豊作(ほうさく)をいのる行事(ぎょうじ)でした。", "sentence_source": "generated"}, {"text": "元々は薬として売られていたお茶が、今は飲み物として人気だ。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)は薬(くすり)として売(う)られていたお茶(ちゃ)が、今(いま)は飲(の)み物(もの)として人気(にんき)だ。", "sentence_source": "generated"}, {"text": "「サンドイッチ」という名前は、元々人の名前から来ている。", "target_word": "元々", "complexity_tier": "T3", "furigana": "「サンドイッチ」という名前(なまえ)は、元々(もともと)人(ひと)の名前(なまえ)から来(き)ている。", "sentence_source": "generated"}, {"text": "このマークは元々、安全をしめすために考えられたものです。", "target_word": "元々", "complexity_tier": "T3", "furigana": "このマークは元々(もともと)、安全(あんぜん)をしめすために考(かんが)えられたものです。", "sentence_source": "generated"}, {"text": "元々この道具は、魚をとるために使われていた。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)この道具(どうぐ)は、魚(さかな)をとるために使(つか)われていた。", "sentence_source": "generated"}, {"text": "カレンダーは元々、農作業の時期を知るためのものだった。", "target_word": "元々", "complexity_tier": "T3", "furigana": "カレンダーは元々(もともと)、農作業(のうさぎょう)の時期(じき)を知(し)るためのものだった。", "sentence_source": "generated"}, {"text": "元々このゲームは、教室で使う教材として開発された。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)このゲームは、教室(きょうしつ)で使(つか)う教材(きょうざい)として開発(かいはつ)された。", "sentence_source": "generated"}, {"text": "誕生日にケーキを食べる習慣は、元々ヨーロッパから広まったと言われている。", "target_word": "元々", "complexity_tier": "T3", "furigana": "誕生日(たんじょうび)にケーキを食(た)べる習慣(しゅうかん)は、元々(もともと)ヨーロッパから広(ひろ)まったと言(い)われている。", "sentence_source": "generated"}, {"text": "元々は研究のために作られたインターネットが、今は生活に欠かせない。", "target_word": "元々", "complexity_tier": "T3", "furigana": "元々(もともと)は研究(けんきゅう)のために作(つく)られたインターネットが、今(いま)は生活(せいかつ)に欠(か)かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "元々", "label": "基本形"}, {"form": "元々の", "label": "連体修飾（の）"}], "register": "neutral", "sense_fingerprint": "originally: explains the original purpose, origin or reason a thing was first made or began", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: いのる (Zipf 1.56)','sentence 4 above tier T2: contains vocabulary far above tier T2: しめす (Zipf 2.26)']::text[], '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38013, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元々", "is_correct": true, "explanation": "ここは〈もともとの目的・由来〉の意味。作られた本来の目的を述べる文に合う。"}, {"text": "決して", "is_correct": false, "explanation": "決しては打ち消しの語と一緒に使うので、肯定の文には入らない。"}, {"text": "一度も", "is_correct": false, "explanation": "一度もは打ち消しの語と一緒に使うので、肯定の文には合わない。"}, {"text": "二度と", "is_correct": false, "explanation": "二度とは打ち消しの語と一緒に使うので、目的を述べる肯定の文には入らない。"}], "explanations": {"元々": "ここは〈もともとの目的・由来〉の意味。作られた本来の目的を述べる文に合う。", "決して": "決しては打ち消しの語と一緒に使うので、肯定の文には入らない。", "一度も": "一度もは打ち消しの語と一緒に使うので、肯定の文には合わない。", "二度と": "二度とは打ち消しの語と一緒に使うので、目的を述べる肯定の文には入らない。"}, "sentence_index": 0, "correct_answer": "元々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の資料を元々届けてくれた。", "explanation": "ここは〈早速〉の意味。すぐに行う動作を表す。元々は由来や目的を述べる語なので、届けてくれた行為には合わない。"}, {"text": "駅で元々旧友に会った。", "explanation": "ここは〈偶然〉の意味。たまたまの出来事を表すので、由来や目的を述べる元々とは合わない。"}, {"text": "来年の計画は、元々決まるだろう。", "explanation": "ここは〈あらかじめ〉の意味。元々は以前からあった状態を表すので、来年の計画を前もって決める〈あらかじめ〉の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38013, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元々", "is_correct": true, "explanation": "ここは〈もともとの目的〉の意味。カレンダーが最初に作られた目的を述べる文に合う。"}, {"text": "全然", "is_correct": false, "explanation": "全然は打ち消しの語と一緒に使うので、肯定の文には入らない。"}, {"text": "無事に", "is_correct": false, "explanation": "無事には無事に終わるといった意味を表すので、目的を説明する文には合わない。"}, {"text": "最近", "is_correct": false, "explanation": "最近は近い時期を表すので、昔の目的を述べる文には合わない。"}], "explanations": {"元々": "ここは〈もともとの目的〉の意味。カレンダーが最初に作られた目的を述べる文に合う。", "全然": "全然は打ち消しの語と一緒に使うので、肯定の文には入らない。", "無事に": "無事には無事に終わるといった意味を表すので、目的を説明する文には合わない。", "最近": "最近は近い時期を表すので、昔の目的を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "元々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "急に大雨が降って、元々みんなが走った。", "explanation": "ここは〈急に〉の意味。突然の出来事を表すので、由来を表す元々とは合わない。"}, {"text": "雨が止むまで、元々待った。", "explanation": "ここは〈しばらく〉の意味。一時的な時間の長さを表すので、由来を表す元々とは合わない。"}, {"text": "たまに、元々昼ご飯を食べた。", "explanation": "ここは〈たまに〉の意味。ときどきの行動を表すので、由来を表す元々とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38013, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は元々で、痛みをやわらげるために作られた。", "corrected_sentence": "この薬は元々、痛みをやわらげるために作られた。", "error_description": "「元々」の後に助詞「で」は続かない。正しくは「元々、」と読点で続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38013, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "元々な目的は、ごみを減らすことだった。", "corrected_sentence": "元々の目的は、ごみを減らすことだった。", "error_description": "「元々」は「元々の～」の形で名詞を修飾する。「元々な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38014, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「話題が」は「なくなった」の主語で、ほかに話題がなくなったという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「話題を」は他動詞の目的語を示す。「なくなった」は自動詞なので「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「話題に」は場所や対象を示すが、「話題になくなった」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「話題へなくなった」は不自然で合わない。"}], "correct_answer": "が", "explanations": {"が": "「話題が」は「なくなった」の主語で、ほかに話題がなくなったという文に合う。", "を": "「話題を」は他動詞の目的語を示す。「なくなった」は自動詞なので「を」は合わない。", "に": "「話題に」は場所や対象を示すが、「話題になくなった」では意味が通らない。", "へ": "「へ」は方向を示すが、「話題へなくなった」は不自然で合わない。"}, "error_tags": {"を": "目的語", "に": "場所・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38014, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「話題を変える」の目的語で、話題を変えようとしたという文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「話題が」は主語になり、「話題が変えようとして」では主語と動詞が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「話題と変える」は相手や並列を示すが、ここでは意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「話題より変える」は比較の基準で、動作の対象を示せず合わない。"}], "correct_answer": "を", "explanations": {"を": "「話題を変える」の目的語で、話題を変えようとしたという文に合う。", "が": "「話題が」は主語になり、「話題が変えようとして」では主語と動詞が合わない。", "と": "「話題と変える」は相手や並列を示すが、ここでは意味が通らない。", "より": "「話題より変える」は比較の基準で、動作の対象を示せず合わない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38014, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなが話すことや考えることのテーマです。", "primary_collocate": null, "pronunciation": "わだい", "ipa": "wadai", "syllable_count": 3, "sentences": [{"text": "今日の会議の話題は新しい制度についてだ。", "target_word": "話題", "complexity_tier": "T3", "furigana": "今日(きょう)の会議(かいぎ)の話題(わだい)は新(あたら)しい制度(せいど)についてだ。", "sentence_source": "generated"}, {"text": "天気の話ばかりで、ほかに話題がなくなった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "天気(てんき)の話(はなし)ばかりで、ほかに話題(わだい)がなくなった。", "sentence_source": "generated"}, {"text": "昨日の試合は学校中の話題になった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "昨日(きのう)の試合(しあい)は学校中(がっこうじゅう)の話題(わだい)になった。", "sentence_source": "generated"}, {"text": "初めて会う人とは、共通の話題を探すのが大切だ。", "target_word": "話題", "complexity_tier": "T3", "furigana": "初(はじ)めて会(あ)う人(ひと)とは、共通(きょうつう)の話題(わだい)を探(さが)すのが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "弟は新しいゲームの話題で友だちと盛り上がっている。", "target_word": "話題", "complexity_tier": "T3", "furigana": "弟(おとうと)は新(あたら)しいゲームの話題(わだい)で友(とも)だちと盛(も)り上(あ)がっている。", "sentence_source": "generated"}, {"text": "食事中は暗い話題を避けたほうがいい。", "target_word": "話題", "complexity_tier": "T3", "furigana": "食事中(しょくじちゅう)は暗(くら)い話題(わだい)を避(さ)けたほうがいい。", "sentence_source": "generated"}, {"text": "彼女の結婚が社員の間で話題になった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の結婚(けっこん)が社員(しゃいん)の間(あいだ)で話題(わだい)になった。", "sentence_source": "generated"}, {"text": "話題を変えようとして、私は旅行の話を始めた。", "target_word": "話題", "complexity_tier": "T3", "furigana": "話題(わだい)を変(か)えようとして、私(わたし)は旅行(りょこう)の話(はなし)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "夏休みの話題が出ると、みんなの顔が明るくなった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "夏休(なつやす)みの話題(わだい)が出(で)ると、みんなの顔(かお)が明(あか)るくなった。", "sentence_source": "generated"}, {"text": "授業の前に先生が、最近のニュースを話題にした。", "target_word": "話題", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)の前(まえ)に先生(せんせい)が、最近(さいきん)のニュースを話題(わだい)にした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話題", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "会話で扱われるテーマ・話の題目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38014, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話題", "is_correct": true, "explanation": "会議で話し合われるテーマを表し、後半の「新しい制度についてだ」とつながる。"}, {"text": "会場", "is_correct": false, "explanation": "会議が行われる場所のことで、「新しい制度についてだ」という内容の説明とは合わない。"}, {"text": "出席者", "is_correct": false, "explanation": "会議に参加する人を指し、会議の中身を説明する文には合わない。"}, {"text": "時間", "is_correct": false, "explanation": "開始や終了の時刻を指し、扱う中身を説明する文には合わない。"}], "explanations": {"話題": "会議で話し合われるテーマを表し、後半の「新しい制度についてだ」とつながる。", "会場": "会議が行われる場所のことで、「新しい制度についてだ」という内容の説明とは合わない。", "出席者": "会議に参加する人を指し、会議の中身を説明する文には合わない。", "時間": "開始や終了の時刻を指し、扱う中身を説明する文には合わない。"}, "sentence_index": 0, "correct_answer": "話題"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の前に、話題を全員に配った。", "explanation": "ここは〈資料〉の意味。配るのは資料で、話題は人々が話すテーマを指すので合わない。"}, {"text": "メールの話題を「お礼」にして送った。", "explanation": "ここは〈件名〉の意味。メールの題は件名と言い、話題は人々が話すテーマを指すので合わない。"}, {"text": "駅までの話題は十分かかる。", "explanation": "ここは〈時間〉の意味。かかるのは時間で、話題は話すテーマを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38014, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話題", "is_correct": true, "explanation": "社員の間で広まって話し合われたという意味で、「〜になった」に合う。"}, {"text": "病気", "is_correct": false, "explanation": "体の不調を指し、結婚が社員の間で広まったという文脈には合わない。"}, {"text": "欠勤", "is_correct": false, "explanation": "仕事を休むことを指し、結婚が社員の間で何になったかという文には合わない。"}, {"text": "出勤", "is_correct": false, "explanation": "職場へ行くことを指し、結婚が社員の間で何になったかという文には合わない。"}], "explanations": {"話題": "社員の間で広まって話し合われたという意味で、「〜になった」に合う。", "病気": "体の不調を指し、結婚が社員の間で広まったという文脈には合わない。", "欠勤": "仕事を休むことを指し、結婚が社員の間で何になったかという文には合わない。", "出勤": "職場へ行くことを指し、結婚が社員の間で何になったかという文には合わない。"}, "sentence_index": 6, "correct_answer": "話題"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の話題は二十歳です。", "explanation": "ここは〈年齢〉の意味。何歳かは年齢と言い、話題は話すテーマを指すので合わない。"}, {"text": "この靴の話題は五千円です。", "explanation": "ここは〈価格〉の意味。値段は価格と言い、話題は話すテーマを指すので合わない。"}, {"text": "その話題は明日の午後に行われる。", "explanation": "ここは〈話し合い〉の意味。行われるのは話し合いで、話題は話す内容を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38014, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼が話題に変えようとしたので、会議は静かになった。", "corrected_sentence": "彼が話題を変えようとしたので、会議は静かになった。", "error_description": "助詞「に」が誤り。「話題を変える」と言うので「を」が正しく、「話題に変える」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38014, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その事件はすぐに話題になした。", "corrected_sentence": "その事件はすぐに話題になった。", "error_description": "動詞の選択の誤り。「話題になる」の過去形は「なった」で、「なした」は別の動詞「なす」の過去形なので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38015, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「話題に上る」は話の種として取り上げられるという決まった言い方で、ここで正しい。"}, {"text": "を", "is_correct": false, "explanation": "「話題を上る」は「上る」が自動詞なので「を」が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「話題で上る」は手段や場所を示す「で」が意味に合わず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「話題と上る」は相手や並列を示す「と」が合わず、不自然。"}], "correct_answer": "に", "explanations": {"に": "「話題に上る」は話の種として取り上げられるという決まった言い方で、ここで正しい。", "を": "「話題を上る」は「上る」が自動詞なので「を」が合わない。", "で": "「話題で上る」は手段や場所を示す「で」が意味に合わず、不自然。", "と": "「話題と上る」は相手や並列を示す「と」が合わず、不自然。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38015, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「話題になった」の「に」で、話題という状態に変わったことを表し正しい。"}, {"text": "が", "is_correct": false, "explanation": "「話題がなった」は助詞が合わず、「話題が」は主語になって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「話題へなった」は方向を示す「へ」が合わず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「話題よりなった」は比較の基準を示すが、ここでは意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「話題になった」の「に」で、話題という状態に変わったことを表し正しい。", "が": "「話題がなった」は助詞が合わず、「話題が」は主語になって不自然。", "へ": "「話題へなった」は方向を示す「へ」が合わず、不自然。", "より": "「話題よりなった」は比較の基準を示すが、ここでは意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38015, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々の間で話し合われる事柄や関心の中心となるテーマ。", "primary_collocate": null, "pronunciation": "わだい", "ipa": "wadai", "syllable_count": 3, "sentences": [{"text": "あの店のパンはテレビで紹介されて、町の話題になった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "あの店(みせ)のパンはテレビで紹介(しょうかい)されて、町(まち)の話題(わだい)になった。", "sentence_source": "generated"}, {"text": "親せきが集まると、いつも子どもの進学が話題に上る。", "target_word": "話題", "complexity_tier": "T3", "furigana": "親(しん)せきが集(あつ)まると、いつも子(こ)どもの進学(しんがく)が話題(わだい)に上(のぼ)る。", "sentence_source": "generated"}, {"text": "彼の新しい小説は発売前から話題だ。", "target_word": "話題", "complexity_tier": "T3", "furigana": "彼(かれ)の新(あたら)しい小説(しょうせつ)は発売前(はつばいまえ)から話題(わだい)だ。", "sentence_source": "generated"}, {"text": "駅前に大きな店ができ、近所の人々の話題をさらった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "駅前(えきまえ)に大(おお)きな店(みせ)ができ、近所(きんじょ)の人々(ひとびと)の話題(わだい)をさらった。", "sentence_source": "generated"}, {"text": "話題の映画を見に、週末に友だちと出かけた。", "target_word": "話題", "complexity_tier": "T3", "furigana": "話題(わだい)の映画(えいが)を見(み)に、週末(しゅうまつ)に友(とも)だちと出(で)かけた。", "sentence_source": "generated"}, {"text": "新しくできた水族館は、開館前から県内の話題になっていた。", "target_word": "話題", "complexity_tier": "T3", "furigana": "新(あたら)しくできた水族館(すいぞくかん)は、開館前(かいかんまえ)から県内(けんない)の話題(わだい)になっていた。", "sentence_source": "generated"}, {"text": "この映画は、公開後しばらく町中の話題を独占した。", "target_word": "話題", "complexity_tier": "T3", "furigana": "この映画(えいが)は、公開後(こうかいご)しばらく町中(まちじゅう)の話題(わだい)を独占(どくせん)した。", "sentence_source": "generated"}, {"text": "市長の発言が、インターネットで大きな話題になった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "市長(しちょう)の発言(はつげん)が、インターネットで大(おお)きな話題(わだい)になった。", "sentence_source": "generated"}, {"text": "選手の大記録がテレビで流れ、翌日の話題をさらった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "選手(せんしゅ)の大記録(だいきろく)がテレビで流(なが)れ、翌日(よくじつ)の話題(わだい)をさらった。", "sentence_source": "generated"}, {"text": "その番組の打ち切り騒動は、一晩で全国の話題になった。", "target_word": "話題", "complexity_tier": "T3", "furigana": "その番組(ばんぐみ)の打(う)ち切(き)り騒動(そうどう)は、一晩(ひとばん)で全国(ぜんこく)の話題(わだい)になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話題", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人々の関心を集めて語られる事柄・注目の的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: 親せき (Zipf 2.05)']::text[], '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38015, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話題", "is_correct": true, "explanation": "テレビで紹介されて町中の注目を集めたことを表し、「〜になった」に合う。"}, {"text": "定休日", "is_correct": false, "explanation": "店が休む日のことで、町の話題になったという文には合わない。"}, {"text": "店員", "is_correct": false, "explanation": "店で働く人のことで、「町の店員になった」では意味が通らない。"}, {"text": "駐車場", "is_correct": false, "explanation": "車を止める場所のことで、「町の駐車場になった」は合わない。"}], "explanations": {"話題": "テレビで紹介されて町中の注目を集めたことを表し、「〜になった」に合う。", "定休日": "店が休む日のことで、町の話題になったという文には合わない。", "店員": "店で働く人のことで、「町の店員になった」では意味が通らない。", "駐車場": "車を止める場所のことで、「町の駐車場になった」は合わない。"}, "sentence_index": 0, "correct_answer": "話題"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の話題は午前九時から始まる。", "explanation": "ここは〈営業時間〉の意味。店が開く時刻は営業時間と言い、話題は人々の注目を集める事柄を指すので合わない。"}, {"text": "店で話題を二つ注文した。", "explanation": "ここは〈料理〉の意味。店で注文するのは料理で、話題は人々の注目を集める事柄を指すので合わない。"}, {"text": "この店のパンは話題が安い。", "explanation": "ここは〈値段〉の意味。安い・高いと言うのは値段で、話題は人々の注目を集める事柄を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38015, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話題", "is_correct": true, "explanation": "町中の人々の注目を集めたという意味で、「〜を独占した」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、町中の注目を独占するという文には合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さのことで、注目を独占するという文には合わない。"}, {"text": "食器", "is_correct": false, "explanation": "料理を盛る器のことで、注目を独占するという文には合わない。"}], "explanations": {"話題": "町中の人々の注目を集めたという意味で、「〜を独占した」に合う。", "天気": "空模様のことで、町中の注目を独占するという文には合わない。", "体重": "体の重さのことで、注目を独占するという文には合わない。", "食器": "料理を盛る器のことで、注目を独占するという文には合わない。"}, "sentence_index": 6, "correct_answer": "話題"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝の話題は三十七度だった。", "explanation": "ここは〈体温〉の意味。体の温かさを表す語で、人々の注目の的を指す話題とは合わない。"}, {"text": "弟の話題は百五十センチだ。", "explanation": "ここは〈身長〉の意味。背の高さは身長と言い、話題は人々が関心を寄せる事柄を指すので合わない。"}, {"text": "その話題は明日行われる。", "explanation": "ここは〈話し合い〉の意味。行われるのは話し合いで、話題そのものが開催されるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38015, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その事故は町の話題を上った。", "corrected_sentence": "その事故は町の話題に上った。", "error_description": "助詞「を」が誤り。「話題に上る」と言うので「に」が正しく、「話題を上る」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38015, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この映画は公開前は話題になかった。", "corrected_sentence": "この映画は公開前は話題にならなかった。", "error_description": "動詞「なる」の否定形の誤り。「話題にならなかった」と言うので、「になかった」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38016, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「鳥の鳴き声に触発され」は、鳴き声がきっかけで心が動いたことを表す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「鳴き声を触発され」は目的語の形になり、きっかけを表せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「鳴き声へ触発され」は方向を表し、きっかけの意味に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「鳴き声の触発され」は文の形が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「鳥の鳴き声に触発され」は、鳴き声がきっかけで心が動いたことを表す正しい助詞。", "を": "「鳴き声を触発され」は目的語の形になり、きっかけを表せず不自然。", "へ": "「鳴き声へ触発され」は方向を表し、きっかけの意味に合わない。", "の": "「鳴き声の触発され」は文の形が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38016, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38016, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを見たり聞いたりして、心が動かされて、新しいことを思いつくこと。", "primary_collocate": null, "pronunciation": "しょくはつ", "ipa": "ɕokɯhatsɯ", "syllable_count": 4, "sentences": [{"text": "町で見かけた古い看板に触発されて、新しいデザインを思いついた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "町[まち]で見[み]かけた古[ふる]い看板[かんばん]に触発[しょくはつ]されて、新[あたら]しいデザインを思[おも]いついた。", "sentence_source": "generated"}, {"text": "鳥の鳴き声に触発され、作曲家は静かな曲の旋律を書きとめた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "鳥[とり]の鳴[な]き声[ごえ]に触発[しょくはつ]され、作曲家[さっきょくか]は静[しず]かな曲[きょく]の旋律[せんりつ]を書[か]きとめた。", "sentence_source": "generated"}, {"text": "外国の料理番組に触発されて、新しいスープを考えてみた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "外国[がいこく]の料理[りょうり]番組[ばんぐみ]に触発[しょくはつ]されて、新[あたら]しいスープを考[かんが]えてみた。", "sentence_source": "generated"}, {"text": "子どもの何気ない一言に触発され、先生は授業のやり方を変えることを思いついた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "子[こ]どもの何気[なにげ]ない一言[ひとこと]に触発[しょくはつ]され、先生[せんせい]は授業[じゅぎょう]のやり方[かた]を変[か]えることを思[おも]いついた。", "sentence_source": "generated"}, {"text": "美術館で見た模様に触発されたのか、彼女は新しい布の柄を描き始めた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で見[み]た模様[もよう]に触発[しょくはつ]されたのか、彼女[かのじょ]は新[あたら]しい布[ぬの]の柄[がら]を描[えが]き始[はじ]めた。", "sentence_source": "generated"}, {"text": "映画の一場面に触発されて、短い物語の筋を思いついた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "映画[えいが]の一場面[いちばめん]に触発[しょくはつ]されて、短[みじか]い物語[ものがたり]の筋[すじ]を思[おも]いついた。", "sentence_source": "generated"}, {"text": "雨音に触発されて、頭の中に新しい歌詞が浮かんだ。", "target_word": "触発", "complexity_tier": "T3", "furigana": "雨音[あまおと]に触発[しょくはつ]されて、頭[あたま]の中[なか]に新[あたら]しい歌詞[かし]が浮[う]かんだ。", "sentence_source": "generated"}, {"text": "古い写真を見て触発された父は、庭に池を作ろうと言い出した。", "target_word": "触発", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を見[み]て触発[しょくはつ]された父[ちち]は、庭[にわ]に池[いけ]を作[つく]ろうと言[い]い出[だ]した。", "sentence_source": "generated"}, {"text": "友だちの手作りの帽子に触発され、私も自分で作ってみようと思った。", "target_word": "触発", "complexity_tier": "T3", "furigana": "友[とも]だちの手作[てづく]りの帽子[ぼうし]に触発[しょくはつ]され、私[わたし]も自分[じぶん]で作[つく]ってみようと思[おも]った。", "sentence_source": "generated"}, {"text": "展示された模型に触発された学生たちは、次々に新しい案を出した。", "target_word": "触発", "complexity_tier": "T3", "furigana": "展示[てんじ]された模型[もけい]に触発[しょくはつ]された学生[がくせい]たちは、次々[つぎつぎ]に新[あたら]しい案[あん]を出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "触発", "label": "基本形（名詞）"}, {"form": "触発する", "label": "終止形"}, {"form": "触発される", "label": "受身形"}, {"form": "触発された", "label": "受身・過去形"}, {"form": "触発されて", "label": "受身・て形"}], "register": "neutral", "sense_fingerprint": "触発：見聞きしたことに心が動かされ、新しい発想を思いつくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38016, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "触発", "is_correct": true, "explanation": "「看板に触発されて」は、見たものをきっかけに新しい発想が浮かんだ意味に合う。"}, {"text": "融解", "is_correct": false, "explanation": "「看板に融解されて」は意味が通らず、発想の流れに合わない。"}, {"text": "摩耗", "is_correct": false, "explanation": "「看板に摩耗されて」は発想のきっかけを表せず、文脈に合わない。"}, {"text": "腐食", "is_correct": false, "explanation": "「看板に腐食されて」は意味が通らず、新しいデザインの発想と結びつかない。"}], "explanations": {"触発": "「看板に触発されて」は、見たものをきっかけに新しい発想が浮かんだ意味に合う。", "融解": "「看板に融解されて」は意味が通らず、発想の流れに合わない。", "摩耗": "「看板に摩耗されて」は発想のきっかけを表せず、文脈に合わない。", "腐食": "「看板に腐食されて」は意味が通らず、新しいデザインの発想と結びつかない。"}, "sentence_index": 0, "correct_answer": "触発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その訃報に触発されて、彼は涙を流した。", "explanation": "ここは〈悲しみ〉の意味。触発は見聞きして新しいことを思いつく意味で、涙を流す反応には使わない。"}, {"text": "強い香りが鼻を触発した。", "explanation": "ここは〈刺激〉の意味。感覚器官を強く働かせる場面に使い、見聞きして発想が浮かぶ〈触発〉とは合わない。"}, {"text": "過労は持病の悪化を触発することがある。", "explanation": "ここは〈誘発〉の意味。好ましくない症状を引き起こす場合に使い、新しい発想を思いつく〈触発〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38016, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触発", "is_correct": true, "explanation": "「雨音に触発されて」は、音をきっかけに歌詞が浮かんだ意味に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「雨音が翻訳されて」は意味が通らず、文脈に合わない。"}, {"text": "圧縮", "is_correct": false, "explanation": "「雨音が圧縮されて」は意味をなさず、歌詞が浮かぶ流れと結びつかない。"}, {"text": "濾過", "is_correct": false, "explanation": "「雨音が濾過されて」は不自然で、文の意味が通らない。"}], "explanations": {"触発": "「雨音に触発されて」は、音をきっかけに歌詞が浮かんだ意味に合う。", "翻訳": "「雨音が翻訳されて」は意味が通らず、文脈に合わない。", "圧縮": "「雨音が圧縮されて」は意味をなさず、歌詞が浮かぶ流れと結びつかない。", "濾過": "「雨音が濾過されて」は不自然で、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "触発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長引く雨は作物の生育に触発した。", "explanation": "ここは〈影響〉の意味。作物の生育のような物理的な変化には〈触発〉を使わず、影響と言う。"}, {"text": "名曲に触発されて、客席は静まり返った。", "explanation": "ここは〈感動〉の意味。心を揺さぶられて黙り込むことを指す語で、新しい発想を思いつく〈触発〉とは合わない。"}, {"text": "この金属は、酸に触発して激しく反応する。", "explanation": "ここは〈反応〉の意味。化学的な変化の場面に使う語で、見聞きしたものから発想が生まれる〈触発〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38016, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の古い石碑を触発されて、父は新しい句を詠んだ。", "corrected_sentence": "庭の古い石碑に触発されて、父は新しい句を詠んだ。", "error_description": "きっかけを表す助詞は「に」。「を」を使うと誤りになる。正しくは「に触発される」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38016, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の桜に触発したのか、母は絵を描き始めた。", "corrected_sentence": "庭の桜に触発されたのか、母は絵を描き始めた。", "error_description": "能動形「触発した」では、母が心を動かされた場面が表せない。母が心を動かされたことを表すには受身の「触発されたのか」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38017, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「体験に触発される」は、体験がきっかけとなって心が動くことを表す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「体験を触発される」は目的語の形になり、きっかけを表せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「体験へ触発される」は方向を表すため、きっかけの意味に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「体験の触発されて」は動詞が続かず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「体験に触発される」は、体験がきっかけとなって心が動くことを表す正しい助詞。", "を": "「体験を触発される」は目的語の形になり、きっかけを表せず不自然。", "へ": "「体験へ触発される」は方向を表すため、きっかけの意味に合わない。", "の": "「体験の触発されて」は動詞が続かず、文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38017, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「景色に触発された」は、景色がきっかけで心が動いたことを表す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「景色を触発された」は目的語の形になり、きっかけを表せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「景色と触発された」は並列の形になり、文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「景色より触発された」は比較の意味になり、文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「景色に触発された」は、景色がきっかけで心が動いたことを表す正しい助詞。", "を": "「景色を触発された」は目的語の形になり、きっかけを表せず不自然。", "と": "「景色と触発された」は並列の形になり、文が通らない。", "より": "「景色より触発された」は比較の意味になり、文脈に合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38017, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事に刺激を受けて、心や考えが動かされ、何かをしようという気持ちになること。", "primary_collocate": null, "pronunciation": "しょくはつ", "ipa": "ɕokɯhatsɯ", "syllable_count": 4, "sentences": [{"text": "先生の一言に触発された生徒が、学級の新しい取り組みを提案した。", "target_word": "触発", "complexity_tier": "T3", "furigana": "先生[せんせい]の一言[ひとこと]に触発[しょくはつ]された生徒[せいと]が、学級[がっきゅう]の新[あたら]しい取[と]り組[く]みを提案[ていあん]した。", "sentence_source": "generated"}, {"text": "友人の留学体験に触発されて、私も英語の勉強を始めた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の留学[りゅうがく]体験[たいけん]に触発[しょくはつ]されて、私[わたし]も英語[えいご]の勉強[べんきょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "先輩の力強い演奏に触発され、彼は毎日ギターを練習するようになった。", "target_word": "触発", "complexity_tier": "T3", "furigana": "先輩[せんぱい]の力強[ちからづよ]い演奏[えんそう]に触発[しょくはつ]され、彼[かれ]は毎日[まいにち]ギターを練習[れんしゅう]するようになった。", "sentence_source": "generated"}, {"text": "この小説に触発された若者が、自分の町の歴史を調べ始めた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]に触発[しょくはつ]された若者[わかもの]が、自分[じぶん]の町[まち]の歴史[れきし]を調[しら]べ始[はじ]めた。", "sentence_source": "generated"}, {"text": "隣のクラスの発表に触発されて、私たちも新しい企画を考えた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "隣[となり]のクラスの発表[はっぴょう]に触発[しょくはつ]されて、私[わたし]たちも新[あたら]しい企画[きかく]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "彼女は展覧会の絵に触発されて、帰るとすぐに筆をとった。", "target_word": "触発", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は展覧会[てんらんかい]の絵[え]に触発[しょくはつ]されて、帰[かえ]るとすぐに筆[ふで]をとった。", "sentence_source": "generated"}, {"text": "優勝した選手の姿に触発された後輩たちは、朝の練習を増やした。", "target_word": "触発", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]した選手[せんしゅ]の姿[すがた]に触発[しょくはつ]された後輩[こうはい]たちは、朝[あさ]の練習[れんしゅう]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "山の景色に触発されて、詩人は何十年ぶりに新しい詩を書いた。", "target_word": "触発", "complexity_tier": "T3", "furigana": "山[やま]の景色[けしき]に触発[しょくはつ]されて、詩人[しじん]は何十年[なんじゅうねん]ぶりに新[あたら]しい詩[し]を書[か]いた。", "sentence_source": "generated"}, {"text": "同僚の熱心な働きぶりに触発され、私も資格の勉強を決意した。", "target_word": "触発", "complexity_tier": "T3", "furigana": "同僚[どうりょう]の熱心[ねっしん]な働[はたら]きぶりに触発[しょくはつ]され、私[わたし]も資格[しかく]の勉強[べんきょう]を決意[けつい]した。", "sentence_source": "generated"}, {"text": "優れた作品に出会うと、人は触発されて自分も何かを創りたくなる。", "target_word": "触発", "complexity_tier": "T3", "furigana": "優[すぐ]れた作品[さくひん]に出会[であ]うと、人[ひと]は触発[しょくはつ]されて自分[じぶん]も何[なに]かを創[つく]りたくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "触発", "label": "基本形（名詞）"}, {"form": "触発する", "label": "終止形"}, {"form": "触発される", "label": "受身形"}, {"form": "触発された", "label": "受身・過去形"}, {"form": "触発されて", "label": "受身・て形"}], "register": "neutral", "sense_fingerprint": "触発：刺激を受けて心が動き、何かをしようという気持ちになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38017, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "触発", "is_correct": true, "explanation": "「一言に触発された」は、言葉をきっかけに心が動き、提案につながった意味に合う。"}, {"text": "破損", "is_correct": false, "explanation": "「一言に破損された」は意味が通らず、提案の流れに合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "「一言に乾燥された」は文脈に合わず、心が動く意味にならない。"}, {"text": "解剖", "is_correct": false, "explanation": "「一言に解剖された」は意味が通らず、提案の流れに合わない。"}], "explanations": {"触発": "「一言に触発された」は、言葉をきっかけに心が動き、提案につながった意味に合う。", "破損": "「一言に破損された」は意味が通らず、提案の流れに合わない。", "乾燥": "「一言に乾燥された」は文脈に合わず、心が動く意味にならない。", "解剖": "「一言に解剖された」は意味が通らず、提案の流れに合わない。"}, "sentence_index": 0, "correct_answer": "触発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その知らせに触発されて、彼は言葉を失った。", "explanation": "ここは〈驚き〉の意味。触発は心が動いて何かをしようという気持ちになることで、言葉を失うような反応には使わない。"}, {"text": "寝不足は頭痛を触発することがある。", "explanation": "ここは〈誘発〉の意味。触発は心が動いて何かをしようという気持ちになることで、病気や症状の引き金には使わない。"}, {"text": "この香辛料は舌を強く触発する。", "explanation": "ここは〈刺激〉の意味。感覚を強く働かせる場面で使う語で、心の動きを表す〈触発〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38017, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触発", "is_correct": true, "explanation": "「姿に触発された」は、見て心が動かされ行動に移った意味になり、文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「姿に翻訳された」は意味が通らず、文の流れに合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "「姿が採掘された」は成り立たず、文脈に合わない。"}, {"text": "圧縮", "is_correct": false, "explanation": "「姿に圧縮された」は意味をなさず、練習を増やした結果と結びつかない。"}], "explanations": {"触発": "「姿に触発された」は、見て心が動かされ行動に移った意味になり、文脈に合う。", "翻訳": "「姿に翻訳された」は意味が通らず、文の流れに合わない。", "採掘": "「姿が採掘された」は成り立たず、文脈に合わない。", "圧縮": "「姿に圧縮された」は意味をなさず、練習を増やした結果と結びつかない。"}, "sentence_index": 6, "correct_answer": "触発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜更かしは翌朝の体調に触発した。", "explanation": "ここは〈影響〉の意味。触発は心が動いて何かを始める意味で、体の調子の変化には使わない。"}, {"text": "彼女の涙に触発されて、皆は黙り込んだ。", "explanation": "ここは〈感動〉の意味。触発は心が動いて行動へ向かうことで、黙り込むだけの反応には使わない。"}, {"text": "その薬品は熱に触発して、激しく反応する。", "explanation": "ここは〈反応〉の意味。化学変化の場面で使う語で、心が動く意味の〈触発〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38017, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同期の成功談を触発されて、私も資格を取ろうと思った。", "corrected_sentence": "同期の成功談に触発されて、私も資格を取ろうと思った。", "error_description": "「触発される」のきっかけは助詞「に」で示す。「を」を使うと誤りになる。正しくは「に触発される」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38017, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部員の熱心な姿勢に触発れて、私も朝の練習を始めた。", "corrected_sentence": "部員の熱心な姿勢に触発されて、私も朝の練習を始めた。", "error_description": "受身の形が誤り。「触発れて」ではなく「触発されて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
