INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38018, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「デザイナーでなる」は文法的に成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ働きで、「デザイナーのなる」では動詞「なる」の対象を示せない。"}, {"text": "に", "is_correct": true, "explanation": "「〜になる」の「に」で、職業や状態に変わることを表す。ここで正しい。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「デザイナーより」は「なる」とつながらず、目標を示せない。"}], "correct_answer": "に", "explanations": {"で": "「で」は手段や場所を示すため、「デザイナーでなる」は文法的に成立しない。", "の": "「の」は名詞をつなぐ働きで、「デザイナーのなる」では動詞「なる」の対象を示せない。", "に": "「〜になる」の「に」で、職業や状態に変わることを表す。ここで正しい。", "より": "「より」は比較を表すため、「デザイナーより」は「なる」とつながらず、目標を示せない。"}, "error_tags": {"で": "手段", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38018, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを作る時に、かたちや色を考える人。", "primary_collocate": null, "pronunciation": "でざいなー", "ipa": "dezainaː", "syllable_count": 5, "sentences": [{"text": "母は洋服のデザイナーで、毎日新しい服の絵を描いている。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "母[はは]は洋服[ようふく]のデザイナーで、毎日[まいにち]新[あたら]しい服[ふく]の絵[え]を描[か]いている。", "sentence_source": "generated"}, {"text": "あのデザイナーは、赤と青をうまく組み合わせる。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "あのデザイナーは、赤[あか]と青[あお]をうまく組[く]み合[あ]わせる。", "sentence_source": "generated"}, {"text": "デザイナーが考えた車は、丸いかたちが特徴だ。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーが考[かんが]えた車[くるま]は、丸[まる]いかたちが特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "いとこは家具のデザイナーを目指して、美術大学に通っている。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "いとこは家具[かぐ]のデザイナーを目指[めざ]して、美術大学[びじゅつだいがく]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "デザイナーは、布の色を決めるために何枚も見本を並べた。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーは、布[ぬの]の色[いろ]を決[き]めるために何枚[なんまい]も見本[みほん]を並[なら]べた。", "sentence_source": "generated"}, {"text": "ファッションショーの後、デザイナーが舞台に出てあいさつした。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "ファッションショーの後[あと]、デザイナーが舞台[ぶたい]に出[で]てあいさつした。", "sentence_source": "generated"}, {"text": "この靴は、イタリアのデザイナーが作ったものだ。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "この靴[くつ]は、イタリアのデザイナーが作[つく]ったものだ。", "sentence_source": "generated"}, {"text": "デザイナーになるには、絵を描く力が必要だと思う。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーになるには、絵[え]を描[か]く力[ちから]が必要[ひつよう]だと思[おも]う。", "sentence_source": "generated"}, {"text": "おもちゃのデザイナーは、子どもが喜ぶかたちをいつも考えている。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "おもちゃのデザイナーは、子[こ]どもが喜[よろこ]ぶかたちをいつも考[かんが]えている。", "sentence_source": "generated"}, {"text": "そのデザイナーは、かばんの色を春らしい黄色にした。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "そのデザイナーは、かばんの色[いろ]を春[はる]らしい黄色[きいろ]にした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "デザイナー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "服・家具・道具などを作る時に、かたちや色を考える人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38018, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ピアニスト", "is_correct": false, "explanation": "ピアニストは楽器を演奏する人で、「洋服の」に続けて服の絵を描く職業としては合わない。"}, {"text": "デザイナー", "is_correct": true, "explanation": "「洋服の」に続き、服の形や色を考えて絵に描く人を表す。文の内容とも一致する。"}, {"text": "パイロット", "is_correct": false, "explanation": "パイロットは飛行機を操縦する人で、「洋服の」の後ろには入らず、服の絵を描く文脈とも合わない。"}, {"text": "パティシエ", "is_correct": false, "explanation": "パティシエは菓子を作る職人で、「洋服の」に続けると意味が通らず、服の絵を描く内容とも合わない。"}], "explanations": {"ピアニスト": "ピアニストは楽器を演奏する人で、「洋服の」に続けて服の絵を描く職業としては合わない。", "デザイナー": "「洋服の」に続き、服の形や色を考えて絵に描く人を表す。文の内容とも一致する。", "パイロット": "パイロットは飛行機を操縦する人で、「洋服の」の後ろには入らず、服の絵を描く文脈とも合わない。", "パティシエ": "パティシエは菓子を作る職人で、「洋服の」に続けると意味が通らず、服の絵を描く内容とも合わない。"}, "sentence_index": 0, "correct_answer": "デザイナー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この器は、デザイナーが一つずつ重さを量って不良品をはじいた。", "explanation": "ここは〈検査員〉の意味。重さを量って不良品を選び出すのは検査員の仕事で、形や色を考えるデザイナーの役割とは違うので合わない。"}, {"text": "この橋は、デザイナーが強度を計算して設計した。", "explanation": "ここは〈設計士〉の意味。橋の強度を計算して設計するのは構造の専門家で、形や色を考えるデザイナーの役割とは違う。"}, {"text": "彼女はデザイナーとして、新しい曲のメロディーを毎週書いている。", "explanation": "ここは〈作曲家〉の意味。デザイナーは曲を作る人ではないので、メロディーを書く職業として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38018, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漁師", "is_correct": false, "explanation": "漁師は海で魚を獲る人で、靴を作るという文脈とは合わない。"}, {"text": "デザイナー", "is_correct": true, "explanation": "「イタリアの」に続き、靴を作った人を表す。文の内容とも一致する。"}, {"text": "俳優", "is_correct": false, "explanation": "俳優は演技をする人で、「イタリアの俳優が作った」は靴の文脈として意味が通らない。"}, {"text": "歌手", "is_correct": false, "explanation": "歌手は歌を歌う人で、靴を作るという内容とは結びつかない。"}], "explanations": {"漁師": "漁師は海で魚を獲る人で、靴を作るという文脈とは合わない。", "デザイナー": "「イタリアの」に続き、靴を作った人を表す。文の内容とも一致する。", "俳優": "俳優は演技をする人で、「イタリアの俳優が作った」は靴の文脈として意味が通らない。", "歌手": "歌手は歌を歌う人で、靴を作るという内容とは結びつかない。"}, "sentence_index": 6, "correct_answer": "デザイナー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "そのデザイナーは、患者の傷口を縫って手術を終えた。", "explanation": "ここは〈医師〉の意味。傷口を縫い手術を行うのは医師の仕事で、形や色を考えるデザイナーの役割とは違うので合わない。"}, {"text": "そのデザイナーは、田んぼに入って稲を一本ずつ植えた。", "explanation": "ここは〈農家〉の意味。稲を植えて育てるのは農家の仕事で、デザイナーの役割とは違うので合わない。"}, {"text": "そのデザイナーは、法廷で被告人の罪を証明する証拠を並べた。", "explanation": "ここは〈検察官〉の意味。罪を証明するために証拠を並べて立証するのは検察官の仕事で、デザイナーの役割とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38018, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は洋服のデザイナーを、毎日新しい服の絵を描いている。", "corrected_sentence": "姉は洋服のデザイナーで、毎日新しい服の絵を描いている。", "error_description": "誤りは「デザイナー」に付く助詞。「デザイナーを」の「を」は目的語を示すが、ここでは「デザイナー」を目的語にする動詞がない。職業は断定の「で」で示すので「洋服のデザイナーで、」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38018, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このかばんは、イタリアのデザイナーを作ったものだ。", "corrected_sentence": "このかばんは、イタリアのデザイナーが作ったものだ。", "error_description": "誤りは「デザイナー」に付く助詞。作る人を表すには主語の「が」が正しい。「を」だと、デザイナーが作られる対象になってしまう。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38019, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『デザイナーとして』で役割や資格を表す『と』。正解。"}, {"text": "が", "is_correct": false, "explanation": "『デザイナーがして』では主語にならず、役割を表す形にならない。"}, {"text": "に", "is_correct": false, "explanation": "『デザイナーにして』は〈〜に任命する〉の形になり、役割の文にならない。"}, {"text": "から", "is_correct": false, "explanation": "『デザイナーからして』は起点の形で、役割を示せない。"}], "correct_answer": "と", "explanations": {"と": "『デザイナーとして』で役割や資格を表す『と』。正解。", "が": "『デザイナーがして』では主語にならず、役割を表す形にならない。", "に": "『デザイナーにして』は〈〜に任命する〉の形になり、役割の文にならない。", "から": "『デザイナーからして』は起点の形で、役割を示せない。"}, "error_tags": {"が": "主語", "に": "任命・到着", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38019, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38019, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "製品やポスターなどの見た目や使い方を考える仕事をする人。", "primary_collocate": null, "pronunciation": "でざいなー", "ipa": "dezainaː", "syllable_count": 5, "sentences": [{"text": "デザイナーの直感に頼って、ポスターの色を決めた。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーの直感[ちょっかん]に頼[たよ]って、ポスターの色[いろ]を決[き]めた。", "sentence_source": "generated"}, {"text": "姉はポスターを作るデザイナーとして、広告会社で働いている。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "姉[あね]はポスターを作[つく]るデザイナーとして、広告会社[こうこくがいしゃ]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "デザイナーは、使いやすさも考えてスマートフォンの形を決めた。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーは、使[つか]いやすさも考[かんが]えてスマートフォンの形[かたち]を決[き]めた。", "sentence_source": "generated"}, {"text": "有名なデザイナーが手がけた椅子は、座り心地がとてもよい。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "有名[ゆうめい]なデザイナーが手[て]がけた椅子[いす]は、座[すわ]り心地[ごこち]がとてもよい。", "sentence_source": "generated"}, {"text": "将来はゲームのデザイナーになりたいと思っている。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "将来[しょうらい]はゲームのデザイナーになりたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "デザイナーと打ち合わせをして、チラシの見た目を決めた。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーと打[う]ち合[あ]わせをして、チラシの見[み]た目[め]を決[き]めた。", "sentence_source": "generated"}, {"text": "その会社では、三人のデザイナーが新しい商品のパッケージを考えている。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]では、三人[さんにん]のデザイナーが新[あたら]しい商品[しょうひん]のパッケージを考[かんが]えている。", "sentence_source": "generated"}, {"text": "デザイナーは客の意見を聞いて、ロゴを何度も直した。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーは客[きゃく]の意見[いけん]を聞[き]いて、ロゴを何度[なんど]も直[なお]した。", "sentence_source": "generated"}, {"text": "彼はウェブサイトのデザイナーなので、画面の見やすさにこだわる。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "彼[かれ]はウェブサイトのデザイナーなので、画面[がめん]の見[み]やすさにこだわる。", "sentence_source": "generated"}, {"text": "デザイナーの仕事は、見た目をよくするだけでなく、使い方を考えることでもある。", "target_word": "デザイナー", "complexity_tier": "T3", "furigana": "デザイナーの仕事[しごと]は、見[み]た目[め]をよくするだけでなく、使[つか]い方[かた]を考[かんが]えることでもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "デザイナー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "製品・ポスター・画面などの見た目や使い方を考えることを職業とする人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38019, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "デザイナー", "is_correct": true, "explanation": "製品の見た目や使い方を考える人。『デザイナーの直感に頼る』と意味が合う。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す器具。直感の持ち主にはならず、『時計の直感』は不自然。"}, {"text": "水道局", "is_correct": false, "explanation": "水を供給する役所。直感を持つ主体として不自然で、文が成り立たない。"}, {"text": "郵便局", "is_correct": false, "explanation": "郵便を扱う施設。直感の主体にはならず、『郵便局の直感』は意味を成さない。"}], "explanations": {"デザイナー": "製品の見た目や使い方を考える人。『デザイナーの直感に頼る』と意味が合う。", "時計": "時刻を示す器具。直感の持ち主にはならず、『時計の直感』は不自然。", "水道局": "水を供給する役所。直感を持つ主体として不自然で、文が成り立たない。", "郵便局": "郵便を扱う施設。直感の主体にはならず、『郵便局の直感』は意味を成さない。"}, "sentence_index": 0, "correct_answer": "デザイナー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食後に、デザイナーを注文した。", "explanation": "ここは〈デザート（菓子）〉の意味と混同している。デザイナーは人の職業で、注文して食べるものではない。"}, {"text": "店で、ケーキをデザイナーの箱に入れた。", "explanation": "ここは〈箱（容器）〉の意味と混同している。デザイナーは人の職業で、物を入れる容器ではないので、この使い方はしない。"}, {"text": "風邪のときに、デザイナーを二錠飲んだ。", "explanation": "ここは〈錠剤の薬〉の意味と混同している。デザイナーは人の職業で、飲むものではないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38019, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "デザイナー", "is_correct": true, "explanation": "商品の見た目を考える人。『三人のデザイナーがパッケージを考える』は自然に通じる。"}, {"text": "段ボール", "is_correct": false, "explanation": "梱包に使う紙の箱。人として考える主体にはならず、文が成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "洗浄用品。パッケージを考える主体にはならず、意味が通らない。"}, {"text": "信号", "is_correct": false, "explanation": "交通の合図。商品のパッケージを考える主体にはならず、不自然。"}], "explanations": {"デザイナー": "商品の見た目を考える人。『三人のデザイナーがパッケージを考える』は自然に通じる。", "段ボール": "梱包に使う紙の箱。人として考える主体にはならず、文が成り立たない。", "石鹸": "洗浄用品。パッケージを考える主体にはならず、意味が通らない。", "信号": "交通の合図。商品のパッケージを考える主体にはならず、不自然。"}, "sentence_index": 6, "correct_answer": "デザイナー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "郵便局で、デザイナーが手紙を配った。", "explanation": "ここは〈郵便配達員〉の意味と混同している。デザイナーは見た目や使い方を考える仕事で、手紙を配る仕事ではない。"}, {"text": "ミシンのかわりに、デザイナーで服を縫った。", "explanation": "ここは〈ミシン（道具）〉の意味と混同している。デザイナーは道具ではなく職業なので、服を縫う手段にはならない。"}, {"text": "売店で、デザイナーを一つ買った。", "explanation": "ここは〈商品〉の意味と混同している。デザイナーは人の職業で、店で買える物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38019, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はデザイナーに、新しい服を考えている。", "corrected_sentence": "彼女はデザイナーとして、新しい服を考えている。", "error_description": "役割を表すには〈として〉を使う。〈に〉では役割を示せず、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38019, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は将来、デザイナーをなりたい。", "corrected_sentence": "私は将来、デザイナーになりたい。", "error_description": "『〜になる』は〈に〉を取る。〈を〉は動作の対象を表すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38020, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38020, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「輪になっている」で、状態の変化を表し正しい。"}, {"text": "を", "is_correct": false, "explanation": "「輪をなっている」は対象を示すが、「なる」は目的語を取らず合わない。"}, {"text": "で", "is_correct": false, "explanation": "「輪でなっている」は手段や場所を示し、なっている状態には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「輪へなっている」は方向を示すが、変化の結果を表す形としては不自然。"}], "correct_answer": "に", "explanations": {"に": "「輪になっている」で、状態の変化を表し正しい。", "を": "「輪をなっている」は対象を示すが、「なる」は目的語を取らず合わない。", "で": "「輪でなっている」は手段や場所を示し、なっている状態には合わない。", "へ": "「輪へなっている」は方向を示すが、変化の結果を表す形としては不自然。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38020, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まるい形で、まんなかにあながあいているもの。わっか。", "primary_collocate": null, "pronunciation": "わ", "ipa": "ɰa", "syllable_count": 1, "sentences": [{"text": "子どもたちはフラフープの輪を腰で回している。", "target_word": "輪", "complexity_tier": "T3", "furigana": "子(こ)どもたちはフラフープの輪(わ)を腰(こし)で回(まわ)している。", "sentence_source": "generated"}, {"text": "紙を細く切って、輪をつなげた飾りを作った。", "target_word": "輪", "complexity_tier": "T3", "furigana": "紙(かみ)を細(ほそ)く切(き)って、輪(わ)をつなげた飾(かざ)りを作(つく)った。", "sentence_source": "generated"}, {"text": "ひもの両端を結んで、大きな輪を作った。", "target_word": "輪", "complexity_tier": "T3", "furigana": "ひもの両端(りょうはし)を結(むす)んで、大(おお)きな輪(わ)を作(つく)った。", "sentence_source": "generated"}, {"text": "犬は飼い主が持った輪の中をジャンプして通り抜けた。", "target_word": "輪", "complexity_tier": "T3", "furigana": "犬(いぬ)は飼(か)い主(ぬし)が持(も)った輪(わ)の中(なか)をジャンプして通(とお)り抜(ぬ)けた。", "sentence_source": "generated"}, {"text": "サーカスの象が火の輪をくぐった。", "target_word": "輪", "complexity_tier": "T3", "furigana": "サーカスの象(ぞう)が火(ひ)の輪(わ)をくぐった。", "sentence_source": "generated"}, {"text": "子どもが金属の輪を指で回して遊んでいる。", "target_word": "輪", "complexity_tier": "T3", "furigana": "子(こ)どもが金属(きんぞく)の輪(わ)を指(ゆび)で回(まわ)して遊(あそ)んでいる。", "sentence_source": "generated"}, {"text": "彼は針金を曲げて、小さな輪を作って見せた。", "target_word": "輪", "complexity_tier": "T3", "furigana": "彼(かれ)は針金(はりがね)を曲(ま)げて、小(ちい)さな輪(わ)を作(つく)って見(み)せた。", "sentence_source": "generated"}, {"text": "電車のつり革は、手で持てる大きさの輪になっている。", "target_word": "輪", "complexity_tier": "T3", "furigana": "電車(でんしゃ)のつり革(かわ)は、手(て)で持(も)てる大(おお)きさの輪(わ)になっている。", "sentence_source": "generated"}, {"text": "赤いリボンで輪を作り、木の枝に結んで飾った。", "target_word": "輪", "complexity_tier": "T3", "furigana": "赤(あか)いリボンで輪(わ)を作(つく)り、木(き)の枝(えだ)に結(むす)んで飾(かざ)った。", "sentence_source": "generated"}, {"text": "鍵をなくさないよう、金属の輪に通して持ち歩く。", "target_word": "輪", "complexity_tier": "T3", "furigana": "鍵(かぎ)をなくさないよう、金属(きんぞく)の輪(わ)に通(とお)して持(も)ち歩(ある)く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輪", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "真ん中が空いた丸い形の物・わっか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38020, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輪", "is_correct": true, "explanation": "フラフープの円く空いた本体を指し、腰で回す対象に合う。"}, {"text": "色", "is_correct": false, "explanation": "物の色を表し、腰で回すという動作の対象にはならない。"}, {"text": "重さ", "is_correct": false, "explanation": "物の重い軽いを表し、回している物そのものを指さない。"}, {"text": "音", "is_correct": false, "explanation": "鳴る響きを指し、腰で回すという文には合わない。"}], "explanations": {"輪": "フラフープの円く空いた本体を指し、腰で回す対象に合う。", "色": "物の色を表し、腰で回すという動作の対象にはならない。", "重さ": "物の重い軽いを表し、回している物そのものを指さない。", "音": "鳴る響きを指し、腰で回すという文には合わない。"}, "sentence_index": 0, "correct_answer": "輪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母の輪は九十歳だ。", "explanation": "ここは〈年齢〉の意味。何歳かは年齢と言い、輪は円い物を指すので合わない。"}, {"text": "今日の輪は晴れだ。", "explanation": "ここは〈天気〉の意味。晴れや雨などの空の様子は天気と言い、輪は円い物を指すので合わない。"}, {"text": "その猫の輪はミケだ。", "explanation": "ここは〈名前〉の意味。猫につける呼び名は名前と言い、輪は円い物を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38020, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輪", "is_correct": true, "explanation": "針金で作る中が空いた円形の物で、作るという動作の目的語に合う。"}, {"text": "声", "is_correct": false, "explanation": "人が出す音の一つで、針金で作るという文には合わない。"}, {"text": "痛み", "is_correct": false, "explanation": "体の感覚を表し、作るという動詞とは合わない。"}, {"text": "目", "is_correct": false, "explanation": "見るための器官で、作るという動作の対象にはならない。"}], "explanations": {"輪": "針金で作る中が空いた円形の物で、作るという動作の目的語に合う。", "声": "人が出す音の一つで、針金で作るという文には合わない。", "痛み": "体の感覚を表し、作るという動詞とは合わない。", "目": "見るための器官で、作るという動作の対象にはならない。"}, "sentence_index": 6, "correct_answer": "輪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "室内の輪は二十五度だ。", "explanation": "ここは〈温度〉の意味。温かさを数字で表すのは温度と言い、輪は円い物を指すので合わない。"}, {"text": "始発の輪は朝五時だ。", "explanation": "ここは〈時刻〉の意味。何時かを表すのは時刻と言い、輪は円い物を指すので合わない。"}, {"text": "この部屋の輪は十畳だ。", "explanation": "ここは〈広さ〉の意味。部屋の面積は広さと言い、輪は円い物を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38020, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その子は、輪が指で回している。", "corrected_sentence": "その子は、輪を指で回している。", "error_description": "助詞「が」が誤り。「回す」の対象なので「輪を」が正しく、「輪が指で回す」は主語が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38020, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは紙テープで、大きな輪を食べて遊んだ。", "corrected_sentence": "子どもは紙テープで、大きな輪を作って遊んだ。", "error_description": "輪と組み合わせる動詞の誤り。輪は「作る」もので、「食べる」は合わないので「作って」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38021, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「輪を描いて」の目的語で、描く対象を示し正しい。"}, {"text": "が", "is_correct": false, "explanation": "「輪が描いて」は主語になり、描くという動作の対象と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「輪に描いて」は場所や相手を示すが、描く対象としては不自然。"}, {"text": "の", "is_correct": false, "explanation": "「輪の描いて」は修飾の形が合わず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「輪を描いて」の目的語で、描く対象を示し正しい。", "が": "「輪が描いて」は主語になり、描くという動作の対象と合わない。", "に": "「輪に描いて」は場所や相手を示すが、描く対象としては不自然。", "の": "「輪の描いて」は修飾の形が合わず、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
