INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38021, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "円の形をした図形や線、またはそのように見える円い形そのもの。", "primary_collocate": null, "pronunciation": "わ", "ipa": "ɰa", "syllable_count": 1, "sentences": [{"text": "先生は黒板にチョークで大きな輪を描いた。", "target_word": "輪", "complexity_tier": "T3", "furigana": "先生(せんせい)は黒板(こくばん)にチョークで大(おお)きな輪(わ)を描(か)いた。", "sentence_source": "generated"}, {"text": "地面に棒で輪を描いて、その中に入って遊んだ。", "target_word": "輪", "complexity_tier": "T3", "furigana": "地面(じめん)に棒(ぼう)で輪(わ)を描(か)いて、その中(なか)に入(はい)って遊(あそ)んだ。", "sentence_source": "generated"}, {"text": "土星のまわりには、氷でできた輪がある。", "target_word": "輪", "complexity_tier": "T3", "furigana": "土星(どせい)のまわりには、氷(こおり)でできた輪(わ)がある。", "sentence_source": "generated"}, {"text": "数学の授業で、コンパスを使って正確な輪を描いた。", "target_word": "輪", "complexity_tier": "T3", "furigana": "数学(すうがく)の授業(じゅぎょう)で、コンパスを使(つか)って正確(せいかく)な輪(わ)を描(か)いた。", "sentence_source": "generated"}, {"text": "月のまわりに白い輪が見えて、明日は雨だと母が言った。", "target_word": "輪", "complexity_tier": "T3", "furigana": "月(つき)のまわりに白(しろ)い輪(わ)が見(み)えて、明日(あした)は雨(あめ)だと母(はは)が言(い)った。", "sentence_source": "generated"}, {"text": "図の中の赤い輪は、集まる場所を示している。", "target_word": "輪", "complexity_tier": "T3", "furigana": "図(ず)の中(なか)の赤(あか)い輪(わ)は、集(あつ)まる場所(ばしょ)を示(しめ)している。", "sentence_source": "generated"}, {"text": "地図には、駅から半径一キロの輪が書いてある。", "target_word": "輪", "complexity_tier": "T3", "furigana": "地図(ちず)には、駅(えき)から半径(はんけい)一(いち)キロの輪(わ)が書(か)いてある。", "sentence_source": "generated"}, {"text": "紙に描いた輪の長さを、ひもを使って測った。", "target_word": "輪", "complexity_tier": "T3", "furigana": "紙(かみ)に描(か)いた輪(わ)の長(なが)さを、ひもを使(つか)って測(はか)った。", "sentence_source": "generated"}, {"text": "五つの輪が重なったマークは、世界的な大会のしるしだ。", "target_word": "輪", "complexity_tier": "T3", "furigana": "五(いつ)つの輪(わ)が重(かさ)なったマークは、世界的(せかいてき)な大会(たいかい)のしるしだ。", "sentence_source": "generated"}, {"text": "ガラスのコップを置くと、机に水の輪が残った。", "target_word": "輪", "complexity_tier": "T3", "furigana": "ガラスのコップを置(お)くと、机(つくえ)に水(みず)の輪(わ)が残(のこ)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輪", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "円形の図形・円く見える線や光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38021, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輪", "is_correct": true, "explanation": "チョークで描く円形の図形を指し、描いたという動作の対象に合う。"}, {"text": "重さ", "is_correct": false, "explanation": "物の重い軽いを表し、描くという動作の対象にはならない。"}, {"text": "匂い", "is_correct": false, "explanation": "鼻で感じる香りで、描くという動作とは合わない。"}, {"text": "温度", "is_correct": false, "explanation": "物の熱さ冷たさを表し、描いた対象にはならない。"}], "explanations": {"輪": "チョークで描く円形の図形を指し、描いたという動作の対象に合う。", "重さ": "物の重い軽いを表し、描くという動作の対象にはならない。", "匂い": "鼻で感じる香りで、描くという動作とは合わない。", "温度": "物の熱さ冷たさを表し、描いた対象にはならない。"}, "sentence_index": 0, "correct_answer": "輪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "授業の輪は五十分だ。", "explanation": "ここは〈時間〉の意味。授業の長さは時間と言い、輪は円形の物を指すので合わない。"}, {"text": "僕の輪は五十キロだ。", "explanation": "ここは〈体重〉の意味。体の重さは体重と言い、輪は円形の物を指すので合わない。"}, {"text": "この小説の輪は夏目漱石だ。", "explanation": "ここは〈作者〉の意味。書いた人は作者と言い、輪は円形の物を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38021, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輪", "is_correct": true, "explanation": "駅を中心にした円の範囲を表し、地図に書いてあるものとして合う。"}, {"text": "体温", "is_correct": false, "explanation": "体の温かさを表す語で、地図に書いてあるという文には合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを表す語で、地図に書いてあるものとは合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表す語で、地図に書いてあるという文には合わない。"}], "explanations": {"輪": "駅を中心にした円の範囲を表し、地図に書いてあるものとして合う。", "体温": "体の温かさを表す語で、地図に書いてあるという文には合わない。", "音量": "音の大きさを表す語で、地図に書いてあるものとは合わない。", "年齢": "人の年数を表す語で、地図に書いてあるという文には合わない。"}, "sentence_index": 6, "correct_answer": "輪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の輪は東京都です。", "explanation": "ここは〈住所〉の意味。住んでいる場所は住所と言い、輪は円形の物を指すので合わない。"}, {"text": "祖父の輪は八十歳だ。", "explanation": "ここは〈年齢〉の意味。何歳かは年齢と言い、輪は円形の物を指すので合わない。"}, {"text": "大会への輪を申し込んだ。", "explanation": "ここは〈参加〉の意味。大会に加わることは参加と言い、輪は円形の物を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38021, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は大きな輪が黒板に描いた。", "corrected_sentence": "先生は大きな輪を黒板に描いた。", "error_description": "助詞「が」が誤り。描く対象は「輪を」で、「輪が描いた」は主語になって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38021, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは砂浜に貝殻で輪を折った。", "corrected_sentence": "子どもは砂浜に貝殻で輪を描いた。", "error_description": "輪と組み合わせる動詞の誤り。図形の輪は「描く」もので、「折る」は合わないので「描いた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
