INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38022, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを少なくすることです。", "primary_collocate": null, "pronunciation": "りでゅーす", "ipa": "ɾidʲɯːsɯ", "syllable_count": 4, "sentences": [{"text": "ごみを出さないようにするリデュースが、大切だと習った。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "ごみを出[だ]さないようにするリデュースが、大切[たいせつ]だと習[なら]った。", "sentence_source": "generated"}, {"text": "買い物袋を持って行くのも、リデュースの一つだ。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "買[か]い物袋[ものぶくろ]を持[も]って行[い]くのも、リデュースの一[ひと]つだ。", "sentence_source": "generated"}, {"text": "必要な物だけ買うことが、リデュースにつながる。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "必要[ひつよう]な物[もの]だけ買[か]うことが、リデュースにつながる。", "sentence_source": "generated"}, {"text": "家族でリデュースを考え、食べ物をむだにしない。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "家族[かぞく]でリデュースを考[かんが]え、食[た]べ物[もの]をむだにしない。", "sentence_source": "generated"}, {"text": "リデュースとは、ものを少なくすることだ。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "リデュースとは、ものを少[すく]なくすることだ。", "sentence_source": "generated"}, {"text": "紙を使わないようにして、リデュースに取り組んだ。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "紙[かみ]を使[つか]わないようにして、リデュースに取[と]り組[く]んだ。", "sentence_source": "generated"}, {"text": "学校で、リデュース、リユース、リサイクルについて学んだ。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "学校[がっこう]で、リデュース、リユース、リサイクルについて学[まな]んだ。", "sentence_source": "generated"}, {"text": "包装の少ない商品を選ぶのは、リデュースの工夫だ。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "包装[ほうそう]の少[すく]ない商品[しょうひん]を選[えら]ぶのは、リデュースの工夫[くふう]だ。", "sentence_source": "generated"}, {"text": "リデュースのために、水筒を持ち歩いている。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "リデュースのために、水筒[すいとう]を持[も]ち歩[ある]いている。", "sentence_source": "generated"}, {"text": "私は毎日、リデュースを意識して、ものを買いすぎないようにしている。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "私[わたし]は毎日[まいにち]、リデュースを意識[いしき]して、ものを買[か]いすぎないようにしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リデュース", "label": "base"}, {"form": "リデュースする", "label": "suru verb"}], "register": "中立", "sense_fingerprint": "ものを少なくすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38022, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リデュース", "is_correct": true, "explanation": "ものを減らす取り組みを指し、ごみを出さない取り組みの主語として自然。"}, {"text": "バリアフリー", "is_correct": false, "explanation": "段差などをなくす取り組みを指し、ごみを出さない話には合わない。"}, {"text": "ダイエット", "is_correct": false, "explanation": "体重を減らすことを指し、ごみの話題には合わない。"}, {"text": "スキンシップ", "is_correct": false, "explanation": "人との身体的なふれ合いを指し、ごみの話題には合わない。"}], "explanations": {"リデュース": "ものを減らす取り組みを指し、ごみを出さない取り組みの主語として自然。", "バリアフリー": "段差などをなくす取り組みを指し、ごみを出さない話には合わない。", "ダイエット": "体重を減らすことを指し、ごみの話題には合わない。", "スキンシップ": "人との身体的なふれ合いを指し、ごみの話題には合わない。"}, "sentence_index": 0, "correct_answer": "リデュース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この実験では、酸素が電子を受け取ってリデュースされた。", "explanation": "ここは化学の〈還元〉の意味。ごみを減らす意味のリデュースとは別なので合わない。"}, {"text": "古い服を洗って、もう一度使うのがリデュースだ。", "explanation": "ここは〈リユース〉（再使用）の話。リデュースは使う量を減らすことなので合わない。"}, {"text": "空き缶を回収して資源として作り直す。それがリデュースだ。", "explanation": "ここは〈リサイクル〉（再資源化）の話。リデュースは量を減らすことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38022, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リデュース", "is_correct": true, "explanation": "並んでいる取り組みの一つとして、ものを減らす取り組みを指すので自然。"}, {"text": "ハイキング", "is_correct": false, "explanation": "山道を歩く行楽で、ごみ対策の取り組みの列挙には入らない。"}, {"text": "キャンプ", "is_correct": false, "explanation": "野外で泊まる行楽で、ごみ対策の列挙には合わない。"}, {"text": "ストレッチ", "is_correct": false, "explanation": "体をほぐす運動で、ごみ対策の取り組みの列挙には合わない。"}], "explanations": {"リデュース": "並んでいる取り組みの一つとして、ものを減らす取り組みを指すので自然。", "ハイキング": "山道を歩く行楽で、ごみ対策の取り組みの列挙には入らない。", "キャンプ": "野外で泊まる行楽で、ごみ対策の列挙には合わない。", "ストレッチ": "体をほぐす運動で、ごみ対策の取り組みの列挙には合わない。"}, "sentence_index": 6, "correct_answer": "リデュース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車は、リデュースで毎月借りている。", "explanation": "ここは〈リース〉（借りる契約）の意味。リデュースは量を減らす意味で、借り方には合わない。"}, {"text": "壊れた椅子を、リデュースして直した。", "explanation": "ここは壊れたものを直す〈修理〉の場面。リデュースは量を減らす取り組みの名前で、直す意味では使わないので合わない。"}, {"text": "古い家具は、業者にリデュースしてもらった。", "explanation": "ここは不用品の〈処分〉の話。リデュースは量を減らす取り組みの名前で、処分の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38022, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は毎日、リデュースに意識して、買い物をしている。", "corrected_sentence": "私は毎日、リデュースを意識して、買い物をしている。", "error_description": "「意識する」は目的語に「を」をとる。「リデュースに」は誤りで、正しくは「リデュースを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
