INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38023, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ごみや資源の使用量を減らすこと。", "primary_collocate": null, "pronunciation": "りでゅーす", "ipa": "ɾidʲɯːsɯ", "syllable_count": 4, "sentences": [{"text": "市はごみのリデュースを進めるため、新しい計画を発表した。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "市[し]はごみのリデュースを進[すす]めるため、新[あたら]しい計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "工場は、資源のリデュースに取り組んでいる。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "工場[こうじょう]は、資源[しげん]のリデュースに取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "水の使用量のリデュースが、今年の目標だ。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "水[みず]の使用量[しようりょう]のリデュースが、今年[ことし]の目標[もくひょう]だ。", "sentence_source": "generated"}, {"text": "リデュースの結果、ごみの量が去年の半分になった。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "リデュースの結果[けっか]、ごみの量[りょう]が去年[きょねん]の半分[はんぶん]になった。", "sentence_source": "generated"}, {"text": "店はレジ袋を有料にして、プラスチックのリデュースを目指した。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "店[みせ]はレジ袋[ぶくろ]を有料[ゆうりょう]にして、プラスチックのリデュースを目指[めざ]した。", "sentence_source": "generated"}, {"text": "会社は紙のリデュースのため、会議の資料をデータで配る。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は紙[かみ]のリデュースのため、会議[かいぎ]の資料[しりょう]をデータで配[くば]る。", "sentence_source": "generated"}, {"text": "食品ロスのリデュースには、家庭の協力が必要だ。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "食品[しょくひん]ロスのリデュースには、家庭[かてい]の協力[きょうりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "省エネで電気のリデュースを進める家が増えた。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "省[しょう]エネで電気[でんき]のリデュースを進[すす]める家[いえ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "製品の包装を薄くすることで、資源のリデュースができる。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "製品[せいひん]の包装[ほうそう]を薄[うす]くすることで、資源[しげん]のリデュースができる。", "sentence_source": "generated"}, {"text": "町内会は、ごみのリデュースの方法を話し合った。", "target_word": "リデュース", "complexity_tier": "T3", "furigana": "町内会[ちょうないかい]は、ごみのリデュースの方法[ほうほう]を話[はな]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リデュース", "label": "base"}, {"form": "リデュースする", "label": "suru verb"}], "register": "中立", "sense_fingerprint": "ごみや資源の使用量を減らす取り組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38023, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リデュース", "is_correct": true, "explanation": "ごみを減らす取り組みを指し、計画の対象として自然。"}, {"text": "ユーモア", "is_correct": false, "explanation": "面白さを表す言葉で、ごみの計画の対象には合わない。"}, {"text": "ワクチン", "is_correct": false, "explanation": "病気の予防薬を指し、ごみの計画の対象には合わない。"}, {"text": "スキンケア", "is_correct": false, "explanation": "肌の手入れを指し、ごみの計画の対象には合わない。"}], "explanations": {"リデュース": "ごみを減らす取り組みを指し、計画の対象として自然。", "ユーモア": "面白さを表す言葉で、ごみの計画の対象には合わない。", "ワクチン": "病気の予防薬を指し、ごみの計画の対象には合わない。", "スキンケア": "肌の手入れを指し、ごみの計画の対象には合わない。"}, "sentence_index": 0, "correct_answer": "リデュース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この実験では、銅イオンが電子を受け取ってリデュースされた。", "explanation": "ここは化学の〈還元〉の意味。ごみや資源の使用量を減らす意味のリデュースとは別なので合わない。"}, {"text": "古い家具を修理して、もう一度使うのがリデュースだ。", "explanation": "ここは〈リユース〉（再使用）の話。リデュースは使用量を減らすことなので合わない。"}, {"text": "使い終わったペットボトルを回収して、新しい容器に作り直す。それがリデュースだ。", "explanation": "ここは〈リサイクル〉（再資源化）の話。リデュースは量を減らす取り組みなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38023, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リデュース", "is_correct": true, "explanation": "食品ロスを減らす取り組みを指し、家庭の協力が必要な対象として自然。"}, {"text": "ハイキング", "is_correct": false, "explanation": "山道を歩く行楽で、食品ロスの取り組みを表す語としては合わない。"}, {"text": "キャンプ", "is_correct": false, "explanation": "野外で泊まる行楽で、食品ロスの取り組みを表す語としては合わない。"}, {"text": "ストレッチ", "is_correct": false, "explanation": "体をほぐす運動で、食品ロスの取り組みを表す語としては合わない。"}], "explanations": {"リデュース": "食品ロスを減らす取り組みを指し、家庭の協力が必要な対象として自然。", "ハイキング": "山道を歩く行楽で、食品ロスの取り組みを表す語としては合わない。", "キャンプ": "野外で泊まる行楽で、食品ロスの取り組みを表す語としては合わない。", "ストレッチ": "体をほぐす運動で、食品ロスの取り組みを表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "リデュース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車は、リデュースで毎月借りている。", "explanation": "ここは〈リース〉（借りる契約）の意味。リデュースは量を減らす意味で、借り方には合わない。"}, {"text": "不要になった本は、リデュースして図書館に寄付した。", "explanation": "ここは不用品を人に譲る〈譲渡〉の話。リデュースは量を減らす取り組みの名前で、譲る意味では使わないので合わない。"}, {"text": "古い冷蔵庫は、業者にリデュースしてもらった。", "explanation": "ここは不用品の〈処分〉の話。リデュースは量を減らす取り組みの名前で、処分の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38023, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は資源のリデュースに取り組みでいる。", "corrected_sentence": "市は資源のリデュースに取り組んでいる。", "error_description": "「取り組む」の活用は「取り組んでいる」。「取り組みでいる」は誤った活用で、正しくは「取り組んでいる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38023, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町内会は、ごみのリデュースを役立つ方法を話し合った。", "corrected_sentence": "町内会は、ごみのリデュースに役立つ方法を話し合った。", "error_description": "「役立つ」は対象を「に」で示す。「リデュースを」は誤りで、正しくは「リデュースに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38024, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38024, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞をつなぐ。「リユースの店」で正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「リユースで店に持っていった」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「リユースへ店に持っていった」は店の方向を表す形にならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「リユースから店に持っていった」では、店の説明にならない。"}], "correct_answer": "の", "explanations": {"の": "名詞をつなぐ。「リユースの店」で正しい。", "で": "手段や場所を示す。「リユースで店に持っていった」では意味が通らない。", "へ": "方向を示す。「リユースへ店に持っていった」は店の方向を表す形にならず不自然。", "から": "起点を示す。「リユースから店に持っていった」では、店の説明にならない。"}, "error_tags": {"で": "手段", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38024, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "もう一度使うことです。", "primary_collocate": null, "pronunciation": "りゆーす", "ipa": "ɾijuːsɯ", "syllable_count": 4, "sentences": [{"text": "このびんは洗えばまた使えるので、リユースできる。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "このびんは洗[あら]えばまた使[つか]えるので、リユースできる。", "sentence_source": "generated"}, {"text": "兄の服を、リユースして私が着ている。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "兄[あに]の服[ふく]を、リユースして私[わたし]が着[き]ている。", "sentence_source": "generated"}, {"text": "リユースは、もう一度使うことだ。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "リユースは、もう一度[いちど]使[つか]うことだ。", "sentence_source": "generated"}, {"text": "古い本をリユースするために、友達にあげた。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]をリユースするために、友達[ともだち]にあげた。", "sentence_source": "generated"}, {"text": "店では、リユースできる袋を売っている。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "店[みせ]では、リユースできる袋[ふくろ]を売[う]っている。", "sentence_source": "generated"}, {"text": "使い終わったランドセルをリユースして、弟が学校へ通っている。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わったランドセルをリユースして、弟[おとうと]が学校[がっこう]へ通[かよ]っている。", "sentence_source": "generated"}, {"text": "洗って使えるカップは、何度もリユースされる。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "洗[あら]って使[つか]えるカップは、何度[なんど]もリユースされる。", "sentence_source": "generated"}, {"text": "不要になった家具を、リユースの店に持っていった。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "不要[ふよう]になった家具[かぐ]を、リユースの店[みせ]に持[も]っていった。", "sentence_source": "generated"}, {"text": "リユースを増やせば、新しく買うものが減る。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "リユースを増[ふ]やせば、新[あたら]しく買[か]うものが減[へ]る。", "sentence_source": "generated"}, {"text": "この傘は修理して、リユースできるようにした。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "この傘[かさ]は修理[しゅうり]して、リユースできるようにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リユース", "label": "基本形"}, {"form": "リユースする", "label": "動詞形"}], "register": "neutral", "sense_fingerprint": "形を変えずにそのままもう一度使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38024, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リユース", "is_correct": true, "explanation": "形を変えずにもう一度使える、という文脈に合う。"}, {"text": "検索", "is_correct": false, "explanation": "情報を探す意味で、びんを使える状態にする文脈には合わない。"}, {"text": "予約", "is_correct": false, "explanation": "前もって取っておく意味で、洗ってまた使えることとは結びつかない。"}, {"text": "録音", "is_correct": false, "explanation": "音を記録する意味で、びんには当てはまらない。"}], "explanations": {"リユース": "形を変えずにもう一度使える、という文脈に合う。", "検索": "情報を探す意味で、びんを使える状態にする文脈には合わない。", "予約": "前もって取っておく意味で、洗ってまた使えることとは結びつかない。", "録音": "音を記録する意味で、びんには当てはまらない。"}, "sentence_index": 0, "correct_answer": "リユース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は温泉に行って、気分をリユースした。", "explanation": "ここは〈リフレッシュ（気分転換）〉の意味。リユースは品物をもう一度使うことで、気分を入れ替える意味では合わない。"}, {"text": "古い紙をリユースして、トイレットペーパーを作っている。", "explanation": "ここは〈リサイクル〉の意味。リユースは形を変えずに使うことで、材料から別の製品を作ることとは合わない。"}, {"text": "ごみは、燃えるものと燃えないものにリユースして出す。", "explanation": "ここは〈分別〉の意味。リユースは形を変えずにもう一度使うことで、種類ごとに仕分けることではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38024, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リユース", "is_correct": true, "explanation": "洗えば何度も使える、という文脈に合う。"}, {"text": "放送", "is_correct": false, "explanation": "電波などで伝える意味で、カップには当てはまらない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮る意味で、カップが何度も使われる流れとは合わない。"}, {"text": "点滅", "is_correct": false, "explanation": "明かりがついたり消えたりする意味で、使われることとは関係しない。"}], "explanations": {"リユース": "洗えば何度も使える、という文脈に合う。", "放送": "電波などで伝える意味で、カップには当てはまらない。", "撮影": "写真や映像を撮る意味で、カップが何度も使われる流れとは合わない。", "点滅": "明かりがついたり消えたりする意味で、使われることとは関係しない。"}, "sentence_index": 6, "correct_answer": "リユース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "使えなくなった傘は、リユースせずに、ごみとして捨てた。", "explanation": "ここは〈廃棄〉の意味。リユースは壊れていない品をそのままもう一度使うことで、捨てる意味ではない。"}, {"text": "古い掃除機は壊れたので、リユースした。", "explanation": "ここは〈買い替え〉の意味。リユースは壊れていない品を使い続けることで、壊れた品を新しく買い直すことではない。"}, {"text": "紙コップは、一度使ったらリユースして捨てる。", "explanation": "ここは〈使い捨て（一度で捨てる）〉の意味。リユースは何度も使うことで、一度で捨てる意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38024, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この容器は、何度もリユースできれる。", "corrected_sentence": "この容器は、何度もリユースできる。", "error_description": "「リユースできる」が正しい。「できれる」は可能の形の誤りで、「れ」が余計に入っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38024, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "使い終わった本は、リユースを店に持っていこう。", "corrected_sentence": "使い終わった本は、リユースの店に持っていこう。", "error_description": "「リユースの店」の「の」が正しい。「を」は目的語で、店を説明する名詞のつながりにならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
