INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38025, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "一度使ったものを、捨てずにまた別の目的で使うこと。", "primary_collocate": null, "pronunciation": "りゆーす", "ipa": "ɾijuːsɯ", "syllable_count": 4, "sentences": [{"text": "古いジーンズをリユースして、かばんを作った。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "古[ふる]いジーンズをリユースして、かばんを作[つく]った。", "sentence_source": "generated"}, {"text": "空き箱を捨てずに、リユースして小物入れにしている。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "空[あ]き箱[ばこ]を捨[す]てずに、リユースして小物入[こものい]れにしている。", "sentence_source": "generated"}, {"text": "お菓子の缶をリユースして、針と糸を入れる箱にした。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "お菓子[かし]の缶[かん]をリユースして、針[はり]と糸[いと]を入[い]れる箱[はこ]にした。", "sentence_source": "generated"}, {"text": "古いタオルをリユースして、掃除に使うことにした。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "古[ふる]いタオルをリユースして、掃除[そうじ]に使[つか]うことにした。", "sentence_source": "generated"}, {"text": "捨てるはずだった木の板をリユースして、本棚を作った。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "捨[す]てるはずだった木[き]の板[いた]をリユースして、本棚[ほんだな]を作[つく]った。", "sentence_source": "generated"}, {"text": "ジャムのびんをリユースして、花びんにしている。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "ジャムのびんをリユースして、花[はな]びんにしている。", "sentence_source": "generated"}, {"text": "着られなくなった服をリユースして、ぞうきんにする。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "着[き]られなくなった服[ふく]をリユースして、ぞうきんにする。", "sentence_source": "generated"}, {"text": "家では、牛乳パックをリユースして、植木鉢の代わりに使う。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "家[いえ]では、牛乳[ぎゅうにゅう]パックをリユースして、植木鉢[うえきばち]の代[か]わりに使[つか]う。", "sentence_source": "generated"}, {"text": "古い雑誌をリユースして、おもしろい形の箱を作った。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "古[ふる]い雑誌[ざっし]をリユースして、おもしろい形[かたち]の箱[はこ]を作[つく]った。", "sentence_source": "generated"}, {"text": "大きな瓶を捨てずにリユースして、水入れにした。", "target_word": "リユース", "complexity_tier": "T3", "furigana": "大[おお]きな瓶[びん]を捨[す]てずにリユースして、水入[みずい]れにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リユース", "label": "基本形"}, {"form": "リユースする", "label": "動詞形"}], "register": "neutral", "sense_fingerprint": "使い終えたものを捨てず別の用途にまた使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38025, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リユース", "is_correct": true, "explanation": "捨てずに別の目的で使い直す、という文脈に合う。"}, {"text": "投稿", "is_correct": false, "explanation": "ネットなどに載せる意味で、ジーンズからかばんを作る流れには合わない。"}, {"text": "申請", "is_correct": false, "explanation": "手続きを頼む意味で、ジーンズが別の物に変わる流れとは関係しない。"}, {"text": "送信", "is_correct": false, "explanation": "相手に送る意味で、ジーンズを加工する文脈には合わない。"}], "explanations": {"リユース": "捨てずに別の目的で使い直す、という文脈に合う。", "投稿": "ネットなどに載せる意味で、ジーンズからかばんを作る流れには合わない。", "申請": "手続きを頼む意味で、ジーンズが別の物に変わる流れとは関係しない。", "送信": "相手に送る意味で、ジーンズを加工する文脈には合わない。"}, "sentence_index": 0, "correct_answer": "リユース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い箱は、リユースして、棚にしまっておいた。", "explanation": "ここは〈保管（しまっておく）〉の意味。リユースは一度使ったものを別の目的で使うことで、しまっておく意味ではない。"}, {"text": "使わなくなったタオルは、リユースで処分した。", "explanation": "ここは〈廃棄（捨てる）〉の意味。リユースは一度使ったものを捨てずに別の目的で使うことで、処分する意味ではない。"}, {"text": "古いラジオは壊れたので、リユースした。", "explanation": "ここは〈買い替え〉の意味。リユースは捨てずに使い道を変えることで、新品に替える意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38025, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リユース", "is_correct": true, "explanation": "捨てずに別の用途で使い直す、という流れに合う。"}, {"text": "精算", "is_correct": false, "explanation": "支払いを済ませる意味で、服をぞうきんにする文脈と関係しない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味で、服の使い道とは関係しない。"}, {"text": "鑑賞", "is_correct": false, "explanation": "見て楽しむ意味で、ぞうきんにする流れには合わない。"}], "explanations": {"リユース": "捨てずに別の用途で使い直す、という流れに合う。", "精算": "支払いを済ませる意味で、服をぞうきんにする文脈と関係しない。", "施錠": "鍵をかける意味で、服の使い道とは関係しない。", "鑑賞": "見て楽しむ意味で、ぞうきんにする流れには合わない。"}, "sentence_index": 6, "correct_answer": "リユース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ごみは、紙とびんにリユースして出す。", "explanation": "ここは〈分別〉の意味。リユースは捨てずに使い道を変えることで、種類ごとに仕分けることではない。"}, {"text": "借りた本は、図書館にリユースした。", "explanation": "ここは〈返却〉の意味。リユースは別の目的で使うことで、借り物を持ち主へ戻す意味ではない。"}, {"text": "古いシャツは、リユースするのをやめて、ごみ袋に入れて捨てた。", "explanation": "ここは〈廃棄〉の意味。リユースは捨てずに使い道を変えることで、捨てる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38025, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "使い終わった缶は、リユースを小物入れにしよう。", "corrected_sentence": "使い終わった缶は、リユースして小物入れにしよう。", "error_description": "「リユースして小物入れにしよう」が正しい。「を」だと目的語にしかならず、「小物入れにする」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38025, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "使い終わった瓶は、リユースできれて、花びんになる。", "corrected_sentence": "使い終わった瓶は、リユースできて、花びんになる。", "error_description": "「できて」の形が正しい。「できれて」は可能の形の誤りで、「れ」が余計に入っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38026, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「入る」の到達点は「に」で示すので、「目に入ってしまった」が正しい形です。"}, {"text": "が", "is_correct": false, "explanation": "「目が入ってしまった」では目が主語になり、ごみが入るという文の流れに合いません。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は「を」を取らないので、「目を入ってしまった」は誤りです。"}, {"text": "で", "is_correct": false, "explanation": "「目で入る」は手段を表すことになり、ごみが目に入るという意味になりません。"}], "correct_answer": "に", "explanations": {"に": "「入る」の到達点は「に」で示すので、「目に入ってしまった」が正しい形です。", "が": "「目が入ってしまった」では目が主語になり、ごみが入るという文の流れに合いません。", "を": "「入る」は「を」を取らないので、「目を入ってしまった」は誤りです。", "で": "「目で入る」は手段を表すことになり、ごみが目に入るという意味になりません。"}, "error_tags": {"が": "subject", "を": "object", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38026, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「目に悪い」の目は影響を受ける対象なので、「に」で示します。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、悪いという状態の対象には使えません。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「目と悪い」は成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「目から悪い」は影響の対象として不自然です。"}], "correct_answer": "に", "explanations": {"に": "「目に悪い」の目は影響を受ける対象なので、「に」で示します。", "へ": "「へ」は方向を表すので、悪いという状態の対象には使えません。", "と": "「と」は並列や相手を示すので、「目と悪い」は成り立ちません。", "から": "「から」は起点を表すので、「目から悪い」は影響の対象として不自然です。"}, "error_tags": {"へ": "direction", "と": "partner", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38026, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを見るときに使う、顔の一部です。", "primary_collocate": null, "pronunciation": "め", "ipa": "me", "syllable_count": 1, "sentences": [{"text": "夜遅くまで本を読んで、目が疲れた。", "target_word": "目", "complexity_tier": "T3", "furigana": "夜遅(よるおそ)くまで本(ほん)を読(よ)んで、目(め)が疲(つか)れた。", "sentence_source": "generated"}, {"text": "風が強くて、ごみが目に入ってしまった。", "target_word": "目", "complexity_tier": "T3", "furigana": "風(かぜ)が強(つよ)くて、ごみが目(め)に入(はい)ってしまった。", "sentence_source": "generated"}, {"text": "赤ちゃんは大きな目で私をじっと見ている。", "target_word": "目", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんは大(おお)きな目(め)で私(わたし)をじっと見(み)ている。", "sentence_source": "generated"}, {"text": "眠いときは、少し目を閉じて休むといい。", "target_word": "目", "complexity_tier": "T3", "furigana": "眠(ねむ)いときは、少(すこ)し目(め)を閉(と)じて休(やす)むといい。", "sentence_source": "generated"}, {"text": "犬は鼻がよいが、人間ほど目はよくないそうだ。", "target_word": "目", "complexity_tier": "T3", "furigana": "犬(いぬ)は鼻(はな)がよいが、人間(にんげん)ほど目(め)はよくないそうだ。", "sentence_source": "generated"}, {"text": "泣きすぎて、目が赤くなった。", "target_word": "目", "complexity_tier": "T3", "furigana": "泣(な)きすぎて、目(め)が赤(あか)くなった。", "sentence_source": "generated"}, {"text": "祖母は年をとって、目が悪くなった。", "target_word": "目", "complexity_tier": "T3", "furigana": "祖母(そぼ)は年(とし)をとって、目(め)が悪(わる)くなった。", "sentence_source": "generated"}, {"text": "画面を長く見ると目に悪いので、少し休んだ。", "target_word": "目", "complexity_tier": "T3", "furigana": "画面(がめん)を長(なが)く見(み)ると目(め)に悪(わる)いので、少(すこ)し休(やす)んだ。", "sentence_source": "generated"}, {"text": "彼女は青い目をした、かわいい猫を飼っている。", "target_word": "目", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は青(あお)い目(め)をした、かわいい猫(ねこ)を飼(か)っている。", "sentence_source": "generated"}, {"text": "眼科で目の検査を受けて、眼鏡を作った。", "target_word": "目", "complexity_tier": "T3", "furigana": "眼科(がんか)で目(め)の検査(けんさ)を受(う)けて、眼鏡(めがね)を作(つく)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "目", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "見るための顔の器官・眼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '988f2522-473b-4ccc-b4c2-00efbda94e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38026, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目", "is_correct": true, "explanation": "読書で疲れるのは目。「目が疲れた」は自然な表現です。"}, {"text": "鼻", "is_correct": false, "explanation": "読書の疲れを感じる部位ではありません。「鼻が疲れた」は不自然です。"}, {"text": "唇", "is_correct": false, "explanation": "唇は読書で疲れる部位ではなく、「唇が疲れた」は通じません。"}, {"text": "額", "is_correct": false, "explanation": "「額が疲れた」とは言いません。長時間の読書で疲れるのは目です。"}], "explanations": {"目": "読書で疲れるのは目。「目が疲れた」は自然な表現です。", "鼻": "読書の疲れを感じる部位ではありません。「鼻が疲れた」は不自然です。", "唇": "唇は読書で疲れる部位ではなく、「唇が疲れた」は通じません。", "額": "「額が疲れた」とは言いません。長時間の読書で疲れるのは目です。"}, "sentence_index": 0, "correct_answer": "目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説は目が分厚くて、読み終わるのに一週間かかった。", "explanation": "ここは〈ページの厚さ〉の意味です。目は見る器官なので、本の厚みを目で表すことはできません。"}, {"text": "このラーメンは目が濃くて、とても美味しい。", "explanation": "ここは〈味〉の意味です。目は見る器官なので、味の濃さを表すことはできません。"}, {"text": "この布は目が粗くて、風が通りやすい。", "explanation": "ここは〈織り目〉の意味です。見る器官の目ではないので、この文の目は教える語義とは別の語義です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38026, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目", "is_correct": true, "explanation": "年をとって悪くなるのは視力で、「目が悪くなった」は自然な表現です。"}, {"text": "指", "is_correct": false, "explanation": "年齢によって「指が悪くなった」とは言わず、この文の内容には合いません。"}, {"text": "爪", "is_correct": false, "explanation": "「爪が悪くなった」は文脈に合わず、加齢の変化を表す語としては不自然です。"}, {"text": "尻", "is_correct": false, "explanation": "「尻が悪くなった」は加齢による変化の表現として不自然です。"}], "explanations": {"目": "年をとって悪くなるのは視力で、「目が悪くなった」は自然な表現です。", "指": "年齢によって「指が悪くなった」とは言わず、この文の内容には合いません。", "爪": "「爪が悪くなった」は文脈に合わず、加齢の変化を表す語としては不自然です。", "尻": "「尻が悪くなった」は加齢による変化の表現として不自然です。"}, "sentence_index": 6, "correct_answer": "目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この看板は目が大きくて、遠くからでも読める。", "explanation": "ここは〈文字〉の意味です。見る器官の目は、文字の大きさを表すことはできません。"}, {"text": "寒い夜、目をすませると、遠くの鐘の音が聞こえた。", "explanation": "ここは〈耳をすます〉（注意して聴く）の意味です。「目をすます」とは言わないので、目はこの文に合いません。"}, {"text": "この参考書は目が安くて、学生でも買いやすい。", "explanation": "ここは〈値段〉の意味です。目は見る器官なので、値段の安さを表すことはできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38026, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "花粉の季節は、目をかゆくなる人が多い。", "corrected_sentence": "花粉の季節は、目がかゆくなる人が多い。", "error_description": "正しくは「目が」です。「かゆくなる」は主語を「が」で示す形容詞の形なので、「目を」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38026, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パソコンの画面を見すぎて、目を疲れた人が増えている。", "corrected_sentence": "パソコンの画面を見すぎて、目が疲れた人が増えている。", "error_description": "正しくは「目が」です。「疲れた」は主語を「が」で示すので、「目を」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04017608-e499-4f0f-8fb3-f5beeedb8c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
