INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38028, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "ごちゃごちゃしていなくて、きれいなこと。", "primary_collocate": null, "pronunciation": "すっきり", "ipa": "sɯkːiɾi", "syllable_count": 4, "sentences": [{"text": "部屋を片づけたら、すっきりして気持ちがいいです。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "部屋(へや)を片(かた)づけたら、すっきりして気持(きも)ちがいいです。", "sentence_source": "generated"}, {"text": "机の上に何もないので、すっきりしています。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "机(つくえ)の上(うえ)に何(なに)もないので、すっきりしています。", "sentence_source": "generated"}, {"text": "本棚の本を減らして、すっきりさせました。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "本棚(ほんだな)の本(ほん)を減(へ)らして、すっきりさせました。", "sentence_source": "generated"}, {"text": "掃除をしたら、玄関に靴が一足しかなくてすっきりした。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "掃除(そうじ)をしたら、玄関(げんかん)に靴(くつ)が一足(いっそく)しかなくてすっきりした。", "sentence_source": "generated"}, {"text": "荷物が少ないから、私の部屋はいつもすっきりしている。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "荷物(にもつ)が少(すく)ないから、私(わたし)の部屋(へや)はいつもすっきりしている。", "sentence_source": "generated"}, {"text": "古い服を捨てたら、クローゼットがすっきりした。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "古(ふる)い服(ふく)を捨(す)てたら、クローゼットがすっきりした。", "sentence_source": "generated"}, {"text": "このキッチンは物が出ていなくて、すっきり見える。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "このキッチンは物(もの)が出(で)ていなくて、すっきり見(み)える。", "sentence_source": "generated"}, {"text": "引っ越しの前に、いらない物を整理して家をすっきりさせた。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの前(まえ)に、いらない物(もの)を整理(せいり)して家(いえ)をすっきりさせた。", "sentence_source": "generated"}, {"text": "机の上をすっきり片づけてから、勉強を始めた。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "机(つくえ)の上(うえ)をすっきり片(かた)づけてから、勉強(べんきょう)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "棚の上がごちゃごちゃしていたが、今はすっきりしている。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "棚(たな)の上(うえ)がごちゃごちゃしていたが、今(いま)はすっきりしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "すっきり", "label": "基本形"}, {"form": "すっきりする", "label": "動詞形"}, {"form": "すっきりした", "label": "過去・連体形"}, {"form": "すっきりと", "label": "と付き形"}], "register": "neutral", "sense_fingerprint": "物が少なく片づいていて、部屋や場所がごちゃごちゃしていない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38028, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "すっきり", "is_correct": true, "explanation": "片づけた結果として、物が少なく整った状態を表す。文の「片づけたら」と合う。"}, {"text": "ぐっしょり", "is_correct": false, "explanation": "水などで濡れて重くなる様子。部屋を片づける話とは関係がなく、意味が合わない。"}, {"text": "ごちゃごちゃ", "is_correct": false, "explanation": "物が散らかって雑然としている様子。片づけた後に気持ちがいいという文脈とは逆になる。"}, {"text": "ぎっしり", "is_correct": false, "explanation": "隙間なく詰まっている様子。片づけて物が減るという流れと反対で合わない。"}], "explanations": {"すっきり": "片づけた結果として、物が少なく整った状態を表す。文の「片づけたら」と合う。", "ぐっしょり": "水などで濡れて重くなる様子。部屋を片づける話とは関係がなく、意味が合わない。", "ごちゃごちゃ": "物が散らかって雑然としている様子。片づけた後に気持ちがいいという文脈とは逆になる。", "ぎっしり": "隙間なく詰まっている様子。片づけて物が減るという流れと反対で合わない。"}, "sentence_index": 0, "correct_answer": "すっきり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この問題は、すっきり分からない。", "explanation": "ここは〈さっぱり〉（まったく、少しも。下に打ち消しを伴う）の意味。〈すっきり〉は整っている様子を表すので、わからなさの程度は表せず合わない。"}, {"text": "教室はすっきりと騒がしかった。", "explanation": "ここは〈がやがや〉（大勢が騒がしく話すさま）の意味。〈すっきり〉は整って余計なものがない様子で、騒がしさは表せないので合わない。"}, {"text": "荷物がすっきりと重かった。", "explanation": "ここは〈ずっしり〉（重みが強く感じられるさま）の意味。〈すっきり〉は整って軽やかな様子で、重さは表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38028, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "すっきり", "is_correct": true, "explanation": "物が出ていない、整って見える様子を表す。文の「物が出ていなくて」と合う。"}, {"text": "ぼろぼろ", "is_correct": false, "explanation": "傷んで崩れている様子。キッチンの片づき具合とは関係がなく、意味が合わない。"}, {"text": "もじゃもじゃ", "is_correct": false, "explanation": "毛や草などが絡み合って乱れている様子。物が少ないという文脈と反対になる。"}, {"text": "ごつごつ", "is_correct": false, "explanation": "表面が角張ってでこぼこしている様子。見た目が片づいているかどうかとは無関係。"}], "explanations": {"すっきり": "物が出ていない、整って見える様子を表す。文の「物が出ていなくて」と合う。", "ぼろぼろ": "傷んで崩れている様子。キッチンの片づき具合とは関係がなく、意味が合わない。", "もじゃもじゃ": "毛や草などが絡み合って乱れている様子。物が少ないという文脈と反対になる。", "ごつごつ": "表面が角張ってでこぼこしている様子。見た目が片づいているかどうかとは無関係。"}, "sentence_index": 6, "correct_answer": "すっきり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合は相手にすっきり負けた。", "explanation": "ここは〈あっさり〉（簡単に、きっぱり）の意味。〈すっきり〉は片づいた様子や爽快さを表すので、負け方には合わない。"}, {"text": "宿題のことを、すっきり忘れていた。", "explanation": "ここは〈すっかり〉（残らず完全に）の意味。〈すっきり〉は余計なものがなく整った感じを表し、忘れたさまには合わない。"}, {"text": "道路が、すっきり混んでいる。", "explanation": "ここは〈ぎっしり〉（隙間なく詰まっているさま）の意味。〈すっきり〉は整って余計なものがない様子で、混み具合は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38028, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物を整理したら、部屋がすっきりな雰囲気になった。", "corrected_sentence": "物を整理したら、部屋がすっきりした雰囲気になった。", "error_description": "誤りは「すっきりな」。名詞の前では「すっきりした」の形にする。「すっきりな雰囲気」は不自然で、正しくは「すっきりした雰囲気」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38028, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "荷物を減らしたので、部屋がすっきりに見える。", "corrected_sentence": "荷物を減らしたので、部屋がすっきり見える。", "error_description": "誤りは「すっきりに」の「に」。すっきりは副詞で「見える」を直接修飾するので、助詞「に」は付けない。「すっきり見える」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
