INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38029, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "余計なものがなく、整っていて気持ちがよいさま。", "primary_collocate": null, "pronunciation": "すっきり", "ipa": "sɯkːiɾi", "syllable_count": 4, "sentences": [{"text": "このスマホはデザインがすっきりしていて、使いやすい。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "このスマホはデザインがすっきりしていて、使(つか)いやすい。", "sentence_source": "generated"}, {"text": "彼女はいつもすっきりした服を着ている。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "彼女(かのじょ)はいつもすっきりした服(ふく)を着(き)ている。", "sentence_source": "generated"}, {"text": "説明が長いと分かりにくいので、文章をすっきりまとめた。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "説明(せつめい)が長(なが)いと分(わ)かりにくいので、文章(ぶんしょう)をすっきりまとめた。", "sentence_source": "generated"}, {"text": "余計な飾りがない、すっきりしたデザインの椅子です。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "余計(よけい)な飾(かざ)りがない、すっきりしたデザインの椅子(いす)です。", "sentence_source": "generated"}, {"text": "髪を短く切って、首元がすっきりした。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "髪(かみ)を短(みじか)く切(き)って、首元(くびもと)がすっきりした。", "sentence_source": "generated"}, {"text": "この画面は文字が少なくて、すっきり見やすい。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "この画面(がめん)は文字(もじ)が少(すく)なくて、すっきり見(み)やすい。", "sentence_source": "generated"}, {"text": "彼の話は無駄がなくて、すっきり分かりやすかった。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はなし)は無駄(むだ)がなくて、すっきり分(わ)かりやすかった。", "sentence_source": "generated"}, {"text": "このレストランは内装がすっきりしていて、落ち着く。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "このレストランは内装(ないそう)がすっきりしていて、落(お)ち着(つ)く。", "sentence_source": "generated"}, {"text": "メニューの数を減らして、すっきりした店になった。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "メニューの数(かず)を減(へ)らして、すっきりした店(みせ)になった。", "sentence_source": "generated"}, {"text": "余計な言葉を消すと、すっきりした文になる。", "target_word": "すっきり", "complexity_tier": "T3", "furigana": "余計(よけい)な言葉(ことば)を消(け)すと、すっきりした文(ぶん)になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "すっきり", "label": "基本形"}, {"form": "すっきりする", "label": "動詞形"}, {"form": "すっきりした", "label": "過去・連体形"}, {"form": "すっきりと", "label": "と付き形"}], "register": "neutral", "sense_fingerprint": "デザイン・文章・外見などに無駄な飾りや余分がなく、整って見える様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38029, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "すっきり", "is_correct": true, "explanation": "余計な飾りがなく、デザインが整っている様子を表す。文の「デザインが」に合う。"}, {"text": "ごてごて", "is_correct": false, "explanation": "飾りや装飾が多すぎる様子。〈すっきり〉の逆で、デザインの説明に合わない。"}, {"text": "ぼさぼさ", "is_correct": false, "explanation": "髪などが乱れて整っていない様子。デザインには使えず、意味が合わない。"}, {"text": "ぐにゃぐにゃ", "is_correct": false, "explanation": "柔らかくて形が崩れる様子。デザインの整い具合を表す文脈とは関係がない。"}], "explanations": {"すっきり": "余計な飾りがなく、デザインが整っている様子を表す。文の「デザインが」に合う。", "ごてごて": "飾りや装飾が多すぎる様子。〈すっきり〉の逆で、デザインの説明に合わない。", "ぼさぼさ": "髪などが乱れて整っていない様子。デザインには使えず、意味が合わない。", "ぐにゃぐにゃ": "柔らかくて形が崩れる様子。デザインの整い具合を表す文脈とは関係がない。"}, "sentence_index": 0, "correct_answer": "すっきり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太陽がすっきりと照りつけた。", "explanation": "ここは〈ぎらぎら〉（強くまぶしく光るさま）の意味。〈すっきり〉は整って余計なものがない様子で、まぶしく照りつける強さは表せないので合わない。"}, {"text": "空がすっきりと曇っている。", "explanation": "ここは〈どんより〉（雲が重く垂れ込めて暗いさま）の意味。〈すっきり〉は整って清らかな様子で、暗く曇ったさまとは合わない。"}, {"text": "工事の音が、すっきりうるさかった。", "explanation": "ここは〈とても〉（程度がきわめて大きいさま）の意味。〈すっきり〉は整った様子を表すので、程度の強さは表せず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38029, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "すっきり", "is_correct": true, "explanation": "無駄がなく、分かりやすく整って伝わる様子を表す。文の「無駄がなくて」と合う。"}, {"text": "ぐだぐだ", "is_correct": false, "explanation": "だらだら長く締まりのない様子。「無駄がなくて」と逆で、話の分かりやすさに合わない。"}, {"text": "ひそひそ", "is_correct": false, "explanation": "小声でこっそり話す様子。話の内容の分かりやすさを表す文脈とは合わない。"}, {"text": "もたもた", "is_correct": false, "explanation": "動作や進みが遅くてはっきりしない様子。話の分かりやすさとは関係がない。"}], "explanations": {"すっきり": "無駄がなく、分かりやすく整って伝わる様子を表す。文の「無駄がなくて」と合う。", "ぐだぐだ": "だらだら長く締まりのない様子。「無駄がなくて」と逆で、話の分かりやすさに合わない。", "ひそひそ": "小声でこっそり話す様子。話の内容の分かりやすさを表す文脈とは合わない。", "もたもた": "動作や進みが遅くてはっきりしない様子。話の分かりやすさとは関係がない。"}, "sentence_index": 6, "correct_answer": "すっきり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この言い方なら、すっきりくる。", "explanation": "ここは〈しっくり〉（ぴたりと合う）の言い換えを誤って使っている。〈すっきり〉は整って無駄がない様子で、合う・収まる感じは表せない。"}, {"text": "提案をすっきり断った。", "explanation": "ここは〈あっさり〉（迷わず簡単に）の言い換えを誤って使っている。〈すっきり〉は整った様子や爽快さを表すので、断り方には合わない。"}, {"text": "昼ご飯の後、すっきりお腹が空いた。", "explanation": "ここは〈ぺこぺこ〉（ひどく空腹なさま）の意味。〈すっきり〉は整って余計なものがない様子で、空腹の程度は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38029, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このアプリは画面がすっきりでいて、迷わず操作できる。", "corrected_sentence": "このアプリは画面がすっきりしていて、迷わず操作できる。", "error_description": "誤りは「すっきりで」。すっきりは「する」を付けて述語になるので「すっきりしていて」と活用させる。「すっきりでいて」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38029, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "メニューを絞って、店がすっきりを見えるようになった。", "corrected_sentence": "メニューを絞って、店がすっきり見えるようになった。", "error_description": "誤りは「すっきりを」の「を」。すっきりは副詞で「見える」を修飾するので、助詞「を」は付かない。「すっきり見える」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38030, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「これが分かる」は、分かる対象を「が」で示します。"}, {"text": "に", "is_correct": false, "explanation": "「これに何か分かる」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは使えません。"}, {"text": "と", "is_correct": false, "explanation": "「これと何か分かる？」は文として成り立ちません。「分かる」の対象は「が」で示します。"}], "correct_answer": "が", "explanations": {"が": "「これが分かる」は、分かる対象を「が」で示します。", "に": "「これに何か分かる」は文として成り立ちません。", "へ": "「へ」は方向を表し、ここでは使えません。", "と": "「これと何か分かる？」は文として成り立ちません。「分かる」の対象は「が」で示します。"}, "error_tags": {"に": "wrong_case", "へ": "direction", "と": "wrong_case"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38030, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「分かると」は条件を表す「と」で、後ろの文につながります。"}, {"text": "を", "is_correct": false, "explanation": "「分かるを」は動詞の終止形に付けられません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、動詞の後ろには付きません。"}, {"text": "で", "is_correct": false, "explanation": "「分かるで」では文がつながりません。"}], "correct_answer": "と", "explanations": {"と": "「分かると」は条件を表す「と」で、後ろの文につながります。", "を": "「分かるを」は動詞の終止形に付けられません。", "へ": "「へ」は方向を表し、動詞の後ろには付きません。", "で": "「分かるで」では文がつながりません。"}, "error_tags": {"を": "wrong_case", "へ": "direction", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38030, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "何かがどういうものか、頭の中でわかること。", "primary_collocate": null, "pronunciation": "わかる", "ipa": "wakaɾɯ", "syllable_count": 3, "sentences": [{"text": "意味が分かる。", "target_word": "分かる", "complexity_tier": "T1", "furigana": "意味[いみ]が分[わ]かる。", "sentence_source": "generated"}, {"text": "これが何か分かる？", "target_word": "分かる", "complexity_tier": "T1", "furigana": "これが何[なに]か分[わ]かる？", "sentence_source": "generated"}, {"text": "犬の気持ちが分かります。", "target_word": "分かります", "complexity_tier": "T2", "furigana": "犬[いぬ]の気持[きも]ちが分[わ]かります。", "sentence_source": "generated"}, {"text": "この文は意味が分かりません。", "target_word": "分かりません", "complexity_tier": "T2", "furigana": "この文[ぶん]は意味[いみ]が分[わ]かりません。", "sentence_source": "generated"}, {"text": "地図を見て、場所が分かった。", "target_word": "分かった", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]て、場所[ばしょ]が分[わ]かった。", "sentence_source": "generated"}, {"text": "名前を聞いても、だれか分からなかった。", "target_word": "分からなかった", "complexity_tier": "T3", "furigana": "名前[なまえ]を聞[き]いても、だれか分[わ]からなかった。", "sentence_source": "generated"}, {"text": "説明すれば、きっと分かってくれる。", "target_word": "分かって", "complexity_tier": "T3", "furigana": "説明[せつめい]すれば、きっと分[わ]かってくれる。", "sentence_source": "generated"}, {"text": "仕組みが分かると、機械を使うのがもっと楽しくなる。", "target_word": "分かる", "complexity_tier": "T4", "furigana": "仕組[しく]みが分[わ]かると、機械[きかい]を使[つか]うのがもっと楽[たの]しくなる。", "sentence_source": "generated"}, {"text": "彼のことは、会ってみないと分からない部分が多い。", "target_word": "分からない", "complexity_tier": "T4", "furigana": "彼[かれ]のことは、会[あ]ってみないと分[わ]からない部分[ぶぶん]が多[おお]い。", "sentence_source": "generated"}, {"text": "問題の本当の原因が分かるまでには、まだ時間がかかりそうだと専門家は話している。", "target_word": "分かる", "complexity_tier": "T5", "furigana": "問題[もんだい]の本当[ほんとう]の原因[げんいん]が分[わ]かるまでには、まだ時間[じかん]がかかりそうだと専門家[せんもんか]は話[はな]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分かります", "label": "活用"}, {"form": "分かった", "label": "活用"}, {"form": "分からない", "label": "活用"}, {"form": "分かって", "label": "活用"}, {"form": "分かりやすい", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 何かがどういうものか頭でわかる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38030, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分かる", "is_correct": true, "explanation": "見出し語の「わかる」そのものです。"}, {"text": "わたる", "is_correct": false, "explanation": "「わたる」は2音目が「か」ではなく「た」で、1モーラ違います。"}, {"text": "はかる", "is_correct": false, "explanation": "「はかる」は1音目が「わ」ではなく「は」で、1モーラ違います。"}, {"text": "わける", "is_correct": false, "explanation": "「わける」は2音目が「か」ではなく「け」で、1モーラ違います。"}, {"text": "かかる", "is_correct": false, "explanation": "「かかる」は1音目が「わ」ではなく「か」で、1モーラ違います。"}], "explanations": {"分かる": "見出し語の「わかる」そのものです。", "わたる": "「わたる」は2音目が「か」ではなく「た」で、1モーラ違います。", "はかる": "「はかる」は1音目が「わ」ではなく「は」で、1モーラ違います。", "わける": "「わける」は2音目が「か」ではなく「け」で、1モーラ違います。", "かかる": "「かかる」は1音目が「わ」ではなく「か」で、1モーラ違います。"}, "sentence_index": null, "correct_answer": "分かる"}, "level_3": {"options": [{"text": "分かる", "is_correct": true, "explanation": "「意味が分かる」は、意味を頭で理解するという自然な表現です。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが意味が合わない。意味が「眠る」ことはありません。"}, {"text": "咲く", "is_correct": false, "explanation": "形は合うが意味が合わない。意味が「咲く」とは言えません。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "形は合うが意味が合わない。意味が「泳ぐ」ことはありません。"}], "explanations": {"分かる": "「意味が分かる」は、意味を頭で理解するという自然な表現です。", "眠る": "形は合うが意味が合わない。意味が「眠る」ことはありません。", "咲く": "形は合うが意味が合わない。意味が「咲く」とは言えません。", "泳ぐ": "形は合うが意味が合わない。意味が「泳ぐ」ことはありません。"}, "sentence_index": 0, "correct_answer": "分かる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を二階まで分かりました。", "explanation": "「分かる」は理解する意味で、荷物を運ぶ意味では使えません。"}, {"text": "毎朝、六時にパンを分かる。", "explanation": "「分かる」は物を食べる動作には使えません。"}, {"text": "雨の中を歩いて、足がとても分かった。", "explanation": "「分かる」は体の状態（濡れる・痛い）を表す語ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.mod