INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38031, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "物事の意味や内容、理由などを理解する。", "primary_collocate": null, "pronunciation": "わかる", "ipa": "wakaɾɯ", "syllable_count": 3, "sentences": [{"text": "みんなのことばがわかります。", "target_word": "わかります", "complexity_tier": "T2", "furigana": "みんなのことばがわかります。", "sentence_source": "mined"}, {"text": "答えが分かる。", "target_word": "分かる", "complexity_tier": "T1", "furigana": "答[こた]えが分[わ]かる。", "sentence_source": "generated"}, {"text": "先生の話が分かりました。", "target_word": "分かりました", "complexity_tier": "T2", "furigana": "先生[せんせい]の話[はなし]が分[わ]かりました。", "sentence_source": "generated"}, {"text": "この漢字の意味は分かりません。", "target_word": "分かりません", "complexity_tier": "T2", "furigana": "この漢字[かんじ]の意味[いみ]は分[わ]かりません。", "sentence_source": "generated"}, {"text": "説明を聞いて、やっと理由が分かった。", "target_word": "分かった", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]いて、やっと理由[りゆう]が分[わ]かった。", "sentence_source": "generated"}, {"text": "日本語が分かるようになりたい。", "target_word": "分かる", "complexity_tier": "T3", "furigana": "日本語[にほんご]が分[わ]かるようになりたい。", "sentence_source": "generated"}, {"text": "何を言っているのか、よく分からない。", "target_word": "分からない", "complexity_tier": "T3", "furigana": "何[なに]を言[い]っているのか、よく分[わ]からない。", "sentence_source": "generated"}, {"text": "考えれば分かる問題なのに、なぜか間違えてしまった。", "target_word": "分かる", "complexity_tier": "T4", "furigana": "考[かんが]えれば分[わ]かる問題[もんだい]なのに、なぜか間違[まちが]えてしまった。", "sentence_source": "generated"}, {"text": "使ってみて、この道具の便利さが分かって驚いた。", "target_word": "分かって", "complexity_tier": "T3", "furigana": "使[つか]ってみて、この道具[どうぐ]の便利[べんり]さが分[わ]かって驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "説明書を何度も読んだのに、操作の仕方がまったく分からなかったので、店員に聞いた。", "target_word": "分からなかった", "complexity_tier": "T5", "furigana": "説明書[せつめいしょ]を何度[なんど]も読[よ]んだのに、操作[そうさ]の仕方[しかた]がまったく分[わ]からなかったので、店員[てんいん]に聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分かります", "label": "活用"}, {"form": "分かった", "label": "活用"}, {"form": "分からない", "label": "活用"}, {"form": "分かって", "label": "活用"}, {"form": "分かりやすい", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物事の意味や理由を理解する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38031, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分かる", "is_correct": true, "explanation": "「わかる」で、理解するという意味の見出し語。"}, {"text": "かかる", "is_correct": false, "explanation": "最初の音が「わ」ではなく「か」で、一音違う。"}, {"text": "はかる", "is_correct": false, "explanation": "最初の音が「わ」ではなく「は」で、一音違う。"}, {"text": "わたる", "is_correct": false, "explanation": "真ん中の音が「か」ではなく「た」で、一音違う。"}, {"text": "わかす", "is_correct": false, "explanation": "最後の音が「る」ではなく「す」で、一音違う。"}], "explanations": {"分かる": "「わかる」で、理解するという意味の見出し語。", "かかる": "最初の音が「わ」ではなく「か」で、一音違う。", "はかる": "最初の音が「わ」ではなく「は」で、一音違う。", "わたる": "真ん中の音が「か」ではなく「た」で、一音違う。", "わかす": "最後の音が「る」ではなく「す」で、一音違う。"}, "sentence_index": null, "correct_answer": "分かる"}, "level_3": {"options": [{"text": "わかります", "is_correct": true, "explanation": "「ことばが分かる」で、言葉の意味を理解するという意味になる。"}, {"text": "ひかります", "is_correct": false, "explanation": "形は合うが、言葉が光るでは意味が合わない。"}, {"text": "こおります", "is_correct": false, "explanation": "形は合うが、言葉が凍るでは意味が合わない。"}, {"text": "さびます", "is_correct": false, "explanation": "形は合うが、言葉がさびるでは意味が合わない。"}], "explanations": {"わかります": "「ことばが分かる」で、言葉の意味を理解するという意味になる。", "ひかります": "形は合うが、言葉が光るでは意味が合わない。", "こおります": "形は合うが、言葉が凍るでは意味が合わない。", "さびます": "形は合うが、言葉がさびるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "わかります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この漢字を紙に分かって書いた。", "explanation": "「分かる」は理解する意味で、「書く」様子を表す言葉として使えない。"}, {"text": "駅で友だちと分かってから、家に帰った。", "explanation": "別れる意味は「分かる」ではなく「別れる」を使う。"}, {"text": "この荷物は重くて、一人で分からない。", "explanation": "持ち上げられない意味を「分からない」で表すのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38031, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分かる", "is_correct": true, "explanation": "「わかる」で、理解するという意味の見出し語。"}, {"text": "たかる", "is_correct": false, "explanation": "最初の音が「わ」ではなく「た」で、一音違う。"}, {"text": "さかる", "is_correct": false, "explanation": "最初の音が「わ」ではなく「さ」で、一音違う。"}, {"text": "わける", "is_correct": false, "explanation": "真ん中の音が「か」ではなく「け」で、一音違う。"}, {"text": "わかつ", "is_correct": false, "explanation": "最後の音が「る」ではなく「つ」で、一音違う。"}], "explanations": {"分かる": "「わかる」で、理解するという意味の見出し語。", "たかる": "最初の音が「わ」ではなく「た」で、一音違う。", "さかる": "最初の音が「わ」ではなく「さ」で、一音違う。", "わける": "真ん中の音が「か」ではなく「け」で、一音違う。", "わかつ": "最後の音が「る」ではなく「つ」で、一音違う。"}, "sentence_index": null, "correct_answer": "分かる"}, "level_3": {"options": [{"text": "分からない", "is_correct": true, "explanation": "何を言っているのか理解できないという意味で自然に合う。"}, {"text": "消えない", "is_correct": false, "explanation": "形は合うが、言っている内容が消えないでは意味が合わない。"}, {"text": "降らない", "is_correct": false, "explanation": "形は合うが、雨や雪が降る意味で文脈に合わない。"}, {"text": "光らない", "is_correct": false, "explanation": "形は合うが、光る意味で文脈に合わない。"}], "explanations": {"分からない": "何を言っているのか理解できないという意味で自然に合う。", "消えない": "形は合うが、言っている内容が消えないでは意味が合わない。", "降らない": "形は合うが、雨や雪が降る意味で文脈に合わない。", "光らない": "形は合うが、光る意味で文脈に合わない。"}, "sentence_index": 6, "correct_answer": "分からない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキを三つに分からなかったので、一人で全部食べた。", "explanation": "切って分ける意味は「分ける」を使い、「分かる」では表せない。"}, {"text": "友だちと駅で分からなかったから、いっしょに帰った。", "explanation": "別れる意味は「別れる」を使い、「分かる」では表せない。"}, {"text": "自分の名前を紙に分からなかったので、先生に聞いた。", "explanation": "「書く」意味を「分からない」で表すのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38031, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちの気持ちが分けました。", "corrected_sentence": "友だちの気持ちが分かりました。", "error_description": "気持ちを理解する意味では「分ける」ではなく「分かる」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
