INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38032, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を表す助詞。「利点は、〜ことだ」の文の主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的格の助詞。主題の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の助詞。ここでは主題の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞。「利点へ、〜ことだ」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "主題を表す助詞。「利点は、〜ことだ」の文の主題を示す。", "を": "目的格の助詞。主題の位置には合わない。", "で": "手段・場所の助詞。ここでは主題の位置に合わない。", "へ": "方向の助詞。「利点へ、〜ことだ」は意味が通らない。"}, "error_tags": {"を": "目的格の助詞。主題の位置には合わない", "で": "手段・場所の助詞。ここでは主題の位置に合わない", "へ": "方向の助詞。「利点へ、〜ことだ」は意味が通らない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "欠点", "is_correct": true, "explanation": "「利点」の対義語。良い点と悪い点という関係で、辞書にも対になっている。"}, {"text": "手間", "is_correct": false, "explanation": "手数や労力の意味で、「利点」の対義語ではない。"}, {"text": "信用", "is_correct": false, "explanation": "人や物への信頼を表す語で、「利点」とは対になる関係ではない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表す語で、「利点」とは対義関係にない。"}], "correct_answer": "欠点", "explanations": {"欠点": "「利点」の対義語。良い点と悪い点という関係で、辞書にも対になっている。", "手間": "手数や労力の意味で、「利点」の対義語ではない。", "信用": "人や物への信頼を表す語で、「利点」とは対になる関係ではない。", "季節": "一年の時期を表す語で、「利点」とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
