INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38032, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに、それが役に立つこと。", "primary_collocate": null, "pronunciation": "りてん", "ipa": "ɾiteɴ", "syllable_count": 3, "sentences": [{"text": "この方法の利点は、時間がかからないことです。", "target_word": "利点", "complexity_tier": "T3", "furigana": "この方法[ほうほう]の利点[りてん]は、時間[じかん]がかからないことです。", "sentence_source": "generated"}, {"text": "車を持たない利点は、お金がかからないことだ。", "target_word": "利点", "complexity_tier": "T3", "furigana": "車[くるま]を持[も]たない利点[りてん]は、お金[かね]がかからないことだ。", "sentence_source": "generated"}, {"text": "小さい会社には、決めるのが速いという利点がある。", "target_word": "利点", "complexity_tier": "T3", "furigana": "小[ちい]さい会社[かいしゃ]には、決[き]めるのが速[はや]いという利点[りてん]がある。", "sentence_source": "generated"}, {"text": "オンライン授業の利点は、家で学べることです。", "target_word": "利点", "complexity_tier": "T3", "furigana": "オンライン授業[じゅぎょう]の利点[りてん]は、家[いえ]で学[まな]べることです。", "sentence_source": "generated"}, {"text": "電車で通うと、本が読めるという利点がある。", "target_word": "利点", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で通[かよ]うと、本[ほん]が読[よ]めるという利点[りてん]がある。", "sentence_source": "generated"}, {"text": "新しい機械には、使いやすいという利点がある。", "target_word": "利点", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]には、使[つか]いやすいという利点[りてん]がある。", "sentence_source": "generated"}, {"text": "現金で払う利点は、使いすぎにくいことだ。", "target_word": "利点", "complexity_tier": "T3", "furigana": "現金[げんきん]で払[はら]う利点[りてん]は、使[つか]いすぎにくいことだ。", "sentence_source": "generated"}, {"text": "二人で住む利点を、友だちに話した。", "target_word": "利点", "complexity_tier": "T3", "furigana": "二人[ふたり]で住[す]む利点[りてん]を、友[とも]だちに話[はな]した。", "sentence_source": "generated"}, {"text": "この辞書の利点は、例文が多いところです。", "target_word": "利点", "complexity_tier": "T3", "furigana": "この辞書[じしょ]の利点[りてん]は、例文[れいぶん]が多[おお]いところです。", "sentence_source": "generated"}, {"text": "利点と欠点を比べてから、決めましょう。", "target_word": "利点", "complexity_tier": "T3", "furigana": "利点[りてん]と欠点[けってん]を比[くら]べてから、決[き]めましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "利点", "label": "基本形"}, {"form": "利点が", "label": "主格"}, {"form": "利点は", "label": "主題"}, {"form": "利点を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "ある行動や方法をとるときの役に立つ点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38032, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利点", "is_correct": true, "explanation": "「時間がかからない」は方法の良い点なので、「利点」が入る。"}, {"text": "季節", "is_correct": false, "explanation": "「この方法の季節は、時間がかからないこと」では意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「この方法の天気は」は文の主題として不自然で、良い点の意味にならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気は時間がかからないこと」は意味が通らない。"}], "explanations": {"利点": "「時間がかからない」は方法の良い点なので、「利点」が入る。", "季節": "「この方法の季節は、時間がかからないこと」では意味が通らない。", "天気": "「この方法の天気は」は文の主題として不自然で、良い点の意味にならない。", "眠気": "「眠気は時間がかからないこと」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "利点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この靴の利点は、雨の日にすぐ滑ることだ。", "explanation": "滑りやすいことは欠点。「利点」は良い点を指すので、ここでは合わない。"}, {"text": "この薬の利点は、飲むと必ず頭が痛くなることだ。", "explanation": "「利点」は良い点を表す語で、押す対象になる物を指さない。ここでは意味が通らない。"}, {"text": "この机の利点は、すぐぐらつくことだ。", "explanation": "ぐらつきは欠点。「利点」は役に立つ点を指すので、この文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38032, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利点", "is_correct": true, "explanation": "「使いすぎにくい」は現金払いの良い点なので、「利点」が入る。"}, {"text": "手荷物", "is_correct": false, "explanation": "「現金で払う手荷物は」では、良い点の意味にならない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は「使いすぎにくい」と結びつかず、文の主題として合わない。"}, {"text": "雑談", "is_correct": false, "explanation": "「現金で払う雑談は」は意味が通らない。"}], "explanations": {"利点": "「使いすぎにくい」は現金払いの良い点なので、「利点」が入る。", "手荷物": "「現金で払う手荷物は」では、良い点の意味にならない。", "寝具": "寝具は「使いすぎにくい」と結びつかず、文の主題として合わない。", "雑談": "「現金で払う雑談は」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "利点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の利点を、先生が採点した。", "explanation": "「利点」は良い点を表す語で、試験の点数を指す意味はない。ここでは意味が通らない。"}, {"text": "彼女は、利点の入った箱を運んだ。", "explanation": "「利点」は役に立つ性質を表す語で、箱の中身を指す意味はない。ここでは意味が通らない。"}, {"text": "この鍋の利点は、ふたを開けて数えることだ。", "explanation": "「利点」は役に立つ性質を表す語で、行為の手順を指す意味はない。ここでは意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
