INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38033, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が持つ、良い結果や役に立つ性質。", "primary_collocate": null, "pronunciation": "りてん", "ipa": "ɾiteɴ", "syllable_count": 3, "sentences": [{"text": "自転車通勤の利点は、体が丈夫になることだ。", "target_word": "利点", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]通勤[つうきん]の利点[りてん]は、体[からだ]が丈夫[じょうぶ]になることだ。", "sentence_source": "generated"}, {"text": "田舎に住む利点は、空気がきれいなことです。", "target_word": "利点", "complexity_tier": "T3", "furigana": "田舎[いなか]に住[す]む利点[りてん]は、空気[くうき]がきれいなことです。", "sentence_source": "generated"}, {"text": "この素材には、軽くて丈夫という利点がある。", "target_word": "利点", "complexity_tier": "T3", "furigana": "この素材[そざい]には、軽[かる]くて丈夫[じょうぶ]という利点[りてん]がある。", "sentence_source": "generated"}, {"text": "太陽光発電の利点は、燃料がいらないことだ。", "target_word": "利点", "complexity_tier": "T3", "furigana": "太陽光[たいようこう]発電[はつでん]の利点[りてん]は、燃料[ねんりょう]がいらないことだ。", "sentence_source": "generated"}, {"text": "計画の利点を、会議で説明した。", "target_word": "利点", "complexity_tier": "T3", "furigana": "計画[けいかく]の利点[りてん]を、会議[かいぎ]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "小さな店には、客との距離が近いという利点がある。", "target_word": "利点", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]には、客[きゃく]との距離[きょり]が近[ちか]いという利点[りてん]がある。", "sentence_source": "generated"}, {"text": "早起きの利点は、朝の時間を自由に使えることです。", "target_word": "利点", "complexity_tier": "T3", "furigana": "早起[はやお]きの利点[りてん]は、朝[あさ]の時間[じかん]を自由[じゆう]に使[つか]えることです。", "sentence_source": "generated"}, {"text": "その案の利点は、費用が安いところだ。", "target_word": "利点", "complexity_tier": "T3", "furigana": "その案[あん]の利点[りてん]は、費用[ひよう]が安[やす]いところだ。", "sentence_source": "generated"}, {"text": "二つの案の利点を、表にまとめました。", "target_word": "利点", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]の利点[りてん]を、表[ひょう]にまとめました。", "sentence_source": "generated"}, {"text": "木の家には、夏すずしいという利点がある。", "target_word": "利点", "complexity_tier": "T3", "furigana": "木[き]の家[いえ]には、夏[なつ]すずしいという利点[りてん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "利点", "label": "基本形"}, {"form": "利点が", "label": "主格"}, {"form": "利点は", "label": "主題"}, {"form": "利点を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "物事が持つ良い結果や役に立つ性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38033, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利点", "is_correct": true, "explanation": "「体が丈夫になる」は通勤の良い点なので、「利点」が入る。"}, {"text": "手荷物", "is_correct": false, "explanation": "「自転車通勤の手荷物は」では、良い点の意味にならない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は通勤の良い点として結びつかず、文の主題として合わない。"}, {"text": "雑談", "is_correct": false, "explanation": "「自転車通勤の雑談は」は意味が通らない。"}], "explanations": {"利点": "「体が丈夫になる」は通勤の良い点なので、「利点」が入る。", "手荷物": "「自転車通勤の手荷物は」では、良い点の意味にならない。", "寝具": "寝具は通勤の良い点として結びつかず、文の主題として合わない。", "雑談": "「自転車通勤の雑談は」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "利点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太陽光発電の利点は、夜になると発電が止まることだ。", "explanation": "夜に発電が止まるのは欠点。「利点」は良い点を指すので、ここでは合わない。"}, {"text": "この機械の利点を、ボタンで押した。", "explanation": "「利点」は良い点を表す語で、押す対象になる物を指さない。ここでは意味が通らない。"}, {"text": "太陽光発電の利点は、屋根が重くなることだ。", "explanation": "屋根が重くなることは不都合で、「利点」が指す良い点とは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38033, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利点", "is_correct": true, "explanation": "「朝の時間を自由に使える」は早起きの良い点なので、「利点」が入る。"}, {"text": "天井", "is_correct": false, "explanation": "「早起きの天井は」では意味が通らない。"}, {"text": "方角", "is_correct": false, "explanation": "「早起きの方角は」は文の主題として合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「早起きの夕焼けは」は意味が通らない。"}], "explanations": {"利点": "「朝の時間を自由に使える」は早起きの良い点なので、「利点」が入る。", "天井": "「早起きの天井は」では意味が通らない。", "方角": "「早起きの方角は」は文の主題として合わない。", "夕焼け": "「早起きの夕焼けは」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "利点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木の家には、夏すずしいという利点を、窓辺に飾った。", "explanation": "「利点」は目に見えない性質を表す語で、窓辺に飾る物にはならない。ここでは意味が通らない。"}, {"text": "夏の暑さに強い木の家は、利点として高価だ。", "explanation": "「高価」は欠点（短所）になりうる点で、良い点を指す「利点」とは逆の意味。"}, {"text": "木の家は、利点を広い庭に植えた。", "explanation": "「利点」は植物を指さないので、庭に植える対象にならない。ここでは意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38033, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自転車通勤の利点を、体が強くなることだ。", "corrected_sentence": "自転車通勤の利点は、体が強くなることだ。", "error_description": "「利点」は主題なので「は」が必要。「を」は目的格で、「〜ことだ」の文とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38033, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早起きの利点を、夜の時間を自由に使えることです。", "corrected_sentence": "早起きの利点は、夜の時間を自由に使えることです。", "error_description": "「利点」は主題なので「は」が必要。「を」は目的格で、「〜ことです」の文と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38034, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「当初」と「予定」を結ぶ連体修飾の「の」。文の「当初の予定では」と合う。"}, {"text": "が", "is_correct": false, "explanation": "「当初が予定では」と主語にすると、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「当初を予定では」と目的語にすると、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「当初に予定では」と時点にすると、文の並びが崩れる。"}], "correct_answer": "の", "explanations": {"の": "「当初」と「予定」を結ぶ連体修飾の「の」。文の「当初の予定では」と合う。", "が": "「当初が予定では」と主語にすると、文が成り立たない。", "を": "「当初を予定では」と目的語にすると、意味が通らない。", "に": "「当初に予定では」と時点にすると、文の並びが崩れる。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "時点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38034, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「当初」と「予定」を結ぶ連体修飾の「の」。「当初の予定どおりに」と合う。"}, {"text": "と", "is_correct": false, "explanation": "「当初と予定どおり」と並べると、意味が通らない。ここは予定を修飾する形が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「当初へ予定どおり」と方向にすると、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「当初で予定どおり」と手段にすると、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「当初」と「予定」を結ぶ連体修飾の「の」。「当初の予定どおりに」と合う。", "と": "「当初と予定どおり」と並べると、意味が通らない。ここは予定を修飾する形が必要。", "へ": "「当初へ予定どおり」と方向にすると、文が成り立たない。", "で": "「当初で予定どおり」と手段にすると、意味が通らない。"}, "error_tags": {"と": "並列", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38034, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "最初のとき。", "primary_collocate": null, "pronunciation": "とうしょ", "ipa": "toːɕo", "syllable_count": 3, "sentences": [{"text": "当初は、この仕事がとても難しかった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)は、この仕事(しごと)がとても難(むずか)しかった。", "sentence_source": "generated"}, {"text": "当初の予定では、今日の午後に着くはずだった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)の予定(よてい)では、今日(きょう)の午後(ごご)に着(つ)くはずだった。", "sentence_source": "generated"}, {"text": "旅行は当初の計画より、一日長くなった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "旅行(りょこう)は当初(とうしょ)の計画(けいかく)より、一日(いちにち)長(なが)くなった。", "sentence_source": "generated"}, {"text": "当初は客が少なかったが、今はいつも混んでいる店だ。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)は客(きゃく)が少(すく)なかったが、今(いま)はいつも混(こ)んでいる店(みせ)だ。", "sentence_source": "generated"}, {"text": "当初の目標は、毎日一時間走ることだった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)の目標(もくひょう)は、毎日(まいにち)一時間(いちじかん)走(はし)ることだった。", "sentence_source": "generated"}, {"text": "当初の値段より、今は少し高くなっている。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)の値段(ねだん)より、今(いま)は少(すこ)し高(たか)くなっている。", "sentence_source": "generated"}, {"text": "会議は当初、十時に始まる予定でした。", "target_word": "当初", "complexity_tier": "T3", "furigana": "会議(かいぎ)は当初(とうしょ)、十時(じゅうじ)に始(はじ)まる予定(よてい)でした。", "sentence_source": "generated"}, {"text": "工事は当初の予定どおりに終わった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "工事(こうじ)は当初(とうしょ)の予定(よてい)どおりに終(お)わった。", "sentence_source": "generated"}, {"text": "当初は反対していた父も、最後には賛成した。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)は反対(はんたい)していた父(ちち)も、最後(さいご)には賛成(さんせい)した。", "sentence_source": "generated"}, {"text": "当初は友だちがいなくて、さびしかったです。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)は友(とも)だちがいなくて、さびしかったです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "当初", "label": "基本形"}, {"form": "当初は", "label": "は付き形"}, {"form": "当初の", "label": "連体形（の付き）"}], "register": "neutral", "sense_fingerprint": "ある出来事や状況の一番はじめの時期（今と比べて言う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: さびしかっ (Zipf 1.73)']::text[], 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38034, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "物事の一番はじめの時期を表す。文頭の「〜は」で、最初の状況を述べる文と合う。"}, {"text": "当然", "is_correct": false, "explanation": "「もちろん」の意で、時期を表す語ではない。「当然は」と続けると文法上は成り立つが、「最初」の意味にならず文脈に合わない。"}, {"text": "確実", "is_correct": false, "explanation": "間違いのないさまを表す。時期を示せず、文脈に合わない。"}, {"text": "無理", "is_correct": false, "explanation": "道理に合わないさまを表す。ここでは時期を示す語として入らない。"}], "explanations": {"当初": "物事の一番はじめの時期を表す。文頭の「〜は」で、最初の状況を述べる文と合う。", "当然": "「もちろん」の意で、時期を表す語ではない。「当然は」と続けると文法上は成り立つが、「最初」の意味にならず文脈に合わない。", "確実": "間違いのないさまを表す。時期を示せず、文脈に合わない。", "無理": "道理に合わないさまを表す。ここでは時期を示す語として入らない。"}, "sentence_index": 0, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当初、夢がかなった。", "explanation": "ここは〈ついに〉（長い過程の末に）の意味。〈当初〉は物事の始まりの時点を表すので、長い過程の末の結果には合わない。"}, {"text": "当初、仕事が終わった。", "explanation": "ここは〈ようやく〉（長い時間を経て）の意味。〈当初〉は始まりの時点なので、終わりの出来事とは合わない。"}, {"text": "当初、みんなで笑って終わった。", "explanation": "ここは〈結局〉（最後にはそうなった）の意味。〈当初〉は始まりの時点を指すので、結末を述べる文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38034, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "物事の始まりの時点を表す。「会議は当初、十時に始まる予定」と、最初の予定を述べる文に合う。"}, {"text": "大半", "is_correct": false, "explanation": "大部分を表す名詞。時点を示さず、ここでは文が成り立たない。"}, {"text": "即座", "is_correct": false, "explanation": "すぐさまという意味。時期の指定にはならず、文脈に合わない。"}, {"text": "極端", "is_correct": false, "explanation": "一方に偏るさまを表す。時点を表す語ではなく、ここでは入らない。"}], "explanations": {"当初": "物事の始まりの時点を表す。「会議は当初、十時に始まる予定」と、最初の予定を述べる文に合う。", "大半": "大部分を表す名詞。時点を示さず、ここでは文が成り立たない。", "即座": "すぐさまという意味。時期の指定にはならず、文脈に合わない。", "極端": "一方に偏るさまを表す。時点を表す語ではなく、ここでは入らない。"}, "sentence_index": 6, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当初は、もっと早く来てください。", "explanation": "ここは〈今後〉（これから先）の言い換えを誤って使っている。〈当初〉は始まりの時点を指すので、これからの指示には合わない。"}, {"text": "当初、最後の一ページを読み終えた。", "explanation": "ここは〈やっと〉（長い時間を経て、ようやく）の意味。〈当初〉は始まりの時点なので、読み終えるという結末には合わない。"}, {"text": "当初、一年後に結果が出た。", "explanation": "ここは〈やがて〉（時間が経って、そのうちに）の意味。〈当初〉は始まりの時点を指すので、一年後の結果とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38034, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当初な予定より早く終わった。", "corrected_sentence": "当初の予定より早く終わった。", "error_description": "誤りは「当初な」の「な」。当初は名詞なので、「の」で「予定」に続ける。「当初な予定」は不自然で、正しくは「当初の予定」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38034, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当初で計画を立てた。", "corrected_sentence": "当初の計画を立てた。", "error_description": "誤りは「で」。「当初」は名詞で、後に「の」を付けて「計画」を修飾する。「当初で」は成り立たないので、正しくは「当初の計画を立てた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38035, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「当初」と「見込み」を結ぶ連体修飾の「の」。「当初の見込み」と合う。"}, {"text": "を", "is_correct": false, "explanation": "「当初を見込み」と目的語にすると、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「当初に見込み」と時点にすると、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「当初で見込み」と手段にすると、文の並びが崩れる。"}], "correct_answer": "の", "explanations": {"の": "「当初」と「見込み」を結ぶ連体修飾の「の」。「当初の見込み」と合う。", "を": "「当初を見込み」と目的語にすると、意味が通らない。", "に": "「当初に見込み」と時点にすると、文が成り立たない。", "で": "「当初で見込み」と手段にすると、文の並びが崩れる。"}, "error_tags": {"を": "目的語", "に": "時点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38035, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「当初から」で始まりの時点を示す。「当初から反対していた」と合う。"}, {"text": "と", "is_correct": false, "explanation": "「当初と反対していた」と並べると、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「当初へ反対していた」と方向にすると、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「当初が反対していた人」と主語にすると、文の構造が崩れる。"}], "correct_answer": "から", "explanations": {"から": "「当初から」で始まりの時点を示す。「当初から反対していた」と合う。", "と": "「当初と反対していた」と並べると、意味が通らない。", "へ": "「当初へ反対していた」と方向にすると、文が成り立たない。", "が": "「当初が反対していた人」と主語にすると、文の構造が崩れる。"}, "error_tags": {"と": "並列", "へ": "方向", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38035, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が始まった時点。最初の段階。", "primary_collocate": null, "pronunciation": "とうしょ", "ipa": "toːɕo", "syllable_count": 3, "sentences": [{"text": "計画の当初から、費用が大きな問題だった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "計画(けいかく)の当初(とうしょ)から、費用(ひよう)が大(おお)きな問題(もんだい)だった。", "sentence_source": "generated"}, {"text": "当初の見込みが甘く、完成が大幅に遅れた。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)の見込(みこ)みが甘(あま)く、完成(かんせい)が大幅(おおはば)に遅(おく)れた。", "sentence_source": "generated"}, {"text": "新製品は当初、あまり売れなかったが、後で人気が出た。", "target_word": "当初", "complexity_tier": "T3", "furigana": "新製品(しんせいひん)は当初(とうしょ)、あまり売(う)れなかったが、後(あと)で人気(にんき)が出(で)た。", "sentence_source": "generated"}, {"text": "事業は当初の計画から大きく変更された。", "target_word": "当初", "complexity_tier": "T3", "furigana": "事業(じぎょう)は当初(とうしょ)の計画(けいかく)から大(おお)きく変更(へんこう)された。", "sentence_source": "generated"}, {"text": "当初は小さな研究会だったが、今は大きな学会になった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)は小(ちい)さな研究会(けんきゅうかい)だったが、今(いま)は大(おお)きな学会(がっかい)になった。", "sentence_source": "generated"}, {"text": "調査を始めた当初の予想とは、結果が違った。", "target_word": "当初", "complexity_tier": "T3", "furigana": "調査(ちょうさ)を始(はじ)めた当初(とうしょ)の予想(よそう)とは、結果(けっか)が違(ちが)った。", "sentence_source": "generated"}, {"text": "当初の目的を忘れずに、最後まで続けよう。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)の目的(もくてき)を忘(わす)れずに、最後(さいご)まで続(つづ)けよう。", "sentence_source": "generated"}, {"text": "当初から反対していた人は、ほんの数人だった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)から反対(はんたい)していた人(ひと)は、ほんの数人(すうにん)だった。", "sentence_source": "generated"}, {"text": "工事費は当初の二倍になってしまった。", "target_word": "当初", "complexity_tier": "T3", "furigana": "工事費(こうじひ)は当初(とうしょ)の二倍(にばい)になってしまった。", "sentence_source": "generated"}, {"text": "当初の説明と実際の内容が違うので、客が怒った。", "target_word": "当初", "complexity_tier": "T3", "furigana": "当初(とうしょ)の説明(せつめい)と実際(じっさい)の内容(ないよう)が違(ちが)うので、客(きゃく)が怒(おこ)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "当初", "label": "基本形"}, {"form": "当初は", "label": "は付き形"}, {"form": "当初の", "label": "連体形（の付き）"}, {"form": "当初から", "label": "から付き形"}], "register": "formal", "sense_fingerprint": "計画・事業・研究などが始まった時点や最初の段階（のちの変化と対比する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38035, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "物事が始まった時点を表す。「計画の当初から」で、計画の始まりを指す。"}, {"text": "完成", "is_correct": false, "explanation": "仕上がることを表す。「計画の完成から」では、費用が問題になった始まりの時点として成り立たない。"}, {"text": "全体", "is_correct": false, "explanation": "全部をまとめた範囲を表す。「計画の全体から」では始まりの時点を示せない。"}, {"text": "撤回", "is_correct": false, "explanation": "取り下げることを表す。「計画の撤回から」では、費用の問題が始まった時点として意味が通らない。"}], "explanations": {"当初": "物事が始まった時点を表す。「計画の当初から」で、計画の始まりを指す。", "完成": "仕上がることを表す。「計画の完成から」では、費用が問題になった始まりの時点として成り立たない。", "全体": "全部をまとめた範囲を表す。「計画の全体から」では始まりの時点を示せない。", "撤回": "取り下げることを表す。「計画の撤回から」では、費用の問題が始まった時点として意味が通らない。"}, "sentence_index": 0, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当初、計画が完成した。", "explanation": "ここは〈ついに〉（とうとう）の意味。〈当初〉は始まりの時点で、完成のような結末には合わない。"}, {"text": "当初、十年後の計画が実現した。", "explanation": "ここは〈やがて〉（時間が経って、そのうちに）の意味。〈当初〉は始まりの時点なので、十年後の実現とは合わない。"}, {"text": "当初、最後には大勢が参加した。", "explanation": "ここは〈結局〉（いろいろあった末に、そうなった）の意味。〈当初〉は始まりの時点を指すので、最後の結末を述べる文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38035, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "物事の始まりの時点を表し、最初に定めた目的を指す。「当初の目的」と合う。"}, {"text": "大量", "is_correct": false, "explanation": "数や量が多いことを表す。「大量の目的」では文が成り立たない。"}, {"text": "完全", "is_correct": false, "explanation": "欠けたところがないさまを表す。「完全の目的」では意味が通らない。"}, {"text": "簡単", "is_correct": false, "explanation": "やさしいさまを表す。「簡単の目的」では文脈に合わない。"}], "explanations": {"当初": "物事の始まりの時点を表し、最初に定めた目的を指す。「当初の目的」と合う。", "大量": "数や量が多いことを表す。「大量の目的」では文が成り立たない。", "完全": "欠けたところがないさまを表す。「完全の目的」では意味が通らない。", "簡単": "やさしいさまを表す。「簡単の目的」では文脈に合わない。"}, "sentence_index": 6, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当初、事業は大きく変わった。", "explanation": "ここは〈その後〉（あとで）の言い換えを誤って使っている。〈当初〉は最初の時点で、後からの変化を述べる文には合わない。"}, {"text": "当初、事業の赤字を完済した。", "explanation": "ここは〈ようやく〉（長い時間をかけて、ついに）の意味。〈当初〉は始まりの時点で、長年の返済を終えるという結末には合わない。"}, {"text": "当初、客が一週間後に増えた。", "explanation": "ここは〈いずれ〉（そのうちに、やがて）の意味。〈当初〉は始まりの時点なので、一週間後の変化とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38035, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "計画の当初まで、費用が問題になった。", "corrected_sentence": "計画の当初から、費用が問題になった。", "error_description": "誤りは「まで」。「当初から」で始まりの時点を示すのが正しい。「まで」は終点を表すので、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38035, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当初へ目標を決めた。", "corrected_sentence": "当初の目標を決めた。", "error_description": "誤りは「へ」。「当初」は名詞で、後に「の」を付けて「目標」を修飾する。「当初へ」は成り立たないので、正しくは「当初の目標を決めた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38036, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「プラスチックのコップ」は、プラスチック製のコップという名詞修飾で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「プラスチックを」だと目的語になり、「コップは落としても割れません」と続かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を表すので、「プラスチックにコップは」と続かない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、後ろの「コップは」と主語が二重になり不自然。"}], "correct_answer": "の", "explanations": {"の": "「プラスチックのコップ」は、プラスチック製のコップという名詞修飾で正しい。", "を": "「プラスチックを」だと目的語になり、「コップは落としても割れません」と続かない。", "に": "「に」は場所や相手を表すので、「プラスチックにコップは」と続かない。", "が": "「が」は主語を示すが、後ろの「コップは」と主語が二重になり不自然。"}, "error_tags": {"を": "目的語", "に": "位置", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38036, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38036, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "プラスチックは、おもちゃやびんなど、いろいろなものをつくるのに つかう ざいりょうです。", "primary_collocate": null, "pronunciation": "ぷらすちっく", "ipa": "pɯɾasɯtɕikkɯ", "syllable_count": 6, "sentences": [{"text": "このおもちゃはプラスチックでできているので、軽くてこわれにくいです。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "このおもちゃはプラスチックでできているので、軽(かる)くてこわれにくいです。", "sentence_source": "generated"}, {"text": "プラスチックのコップは落としても割れません。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "プラスチックのコップは落(お)としても割(わ)れません。", "sentence_source": "generated"}, {"text": "姉はプラスチックのびんに水を入れて、学校へ持っていきました。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "姉(あね)はプラスチックのびんに水(みず)を入(い)れて、学校(がっこう)へ持(も)っていきました。", "sentence_source": "generated"}, {"text": "木ではなくプラスチックで作ったので、このいすは安いです。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "木(き)ではなくプラスチックで作(つく)ったので、このいすは安(やす)いです。", "sentence_source": "generated"}, {"text": "プラスチックのお皿は、ガラスのお皿より軽いです。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "プラスチックのお皿(さら)は、ガラスのお皿より軽(かる)いです。", "sentence_source": "generated"}, {"text": "弟はプラスチックのブロックで大きな家を作りました。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "弟(おとうと)はプラスチックのブロックで大(おお)きな家(いえ)を作(つく)りました。", "sentence_source": "generated"}, {"text": "この箱はプラスチックなので、水にぬれてもだいじょうぶです。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "この箱(はこ)はプラスチックなので、水(みず)にぬれてもだいじょうぶです。", "sentence_source": "generated"}, {"text": "熱いお湯を入れると、プラスチックのコップはとけることがあります。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "熱(あつ)いお湯(ゆ)を入(い)れると、プラスチックのコップはとけることがあります。", "sentence_source": "generated"}, {"text": "店でプラスチックのふくろをもらいました。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "店(みせ)でプラスチックのふくろをもらいました。", "sentence_source": "generated"}, {"text": "古いプラスチックのおもちゃを集めて、リサイクルに出しました。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "古(ふる)いプラスチックのおもちゃを集(あつ)めて、リサイクルに出(だ)しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プラスチック", "label": "基本形"}], "register": "中立（です・ます体と普通体が混在）", "sense_fingerprint": "おもちゃ・びん・コップなど身近な物を作る軽い材料としてのプラスチック", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38036, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プラスチック", "is_correct": true, "explanation": "軽くて割れにくいおもちゃの材料として、文の内容に合う。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは重くて割れやすいので、「軽くてこわれにくい」と矛盾する。"}, {"text": "金属", "is_correct": false, "explanation": "金属は重く、さびることもあるので、「軽くてこわれにくい」に合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は重く、落とすと割れやすいので、「軽くてこわれにくい」に合わない。"}], "explanations": {"プラスチック": "軽くて割れにくいおもちゃの材料として、文の内容に合う。", "ガラス": "ガラスは重くて割れやすいので、「軽くてこわれにくい」と矛盾する。", "金属": "金属は重く、さびることもあるので、「軽くてこわれにくい」に合わない。", "石": "石は重く、落とすと割れやすいので、「軽くてこわれにくい」に合わない。"}, "sentence_index": 0, "correct_answer": "プラスチック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "プラスチックは鉄を溶かして型に流し込んで作るので、この鍋は重くて丈夫です。", "explanation": "〈金属〉と混同した文。プラスチックは鉄ではなく石油などから作るので、鉄を溶かして作るとは言わない。"}, {"text": "プラスチックは水を凍らせて作るので、このびんは冷たくて割れにくいです。", "explanation": "〈氷〉と混同した文。プラスチックは水を凍らせて作るのではなく、石油などから作るので、この言い方は合わない。"}, {"text": "プラスチックは山の木を切って作るので、このいすは丈夫です。", "explanation": "〈木材〉と混同した文。プラスチックは木ではなく石油などから作るので、木から作るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38036, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プラスチック", "is_correct": true, "explanation": "水にぬれてもだいじょうぶな素材として、文の内容に合う。"}, {"text": "紙", "is_correct": false, "explanation": "紙は水にぬれるとやぶれるので、「水にぬれてもだいじょうぶ」に合わない。"}, {"text": "段ボール", "is_correct": false, "explanation": "段ボールは水にぬれるとくずれるので、「水にぬれてもだいじょうぶ」に合わない。"}, {"text": "木", "is_correct": false, "explanation": "木は水にぬれると反ったりくさったりするおそれがあり、文の内容に合わない。"}], "explanations": {"プラスチック": "水にぬれてもだいじょうぶな素材として、文の内容に合う。", "紙": "紙は水にぬれるとやぶれるので、「水にぬれてもだいじょうぶ」に合わない。", "段ボール": "段ボールは水にぬれるとくずれるので、「水にぬれてもだいじょうぶ」に合わない。", "木": "木は水にぬれると反ったりくさったりするおそれがあり、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "プラスチック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プラスチックは砂を高温で溶かして作るので、このびんは中が見えます。", "explanation": "〈ガラス〉と混同した文。プラスチックは砂ではなく石油などから作るので、砂から作るとは言わない。"}, {"text": "プラスチックは山から切り出すので、この置物は重くてかたいです。", "explanation": "〈石〉と混同した文。プラスチックは山で採る素材ではなく、人工的に作るものなので、この言葉はこうは使わない。"}, {"text": "プラスチックは木をくだいてパルプにして作るので、この箱は軽いです。", "explanation": "〈紙〉と混同した文。プラスチックは木からパルプを作って作るものではないので、この言葉はこうは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38036, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このコップはプラスチックにできているので、軽くてこわれにくいです。", "corrected_sentence": "このコップはプラスチックでできているので、軽くてこわれにくいです。", "error_description": "誤りは助詞「に」。材料を表す「〜でできている」の「で」が正しく、「にできている」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38036, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "プラスチックを箱は、水にぬれてもだいじょうぶです。", "corrected_sentence": "プラスチックの箱は、水にぬれてもだいじょうぶです。", "error_description": "誤りは助詞「を」。「プラスチック」は名詞「箱」を修飾するので「の」が正しい。「を」は目的語を表すため、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38037, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「プラスチックを熱で溶かす」の目的語で、「溶かして」と正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「プラスチックが熱で溶かして」では、溶かす対象を示せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を表すので、「プラスチックに熱で溶かして」と続かない。"}, {"text": "の", "is_correct": false, "explanation": "「プラスチックの熱で溶かして」では、熱を修飾する形になり、溶かす対象が不明になる。"}], "correct_answer": "を", "explanations": {"を": "「プラスチックを熱で溶かす」の目的語で、「溶かして」と正しく続く。", "が": "「プラスチックが熱で溶かして」では、溶かす対象を示せず不自然。", "に": "「に」は場所や相手を表すので、「プラスチックに熱で溶かして」と続かない。", "の": "「プラスチックの熱で溶かして」では、熱を修飾する形になり、溶かす対象が不明になる。"}, "error_tags": {"が": "主語", "に": "位置", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38037, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38037, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "プラスチックとは、石油などを原料として人工的に作られた、軽くて加工しやすい合成樹脂のことです。", "primary_collocate": null, "pronunciation": "ぷらすちっく", "ipa": "pɯɾasɯtɕikkɯ", "syllable_count": 6, "sentences": [{"text": "プラスチックは石油から作られる合成樹脂の一種です。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "プラスチックは石油(せきゆ)から作(つく)られる合成樹脂(ごうせいじゅし)の一種(いっしゅ)です。", "sentence_source": "generated"}, {"text": "工場では、プラスチックを熱で溶かして、型に流し込みます。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "工場(こうじょう)では、プラスチックを熱(ねつ)で溶(と)かして、型(かた)に流(なが)し込(こ)みます。", "sentence_source": "generated"}, {"text": "プラスチックは加工しやすいので、車の部品にもたくさん使われています。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "プラスチックは加工(かこう)しやすいので、車(くるま)の部品(ぶひん)にもたくさん使(つか)われています。", "sentence_source": "generated"}, {"text": "金属にくらべて、プラスチックは軽くてさびません。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "金属(きんぞく)にくらべて、プラスチックは軽(かる)くてさびません。", "sentence_source": "generated"}, {"text": "プラスチックは自然の中でなかなか分解されないため、環境の問題になっています。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "プラスチックは自然(しぜん)の中(なか)でなかなか分解(ぶんかい)されないため、環境(かんきょう)の問題(もんだい)になっています。", "sentence_source": "generated"}, {"text": "この会社は、石油を原料にした新しいプラスチックを開発しました。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "この会社(かいしゃ)は、石油(せきゆ)を原料(げんりょう)にした新(あたら)しいプラスチックを開発(かいはつ)しました。", "sentence_source": "generated"}, {"text": "電気を通さないので、コードのカバーにはプラスチックが使われます。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "電気(でんき)を通(とお)さないので、コードのカバーにはプラスチックが使(つか)われます。", "sentence_source": "generated"}, {"text": "研究者は、海のごみに含まれるプラスチックの量を調べました。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "研究者(けんきゅうしゃ)は、海(うみ)のごみに含(ふく)まれるプラスチックの量(りょう)を調(しら)べました。", "sentence_source": "generated"}, {"text": "石油の値段が上がると、プラスチックの値段も上がります。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "石油(せきゆ)の値段(ねだん)が上(あ)がると、プラスチックの値段(ねだん)も上(あ)がります。", "sentence_source": "generated"}, {"text": "医療の現場では、使い捨てのプラスチックがよく利用されています。", "target_word": "プラスチック", "complexity_tier": "T3", "furigana": "医療(いりょう)の現場(げんば)では、使(つか)い捨(す)てのプラスチックがよく利用(りよう)されています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プラスチック", "label": "基本形"}], "register": "中立（説明的な文体）", "sense_fingerprint": "石油から作る合成樹脂という素材・工業材料としてのプラスチック", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38037, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プラスチック", "is_correct": true, "explanation": "石油から作られる合成樹脂そのものを指し、文の定義と一致する。"}, {"text": "金属", "is_correct": false, "explanation": "金属は石油から作るものではないので、「石油から作られる合成樹脂」に合わない。"}, {"text": "木", "is_correct": false, "explanation": "木は植物から得る材料で、石油から作る合成樹脂ではないので合わない。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは砂などから作るもので、石油からは作らないので合わない。"}], "explanations": {"プラスチック": "石油から作られる合成樹脂そのものを指し、文の定義と一致する。", "金属": "金属は石油から作るものではないので、「石油から作られる合成樹脂」に合わない。", "木": "木は植物から得る材料で、石油から作る合成樹脂ではないので合わない。", "ガラス": "ガラスは砂などから作るもので、石油からは作らないので合わない。"}, "sentence_index": 0, "correct_answer": "プラスチック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "プラスチックは溶かした鉄を型に流し込んで作るので、このフライパンは重くて丈夫です。", "explanation": "〈金属〉と混同した文。プラスチックは鉄ではなく石油などから作るので、鉄を溶かして作るとは言わない。"}, {"text": "天然プラスチックは木の樹液から取れるので、このタイヤは自然の材料です。", "explanation": "〈天然ゴム〉と混同した文。プラスチックは石油などから人工的に作るので、「天然」とは言わない。"}, {"text": "プラスチックは砂を高温で溶かして作るので、この窓は透明で割れにくいです。", "explanation": "〈ガラス〉と混同した文。プラスチックは砂ではなく石油などから作るので、砂を溶かして作るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38037, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プラスチック", "is_correct": true, "explanation": "電気を通さない絶縁材料として使われるので、文の内容に合う。"}, {"text": "銅", "is_correct": false, "explanation": "銅は電気をよく通すので、「電気を通さないので」と矛盾する。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄も電気を通すので、コードのカバーとして使うと「電気を通さない」に合わない。"}, {"text": "銀", "is_correct": false, "explanation": "銀は電気をとてもよく通すので、「電気を通さないので」と矛盾する。"}], "explanations": {"プラスチック": "電気を通さない絶縁材料として使われるので、文の内容に合う。", "銅": "銅は電気をよく通すので、「電気を通さないので」と矛盾する。", "鉄": "鉄も電気を通すので、コードのカバーとして使うと「電気を通さない」に合わない。", "銀": "銀は電気をとてもよく通すので、「電気を通さないので」と矛盾する。"}, "sentence_index": 6, "correct_answer": "プラスチック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プラスチックは植物の繊維から作るので、このシャツは自然の風合いです。", "explanation": "〈綿〉と混同した文。プラスチックは植物ではなく石油などから作るので、この言葉はこうは使わない。"}, {"text": "プラスチックは山から切り出すので、このかべは重いです。", "explanation": "〈石〉と混同した文。プラスチックは山で採る素材ではないので、この言葉はこうは使わない。"}, {"text": "プラスチックは土を焼いて作るので、このお皿はわれやすいです。", "explanation": "〈陶器〉と混同した文。プラスチックは土ではなく石油から作るので、土を焼くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38037, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "プラスチックを加工は、工場で行われます。", "corrected_sentence": "プラスチックの加工は、工場で行われます。", "error_description": "誤りは助詞「を」。「加工」を修飾する「プラスチックの」の「の」が正しい。「を」にすると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38037, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このかさの骨は、プラスチックに作られています。", "corrected_sentence": "このかさの骨は、プラスチックで作られています。", "error_description": "誤りは助詞「に」。材料を表す「で作られる」の「で」が正しく、「に作られる」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38038, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「分別がとても細かい」と、「が」で分別を主語にして「細かい」と評価する形になる。"}, {"text": "を", "is_correct": false, "explanation": "「分別をとても細かい」と目的語にすると、形容詞「細かい」の主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「分別に細かい」は対象・方向の「に」で、「細かい」の主語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「分別と細かい」は並列の「と」で、文の述語が「細かい」に続かない。"}], "correct_answer": "が", "explanations": {"が": "「分別がとても細かい」と、「が」で分別を主語にして「細かい」と評価する形になる。", "を": "「分別をとても細かい」と目的語にすると、形容詞「細かい」の主語にならない。", "に": "「分別に細かい」は対象・方向の「に」で、「細かい」の主語として成り立たない。", "と": "「分別と細かい」は並列の「と」で、文の述語が「細かい」に続かない。"}, "error_tags": {"を": "目的語", "に": "対象", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38038, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「分別の仕方」と、「の」で分別と仕方を結んで「ごみの分別の仕方」という名詞句を作る。"}, {"text": "で", "is_correct": false, "explanation": "「分別で仕方」は手段の「で」で、仕方とつながらず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「分別より仕方」は比較の「より」で、教える内容の文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「分別へ仕方」は方向の「へ」で、仕方を教える文の形にならない。"}], "correct_answer": "の", "explanations": {"の": "「分別の仕方」と、「の」で分別と仕方を結んで「ごみの分別の仕方」という名詞句を作る。", "で": "「分別で仕方」は手段の「で」で、仕方とつながらず文が成り立たない。", "より": "「分別より仕方」は比較の「より」で、教える内容の文に合わない。", "へ": "「分別へ仕方」は方向の「へ」で、仕方を教える文の形にならない。"}, "error_tags": {"で": "手段", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38038, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "家庭などでごみを種類ごとに分けて、決まった袋や箱に入れること。", "primary_collocate": null, "pronunciation": "ぶんべつ", "ipa": "bɯmbetsɯ", "syllable_count": 4, "sentences": [{"text": "ごみの分別は、朝の八時までに終わらせてください。", "target_word": "分別", "complexity_tier": "T3", "furigana": "ごみの分別(ぶんべつ)は、朝(あさ)の八時(はちじ)までに終(お)わらせてください。", "sentence_source": "generated"}, {"text": "私の町では、ごみの分別がとても細かい。", "target_word": "分別", "complexity_tier": "T3", "furigana": "私(わたし)の町(まち)では、ごみの分別(ぶんべつ)がとても細(こま)かい。", "sentence_source": "generated"}, {"text": "分別したごみを、決められた日に出します。", "target_word": "分別", "complexity_tier": "T3", "furigana": "分別(ぶんべつ)したごみを、決(き)められた日(ひ)に出(だ)します。", "sentence_source": "generated"}, {"text": "家族みんなで、ごみを分別するようにしている。", "target_word": "分別", "complexity_tier": "T3", "furigana": "家族(かぞく)みんなで、ごみを分別(ぶんべつ)するようにしている。", "sentence_source": "generated"}, {"text": "缶とペットボトルは、分別して別の袋に入れてください。", "target_word": "分別", "complexity_tier": "T3", "furigana": "缶(かん)とペットボトルは、分別(ぶんべつ)して別(べつ)の袋(ふくろ)に入(い)れてください。", "sentence_source": "generated"}, {"text": "分別をしないと、ごみを回収してもらえない。", "target_word": "分別", "complexity_tier": "T3", "furigana": "分別(ぶんべつ)をしないと、ごみを回収(かいしゅう)してもらえない。", "sentence_source": "generated"}, {"text": "引っ越してきたばかりで、ごみの分別が分からない。", "target_word": "分別", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)してきたばかりで、ごみの分別(ぶんべつ)が分(わ)からない。", "sentence_source": "generated"}, {"text": "子どもにごみの分別の仕方を教えた。", "target_word": "分別", "complexity_tier": "T3", "furigana": "子(こ)どもにごみの分別(ぶんべつ)の仕方(しかた)を教(おし)えた。", "sentence_source": "generated"}, {"text": "台所に分別用のごみ箱を三つ置いている。", "target_word": "分別", "complexity_tier": "T3", "furigana": "台所(だいどころ)に分別(ぶんべつ)用(よう)のごみ箱(ばこ)を三(みっ)つ置(お)いている。", "sentence_source": "generated"}, {"text": "分別が面倒でも、環境のために続けたい。", "target_word": "分別", "complexity_tier": "T3", "furigana": "分別(ぶんべつ)が面倒(めんどう)でも、環境(かんきょう)のために続(つづ)けたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分別", "label": "基本形"}, {"form": "分別する", "label": "動詞形"}, {"form": "分別して", "label": "て形"}, {"form": "分別した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "家庭などでごみを種類ごとに分けて、決まった袋や箱に入れること（ぶんべつ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38038, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分別", "is_correct": true, "explanation": "「ごみの分別」はごみを種類ごとに分けることで、朝の締め切りの文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「ごみの天気」は意味をなさず、締め切りの文脈にも合わない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は意見の述べ方で、ごみの締め切りの話には結びつかない。"}, {"text": "残高", "is_correct": false, "explanation": "残高は金額の残りを表し、ごみの作業には使えない。"}], "explanations": {"分別": "「ごみの分別」はごみを種類ごとに分けることで、朝の締め切りの文に合う。", "天気": "「ごみの天気」は意味をなさず、締め切りの文脈にも合わない。", "感想": "感想は意見の述べ方で、ごみの締め切りの話には結びつかない。", "残高": "残高は金額の残りを表し、ごみの作業には使えない。"}, "sentence_index": 0, "correct_answer": "分別"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は、利益を全社員に分別して配った。", "explanation": "ここは〈分配〉（割り当てて配ること）の意味。分別は種類ごとに分けることで、利益を配る意味では使わない。"}, {"text": "細胞が二つに分別して、数が増えた。", "explanation": "ここは〈分裂〉（細胞が二つに分かれること）の意味。分別は種類ごとに分けることで、細胞の増殖には使わない。"}, {"text": "双子の名前を分別できる人は少ない。", "explanation": "ここは〈区別〉（違いを見分けること）の意味。分別はものを種類ごとに分けることなので、見分ける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38038, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分別", "is_correct": true, "explanation": "「ごみの分別が分からない」で、ごみの分け方が分からないという文に合う。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏はごみの話題と結びつかず、「ごみの演奏が分からない」は成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "季節はごみの分け方の話に合わず、文が通らない。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は書類の一種で、ごみの分け方を表せない。"}], "explanations": {"分別": "「ごみの分別が分からない」で、ごみの分け方が分からないという文に合う。", "演奏": "演奏はごみの話題と結びつかず、「ごみの演奏が分からない」は成り立たない。", "季節": "季節はごみの分け方の話に合わず、文が通らない。", "名刺": "名刺は書類の一種で、ごみの分け方を表せない。"}, "sentence_index": 6, "correct_answer": "分別"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この道は駅の手前で二つに分別している。", "explanation": "ここは〈分岐〉（道が分かれること）の意味。分別はものを種類ごとに分けることで、道が分かれる意味では使わない。"}, {"text": "有機物は微生物によって細かく分別される。", "explanation": "ここは〈分解〉（化学的に細かく分けること）の意味。分別は種類ごとに分けることで、物質の化学変化には使わない。"}, {"text": "土地を三つに分別して売った。", "explanation": "ここは〈分割〉（一つを複数に分けること）の意味。分別は種類で分けることなので、土地を区画に分けるなら分割を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38038, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "缶は分別れて、決まった箱に入れてください。", "corrected_sentence": "缶は分別して、決まった箱に入れてください。", "error_description": "「分別れて」は誤り。分別は名詞で、動詞にするには「分別する」の形をとるため、て形は「分別して」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38038, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引っ越してきたばかりで、ごみの分別に仕方が分からない。", "corrected_sentence": "引っ越してきたばかりで、ごみの分別の仕方が分からない。", "error_description": "「分別に仕方」は誤り。「分別」と「仕方」をつなぐのは連体の「の」で、「に」では「仕方」が結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38039, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「素材ごとに分別している」で、分け方の基準を「ごとに」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「素材ごとが分別している」は、素材が分別の主体になり文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「素材ごとへ分別している」は方向の「へ」で、分ける基準を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「素材ごとと分別している」は並列の「と」で、動詞に合わない。"}], "correct_answer": "に", "explanations": {"に": "「素材ごとに分別している」で、分け方の基準を「ごとに」で示す。", "が": "「素材ごとが分別している」は、素材が分別の主体になり文として不自然。", "へ": "「素材ごとへ分別している」は方向の「へ」で、分ける基準を表せない。", "と": "「素材ごとと分別している」は並列の「と」で、動詞に合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38039, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「素材ごとに分別している」で、分け方の基準を「ごとに」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「素材ごとを分別している」は、「ごと」を分別の目的語にするのが不自然。"}, {"text": "より", "is_correct": false, "explanation": "「素材ごとより分別している」は比較の「より」で、分け方の基準にならない。"}, {"text": "で", "is_correct": false, "explanation": "「素材ごとで分別している」は手段の「で」で、分け方の基準として不自然。"}], "correct_answer": "に", "explanations": {"に": "「素材ごとに分別している」で、分け方の基準を「ごとに」で示す。", "を": "「素材ごとを分別している」は、「ごと」を分別の目的語にするのが不自然。", "より": "「素材ごとより分別している」は比較の「より」で、分け方の基準にならない。", "で": "「素材ごとで分別している」は手段の「で」で、分け方の基準として不自然。"}, "error_tags": {"を": "目的語", "より": "比較", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38039, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを種類ごとに分けること。特に、資源として再利用するために、ごみを素材ごとに分類すること。", "primary_collocate": null, "pronunciation": "ぶんべつ", "ipa": "bɯmbetsɯ", "syllable_count": 4, "sentences": [{"text": "資源として再利用するため、ごみの分別は大切だ。", "target_word": "分別", "complexity_tier": "T3", "furigana": "資源(しげん)として再利用(さいりよう)するため、ごみの分別(ぶんべつ)は大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "工場では、集めた廃棄物を素材ごとに分別している。", "target_word": "分別", "complexity_tier": "T3", "furigana": "工場(こうじょう)では、集(あつ)めた廃棄物(はいきぶつ)を素材(そざい)ごとに分別(ぶんべつ)している。", "sentence_source": "generated"}, {"text": "分別された紙やガラスは、リサイクル工場に運ばれる。", "target_word": "分別", "complexity_tier": "T3", "furigana": "分別(ぶんべつ)された紙(かみ)やガラスは、リサイクル工場(こうじょう)に運(はこ)ばれる。", "sentence_source": "generated"}, {"text": "正しく分別すれば、ごみの多くが資源になる。", "target_word": "分別", "complexity_tier": "T3", "furigana": "正(ただ)しく分別(ぶんべつ)すれば、ごみの多(おお)くが資源(しげん)になる。", "sentence_source": "generated"}, {"text": "この市は分別が進み、リサイクル率が上がった。", "target_word": "分別", "complexity_tier": "T3", "furigana": "この市(し)は分別(ぶんべつ)が進(すす)み、リサイクル率(りつ)が上(あ)がった。", "sentence_source": "generated"}, {"text": "分別の徹底により、燃えるごみの量が減った。", "target_word": "分別", "complexity_tier": "T3", "furigana": "分別(ぶんべつ)の徹底(てってい)により、燃(も)えるごみの量(りょう)が減(へ)った。", "sentence_source": "generated"}, {"text": "古い電化製品は、金属とプラスチックに分別する。", "target_word": "分別", "complexity_tier": "T3", "furigana": "古(ふる)い電化製品(でんかせいひん)は、金属(きんぞく)とプラスチックに分別(ぶんべつ)する。", "sentence_source": "generated"}, {"text": "学校でも、給食のごみを素材ごとに分別している。", "target_word": "分別", "complexity_tier": "T3", "furigana": "学校(がっこう)でも、給食(きゅうしょく)のごみを素材(そざい)ごとに分別(ぶんべつ)している。", "sentence_source": "generated"}, {"text": "分別が正しくないと、資源として再利用できない。", "target_word": "分別", "complexity_tier": "T3", "furigana": "分別(ぶんべつ)が正(ただ)しくないと、資源(しげん)として再利用(さいりよう)できない。", "sentence_source": "generated"}, {"text": "町内会で、ごみの分別の方法を説明する会を開いた。", "target_word": "分別", "complexity_tier": "T3", "furigana": "町内会(ちょうないかい)で、ごみの分別(ぶんべつ)の方法(ほうほう)を説明(せつめい)する会(かい)を開(ひら)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分別", "label": "基本形"}, {"form": "分別する", "label": "動詞形"}, {"form": "分別された", "label": "受身過去形"}, {"form": "分別して", "label": "て形"}], "register": "formal", "sense_fingerprint": "資源の再利用のために、ごみや廃棄物を素材ごとに分類すること（ぶんべつ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38039, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分別", "is_correct": true, "explanation": "「ごみの分別は大切だ」で、資源として再利用するための分け方を述べる文に合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は人に向けるもので、ごみの分け方の文には入らない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は布団などを指し、資源やごみの話には合わない。"}, {"text": "音階", "is_correct": false, "explanation": "音階は音楽の用語で、資源再利用の文脈に合わない。"}], "explanations": {"分別": "「ごみの分別は大切だ」で、資源として再利用するための分け方を述べる文に合う。", "挨拶": "挨拶は人に向けるもので、ごみの分け方の文には入らない。", "寝具": "寝具は布団などを指し、資源やごみの話には合わない。", "音階": "音階は音楽の用語で、資源再利用の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "分別"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は、利益を社員の間で分別した。", "explanation": "ここは〈配分〉（割り当てて配ること）の意味。分別は種類ごとに分けることで、利益を割り当てる意味では使わない。"}, {"text": "細胞が二つに分別して、数が増えた。", "explanation": "ここは〈分裂〉（細胞が二つに分かれること）の意味。分別は素材などで分類することなので、細胞の増殖には使わない。"}, {"text": "二人の声を分別できる人は少ない。", "explanation": "ここは〈区別〉（違いを見分けること）の意味。分別は分類して分けることで、声の違いを見分ける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38039, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分別", "is_correct": true, "explanation": "「金属とプラスチックに分別する」で、種類ごとに分けるという動作を表す。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は音楽に関する行為で、電化製品を分けることには使わない。"}, {"text": "朝食", "is_correct": false, "explanation": "朝食は食事のことで、金属とプラスチックの区分には合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は紙の一種で、電化製品の素材を分ける文には入らない。"}], "explanations": {"分別": "「金属とプラスチックに分別する」で、種類ごとに分けるという動作を表す。", "演奏": "演奏は音楽に関する行為で、電化製品を分けることには使わない。", "朝食": "朝食は食事のことで、金属とプラスチックの区分には合わない。", "名刺": "名刺は紙の一種で、電化製品の素材を分ける文には入らない。"}, "sentence_index": 6, "correct_answer": "分別"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の手前で、道が二つに分別している。", "explanation": "ここは〈分岐〉（道が分かれること）の意味。分別は分類して分けることで、道が分かれる意味では使わない。"}, {"text": "食べ物は胃や腸で細かく分別される。", "explanation": "ここは〈分解〉（細かく分けて成分にすること）の意味。分別は分類することで、消化や化学変化には使わない。"}, {"text": "この土地は三つに分別して売り出された。", "explanation": "ここは〈分割〉（一つを複数に分けること）の意味。土地を区画に分けるなら分割を使い、分別は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38039, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "プラスチックは分別で、リサイクル工場に運ばれる。", "corrected_sentence": "プラスチックは分別されて、リサイクル工場に運ばれる。", "error_description": "「分別で」は誤り。分別は「する」を付けて動詞になるので、受身の「分別されて」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38039, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "分別に徹底すると、燃えるごみが減る。", "corrected_sentence": "分別を徹底すると、燃えるごみが減る。", "error_description": "「分別に徹底する」は誤り。「徹底する」は「〜を徹底する」と目的語の「を」を取るので、「に」を「を」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38040, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ガラスのコップ」と名詞を修飾する「の」で、文として正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「ガラスを コップを」と目的語が重なり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ガラスに コップ」と場所や相手の「に」はコップに続かず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「ガラスで コップを落として」と手段の「で」は、文脈上つながらず不自然。"}], "correct_answer": "の", "explanations": {"の": "「ガラスのコップ」と名詞を修飾する「の」で、文として正しく続く。", "を": "「ガラスを コップを」と目的語が重なり、文が成り立たない。", "に": "「ガラスに コップ」と場所や相手の「に」はコップに続かず、意味が通らない。", "で": "「ガラスで コップを落として」と手段の「で」は、文脈上つながらず不自然。"}, "error_tags": {"を": "目的格", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38040, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38040, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ガラスは、かたいけれど、われることがある、とうめいなものです。", "primary_collocate": null, "pronunciation": "がらす", "ipa": "ɡaɾasɯ", "syllable_count": 3, "sentences": [{"text": "ガラスは透明なので、向こう側がよく見える。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "ガラスは透明[とうめい]なので、向[む]こう側[がわ]がよく見[み]える。", "sentence_source": "generated"}, {"text": "手がすべって、ガラスのコップを落として割ってしまった。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "手[て]がすべって、ガラスのコップを落[お]として割[わ]ってしまった。", "sentence_source": "generated"}, {"text": "子どもがボールを投げて、ガラスが割れた。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "子[こ]どもがボールを投[な]げて、ガラスが割[わ]れた。", "sentence_source": "generated"}, {"text": "ガラスの破片が床に散らばっているので、はだしで歩くと危ない。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "ガラスの破片[はへん]が床[ゆか]に散[ち]らばっているので、はだしで歩[ある]くと危[あぶ]ない。", "sentence_source": "generated"}, {"text": "この店では、ガラスの動物を手作りして売っている。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "この店[みせ]では、ガラスの動物[どうぶつ]を手作[てづく]りして売[う]っている。", "sentence_source": "generated"}, {"text": "水族館の大きなガラスの向こうを、魚が泳いでいた。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "水族館[すいぞくかん]の大[おお]きなガラスの向[む]こうを、魚[さかな]が泳[およ]いでいた。", "sentence_source": "generated"}, {"text": "冬は寒さで、ガラスが白くくもる。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]さで、ガラスが白[しろ]くくもる。", "sentence_source": "generated"}, {"text": "ガラスは硬いが、強くぶつけると簡単に割れる。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "ガラスは硬[かた]いが、強[つよ]くぶつけると簡単[かんたん]に割[わ]れる。", "sentence_source": "generated"}, {"text": "博物館で、千年前のガラスの器を見た。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、千年前[せんねんまえ]のガラスの器[うつわ]を見[み]た。", "sentence_source": "generated"}, {"text": "雨粒がガラスを伝って、ゆっくり流れ落ちた。", "target_word": "ガラス", "complexity_tier": "T3", "furigana": "雨粒[あまつぶ]がガラスを伝[つた]って、ゆっくり流[なが]れ落[お]ちた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ガラス", "label": "基本形"}, {"form": "ガラスの", "label": "連体形"}, {"form": "ガラスが", "label": "格助詞つき"}], "register": "中立（普通体）", "sense_fingerprint": "透明で硬いが割れやすい物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: くもる (Zipf 1.44)','sentence 9 above tier T2: contains vocabulary far above tier T2: 雨粒 (Zipf 2.42)']::text[], '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38040, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ガラス", "is_correct": true, "explanation": "ガラスは透明な素材なので、「透明なので向こう側がよく見える」という文脈に合う。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は不透明な金属なので、「透明なので向こう側がよく見える」という文脈に合わない。"}, {"text": "木", "is_correct": false, "explanation": "木は不透明なので、透明だから向こうがよく見えるという理由の文脈に合わない。"}, {"text": "土", "is_correct": false, "explanation": "土は不透明なので、透明だから向こうがよく見えるという文脈に合わない。"}], "explanations": {"ガラス": "ガラスは透明な素材なので、「透明なので向こう側がよく見える」という文脈に合う。", "鉄": "鉄は不透明な金属なので、「透明なので向こう側がよく見える」という文脈に合わない。", "木": "木は不透明なので、透明だから向こうがよく見えるという理由の文脈に合わない。", "土": "土は不透明なので、透明だから向こうがよく見えるという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ガラス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方の畑で、ガラスが大声で鳴いて、みんなが驚いた。", "explanation": "ここはカラス（鳥）の意味。ガラスは素材なので、鳴く生き物にはならない。"}, {"text": "夏は暑いので、ガラスを開けて風を入れた。", "explanation": "ここは窓の意味。ガラスは素材で、開け閉めするのは窓の枠や戸なので合わない。"}, {"text": "台風で壊れた水道管を、ガラスが直しに来た。", "explanation": "ここはガラス屋（ガラスを扱う職人や店）の意味。ガラスは素材なので、人のように直しに来ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38040, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガラス", "is_correct": true, "explanation": "ガラスは冬に表面が白くくもる素材なので、「寒さで白くくもる」という文脈に合う。"}, {"text": "布", "is_correct": false, "explanation": "布は表面がくもるものではないので、「寒さで白くくもる」という文脈に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は寒さで白くくもる性質がないので、この文脈に合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は寒さで白くくもるものではないので、この文脈に合わない。"}], "explanations": {"ガラス": "ガラスは冬に表面が白くくもる素材なので、「寒さで白くくもる」という文脈に合う。", "布": "布は表面がくもるものではないので、「寒さで白くくもる」という文脈に合わない。", "紙": "紙は寒さで白くくもる性質がないので、この文脈に合わない。", "砂": "砂は寒さで白くくもるものではないので、この文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ガラス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公園に残ったパンを、ガラスがついばんで食べていた。", "explanation": "ここはカラス（鳥）の意味。ガラスは素材なので、パンをついばむ主体にはならない。"}, {"text": "夏の暑い日、麦茶にガラスを入れて飲んだ。", "explanation": "ここは氷（水が凍った物）の意味。ガラスは素材なので、飲み物を冷やす具材としては使わない。"}, {"text": "悲しい映画を見て、ガラスが頬を伝って流れ落ちた。", "explanation": "ここは涙の意味。ガラスは素材なので、頬を伝って流れ落ちる液体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38040, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラスに向こうに、大きな海が広がっている。", "corrected_sentence": "ガラスの向こうに、大きな海が広がっている。", "error_description": "正しくは「ガラスの向こう」。「ガラス」が「向こう」を修飾するので連体修飾の「の」が必要で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38040, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の朝、ガラスを霜がついて白くなっていた。", "corrected_sentence": "冬の朝、ガラスに霜がついて白くなっていた。", "error_description": "正しくは「ガラスに霜がつく」。「つく」は付着する場所を「に」で示すので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
