INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38042, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "電気が通っていなかった場所や家に電気を引き、電灯などを使えるようにすること。", "primary_collocate": null, "pronunciation": "でんか", "ipa": "deŋka", "syllable_count": 3, "sentences": [{"text": "この村では、去年やっと電化が終わった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "この村[むら]では、去年[きょねん]やっと電化[でんか]が終[お]わった。", "sentence_source": "generated"}, {"text": "山の家も電化して、夜でも明るくなった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "山[やま]の家[いえ]も電化[でんか]して、夜[よる]でも明[あか]るくなった。", "sentence_source": "generated"}, {"text": "電化が進むと、ランプを使う人は少なくなる。", "target_word": "電化", "complexity_tier": "T3", "furigana": "電化[でんか]が進[すす]むと、ランプを使[つか]う人[ひと]は少[すく]なくなる。", "sentence_source": "generated"}, {"text": "祖母の育った町は、戦後に電化した。", "target_word": "電化", "complexity_tier": "T3", "furigana": "祖母[そぼ]の育[そだ]った町[まち]は、戦後[せんご]に電化[でんか]した。", "sentence_source": "generated"}, {"text": "電化のおかげで、冬の夜も本が読めるようになった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "電化[でんか]のおかげで、冬[ふゆ]の夜[よる]も本[ほん]が読[よ]めるようになった。", "sentence_source": "generated"}, {"text": "島の電化には、海の下にケーブルを通す工事が必要だった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "島[しま]の電化[でんか]には、海[うみ]の下[した]にケーブルを通[とお]す工事[こうじ]が必要[ひつよう]だった。", "sentence_source": "generated"}, {"text": "川のそばの小さな町でも、電化が少しずつ進んでいる。", "target_word": "電化", "complexity_tier": "T3", "furigana": "川[かわ]のそばの小[ちい]さな町[まち]でも、電化[でんか]が少[すこ]しずつ進[すす]んでいる。", "sentence_source": "generated"}, {"text": "電気がなかった時代、家の電化は人々の夢だった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "電気[でんき]がなかった時代[じだい]、家[いえ]の電化[でんか]は人々[ひとびと]の夢[ゆめ]だった。", "sentence_source": "generated"}, {"text": "学校の電化が決まり、教室に電灯がつくことになった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "学校[がっこう]の電化[でんか]が決[き]まり、教室[きょうしつ]に電灯[でんとう]がつくことになった。", "sentence_source": "generated"}, {"text": "電化によって、夜に勉強する子どもが増えた。", "target_word": "電化", "complexity_tier": "T3", "furigana": "電化[でんか]によって、夜[よる]に勉強[べんきょう]する子[こ]どもが増[ふ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電化", "label": "名詞形"}, {"form": "電化する", "label": "辞書形"}, {"form": "電化した", "label": "過去形"}, {"form": "電化して", "label": "て形"}, {"form": "電化される", "label": "受身形"}], "register": "やや硬い書き言葉（常体）", "sense_fingerprint": "電気のなかった場所や家に電気が通り、電灯などを使えるようになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38042, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電化", "is_correct": true, "explanation": "「終わった」と合う。村に電気の設備を通す工事が完了したという意味になる。"}, {"text": "電灯", "is_correct": false, "explanation": "電灯は器具そのものを指すので、「電灯が終わった」とは言えない。"}, {"text": "人口", "is_correct": false, "explanation": "人口は増減するもので、「終わった」の主語にはならない。"}, {"text": "漁業", "is_correct": false, "explanation": "漁業は産業の名前なので、「漁業が終わった」とは続かない。"}], "explanations": {"電化": "「終わった」と合う。村に電気の設備を通す工事が完了したという意味になる。", "電灯": "電灯は器具そのものを指すので、「電灯が終わった」とは言えない。", "人口": "人口は増減するもので、「終わった」の主語にはならない。", "漁業": "漁業は産業の名前なので、「漁業が終わった」とは続かない。"}, "sentence_index": 0, "correct_answer": "電化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の帳簿を電化して、紙の書類を減らした。", "explanation": "ここは〈電子化〉の意味。電化は設備や機器の動力を電気に切り替えることで、帳簿のデータ化には使わない。"}, {"text": "このアプリは、一年で全国に電化した。", "explanation": "ここは〈普及〉の意味。電化は機器や設備に電気を使うようにすることで、アプリが広まる意味では使わない。"}, {"text": "夜は節電のため、電化を心がけた。", "explanation": "ここは〈電気の使用を減らす〉の意味。電化は電気を使うようにすることで、使用を減らす意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38042, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電化", "is_correct": true, "explanation": "「進んでいる」の主語として合う。川沿いの町で電気を使えるようにする動きが進んでいるという意味になる。"}, {"text": "雨量", "is_correct": false, "explanation": "雨量は量を表すので、「進んでいる」の主語には合わない。"}, {"text": "年金", "is_correct": false, "explanation": "年金は制度の名前で、「進んでいる」の主語としては不自然。"}, {"text": "食糧", "is_correct": false, "explanation": "食糧は物資を指すので、「食糧が進む」という使い方は成り立たない。"}], "explanations": {"電化": "「進んでいる」の主語として合う。川沿いの町で電気を使えるようにする動きが進んでいるという意味になる。", "雨量": "雨量は量を表すので、「進んでいる」の主語には合わない。", "年金": "年金は制度の名前で、「進んでいる」の主語としては不自然。", "食糧": "食糧は物資を指すので、「食糧が進む」という使い方は成り立たない。"}, "sentence_index": 6, "correct_answer": "電化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は新しい電化を買った。", "explanation": "ここは〈電化製品〉の意味。「電化」は電気を使うようにすることを表す語で、家電そのものを指さないので「買う」の対象にはならない。"}, {"text": "停電で電化が止まった。", "explanation": "ここは〈電気〉の意味。「電化」は電気を使うようにすることで、電気そのものを指さないので「止まる」とは続かない。"}, {"text": "部屋の電化をつけた。", "explanation": "ここは〈電灯〉の意味。「電化」は電気の利用を進めることで、灯りをつける動作とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38042, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町は電化を進んで、夜も明るくなった。", "corrected_sentence": "この町は電化が進んで、夜も明るくなった。", "error_description": "正しくは「電化が進む」。「進む」は自動詞なので、主語を「が」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38042, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は来年、電化した予定だ。", "corrected_sentence": "町は来年、電化する予定だ。", "error_description": "「予定」は未来の動作につくので「電化する」が正しい。過去形の「電化した」は「予定」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38043, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「進み」の主語を示す。「電化が進み」で、電化が進むという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「進む」は自動詞なので目的語の「を」は取れない。"}, {"text": "と", "is_correct": false, "explanation": "「電化と進み」は並列にしても主語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、ここでは主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「進み」の主語を示す。「電化が進み」で、電化が進むという意味になる。", "を": "「進む」は自動詞なので目的語の「を」は取れない。", "と": "「電化と進み」は並列にしても主語として成り立たない。", "より": "比較の「より」は、ここでは主語を示せない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38043, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「使う」の対象を示す。「鉄道の電化に」で、お金を使う先を表す。"}, {"text": "を", "is_correct": false, "explanation": "「お金を使う」の目的語がすでにあるため、「電化を」を重ねると文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「電化と使う」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「お金を使う先」を示すには「へ」は不自然。方向の意味に限られる。"}], "correct_answer": "に", "explanations": {"に": "「使う」の対象を示す。「鉄道の電化に」で、お金を使う先を表す。", "を": "「お金を使う」の目的語がすでにあるため、「電化を」を重ねると文が成り立たない。", "と": "「と」は相手や並列を示すが、「電化と使う」とは続かない。", "へ": "「お金を使う先」を示すには「へ」は不自然。方向の意味に限られる。"}, "error_tags": {"を": "目的語の重複", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38043, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "熱や動力などに電気を使うようにすること。", "primary_collocate": null, "pronunciation": "でんか", "ipa": "deŋka", "syllable_count": 3, "sentences": [{"text": "この路線は来年、電化される予定だ。", "target_word": "電化", "complexity_tier": "T3", "furigana": "この路線[ろせん]は来年[らいねん]、電化[でんか]される予定[よてい]だ。", "sentence_source": "generated"}, {"text": "台所の電化が進み、ガスを使わない家が増えた。", "target_word": "電化", "complexity_tier": "T3", "furigana": "台所[だいどころ]の電化[でんか]が進[すす]み、ガスを使[つか]わない家[いえ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "ボイラーの電化は、燃焼による大気汚染を減らすために必要だ。", "target_word": "電化", "complexity_tier": "T3", "furigana": "ボイラーの電化[でんか]は、燃焼による大気汚染を減らすために必要だ。", "sentence_source": "generated"}, {"text": "除雪機の電化により、排気ガスを吸わずに作業できるようになった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "除雪機の電化[でんか]により、排気ガスを吸わずに作業できるようになった。", "sentence_source": "generated"}, {"text": "暖房を電化したら、ガスの代わりに電気で部屋が暖まるようになった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "暖房[だんぼう]を電化[でんか]したら、ガスの代[か]わりに電気[でんき]で部屋[へや]が暖[あたた]まるようになった。", "sentence_source": "generated"}, {"text": "この工場は、熱を使う機械を電化して、石油を使う量を減らした。", "target_word": "電化", "complexity_tier": "T3", "furigana": "この工場[こうじょう]は、熱[ねつ]を使[つか]う機械[きかい]を電化[でんか]して、石油[せきゆ]を使[つか]う量[りょう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "家の電化で、お湯も料理も電気でまかなっている。", "target_word": "電化", "complexity_tier": "T3", "furigana": "家[いえ]の電化[でんか]で、お湯[ゆ]も料理[りょうり]も電気[でんき]でまかなっている。", "sentence_source": "generated"}, {"text": "政府は、鉄道の電化に多くのお金を使ってきた。", "target_word": "電化", "complexity_tier": "T3", "furigana": "政府[せいふ]は、鉄道[てつどう]の電化[でんか]に多[おお]くのお金[かね]を使[つか]ってきた。", "sentence_source": "generated"}, {"text": "農場の機械を電化すると、エンジンの音が静かになる。", "target_word": "電化", "complexity_tier": "T3", "furigana": "農場[のうじょう]の機械[きかい]を電化[でんか]すると、エンジンの音[おと]が静[しず]かになる。", "sentence_source": "generated"}, {"text": "ビルの暖房と給湯を電化する工事が、夏に終わった。", "target_word": "電化", "complexity_tier": "T3", "furigana": "ビルの暖房[だんぼう]と給湯[きゅうとう]を電化[でんか]する工事[こうじ]が、夏[なつ]に終[お]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電化", "label": "名詞形"}, {"form": "電化する", "label": "辞書形"}, {"form": "電化した", "label": "過去形"}, {"form": "電化して", "label": "て形"}, {"form": "電化される", "label": "受身形"}], "register": "やや硬い書き言葉（常体）", "sense_fingerprint": "ガス・石油・蒸気などで得ていた熱や動力を、電気に切り替えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38043, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電化", "is_correct": true, "explanation": "「予定される」の主語として合う。路線の動力を電気に切り替えるという意味になる。"}, {"text": "車両", "is_correct": false, "explanation": "車両は車体そのものを指すので、「来年、車両される予定」とは言えない。"}, {"text": "乗客", "is_correct": false, "explanation": "乗客は人を指すので、路線を対象にした文の主語として合わない。"}, {"text": "食堂", "is_correct": false, "explanation": "食堂は店の種類なので、「食堂される予定」とは続かない。"}], "explanations": {"電化": "「予定される」の主語として合う。路線の動力を電気に切り替えるという意味になる。", "車両": "車両は車体そのものを指すので、「来年、車両される予定」とは言えない。", "乗客": "乗客は人を指すので、路線を対象にした文の主語として合わない。", "食堂": "食堂は店の種類なので、「食堂される予定」とは続かない。"}, "sentence_index": 0, "correct_answer": "電化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は服を電化した。", "explanation": "服は電化の対象ではない。「電化する」は機器や設備の動力を電気に切り替えることで、服には使わない。"}, {"text": "夜は寝る前に電化を消した。", "explanation": "電化は動力を電気に切り替えることで、明かりを消す意味はない。「消す」の目的語としては不自然。"}, {"text": "急いで電化で連絡した。", "explanation": "電化は動力を電気にすることで、連絡の手段を指さない。「連絡した」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38043, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電化", "is_correct": true, "explanation": "「家の〜で」の形で、家庭の動力を電気に切り替えたことを表す。文の意味に合う。"}, {"text": "人口", "is_correct": false, "explanation": "人口は人の数なので、「家の人口で、お湯も料理も電気でまかなっている」とは言えない。"}, {"text": "地形", "is_correct": false, "explanation": "地形は土地の形を表すので、家の設備の話には合わない。"}, {"text": "海流", "is_correct": false, "explanation": "海流は海の水の流れなので、家庭のエネルギーの話とは関係がない。"}], "explanations": {"電化": "「家の〜で」の形で、家庭の動力を電気に切り替えたことを表す。文の意味に合う。", "人口": "人口は人の数なので、「家の人口で、お湯も料理も電気でまかなっている」とは言えない。", "地形": "地形は土地の形を表すので、家の設備の話には合わない。", "海流": "海流は海の水の流れなので、家庭のエネルギーの話とは関係がない。"}, "sentence_index": 6, "correct_answer": "電化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブレーカーが落ちて、電化が止まった。", "explanation": "電化は動作を表す語で、電気そのものを指さない。「電化が止まった」とは続かない。"}, {"text": "コンロのガスに電化を当てた。", "explanation": "電化は動力を電気に切り替えることで、ガスに火を当てる対象にはならない。"}, {"text": "店で新しい電化を買った。", "explanation": "電化は切り替える動作を表し、「買う」の対象となる物の名前ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38043, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の機械を電化されると、夜の音が静かになった。", "corrected_sentence": "町の機械を電化すると、夜の音が静かになった。", "error_description": "「を」の目的語には能動形の「電化する」が続く。受身の「電化される」は「機械が電化される」の形になるので、「機械を」と並べると誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38043, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校の電化が進める計画がある。", "corrected_sentence": "学校の電化を進める計画がある。", "error_description": "「進める」は他動詞なので、目的語を「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38044, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この企業は」と、話題の主語として企業を示す。"}, {"text": "を", "is_correct": false, "explanation": "「この企業を、新しい商品を作って」は、企業を作る対象にしてしまい文の主語として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「この企業に新しい商品を作って」は対象の「に」で、文の主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「この企業へ新しい商品を作って」は方向の「へ」で、主語の役割を果たさない。"}], "correct_answer": "は", "explanations": {"は": "「この企業は」と、話題の主語として企業を示す。", "を": "「この企業を、新しい商品を作って」は、企業を作る対象にしてしまい文の主語として不自然。", "に": "「この企業に新しい商品を作って」は対象の「に」で、文の主語として成り立たない。", "へ": "「この企業へ新しい商品を作って」は方向の「へ」で、主語の役割を果たさない。"}, "error_tags": {"を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38044, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「多くの企業」と、「の」で数量の「多く」を企業につなげる。"}, {"text": "が", "is_correct": false, "explanation": "「多くが企業が」は主語が重なり、文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「多くで企業が」は手段の「で」で、数量を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「多くと企業が」は並列の「と」で、「多く」が名詞として並ばない。"}], "correct_answer": "の", "explanations": {"の": "「多くの企業」と、「の」で数量の「多く」を企業につなげる。", "が": "「多くが企業が」は主語が重なり、文として不自然。", "で": "「多くで企業が」は手段の「で」で、数量を表せない。", "と": "「多くと企業が」は並列の「と」で、「多く」が名詞として並ばない。"}, "error_tags": {"が": "主語", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
